// Nuvemath — 11-sinf, I qism (Algebra va analiz asoslari 11) nazariyasi, t1–t10. Format: js/theory/GUIDE.md
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '11-1';

  // ---------- t1. Orttirmalar nisbati va limit haqida tushuncha ----------
  T.add(P, 't1', { sections: [
    { kind: 'intro', h: L('O‘zgarishni o‘lchash san’ati', 'Искусство измерять изменение', 'The art of measuring change'), p: [
      L('Avtomobil spidometriga qarang: u aynan shu lahzadagi tezlikni ko‘rsatadi. Ammo «lahza» nima? Bir lahzada mashina hech qancha yo‘l bosmaydi, vaqt ham o‘tmaydi — u holda tezlik 0/0 bo‘lib qolmaydimi? Bu savol qadimgi yunon faylasufi Zenonni ham qiynagan: uning mashhur «uchayotgan o‘q» paradoksida o‘q har bir lahzada qimirlamay turgandek tuyuladi.', 'Посмотрите на спидометр автомобиля: он показывает скорость именно в данный момент. Но что такое «момент»? За одно мгновение машина не проезжает никакого пути и время не проходит — не получается ли скорость 0/0? Этот вопрос мучил ещё древнегреческого философа Зенона: в его знаменитом парадоксе «летящая стрела» в каждый момент будто бы покоится.', 'Look at a car’s speedometer: it shows the speed at this very instant. But what is an “instant”? In one instant the car covers no distance and no time passes — so is the speed not 0/0? This question troubled the ancient Greek philosopher Zeno: in his famous “flying arrow” paradox the arrow seems to be at rest at every instant.'),
      L('Matematika bu muammoni juda chiroyli yo‘l bilan hal qildi. Biz avval kichik, lekin noldan farqli vaqt oralig‘ida o‘rtacha tezlikni hisoblaymiz, so‘ng bu oraliqni tobora kichraytirib, o‘rtacha tezliklar qaysi songa yaqinlashayotganini kuzatamiz. Ana shu son — <b>limit</b> — oniy tezlik bo‘ladi.', 'Математика решила эту проблему очень изящно. Сначала мы вычисляем среднюю скорость на маленьком, но ненулевом промежутке времени, затем всё уменьшаем промежуток и следим, к какому числу приближаются средние скорости. Это число — <b>предел</b> — и есть мгновенная скорость.', 'Mathematics solved the problem very elegantly. First we compute the average speed over a small but non-zero time interval, then we keep shrinking the interval and watch which number the average speeds approach. That number — the <b>limit</b> — is the instantaneous speed.'),
      L('Bu bobda biz matematik analizning ikki asosiy g‘ishtini o‘rganamiz: <b>orttirma</b> (qancha o‘zgardi?) va <b>limit</b> (o‘zgarish cheksiz kichik bo‘lganda nima bo‘ladi?). Keyingi barcha mavzular — hosila, urinma, ekstremum, integral — shu ikki tushuncha ustiga quriladi.', 'В этой главе мы изучим два основных кирпичика математического анализа: <b>приращение</b> (насколько изменилось?) и <b>предел</b> (что будет, когда изменение бесконечно мало?). Все следующие темы — производная, касательная, экстремум, интеграл — строятся на этих двух понятиях.', 'In this chapter we study the two basic bricks of calculus: the <b>increment</b> (how much did it change?) and the <b>limit</b> (what happens when the change becomes infinitely small?). All later topics — derivative, tangent, extremum, integral — are built on these two ideas.')
    ] },
    { kind: 'def', h: L('Argument va funksiya orttirmasi', 'Приращение аргумента и функции', 'Increment of the argument and of the function'), p: [
      L('y = f(x) funksiya va uning aniqlanish sohasidagi x₀ nuqta berilgan bo‘lsin. Argumentni x₀ dan yangi x qiymatga o‘zgartiramiz. Ayirma <b>Δx = x − x₀</b> argument orttirmasi deyiladi (Δ — yunoncha «delta» harfi, «farq» ma’nosida). Unga mos ravishda funksiya ham o‘zgaradi: <b>Δy = f(x₀ + Δx) − f(x₀)</b> — funksiya orttirmasi.', 'Пусть дана функция y = f(x) и точка x₀ из её области определения. Изменим аргумент от x₀ до нового значения x. Разность <b>Δx = x − x₀</b> называется приращением аргумента (Δ — греческая буква «дельта», в смысле «разность»). Соответственно изменится и функция: <b>Δy = f(x₀ + Δx) − f(x₀)</b> — приращение функции.', 'Let y = f(x) be a function and x₀ a point of its domain. Change the argument from x₀ to a new value x. The difference <b>Δx = x − x₀</b> is called the increment of the argument (Δ is the Greek letter “delta”, meaning “difference”). The function changes accordingly: <b>Δy = f(x₀ + Δx) − f(x₀)</b> is the increment of the function.'),
      L('Orttirma musbat ham, manfiy ham bo‘lishi mumkin: «orttirma» so‘zi faqat «o‘sish» degani emas, balki umuman «o‘zgarish» demakdir. Masalan, f(x) = x² uchun x₀ = 3, Δx = −1 bo‘lsa, Δy = f(2) − f(3) = 4 − 9 = −5.', 'Приращение может быть как положительным, так и отрицательным: слово «приращение» означает не только «рост», а вообще «изменение». Например, для f(x) = x² при x₀ = 3, Δx = −1 имеем Δy = f(2) − f(3) = 4 − 9 = −5.', 'An increment can be positive or negative: the word does not mean only “growth” but “change” in general. For example, for f(x) = x² with x₀ = 3, Δx = −1 we get Δy = f(2) − f(3) = 4 − 9 = −5.'),
      L('<b>Orttirmalar nisbati</b> Δy/Δx — funksiyaning [x₀; x₀ + Δx] oraliqdagi <b>o‘rtacha o‘zgarish tezligi</b>. Geometrik nuqtai nazardan bu — grafikdagi ikki nuqtani tutashtiruvchi <b>kesuvchi</b>ning burchak koeffitsiyenti.', '<b>Отношение приращений</b> Δy/Δx — <b>средняя скорость изменения</b> функции на промежутке [x₀; x₀ + Δx]. Геометрически это угловой коэффициент <b>секущей</b>, соединяющей две точки графика.', 'The <b>ratio of increments</b> Δy/Δx is the <b>average rate of change</b> of the function on [x₀; x₀ + Δx]. Geometrically it is the slope of the <b>secant</b> joining two points of the graph.')
    ] },
    { kind: 'history', h: L('Limit g‘oyasining tarixi', 'История идеи предела', 'The history of the limit idea'), p: [
      L('Limit g‘oyasining ildizlari Qadimgi Yunonistonga borib taqaladi. Evdoks (mil. av. IV asr) «tugatish usuli»ni ixtiro qildi, Arximed (mil. av. III asr) esa shu usul bilan doiraga ichki va tashqi ko‘pburchaklar chizib, π sonini 3<sup>10</sup>/<sub>71</sub> va 3<sup>1</sup>/<sub>7</sub> orasida ekanini isbotladi. Bu aslida limitga o‘tishning dastlabki namunasi edi.', 'Корни идеи предела уходят в Древнюю Грецию. Евдокс (IV в. до н. э.) изобрёл «метод исчерпывания», а Архимед (III в. до н. э.), вписывая в круг и описывая около него многоугольники, доказал, что π лежит между 3<sup>10</sup>/<sub>71</sub> и 3<sup>1</sup>/<sub>7</sub>. По сути это был первый пример предельного перехода.', 'The roots of the limit idea go back to ancient Greece. Eudoxus (4th century BC) invented the “method of exhaustion”, and Archimedes (3rd century BC), inscribing and circumscribing polygons around a circle, proved that π lies between 3<sup>10</sup>/<sub>71</sub> and 3<sup>1</sup>/<sub>7</sub>. In essence this was the first example of passing to a limit.'),
      L('XVII asrda Isaak Nyuton va Gotfrid Leybnits differensial hisobni yaratishdi, lekin «cheksiz kichik miqdor»ni aniq ta’riflay olmadilar. Irlandiyalik episkop Jorj Berkli 1734-yilda ularni masxara qilib, cheksiz kichiklarni «vafot etgan miqdorlarning arvohlari» deb atagan. Bu tanqid adolatli edi.', 'В XVII веке Исаак Ньютон и Готфрид Лейбниц создали дифференциальное исчисление, но не смогли строго определить «бесконечно малую величину». Ирландский епископ Джордж Беркли в 1734 году высмеял их, назвав бесконечно малые «призраками усопших величин». Эта критика была справедливой.', 'In the 17th century Isaac Newton and Gottfried Leibniz created differential calculus, but they could not define an “infinitely small quantity” rigorously. In 1734 the Irish bishop George Berkeley mocked them, calling infinitesimals “the ghosts of departed quantities”. The criticism was fair.'),
      L('Muammoni fransuz matematigi Ogyusten Koshi 1821-yilda «Analiz kursi» kitobida hal qildi: u limitni aniq ta’rifladi. Keyinroq nemis olimi Karl Veyershtrass uni hozir ishlatiladigan «ε–δ» tilida yozdi. Shu tariqa analiz mustahkam poydevorga ega bo‘ldi.', 'Проблему решил французский математик Огюстен Коши в 1821 году в «Курсе анализа»: он дал точное определение предела. Позже немецкий учёный Карл Вейерштрасс записал его на современном языке «ε–δ». Так анализ получил прочный фундамент.', 'The problem was solved by the French mathematician Augustin Cauchy in his 1821 “Course of Analysis”: he gave a precise definition of the limit. Later the German Karl Weierstrass wrote it in the modern “ε–δ” language. Thus analysis received a solid foundation.')
    ] },
    { kind: 'def', h: L('Funksiya limiti', 'Предел функции', 'The limit of a function'), p: [
      L('Agar x soni a ga yetarlicha yaqin (lekin a ga teng emas) bo‘lganda f(x) qiymatlari biror A soniga istalgancha yaqin bo‘lsa, A soni f(x) funksiyaning x → a dagi <b>limiti</b> deyiladi va <b>lim<sub>x→a</sub> f(x) = A</b> deb yoziladi.', 'Если при x, достаточно близких к a (но не равных a), значения f(x) сколь угодно близки к некоторому числу A, то A называется <b>пределом</b> функции f(x) при x → a и пишут <b>lim<sub>x→a</sub> f(x) = A</b>.', 'If, for x sufficiently close to a (but not equal to a), the values f(x) are arbitrarily close to some number A, then A is called the <b>limit</b> of f(x) as x → a, written <b>lim<sub>x→a</sub> f(x) = A</b>.'),
      L('Aniqroq (Koshi–Veyershtrass ta’rifi): har qanday ε &gt; 0 uchun shunday δ &gt; 0 topiladiki, 0 &lt; |x − a| &lt; δ bo‘lganda |f(x) − A| &lt; ε bajariladi. Ya’ni «natijaning aniqligini qanchalik talab qilsangiz, argumentni shunchalik yaqin olish yetarli».', 'Точнее (определение Коши–Вейерштрасса): для любого ε &gt; 0 найдётся δ &gt; 0 такое, что при 0 &lt; |x − a| &lt; δ выполняется |f(x) − A| &lt; ε. То есть «какую бы точность результата вы ни потребовали, достаточно взять аргумент достаточно близко».', 'More precisely (Cauchy–Weierstrass definition): for every ε &gt; 0 there is δ &gt; 0 such that 0 &lt; |x − a| &lt; δ implies |f(x) − A| &lt; ε. In words: “however much accuracy you demand of the result, it is enough to take the argument close enough”.'),
      L('Muhim jihat: limit f(a) ning qiymatiga bog‘liq emas, funksiya a nuqtada aniqlanmagan bo‘lishi ham mumkin. Masalan, f(x) = (x² − 1)/(x − 1) funksiyasi x = 1 da aniqlanmagan, ammo x ≠ 1 da f(x) = x + 1, shuning uchun lim<sub>x→1</sub> f(x) = 2.', 'Важно: предел не зависит от значения f(a), функция может быть даже не определена в точке a. Например, f(x) = (x² − 1)/(x − 1) не определена при x = 1, но при x ≠ 1 f(x) = x + 1, поэтому lim<sub>x→1</sub> f(x) = 2.', 'Important: the limit does not depend on the value f(a); the function may even be undefined at a. For example, f(x) = (x² − 1)/(x − 1) is undefined at x = 1, but for x ≠ 1 f(x) = x + 1, so lim<sub>x→1</sub> f(x) = 2.')
    ] },
    { kind: 'rule', h: L('Limitlar haqida asosiy teoremalar', 'Основные теоремы о пределах', 'Basic limit theorems'), p: [
      L('Agar lim f(x) = A va lim g(x) = B (x → a) mavjud bo‘lsa, quyidagilar o‘rinli:', 'Если существуют lim f(x) = A и lim g(x) = B (x → a), то справедливо:', 'If lim f(x) = A and lim g(x) = B (x → a) exist, then:')
    ], list: [
      L('lim (f ± g) = A ± B — yig‘indi limiti limitlar yig‘indisiga teng;', 'lim (f ± g) = A ± B — предел суммы равен сумме пределов;', 'lim (f ± g) = A ± B — the limit of a sum is the sum of the limits;'),
      L('lim (C·f) = C·A — o‘zgarmas ko‘paytuvchini limit belgisidan chiqarish mumkin;', 'lim (C·f) = C·A — постоянный множитель выносится за знак предела;', 'lim (C·f) = C·A — a constant factor can be taken out of the limit;'),
      L('lim (f·g) = A·B — ko‘paytma limiti;', 'lim (f·g) = A·B — предел произведения;', 'lim (f·g) = A·B — the limit of a product;'),
      L('lim (f/g) = A/B, agar B ≠ 0 bo‘lsa — bo‘linma limiti;', 'lim (f/g) = A/B, если B ≠ 0 — предел частного;', 'lim (f/g) = A/B, provided B ≠ 0 — the limit of a quotient;'),
      L('Ko‘phad va kasr-ratsional funksiyalar uchun (maxraj nolga aylanmasa) lim<sub>x→a</sub> f(x) = f(a): shunchaki x o‘rniga a qo‘yiladi. Bunday funksiyalar <b>uzluksiz</b> deyiladi.', 'Для многочленов и дробно-рациональных функций (если знаменатель не обращается в нуль) lim<sub>x→a</sub> f(x) = f(a): достаточно подставить a вместо x. Такие функции называются <b>непрерывными</b>.', 'For polynomials and rational functions (where the denominator is non-zero) lim<sub>x→a</sub> f(x) = f(a): just substitute a for x. Such functions are called <b>continuous</b>.')
    ], after: [
      L('Agar qo‘yganda 0/0 chiqsa — bu «aniqmaslik»: javob hali noma’lum. Kasrni soddalashtirish (ko‘paytuvchilarga ajratish, qisqartirish, qo‘shmaga ko‘paytirish) kerak.', 'Если при подстановке получается 0/0 — это «неопределённость»: ответ ещё неизвестен. Нужно упростить дробь (разложить на множители, сократить, умножить на сопряжённое).', 'If substitution gives 0/0, this is an “indeterminate form”: the answer is not yet known. Simplify the fraction (factor, cancel, multiply by the conjugate).')
    ] },
    { kind: 'steps', h: L('Orttirmalar nisbatining limitini topish', 'Как найти предел отношения приращений', 'Finding the limit of the ratio of increments'), list: [
      L('1) f(x₀ + Δx) ni hisoblang (qavslarni ochib).', '1) Вычислите f(x₀ + Δx) (раскрыв скобки).', '1) Compute f(x₀ + Δx) (expanding brackets).'),
      L('2) Δy = f(x₀ + Δx) − f(x₀) ni toping va soddalashtiring.', '2) Найдите Δy = f(x₀ + Δx) − f(x₀) и упростите.', '2) Find Δy = f(x₀ + Δx) − f(x₀) and simplify.'),
      L('3) Δy/Δx nisbatni tuzing va Δx ga qisqartiring (Δx ≠ 0).', '3) Составьте отношение Δy/Δx и сократите на Δx (Δx ≠ 0).', '3) Form Δy/Δx and cancel Δx (Δx ≠ 0).'),
      L('4) Δx → 0 da limitga o‘ting: qolgan ifodaga Δx = 0 ni qo‘ying.', '4) Перейдите к пределу при Δx → 0: подставьте Δx = 0 в оставшееся выражение.', '4) Pass to the limit as Δx → 0: put Δx = 0 into the remaining expression.'),
      L('5) Natijani ma’nosi bilan tekshiring: u kesuvchilarning «chegaraviy» qiyaligi, ya’ni oniy o‘zgarish tezligi.', '5) Проверьте результат по смыслу: это «предельный» наклон секущих, то есть мгновенная скорость изменения.', '5) Check the meaning: it is the “limiting” slope of the secants, i.e. the instantaneous rate of change.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('f(x) = x² uchun x₀ = 2, Δx = 0,1 bo‘lganda Δx, Δy va Δy/Δx ni toping.', 'Для f(x) = x² при x₀ = 2, Δx = 0,1 найдите Δy и Δy/Δx.', 'For f(x) = x² with x₀ = 2, Δx = 0.1, find Δy and Δy/Δx.'),
        s: L('f(2,1) = 4,41, f(2) = 4. Δy = 4,41 − 4 = 0,41. Δy/Δx = 0,41 : 0,1 = <b>4,1</b>. Δx kichraygan sari bu nisbat 4 ga yaqinlashadi (Δx = 0,01 da 4,01).', 'f(2,1) = 4,41, f(2) = 4. Δy = 4,41 − 4 = 0,41. Δy/Δx = 0,41 : 0,1 = <b>4,1</b>. При уменьшении Δx отношение приближается к 4 (при Δx = 0,01 получаем 4,01).', 'f(2.1) = 4.41, f(2) = 4. Δy = 4.41 − 4 = 0.41. Δy/Δx = 0.41 / 0.1 = <b>4.1</b>. As Δx shrinks the ratio approaches 4 (for Δx = 0.01 it is 4.01).') },
      { q: L('f(x) = 3x² − x uchun Δy/Δx ni toping va Δx → 0 dagi limitini hisoblang.', 'Для f(x) = 3x² − x найдите Δy/Δx и его предел при Δx → 0.', 'For f(x) = 3x² − x find Δy/Δx and its limit as Δx → 0.'),
        s: L('f(x₀ + Δx) = 3x₀² + 6x₀Δx + 3Δx² − x₀ − Δx. Δy = 6x₀Δx + 3Δx² − Δx. Δy/Δx = 6x₀ − 1 + 3Δx → <b>6x₀ − 1</b>.', 'f(x₀ + Δx) = 3x₀² + 6x₀Δx + 3Δx² − x₀ − Δx. Δy = 6x₀Δx + 3Δx² − Δx. Δy/Δx = 6x₀ − 1 + 3Δx → <b>6x₀ − 1</b>.', 'f(x₀ + Δx) = 3x₀² + 6x₀Δx + 3Δx² − x₀ − Δx. Δy = 6x₀Δx + 3Δx² − Δx. Δy/Δx = 6x₀ − 1 + 3Δx → <b>6x₀ − 1</b>.') },
      { q: L('lim<sub>x→3</sub> (x² − 9)/(x − 3) ni hisoblang.', 'Вычислите lim<sub>x→3</sub> (x² − 9)/(x − 3).', 'Compute lim<sub>x→3</sub> (x² − 9)/(x − 3).'),
        s: L('Qo‘yish 0/0 beradi. x² − 9 = (x − 3)(x + 3), x ≠ 3 da qisqartiramiz: x + 3. Limit 3 + 3 = <b>6</b>.', 'Подстановка даёт 0/0. x² − 9 = (x − 3)(x + 3), при x ≠ 3 сокращаем: x + 3. Предел 3 + 3 = <b>6</b>.', 'Substitution gives 0/0. x² − 9 = (x − 3)(x + 3); for x ≠ 3 cancel to get x + 3. The limit is 3 + 3 = <b>6</b>.') },
      { q: L('lim<sub>x→0</sub> (√(x + 4) − 2)/x ni hisoblang.', 'Вычислите lim<sub>x→0</sub> (√(x + 4) − 2)/x.', 'Compute lim<sub>x→0</sub> (√(x + 4) − 2)/x.'),
        s: L('Surat va maxrajni √(x + 4) + 2 ga ko‘paytiramiz: (x + 4 − 4)/(x(√(x + 4) + 2)) = 1/(√(x + 4) + 2). x = 0 da 1/(2 + 2) = <b>1/4</b>.', 'Умножим числитель и знаменатель на √(x + 4) + 2: (x + 4 − 4)/(x(√(x + 4) + 2)) = 1/(√(x + 4) + 2). При x = 0: 1/(2 + 2) = <b>1/4</b>.', 'Multiply top and bottom by √(x + 4) + 2: (x + 4 − 4)/(x(√(x + 4) + 2)) = 1/(√(x + 4) + 2). At x = 0: 1/(2 + 2) = <b>1/4</b>.') }
    ] },
    { kind: 'table', h: L('Δx kichrayganda nima bo‘ladi?', 'Что происходит при уменьшении Δx?', 'What happens as Δx shrinks?'), p: [
      L('f(x) = x³, x₀ = 1 uchun orttirmalar nisbati jadvali. Δy/Δx = 3 + 3Δx + Δx² ekanini tekshirish oson.', 'Таблица отношений приращений для f(x) = x³, x₀ = 1. Легко проверить, что Δy/Δx = 3 + 3Δx + Δx².', 'Table of ratios for f(x) = x³, x₀ = 1. It is easy to check that Δy/Δx = 3 + 3Δx + Δx².')
    ], table: { head: [L('Δx', 'Δx', 'Δx'), L('Δy', 'Δy', 'Δy'), L('Δy/Δx', 'Δy/Δx', 'Δy/Δx')], rows: [
      ['1', '7', '7'], ['0,1', '0,331', '3,31'], ['0,01', '0,030301', '3,0301'], ['0,001', '0,003003001', '3,003001'], ['−0,01', '−0,029701', '2,9701']
    ] }, after: [
      L('Ikki tomondan (Δx &gt; 0 va Δx &lt; 0) ham nisbat 3 ga yaqinlashmoqda. Demak, limit 3 ga teng — bu x³ funksiyasining x = 1 nuqtadagi oniy o‘zgarish tezligi.', 'С обеих сторон (Δx &gt; 0 и Δx &lt; 0) отношение приближается к 3. Значит, предел равен 3 — это мгновенная скорость изменения функции x³ в точке x = 1.', 'From both sides (Δx &gt; 0 and Δx &lt; 0) the ratio approaches 3. So the limit is 3 — the instantaneous rate of change of x³ at x = 1.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Δy = f(Δx) deb yozish.</b> Noto‘g‘ri: Δy = f(x₀ + Δx) − f(x₀). Masalan, x² uchun Δy ≠ Δx², balki 2x₀Δx + Δx².', '<b>Писать Δy = f(Δx).</b> Неверно: Δy = f(x₀ + Δx) − f(x₀). Например, для x² Δy ≠ Δx², а 2x₀Δx + Δx².', '<b>Writing Δy = f(Δx).</b> Wrong: Δy = f(x₀ + Δx) − f(x₀). For x², Δy ≠ Δx² but 2x₀Δx + Δx².'),
      L('<b>0/0 = 1 yoki 0/0 = 0 deb hisoblash.</b> 0/0 — son emas, aniqmaslik. Avval ifodani soddalashtirish kerak.', '<b>Считать 0/0 = 1 или 0/0 = 0.</b> 0/0 — не число, а неопределённость. Сначала нужно упростить выражение.', '<b>Treating 0/0 as 1 or 0.</b> 0/0 is not a number but an indeterminate form. Simplify first.'),
      L('<b>Limitni f(a) bilan aralashtirish.</b> Funksiya a da aniqlanmagan bo‘lsa ham limit mavjud bo‘lishi mumkin.', '<b>Путать предел с f(a).</b> Предел может существовать, даже если функция в a не определена.', '<b>Confusing the limit with f(a).</b> A limit can exist even if the function is undefined at a.'),
      L('<b>(a + b)² ni a² + b² deb ochish.</b> f(x₀ + Δx) ni hisoblashda 2x₀Δx hadi yo‘qolib qoladi — butun natija buziladi.', '<b>Раскрывать (a + b)² как a² + b².</b> При вычислении f(x₀ + Δx) теряется член 2x₀Δx — и весь результат неверен.', '<b>Expanding (a + b)² as a² + b².</b> The term 2x₀Δx gets lost when computing f(x₀ + Δx), ruining the result.'),
      L('<b>Δx ga qisqartirmasdan Δx = 0 qo‘yish.</b> Avval qisqartirish, keyin limitga o‘tish kerak.', '<b>Подставлять Δx = 0, не сократив.</b> Сначала сокращение, затем предельный переход.', '<b>Setting Δx = 0 before cancelling.</b> Cancel first, then pass to the limit.')
    ] },
    { kind: 'life', h: L('Hayotda orttirmalar va limitlar', 'Приращения и пределы в жизни', 'Increments and limits in life'), p: [
      L('<b>Transport:</b> Toshkentdan Samarqandgacha 300 km ni 4 soatda bosgan poyezdning o‘rtacha tezligi 75 km/soat — bu Δs/Δt. Ammo radar bilan o‘lchangan tezlik — juda kichik vaqt oralig‘idagi nisbat, ya’ni limitga yaqin qiymat.', '<b>Транспорт:</b> поезд, прошедший 300 км от Ташкента до Самарканда за 4 часа, имеет среднюю скорость 75 км/ч — это Δs/Δt. А скорость, измеренная радаром, — отношение на очень малом промежутке времени, то есть значение, близкое к пределу.', '<b>Transport:</b> a train covering the 300 km from Tashkent to Samarkand in 4 hours has an average speed of 75 km/h — that is Δs/Δt. A radar speed, however, is the ratio over a tiny time interval, i.e. a value close to the limit.'),
      L('<b>Iqtisod:</b> narx bir oyda 12 000 so‘mdan 12 600 so‘mga oshsa, Δ = 600 so‘m, nisbiy o‘zgarish 5 %. Inflyatsiya, aksiyalar kursi, valyuta — hammasi orttirmalar tilida tasvirlanadi.', '<b>Экономика:</b> если цена за месяц выросла с 12 000 до 12 600 сумов, Δ = 600 сумов, относительное изменение 5 %. Инфляция, курс акций, валюты — всё описывается языком приращений.', '<b>Economics:</b> if a price rises from 12,000 to 12,600 sum in a month, Δ = 600 sum, a relative change of 5 %. Inflation, share prices, currency rates are all described in the language of increments.'),
      L('<b>Tibbiyot va fizika:</b> harorat grafigida Δt/Δvaqt — isitma qanchalik tez ko‘tarilayotganini ko‘rsatadi. Kompyuter grafikasi va o‘yinlarda harakat kichik Δt qadamlar bilan hisoblanadi — bu limit g‘oyasining amaliy ko‘rinishi.', '<b>Медицина и физика:</b> на графике температуры Δt/Δвремя показывает, как быстро растёт жар. В компьютерной графике и играх движение рассчитывается малыми шагами Δt — это практическое воплощение идеи предела.', '<b>Medicine and physics:</b> on a temperature chart, Δtemperature/Δtime shows how fast a fever rises. In computer graphics and games, motion is computed in small steps Δt — a practical form of the limit idea.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('«Limit» lotincha <i>limes</i> — «chegara» so‘zidan. lim belgisini 1786-yilda shveytsariyalik Simon Lhuilye kiritgan, «→» strelkasi esa XX asr boshida keng tarqaldi.', '«Предел» по-латыни <i>limes</i> — «граница». Знак lim ввёл швейцарец Симон Люилье в 1786 году, стрелка «→» распространилась в начале XX века.', '“Limit” comes from the Latin <i>limes</i>, “boundary”. The symbol lim was introduced by the Swiss Simon Lhuilier in 1786; the arrow “→” spread in the early 20th century.'),
      L('Mashhur «ajoyib limit»: lim<sub>x→0</sub> (sin x)/x = 1 (x radianda). Shu sababli kichik burchaklarda sin x ≈ x.', 'Знаменитый «замечательный предел»: lim<sub>x→0</sub> (sin x)/x = 1 (x в радианах). Поэтому при малых углах sin x ≈ x.', 'A famous “remarkable limit”: lim<sub>x→0</sub> (sin x)/x = 1 (x in radians). That is why sin x ≈ x for small angles.'),
      L('e ≈ 2,71828 soni ham limit: (1 + 1/n)<sup>n</sup> ning n → ∞ dagi limiti. Uni bankdagi murakkab foiz masalasida Yakob Bernulli 1683-yilda kashf etgan.', 'Число e ≈ 2,71828 — тоже предел: (1 + 1/n)<sup>n</sup> при n → ∞. Его открыл Якоб Бернулли в 1683 году в задаче о сложных процентах.', 'The number e ≈ 2.71828 is also a limit: (1 + 1/n)<sup>n</sup> as n → ∞. Jacob Bernoulli discovered it in 1683 in a compound-interest problem.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Δx = x − x₀ — argument orttirmasi, Δy = f(x₀ + Δx) − f(x₀) — funksiya orttirmasi.', 'Δx = x − x₀ — приращение аргумента, Δy = f(x₀ + Δx) − f(x₀) — приращение функции.', 'Δx = x − x₀ is the increment of the argument; Δy = f(x₀ + Δx) − f(x₀) that of the function.'),
      L('Δy/Δx — o‘rtacha o‘zgarish tezligi, kesuvchining qiyaligi.', 'Δy/Δx — средняя скорость изменения, наклон секущей.', 'Δy/Δx is the average rate of change, the slope of a secant.'),
      L('lim<sub>x→a</sub> f(x) = A — x a ga yaqinlashganda f(x) A ga yaqinlashadi; f(a) ning qiymati muhim emas.', 'lim<sub>x→a</sub> f(x) = A — при x → a значения f(x) приближаются к A; значение f(a) не важно.', 'lim<sub>x→a</sub> f(x) = A means f(x) approaches A as x approaches a; the value f(a) does not matter.'),
      L('Limitlar yig‘indi, ko‘paytma va bo‘linmaga mos keladi (maxraj limiti 0 bo‘lmasa).', 'Пределы согласованы с суммой, произведением и частным (если предел знаменателя не 0).', 'Limits respect sums, products and quotients (if the denominator’s limit is not 0).'),
      L('0/0 aniqmasligi soddalashtirish orqali ochiladi; x² uchun Δy/Δx = 2x₀ + Δx → 2x₀.', 'Неопределённость 0/0 раскрывается упрощением; для x² Δy/Δx = 2x₀ + Δx → 2x₀.', 'The form 0/0 is resolved by simplifying; for x², Δy/Δx = 2x₀ + Δx → 2x₀.')
    ] }
  ] });

  // ---------- t2. Hosila, uning geometrik va fizik ma’nosi ----------
  T.add(P, 't2', { sections: [
    { kind: 'intro', h: L('Bir lahzadagi tezlik', 'Скорость в одно мгновение', 'Speed at a single instant'), p: [
      L('Tosh minoradan tashlandi. Galiley tajribalaridan ma’lumki, t sekundda u taxminan s(t) = 5t² metr yo‘l bosadi (g ≈ 10 m/s²). 2-sekund oxirida toshning tezligi qancha? O‘rtacha tezlik bilan javob berib bo‘lmaydi: tosh har lahzada tezlashib boradi.', 'Камень бросили с башни. Из опытов Галилея известно, что за t секунд он проходит примерно s(t) = 5t² метров (g ≈ 10 м/с²). Какова скорость камня в конце 2-й секунды? Средней скоростью тут не ответишь: камень всё время ускоряется.', 'A stone is dropped from a tower. From Galileo’s experiments we know that in t seconds it falls about s(t) = 5t² metres (g ≈ 10 m/s²). What is its speed at the end of the 2nd second? An average speed will not do: the stone keeps accelerating.'),
      L('[2; 2 + Δt] oraliqda o‘rtacha tezlik: Δs/Δt = (5(2 + Δt)² − 20)/Δt = 20 + 5Δt. Δt → 0 da bu 20 ga intiladi. Demak, oniy tezlik 20 m/s. Biz hozirgina hosilani hisobladik! Hosila — oldingi mavzudagi orttirmalar nisbati limitining maxsus nomi.', 'Средняя скорость на [2; 2 + Δt]: Δs/Δt = (5(2 + Δt)² − 20)/Δt = 20 + 5Δt. При Δt → 0 это стремится к 20. Значит, мгновенная скорость 20 м/с. Мы только что вычислили производную! Производная — специальное название предела отношения приращений из прошлой темы.', 'The average speed on [2; 2 + Δt] is Δs/Δt = (5(2 + Δt)² − 20)/Δt = 20 + 5Δt. As Δt → 0 this tends to 20. So the instantaneous speed is 20 m/s. We have just computed a derivative! The derivative is a special name for the limit of the ratio of increments from the previous topic.'),
      L('Bu mavzuda hosilaning ta’rifini, uning ikki asosiy ma’nosini — geometrik (urinma qiyaligi) va fizik (oniy tezlik) — hamda eng sodda funksiyalarning hosilalarini ta’rif bo‘yicha topishni o‘rganamiz.', 'В этой теме мы изучим определение производной, два её главных смысла — геометрический (наклон касательной) и физический (мгновенная скорость) — и научимся находить по определению производные простейших функций.', 'In this topic we study the definition of the derivative, its two main meanings — geometric (slope of the tangent) and physical (instantaneous speed) — and learn to find derivatives of the simplest functions from the definition.')
    ] },
    { kind: 'def', h: L('Hosila ta’rifi', 'Определение производной', 'Definition of the derivative'), p: [
      L('y = f(x) funksiyaning x₀ nuqtadagi <b>hosilasi</b> deb, argument orttirmasi nolga intilganda funksiya orttirmasining argument orttirmasiga nisbatining limitiga aytiladi (agar bu limit mavjud bo‘lsa):', '<b>Производной</b> функции y = f(x) в точке x₀ называется предел отношения приращения функции к приращению аргумента, когда приращение аргумента стремится к нулю (если этот предел существует):', 'The <b>derivative</b> of y = f(x) at x₀ is the limit of the ratio of the increment of the function to the increment of the argument as the latter tends to zero (if this limit exists):'),
      L('<b>f′(x₀) = lim<sub>Δx→0</sub> (f(x₀ + Δx) − f(x₀))/Δx.</b>', '<b>f′(x₀) = lim<sub>Δx→0</sub> (f(x₀ + Δx) − f(x₀))/Δx.</b>', '<b>f′(x₀) = lim<sub>Δx→0</sub> (f(x₀ + Δx) − f(x₀))/Δx.</b>'),
      L('Hosilasi mavjud bo‘lgan funksiya shu nuqtada <b>differensiallanuvchi</b> deyiladi. Hosilani topish amali <b>differensiallash</b> deyiladi. Agar funksiya oraliqning har bir nuqtasida differensiallanuvchi bo‘lsa, har bir x ga f′(x) sonini mos qo‘yib, yangi funksiya — <b>hosila funksiya</b> hosil bo‘ladi.', 'Функция, имеющая производную, называется <b>дифференцируемой</b> в этой точке. Нахождение производной называется <b>дифференцированием</b>. Если функция дифференцируема в каждой точке промежутка, то, сопоставив каждому x число f′(x), получим новую функцию — <b>производную функцию</b>.', 'A function that has a derivative at a point is <b>differentiable</b> there. Finding the derivative is called <b>differentiation</b>. If a function is differentiable at every point of an interval, assigning f′(x) to each x gives a new function — the <b>derivative function</b>.'),
      L('Belgilashlar: f′(x) (Lagranj), dy/dx (Leybnits), ẏ (Nyuton, asosan fizikada vaqt bo‘yicha hosila uchun).', 'Обозначения: f′(x) (Лагранж), dy/dx (Лейбниц), ẏ (Ньютон, в основном в физике для производной по времени).', 'Notation: f′(x) (Lagrange), dy/dx (Leibniz), ẏ (Newton, mainly in physics for time derivatives).')
    ] },
    { kind: 'history', h: L('Nyuton, Leybnits va ustuvorlik bahsi', 'Ньютон, Лейбниц и спор о приоритете', 'Newton, Leibniz and the priority dispute'), p: [
      L('Urinmalarni topish usullarini Per Ferma 1630-yillardayoq ishlab chiqqan edi: u funksiya qiymatlarini yaqin nuqtalarda «tenglashtirib», maksimum va urinmani topardi. Nyutonning ustozi Isaak Barrou ham urinma va yuza masalalarining bog‘liqligini sezgan.', 'Методы нахождения касательных разработал ещё Пьер Ферма в 1630-х годах: он «приравнивал» значения функции в близких точках и находил максимум и касательную. Учитель Ньютона Исаак Барроу тоже заметил связь задач о касательной и о площади.', 'Pierre de Fermat had developed methods for finding tangents as early as the 1630s: he “equated” function values at nearby points to find maxima and tangents. Newton’s teacher Isaac Barrow also noticed the link between tangent and area problems.'),
      L('Isaak Nyuton 1665–1666-yillarda, Kembrijdagi universitet vabo sababli yopilgan paytda, «flyuksiyalar usuli»ni yaratdi: o‘zgaruvchi miqdorni «flyuyenta», uning tezligini «flyuksiya» deb atadi. Ammo bu ishini uzoq vaqt chop etmadi. Gotfrid Vilgelm Leybnits esa mustaqil ravishda 1675-yilda o‘z hisobini yaratib, 1684-yilda «Nova Methodus» maqolasida e’lon qildi. dy/dx va ∫ belgilari aynan Leybnitsniki.', 'Исаак Ньютон в 1665–1666 годах, когда Кембриджский университет закрыли из-за чумы, создал «метод флюксий»: переменную величину он называл «флюентой», её скорость — «флюксией». Но эту работу он долго не публиковал. Готфрид Вильгельм Лейбниц независимо создал своё исчисление в 1675 году и опубликовал его в 1684 году в статье «Nova Methodus». Обозначения dy/dx и ∫ — именно лейбницевские.', 'Isaac Newton created his “method of fluxions” in 1665–1666, when Cambridge University was closed by the plague: he called a changing quantity a “fluent” and its rate a “fluxion”. But he did not publish it for a long time. Gottfried Wilhelm Leibniz independently created his calculus in 1675 and published it in 1684 in the paper “Nova Methodus”. The symbols dy/dx and ∫ are Leibniz’s.'),
      L('Kim birinchi ekanligi haqidagi bahs Angliya va qit’a olimlarini o‘nlab yillarga ajratib qo‘ydi. Bugun tarixchilar ikkalasi ham mustaqil kashf qilgan deb hisoblaydi. «Hosila» atamasi va f′ belgisini 1797-yilda Jozef Lui Lagranj kiritgan.', 'Спор о приоритете на десятилетия разделил учёных Англии и континента. Сегодня историки считают, что оба открыли исчисление независимо. Термин «производная» и обозначение f′ ввёл Жозеф Луи Лагранж в 1797 году.', 'The priority dispute divided English and continental scholars for decades. Today historians agree that both discovered calculus independently. The term “derivative” and the notation f′ were introduced by Joseph-Louis Lagrange in 1797.')
    ] },
    { kind: 'rule', h: L('Geometrik ma’no: urinma qiyaligi', 'Геометрический смысл: наклон касательной', 'Geometric meaning: slope of the tangent'), p: [
      L('Grafikda A(x₀; f(x₀)) va B(x₀ + Δx; f(x₀ + Δx)) nuqtalarni olamiz. AB kesuvchining burchak koeffitsiyenti k<sub>AB</sub> = Δy/Δx. Endi B nuqtani grafik bo‘ylab A ga yaqinlashtiramiz (Δx → 0). Kesuvchi A atrofida aylanib, chegaraviy holatga — <b>urinma</b>ga intiladi.', 'Возьмём на графике точки A(x₀; f(x₀)) и B(x₀ + Δx; f(x₀ + Δx)). Угловой коэффициент секущей AB: k<sub>AB</sub> = Δy/Δx. Будем приближать B к A по графику (Δx → 0). Секущая, поворачиваясь вокруг A, стремится к предельному положению — <b>касательной</b>.', 'Take the points A(x₀; f(x₀)) and B(x₀ + Δx; f(x₀ + Δx)) on the graph. The slope of the secant AB is k<sub>AB</sub> = Δy/Δx. Now move B along the graph towards A (Δx → 0). The secant turns about A and tends to a limiting position — the <b>tangent</b>.'),
      L('Shuning uchun: <b>f′(x₀) = k = tg α</b>, bu yerda α — urinmaning Ox o‘qining musbat yo‘nalishi bilan hosil qilgan burchagi. f′(x₀) &gt; 0 bo‘lsa, urinma «yuqoriga» ko‘tariladi (α o‘tkir), f′(x₀) &lt; 0 bo‘lsa — pastga tushadi (α o‘tmas), f′(x₀) = 0 bo‘lsa — urinma gorizontal.', 'Поэтому: <b>f′(x₀) = k = tg α</b>, где α — угол касательной с положительным направлением оси Ox. Если f′(x₀) &gt; 0, касательная «поднимается» (α острый), если f′(x₀) &lt; 0 — опускается (α тупой), если f′(x₀) = 0 — касательная горизонтальна.', 'Hence <b>f′(x₀) = k = tan α</b>, where α is the angle between the tangent and the positive direction of the Ox axis. If f′(x₀) &gt; 0 the tangent rises (α acute), if f′(x₀) &lt; 0 it falls (α obtuse), if f′(x₀) = 0 the tangent is horizontal.'),
      L('Masalan, y = x² uchun x₀ = 1 da f′(1) = 2, ya’ni urinma Ox bilan tg α = 2, α ≈ 63,4° burchak hosil qiladi.', 'Например, для y = x² при x₀ = 1 f′(1) = 2, т. е. касательная образует с Ox угол с tg α = 2, α ≈ 63,4°.', 'For example, for y = x² at x₀ = 1, f′(1) = 2, so the tangent makes an angle with tan α = 2, α ≈ 63.4°, with Ox.')
    ] },
    { kind: 'rule', h: L('Fizik ma’no: oniy tezlik va tezlanish', 'Физический смысл: мгновенная скорость и ускорение', 'Physical meaning: instantaneous velocity and acceleration'), p: [
      L('Agar moddiy nuqta to‘g‘ri chiziq bo‘ylab harakatlanib, t vaqtda s(t) koordinatada bo‘lsa, [t; t + Δt] oraliqdagi o‘rtacha tezlik Δs/Δt. Uning Δt → 0 dagi limiti — <b>oniy tezlik</b>: <b>v(t) = s′(t)</b>.', 'Если материальная точка движется по прямой и в момент t имеет координату s(t), то средняя скорость на [t; t + Δt] равна Δs/Δt. Её предел при Δt → 0 — <b>мгновенная скорость</b>: <b>v(t) = s′(t)</b>.', 'If a particle moves along a line and has coordinate s(t) at time t, its average velocity on [t; t + Δt] is Δs/Δt. Its limit as Δt → 0 is the <b>instantaneous velocity</b>: <b>v(t) = s′(t)</b>.'),
      L('Xuddi shunday, tezlikning o‘zgarish tezligi — <b>tezlanish</b>: <b>a(t) = v′(t)</b>. Umuman, har qanday kattalikning vaqt bo‘yicha hosilasi uning o‘zgarish tezligidir: zaryaddan — tok kuchi (I = q′), ish bajarilishidan — quvvat (N = A′), aholi sonidan — o‘sish sur’ati.', 'Аналогично скорость изменения скорости — <b>ускорение</b>: <b>a(t) = v′(t)</b>. Вообще производная любой величины по времени — это скорость её изменения: от заряда — сила тока (I = q′), от работы — мощность (N = A′), от численности населения — темп роста.', 'Similarly, the rate of change of velocity is the <b>acceleration</b>: <b>a(t) = v′(t)</b>. In general, the time derivative of any quantity is its rate of change: from charge — current (I = q′), from work — power (P = A′), from population — growth rate.'),
      L('Hosilaning birligi: [y birligi] / [x birligi]. Masalan, metrning sekund bo‘yicha hosilasi — m/s, so‘mning kilogramm bo‘yicha — so‘m/kg.', 'Единица производной: [единица y] / [единица x]. Например, производная метров по секундам — м/с, сумов по килограммам — сум/кг.', 'The unit of a derivative is [unit of y] / [unit of x]: metres per second give m/s, sum per kilogram give sum/kg.')
    ] },
    { kind: 'steps', h: L('Hosilani ta’rif bo‘yicha topish', 'Нахождение производной по определению', 'Finding a derivative from the definition'), list: [
      L('1) x ga Δx orttirma bering va f(x + Δx) ni yozing.', '1) Дайте x приращение Δx и запишите f(x + Δx).', '1) Give x an increment Δx and write f(x + Δx).'),
      L('2) Δy = f(x + Δx) − f(x) ni soddalashtiring.', '2) Упростите Δy = f(x + Δx) − f(x).', '2) Simplify Δy = f(x + Δx) − f(x).'),
      L('3) Δy/Δx nisbatni tuzib, Δx ga qisqartiring.', '3) Составьте Δy/Δx и сократите на Δx.', '3) Form Δy/Δx and cancel Δx.'),
      L('4) Δx → 0 da limitni toping — bu f′(x).', '4) Найдите предел при Δx → 0 — это f′(x).', '4) Find the limit as Δx → 0 — that is f′(x).'),
      L('5) Kerakli nuqtada qiymatini hisoblang va ma’nosini izohlang (qiyalik yoki tezlik).', '5) Вычислите значение в нужной точке и истолкуйте его (наклон или скорость).', '5) Evaluate at the required point and interpret it (slope or speed).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Ta’rif bo‘yicha (x³)′ ni toping.', 'Найдите (x³)′ по определению.', 'Find (x³)′ from the definition.'),
        s: L('(x + Δx)³ − x³ = 3x²Δx + 3xΔx² + Δx³. Δy/Δx = 3x² + 3xΔx + Δx² → <b>3x²</b>.', '(x + Δx)³ − x³ = 3x²Δx + 3xΔx² + Δx³. Δy/Δx = 3x² + 3xΔx + Δx² → <b>3x²</b>.', '(x + Δx)³ − x³ = 3x²Δx + 3xΔx² + Δx³. Δy/Δx = 3x² + 3xΔx + Δx² → <b>3x²</b>.') },
      { q: L('Ta’rif bo‘yicha (1/x)′ ni toping (x ≠ 0).', 'Найдите (1/x)′ по определению (x ≠ 0).', 'Find (1/x)′ from the definition (x ≠ 0).'),
        s: L('Δy = 1/(x + Δx) − 1/x = −Δx/(x(x + Δx)). Δy/Δx = −1/(x(x + Δx)) → <b>−1/x²</b>.', 'Δy = 1/(x + Δx) − 1/x = −Δx/(x(x + Δx)). Δy/Δx = −1/(x(x + Δx)) → <b>−1/x²</b>.', 'Δy = 1/(x + Δx) − 1/x = −Δx/(x(x + Δx)). Δy/Δx = −1/(x(x + Δx)) → <b>−1/x²</b>.') },
      { q: L('Ta’rif bo‘yicha (√x)′ ni toping (x &gt; 0).', 'Найдите (√x)′ по определению (x &gt; 0).', 'Find (√x)′ from the definition (x &gt; 0).'),
        s: L('Δy/Δx = (√(x + Δx) − √x)/Δx. Qo‘shmaga ko‘paytiramiz: = 1/(√(x + Δx) + √x) → <b>1/(2√x)</b>.', 'Δy/Δx = (√(x + Δx) − √x)/Δx. Умножим на сопряжённое: = 1/(√(x + Δx) + √x) → <b>1/(2√x)</b>.', 'Δy/Δx = (√(x + Δx) − √x)/Δx. Multiply by the conjugate: = 1/(√(x + Δx) + √x) → <b>1/(2√x)</b>.') },
      { q: L('Nuqta s(t) = t² + 3t (m) qonun bo‘yicha harakatlanadi. t = 4 s dagi tezlikni toping.', 'Точка движется по закону s(t) = t² + 3t (м). Найдите скорость при t = 4 с.', 'A point moves by s(t) = t² + 3t (m). Find its velocity at t = 4 s.'),
        s: L('Δs/Δt = 2t + 3 + Δt → v(t) = 2t + 3. v(4) = 8 + 3 = <b>11 m/s</b>.', 'Δs/Δt = 2t + 3 + Δt → v(t) = 2t + 3. v(4) = 8 + 3 = <b>11 м/с</b>.', 'Δs/Δt = 2t + 3 + Δt → v(t) = 2t + 3. v(4) = 8 + 3 = <b>11 m/s</b>.') }
    ] },
    { kind: 'table', h: L('Ta’rifdan olingan hosilalar', 'Производные, полученные по определению', 'Derivatives obtained from the definition'), table: { head: [L('f(x)', 'f(x)', 'f(x)'), L('f′(x)', 'f′(x)', 'f′(x)'), L('Izoh', 'Комментарий', 'Comment')], rows: [
      ['C', '0', L('o‘zgarmas o‘zgarmaydi — tezligi nol', 'константа не меняется — скорость ноль', 'a constant does not change — zero rate')],
      ['kx + b', 'k', L('to‘g‘ri chiziqning qiyaligi hamma joyda bir xil', 'наклон прямой везде одинаков', 'a line has the same slope everywhere')],
      ['x²', '2x', L('parabola tobora tikroq', 'парабола всё круче', 'the parabola gets steeper')],
      ['x³', '3x²', L('x = 0 da gorizontal urinma', 'при x = 0 горизонтальная касательная', 'horizontal tangent at x = 0')],
      ['1/x', '−1/x²', L('giperbola doim kamayadi', 'гипербола всё время убывает', 'the hyperbola always decreases')],
      ['√x', '1/(2√x)', L('x = 0 da urinma vertikal', 'при x = 0 касательная вертикальна', 'vertical tangent at x = 0')]
    ] }, after: [
      L('Qonuniyatni ko‘ryapsizmi? x², x³, x<sup>−1</sup>, x<sup>1/2</sup> uchun (xⁿ)′ = nxⁿ⁻¹. Bu umumiy formulani keyingi mavzuda qo‘llaymiz.', 'Видите закономерность? Для x², x³, x<sup>−1</sup>, x<sup>1/2</sup> выполняется (xⁿ)′ = nxⁿ⁻¹. Эту общую формулу мы применим в следующей теме.', 'See the pattern? For x², x³, x<sup>−1</sup>, x<sup>1/2</sup> we have (xⁿ)′ = nxⁿ⁻¹. We will use this general formula in the next topic.')
    ] },
    { kind: 'fact', h: L('Differensiallanuvchanlik va uzluksizlik', 'Дифференцируемость и непрерывность', 'Differentiability and continuity'), p: [
      L('<b>Teorema.</b> Agar f funksiya x₀ nuqtada differensiallanuvchi bo‘lsa, u shu nuqtada uzluksiz. <i>Isbot g‘oyasi:</i> Δy = (Δy/Δx)·Δx → f′(x₀)·0 = 0, ya’ni kichik Δx da Δy ham kichik.', '<b>Теорема.</b> Если функция f дифференцируема в точке x₀, то она непрерывна в этой точке. <i>Идея доказательства:</i> Δy = (Δy/Δx)·Δx → f′(x₀)·0 = 0, т. е. при малом Δx и Δy мало.', '<b>Theorem.</b> If f is differentiable at x₀, it is continuous there. <i>Proof idea:</i> Δy = (Δy/Δx)·Δx → f′(x₀)·0 = 0, so a small Δx gives a small Δy.'),
      L('Teskarisi to‘g‘ri emas! y = |x| funksiyasi x = 0 da uzluksiz, ammo Δx &gt; 0 da Δy/Δx = 1, Δx &lt; 0 da −1. Yagona limit yo‘q, grafikda «sinish» (burchak) bor, urinma o‘tkazib bo‘lmaydi.', 'Обратное неверно! Функция y = |x| непрерывна при x = 0, но при Δx &gt; 0 Δy/Δx = 1, при Δx &lt; 0 равно −1. Единого предела нет, на графике «излом», касательную провести нельзя.', 'The converse is false! y = |x| is continuous at x = 0, but Δy/Δx = 1 for Δx &gt; 0 and −1 for Δx &lt; 0. There is no single limit, the graph has a “corner” and no tangent.'),
      L('1872-yilda Veyershtrass hamma joyda uzluksiz, lekin hech bir nuqtada hosilaga ega bo‘lmagan funksiya qurib, matematiklarni hayratda qoldirgan. Fraktallar va birja grafiklari shunga o‘xshaydi.', 'В 1872 году Вейерштрасс построил функцию, непрерывную всюду, но ни в одной точке не имеющую производной, и поразил математиков. Похожи на неё фракталы и биржевые графики.', 'In 1872 Weierstrass astonished mathematicians by constructing a function continuous everywhere but differentiable nowhere. Fractals and stock-market charts look like it.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>f′(x₀) ni f(x₀) bilan aralashtirish.</b> f(x₀) — nuqtaning balandligi, f′(x₀) — grafikning shu yerdagi tikligi. y = x² da x = 0: f = 0, f′ = 0; x = 1: f = 1, f′ = 2.', '<b>Путать f′(x₀) и f(x₀).</b> f(x₀) — высота точки, f′(x₀) — крутизна графика в ней. Для y = x² при x = 0: f = 0, f′ = 0; при x = 1: f = 1, f′ = 2.', '<b>Confusing f′(x₀) with f(x₀).</b> f(x₀) is the height of the point, f′(x₀) is the steepness there. For y = x²: at x = 0, f = 0, f′ = 0; at x = 1, f = 1, f′ = 2.'),
      L('<b>O‘rtacha va oniy tezlikni chalkashtirish.</b> s(t) = 5t² da [0; 2] dagi o‘rtacha tezlik 10 m/s, t = 2 dagi oniy tezlik esa 20 m/s.', '<b>Путать среднюю и мгновенную скорость.</b> При s(t) = 5t² средняя скорость на [0; 2] — 10 м/с, а мгновенная при t = 2 — 20 м/с.', '<b>Mixing average and instantaneous speed.</b> For s(t) = 5t² the average speed on [0; 2] is 10 m/s, but the instantaneous speed at t = 2 is 20 m/s.'),
      L('<b>Uzluksiz funksiya albatta differensiallanuvchi deb o‘ylash.</b> |x| misoli buni rad etadi.', '<b>Думать, что непрерывная функция обязательно дифференцируема.</b> Пример |x| опровергает это.', '<b>Thinking a continuous function must be differentiable.</b> The example |x| refutes this.'),
      L('<b>tg α ni burchakning o‘zi deb olish.</b> f′(x₀) = 1 bo‘lsa, α = 45°, f′(x₀) = 1 radian emas.', '<b>Принимать tg α за сам угол.</b> Если f′(x₀) = 1, то α = 45°, а не 1 радиан.', '<b>Taking tan α for the angle itself.</b> If f′(x₀) = 1, then α = 45°, not 1 radian.')
    ] },
    { kind: 'life', h: L('Hosila atrofimizda', 'Производная вокруг нас', 'The derivative around us'), p: [
      L('<b>Avtomobil:</b> spidometr — yo‘lning vaqt bo‘yicha hosilasini, akselerometr (smartfoningizda ham bor!) — tezlikning hosilasini o‘lchaydi. Yo‘l harakati xavfsizligi tizimlari tormozlanishdagi tezlanishni kuzatib, xavfli vaziyatni aniqlaydi.', '<b>Автомобиль:</b> спидометр измеряет производную пути по времени, акселерометр (он есть и в вашем смартфоне!) — производную скорости. Системы безопасности по ускорению при торможении распознают опасную ситуацию.', '<b>Cars:</b> the speedometer measures the time derivative of distance, and the accelerometer (your smartphone has one too!) measures the derivative of velocity. Safety systems detect danger from the deceleration during braking.'),
      L('<b>Yo‘l qurilishi:</b> tog‘ yo‘lining qiyaligi (masalan, 8 %) — balandlikning gorizontal masofa bo‘yicha hosilasi. Kamchiq dovonidagi yo‘l loyihachilari qiyalik yuk mashinalari uchun xavfsiz bo‘lishini hisoblaydi.', '<b>Строительство дорог:</b> уклон горной дороги (например, 8 %) — производная высоты по горизонтальному расстоянию. Проектировщики дороги через перевал Камчик рассчитывают, чтобы уклон был безопасен для грузовиков.', '<b>Road building:</b> the gradient of a mountain road (say 8 %) is the derivative of height with respect to horizontal distance. Engineers of the Kamchik pass road make sure the gradient is safe for lorries.'),
      L('<b>Tibbiyot:</b> shifokorlar dori konsentratsiyasining qondagi o‘zgarish tezligini hisoblab, dozani belgilaydi. <b>Iqtisod:</b> YaIM o‘sish sur’ati — iqtisodiyot hajmining hosilasi.', '<b>Медицина:</b> врачи рассчитывают скорость изменения концентрации лекарства в крови и подбирают дозу. <b>Экономика:</b> темп роста ВВП — производная объёма экономики.', '<b>Medicine:</b> doctors compute the rate of change of a drug’s concentration in blood to choose the dose. <b>Economics:</b> GDP growth rate is the derivative of the size of the economy.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('f′(x₀) = lim<sub>Δx→0</sub> Δy/Δx — hosila.', 'f′(x₀) = lim<sub>Δx→0</sub> Δy/Δx — производная.', 'f′(x₀) = lim<sub>Δx→0</sub> Δy/Δx is the derivative.'),
      L('Geometrik ma’no: f′(x₀) = tg α — urinmaning burchak koeffitsiyenti.', 'Геометрический смысл: f′(x₀) = tg α — угловой коэффициент касательной.', 'Geometric meaning: f′(x₀) = tan α, the slope of the tangent.'),
      L('Fizik ma’no: v = s′, a = v′ — oniy tezlik va tezlanish.', 'Физический смысл: v = s′, a = v′ — мгновенная скорость и ускорение.', 'Physical meaning: v = s′, a = v′ — instantaneous velocity and acceleration.'),
      L('Ta’rifdan: C′ = 0, (x²)′ = 2x, (x³)′ = 3x², (1/x)′ = −1/x², (√x)′ = 1/(2√x).', 'По определению: C′ = 0, (x²)′ = 2x, (x³)′ = 3x², (1/x)′ = −1/x², (√x)′ = 1/(2√x).', 'From the definition: C′ = 0, (x²)′ = 2x, (x³)′ = 3x², (1/x)′ = −1/x², (√x)′ = 1/(2√x).'),
      L('Differensiallanuvchi ⇒ uzluksiz, lekin teskarisi noto‘g‘ri (|x|).', 'Дифференцируема ⇒ непрерывна, но не наоборот (|x|).', 'Differentiable ⇒ continuous, but not conversely (|x|).'),
      L('Hosilani Nyuton va Leybnits yaratgan, Koshi qat’iy asosladi, f′ belgisi Lagranjniki.', 'Производную создали Ньютон и Лейбниц, строго обосновал Коши, обозначение f′ — Лагранжа.', 'The derivative was created by Newton and Leibniz, made rigorous by Cauchy; the notation f′ is Lagrange’s.')
    ] }
  ] });

  // ---------- t3. Hosilani hisoblash qoidalari ----------
  T.add(P, 't3', { sections: [
    { kind: 'intro', h: L('Har safar limit hisoblamaslik uchun', 'Чтобы не считать предел каждый раз', 'So that we need not compute a limit every time'), p: [
      L('Oldingi mavzuda x², x³, 1/x funksiyalarining hosilasini ta’rif bo‘yicha — limit orqali topdik. Bu usul ishonchli, ammo sekin. Tasavvur qiling: y = x⁵ sin x + 7/x² hosilasini ta’rif bo‘yicha topish uchun bir sahifa hisob kerak bo‘lardi.', 'В прошлой теме мы находили производные x², x³, 1/x по определению — через предел. Этот способ надёжен, но медленен. Представьте: чтобы найти по определению производную y = x⁵ sin x + 7/x², понадобилась бы страница вычислений.', 'In the previous topic we found the derivatives of x², x³, 1/x from the definition — via a limit. That method is reliable but slow. Imagine finding the derivative of y = x⁵ sin x + 7/x² from the definition: it would take a page of work.'),
      L('Leybnitsning eng katta yutug‘i ham shunda edi: u hosilani <b>hisoblash</b> uchun qulay qoidalar — «algoritm» yaratdi. Shu qoidalarni bilgan o‘quvchi har qanday elementar funksiyaning hosilasini bir necha qatorda topadi. Aslida kompyuter algebra tizimlari (masalan, Wolfram Alpha) ham aynan shu qoidalar asosida ishlaydi.', 'В этом и было главное достижение Лейбница: он создал удобные правила — «алгоритм» — для <b>вычисления</b> производной. Ученик, знающий эти правила, находит производную любой элементарной функции за несколько строк. Системы компьютерной алгебры (например, Wolfram Alpha) работают именно на этих правилах.', 'This was Leibniz’s greatest achievement: he created convenient rules — an “algorithm” — for <b>computing</b> derivatives. A student who knows these rules can differentiate any elementary function in a few lines. Computer algebra systems (such as Wolfram Alpha) work on exactly these rules.'),
      L('Bu mavzuda ikkita narsani o‘rganamiz: asosiy elementar funksiyalar hosilalari <b>jadvali</b> va funksiyalar ustidagi amallar (yig‘indi, ko‘paytma, bo‘linma) uchun <b>differensiallash qoidalari</b>.', 'В этой теме мы изучим две вещи: <b>таблицу</b> производных основных элементарных функций и <b>правила дифференцирования</b> для действий над функциями (сумма, произведение, частное).', 'In this topic we learn two things: the <b>table</b> of derivatives of the basic elementary functions and the <b>rules of differentiation</b> for operations on functions (sum, product, quotient).')
    ] },
    { kind: 'table', h: L('Asosiy hosilalar jadvali', 'Таблица основных производных', 'Table of basic derivatives'), table: { head: [L('Funksiya', 'Функция', 'Function'), L('Hosila', 'Производная', 'Derivative')], rows: [
      ['C', '0'], ['xⁿ', L('n·xⁿ⁻¹', 'n·xⁿ⁻¹', 'n·xⁿ⁻¹')], ['√x', '1/(2√x)'], ['1/x', '−1/x²'], ['sin x', 'cos x'], ['cos x', '−sin x'],
      ['tg x', L('1/cos² x', '1/cos² x', '1/cos² x')], ['ctg x', L('−1/sin² x', '−1/sin² x', '−1/sin² x')], ['eˣ', 'eˣ'], ['aˣ', L('aˣ·ln a', 'aˣ·ln a', 'aˣ·ln a')], ['ln x', '1/x'], [L('log<sub>a</sub> x', 'log<sub>a</sub> x', 'log<sub>a</sub> x'), L('1/(x ln a)', '1/(x ln a)', '1/(x ln a)')]
    ] }, after: [
      L('(xⁿ)′ = nxⁿ⁻¹ formulasi istalgan haqiqiy n uchun to‘g‘ri: (x<sup>−3</sup>)′ = −3x<sup>−4</sup>, (x<sup>2/3</sup>)′ = (2/3)x<sup>−1/3</sup>. eˣ — o‘z hosilasiga teng yagona (o‘zgarmas ko‘paytuvchi aniqligida) funksiya; e soni shuning uchun ham «tabiiy» asos deyiladi.', 'Формула (xⁿ)′ = nxⁿ⁻¹ верна для любого действительного n: (x<sup>−3</sup>)′ = −3x<sup>−4</sup>, (x<sup>2/3</sup>)′ = (2/3)x<sup>−1/3</sup>. eˣ — единственная (с точностью до постоянного множителя) функция, равная своей производной; поэтому e и называют «натуральным» основанием.', 'The formula (xⁿ)′ = nxⁿ⁻¹ holds for any real n: (x<sup>−3</sup>)′ = −3x<sup>−4</sup>, (x<sup>2/3</sup>)′ = (2/3)x<sup>−1/3</sup>. eˣ is the only function (up to a constant factor) equal to its own derivative; that is why e is called the “natural” base.')
    ] },
    { kind: 'rule', h: L('Differensiallash qoidalari', 'Правила дифференцирования', 'Rules of differentiation'), p: [
      L('u(x) va v(x) differensiallanuvchi funksiyalar, C — o‘zgarmas son bo‘lsin. U holda:', 'Пусть u(x) и v(x) — дифференцируемые функции, C — постоянная. Тогда:', 'Let u(x) and v(x) be differentiable functions and C a constant. Then:')
    ], list: [
      L('<b>(u ± v)′ = u′ ± v′</b> — yig‘indining hosilasi hosilalar yig‘indisiga teng;', '<b>(u ± v)′ = u′ ± v′</b> — производная суммы равна сумме производных;', '<b>(u ± v)′ = u′ ± v′</b> — the derivative of a sum is the sum of the derivatives;'),
      L('<b>(Cu)′ = C·u′</b> — o‘zgarmas ko‘paytuvchi hosila belgisidan tashqariga chiqadi;', '<b>(Cu)′ = C·u′</b> — постоянный множитель выносится за знак производной;', '<b>(Cu)′ = C·u′</b> — a constant factor comes out of the derivative;'),
      L('<b>(uv)′ = u′v + uv′</b> — ko‘paytmaning hosilasi (Leybnits qoidasi);', '<b>(uv)′ = u′v + uv′</b> — производная произведения (правило Лейбница);', '<b>(uv)′ = u′v + uv′</b> — the product rule (Leibniz rule);'),
      L('<b>(u/v)′ = (u′v − uv′)/v²</b>, v ≠ 0 — bo‘linmaning hosilasi.', '<b>(u/v)′ = (u′v − uv′)/v²</b>, v ≠ 0 — производная частного.', '<b>(u/v)′ = (u′v − uv′)/v²</b>, v ≠ 0 — the quotient rule.')
    ], after: [
      L('Qoidalar birgalikda «chiziqlilik»ni beradi: (au + bv)′ = au′ + bv′. Shuning uchun ko‘phadning hosilasini har bir hadi bo‘yicha alohida topish mumkin: (5x³ − 4x² + 7)′ = 15x² − 8x.', 'Вместе правила дают «линейность»: (au + bv)′ = au′ + bv′. Поэтому производную многочлена можно находить почленно: (5x³ − 4x² + 7)′ = 15x² − 8x.', 'Together the rules give “linearity”: (au + bv)′ = au′ + bv′. So a polynomial can be differentiated term by term: (5x³ − 4x² + 7)′ = 15x² − 8x.')
    ] },
    { kind: 'def', h: L('Qoidalarning isbot g‘oyasi', 'Идея доказательства правил', 'Why the rules are true'), p: [
      L('<b>Ko‘paytma qoidasi.</b> x ga Δx orttirma bersak, u → u + Δu, v → v + Δv bo‘ladi. Ko‘paytma orttirmasi: Δ(uv) = (u + Δu)(v + Δv) − uv = Δu·v + u·Δv + Δu·Δv. Δx ga bo‘lamiz: (Δu/Δx)·v + u·(Δv/Δx) + (Δu/Δx)·Δv. Δx → 0 da Δv → 0 (differensiallanuvchi funksiya uzluksiz), shuning uchun oxirgi had yo‘qoladi va (uv)′ = u′v + uv′.', '<b>Правило произведения.</b> При приращении Δx имеем u → u + Δu, v → v + Δv. Приращение произведения: Δ(uv) = (u + Δu)(v + Δv) − uv = Δu·v + u·Δv + Δu·Δv. Делим на Δx: (Δu/Δx)·v + u·(Δv/Δx) + (Δu/Δx)·Δv. При Δx → 0 Δv → 0 (дифференцируемая функция непрерывна), последнее слагаемое исчезает и (uv)′ = u′v + uv′.', '<b>Product rule.</b> With an increment Δx, u → u + Δu and v → v + Δv. The increment of the product is Δ(uv) = (u + Δu)(v + Δv) − uv = Δu·v + u·Δv + Δu·Δv. Divide by Δx: (Δu/Δx)·v + u·(Δv/Δx) + (Δu/Δx)·Δv. As Δx → 0, Δv → 0 (a differentiable function is continuous), so the last term vanishes and (uv)′ = u′v + uv′.'),
      L('Geometrik talqin: tomonlari u va v bo‘lgan to‘g‘ri to‘rtburchak yuzasi uv. Tomonlar ozgina o‘sganda yuza ikkita ingichka tasma (Δu·v va u·Δv) hamda juda kichik burchak kvadratchasi (Δu·Δv) qadar o‘sadi — oxirgisi e’tiborga olinmaydi.', 'Геометрическое толкование: площадь прямоугольника со сторонами u и v равна uv. При малом росте сторон площадь увеличивается на две тонкие полоски (Δu·v и u·Δv) и крошечный угловой квадратик (Δu·Δv) — им пренебрегают.', 'Geometric picture: a rectangle with sides u and v has area uv. When the sides grow slightly, the area grows by two thin strips (Δu·v and u·Δv) and a tiny corner square (Δu·Δv), which is negligible.'),
      L('<b>sin x hosilasi.</b> sin(x + Δx) − sin x = 2 sin(Δx/2)·cos(x + Δx/2). Δx ga bo‘lib, sin(Δx/2)/(Δx/2) → 1 ajoyib limitdan foydalansak, (sin x)′ = cos x kelib chiqadi. Bo‘linma qoidasi esa (tg x)′ = (cos² x + sin² x)/cos² x = 1/cos² x ni beradi.', '<b>Производная sin x.</b> sin(x + Δx) − sin x = 2 sin(Δx/2)·cos(x + Δx/2). Разделив на Δx и используя замечательный предел sin(Δx/2)/(Δx/2) → 1, получаем (sin x)′ = cos x. А правило частного даёт (tg x)′ = (cos² x + sin² x)/cos² x = 1/cos² x.', '<b>Derivative of sin x.</b> sin(x + Δx) − sin x = 2 sin(Δx/2)·cos(x + Δx/2). Dividing by Δx and using the remarkable limit sin(Δx/2)/(Δx/2) → 1 gives (sin x)′ = cos x. The quotient rule then gives (tan x)′ = (cos² x + sin² x)/cos² x = 1/cos² x.')
    ] },
    { kind: 'history', h: L('Qoidalar tarixi', 'История правил', 'History of the rules'), p: [
      L('Ko‘paytma va bo‘linma qoidalarini Leybnits 1675–1677-yillardagi qo‘lyozmalarida keltirib chiqargan. Dastlab u (uv)′ = u′v′ deb o‘ylagan, ammo tez orada xatoni topib, to‘g‘ri formulani yozgan — buyuk olimlar ham shu xatoni qilgan ekan!', 'Правила произведения и частного Лейбниц вывел в рукописах 1675–1677 годов. Сначала он полагал, что (uv)′ = u′v′, но вскоре нашёл ошибку и записал верную формулу — даже великие учёные делали эту ошибку!', 'Leibniz derived the product and quotient rules in manuscripts of 1675–1677. At first he thought (uv)′ = u′v′, but soon found the mistake and wrote the correct formula — even great scholars made this error!'),
      L('Birinchi analiz darsligini 1696-yilda fransuz markizi Giyom de Lopital yozgan: «Egri chiziqlarni tushunish uchun cheksiz kichiklar tahlili». Unda qoidalar shveytsariyalik Iogann Bernulli ma’ruzalari asosida bayon qilingan edi.', 'Первый учебник анализа написал в 1696 году французский маркиз Гийом де Лопиталь: «Анализ бесконечно малых для понимания кривых линий». Правила в нём изложены по лекциям швейцарца Иоганна Бернулли.', 'The first calculus textbook was written in 1696 by the French marquis Guillaume de l’Hôpital: “Analysis of the Infinitely Small for the Understanding of Curved Lines”. Its rules were based on lectures by the Swiss Johann Bernoulli.'),
      L('eˣ ning o‘ziga teng hosilasini va e sonining ko‘plab xossalarini XVIII asrda Leonard Eyler o‘rgangan; aynan u «e» harfini kiritgan (1727–1728). Eyler hosilalar jadvalini bugungi ko‘rinishga yaqinlashtirgan.', 'То, что производная eˣ равна самой функции, и многие свойства числа e изучил в XVIII веке Леонард Эйлер; именно он ввёл букву «e» (1727–1728). Эйлер приблизил таблицу производных к современному виду.', 'That eˣ is its own derivative, along with many properties of e, was studied in the 18th century by Leonhard Euler; he introduced the letter “e” (1727–1728). Euler brought the table of derivatives close to its modern form.')
    ] },
    { kind: 'steps', h: L('Hosilani topish tartibi', 'Порядок нахождения производной', 'How to differentiate step by step'), list: [
      L('1) Funksiyaning tuzilishini aniqlang: yig‘indimi, ko‘paytmami, bo‘linmami?', '1) Определите структуру функции: сумма, произведение, частное?', '1) Identify the structure: a sum, a product, a quotient?'),
      L('2) Iloji bo‘lsa, soddalashtiring: ildiz va kasrlarni daraja ko‘rinishiga keltiring (√x = x<sup>1/2</sup>, 1/x³ = x<sup>−3</sup>).', '2) По возможности упростите: корни и дроби запишите в виде степеней (√x = x<sup>1/2</sup>, 1/x³ = x<sup>−3</sup>).', '2) Simplify if possible: write roots and fractions as powers (√x = x<sup>1/2</sup>, 1/x³ = x<sup>−3</sup>).'),
      L('3) Tegishli qoidani qo‘llang va har bir bo‘lak uchun jadvaldan foydalaning.', '3) Примените нужное правило и для каждой части используйте таблицу.', '3) Apply the right rule and use the table for each part.'),
      L('4) Natijani soddalashtiring (o‘xshash hadlar, umumiy ko‘paytuvchi).', '4) Упростите результат (подобные члены, общий множитель).', '4) Simplify the result (like terms, common factors).'),
      L('5) Kerak bo‘lsa, nuqtadagi qiymatni hisoblang.', '5) При необходимости вычислите значение в точке.', '5) If needed, evaluate at the given point.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('y = 3x⁴ − 5x + 2. y′ ni toping.', 'y = 3x⁴ − 5x + 2. Найдите y′.', 'y = 3x⁴ − 5x + 2. Find y′.'),
        s: L('Hadma-had: (3x⁴)′ = 12x³, (−5x)′ = −5, 2′ = 0. <b>y′ = 12x³ − 5</b>.', 'Почленно: (3x⁴)′ = 12x³, (−5x)′ = −5, 2′ = 0. <b>y′ = 12x³ − 5</b>.', 'Term by term: (3x⁴)′ = 12x³, (−5x)′ = −5, 2′ = 0. <b>y′ = 12x³ − 5</b>.') },
      { q: L('y = x² sin x. y′ ni toping.', 'y = x² sin x. Найдите y′.', 'y = x² sin x. Find y′.'),
        s: L('Ko‘paytma: u = x², v = sin x. y′ = 2x·sin x + x²·cos x = <b>x(2 sin x + x cos x)</b>.', 'Произведение: u = x², v = sin x. y′ = 2x·sin x + x²·cos x = <b>x(2 sin x + x cos x)</b>.', 'Product: u = x², v = sin x. y′ = 2x·sin x + x²·cos x = <b>x(2 sin x + x cos x)</b>.') },
      { q: L('y = (x + 1)/(x − 1). y′ ni toping.', 'y = (x + 1)/(x − 1). Найдите y′.', 'y = (x + 1)/(x − 1). Find y′.'),
        s: L('y′ = (1·(x − 1) − (x + 1)·1)/(x − 1)² = <b>−2/(x − 1)²</b>.', 'y′ = (1·(x − 1) − (x + 1)·1)/(x − 1)² = <b>−2/(x − 1)²</b>.', 'y′ = (1·(x − 1) − (x + 1)·1)/(x − 1)² = <b>−2/(x − 1)²</b>.') },
      { q: L('y = 4√x + 6/x² − eˣ. y′(1) ni toping.', 'y = 4√x + 6/x² − eˣ. Найдите y′(1).', 'y = 4√x + 6/x² − eˣ. Find y′(1).'),
        s: L('y = 4x<sup>1/2</sup> + 6x<sup>−2</sup> − eˣ, y′ = 2/√x − 12/x³ − eˣ. y′(1) = 2 − 12 − e = <b>−10 − e ≈ −12,72</b>.', 'y = 4x<sup>1/2</sup> + 6x<sup>−2</sup> − eˣ, y′ = 2/√x − 12/x³ − eˣ. y′(1) = 2 − 12 − e = <b>−10 − e ≈ −12,72</b>.', 'y = 4x<sup>1/2</sup> + 6x<sup>−2</sup> − eˣ, y′ = 2/√x − 12/x³ − eˣ. y′(1) = 2 − 12 − e = <b>−10 − e ≈ −12.72</b>.') },
      { q: L('y = eˣ ln x. y′ ni toping.', 'y = eˣ ln x. Найдите y′.', 'y = eˣ ln x. Find y′.'),
        s: L('y′ = eˣ ln x + eˣ·(1/x) = <b>eˣ(ln x + 1/x)</b>.', 'y′ = eˣ ln x + eˣ·(1/x) = <b>eˣ(ln x + 1/x)</b>.', 'y′ = eˣ ln x + eˣ·(1/x) = <b>eˣ(ln x + 1/x)</b>.') }
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('eˣ funksiyasi — differensiallashdan «qo‘rqmaydigan» yagona funksiya: uni necha marta differensiallasangiz ham o‘zgarmaydi. Matematiklar orasida shunday hazil bor: «Funksiyalar ziyofatida differensial operator hammani o‘zgartirib yuborar ekan, faqat eˣ xotirjam turibdi».', 'Функция eˣ — единственная, которая «не боится» дифференцирования: сколько раз её ни дифференцируй, она не меняется. Среди математиков есть шутка: «На вечеринке функций оператор дифференцирования всех меняет, и только eˣ остаётся спокойной».', 'The function eˣ is the only one that is “not afraid” of differentiation: however many times you differentiate it, it does not change. Mathematicians joke: “At the functions’ party the differential operator transforms everybody, only eˣ stays calm”.'),
      L('sin x ni to‘rt marta differensiallasak, yana sin x hosil bo‘ladi: sin → cos → −sin → −cos → sin. Shuning uchun tebranishlar (prujina, mayatnik, o‘zgaruvchan tok) sinus bilan tasvirlanadi.', 'Если продифференцировать sin x четыре раза, снова получится sin x: sin → cos → −sin → −cos → sin. Поэтому колебания (пружина, маятник, переменный ток) описываются синусом.', 'Differentiating sin x four times returns sin x: sin → cos → −sin → −cos → sin. That is why oscillations (springs, pendulums, alternating current) are described by sines.'),
      L('n ta funksiya ko‘paytmasi uchun ham qoida bor: (uvw)′ = u′vw + uv′w + uvw′ — har safar faqat bitta ko‘paytuvchi differensiallanadi.', 'Есть правило и для произведения n функций: (uvw)′ = u′vw + uv′w + uvw′ — каждый раз дифференцируется только один множитель.', 'There is a rule for a product of n functions too: (uvw)′ = u′vw + uv′w + uvw′ — each time only one factor is differentiated.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>(uv)′ = u′v′ deb yozish.</b> Tekshiring: (x·x)′ = (x²)′ = 2x, lekin x′·x′ = 1. To‘g‘ri: u′v + uv′.', '<b>Писать (uv)′ = u′v′.</b> Проверьте: (x·x)′ = (x²)′ = 2x, но x′·x′ = 1. Верно: u′v + uv′.', '<b>Writing (uv)′ = u′v′.</b> Check: (x·x)′ = (x²)′ = 2x, but x′·x′ = 1. Correct: u′v + uv′.'),
      L('<b>Bo‘linma qoidasida suratdagi tartibni almashtirish.</b> u′v − uv′, ya’ni avval suratning hosilasi. Teskari tartib ishorani o‘zgartiradi.', '<b>Менять порядок в числителе правила частного.</b> u′v − uv′, т. е. сначала производная числителя. Обратный порядок меняет знак.', '<b>Swapping the order in the quotient rule.</b> It is u′v − uv′, the derivative of the numerator first. Reversing changes the sign.'),
      L('<b>(cos x)′ = sin x deb yozish.</b> Minus yo‘qoladi: (cos x)′ = −sin x.', '<b>Писать (cos x)′ = sin x.</b> Теряется минус: (cos x)′ = −sin x.', '<b>Writing (cos x)′ = sin x.</b> The minus is lost: (cos x)′ = −sin x.'),
      L('<b>(5ˣ)′ = x·5ˣ⁻¹ deb yozish.</b> Bu ko‘rsatkichli funksiya, darajali emas: (5ˣ)′ = 5ˣ ln 5.', '<b>Писать (5ˣ)′ = x·5ˣ⁻¹.</b> Это показательная функция, а не степенная: (5ˣ)′ = 5ˣ ln 5.', '<b>Writing (5ˣ)′ = x·5ˣ⁻¹.</b> This is an exponential, not a power function: (5ˣ)′ = 5ˣ ln 5.'),
      L('<b>O‘zgarmasning hosilasini unutish.</b> (π²)′ = 0, (e³)′ = 0 — bular sonlar, x ga bog‘liq emas.', '<b>Забывать, что производная константы — ноль.</b> (π²)′ = 0, (e³)′ = 0 — это числа, от x не зависят.', '<b>Forgetting constants have zero derivative.</b> (π²)′ = 0, (e³)′ = 0 — they are numbers independent of x.')
    ] },
    { kind: 'life', h: L('Qoidalar amalda', 'Правила на практике', 'The rules in practice'), p: [
      L('<b>Biznes:</b> daromad R = p·q (narx × sotilgan miqdor). Agar narx ham, miqdor ham vaqt bo‘yicha o‘zgarsa, ko‘paytma qoidasi R′ = p′q + pq′ ni beradi: daromadning o‘zgarishi narx o‘zgarishi va savdo hajmi o‘zgarishi hissalaridan tuziladi.', '<b>Бизнес:</b> выручка R = p·q (цена × количество). Если и цена, и количество меняются со временем, правило произведения даёт R′ = p′q + pq′: изменение выручки складывается из вклада изменения цены и изменения объёма продаж.', '<b>Business:</b> revenue R = p·q (price × quantity). If both change over time, the product rule gives R′ = p′q + pq′: the change in revenue consists of the contributions of the price change and the sales-volume change.'),
      L('<b>Fizika:</b> kinetik energiya E = mv²/2. Raketa yoqilg‘isi yonib, massa ham kamayadi, tezlik ham oshadi — energiyaning o‘zgarish tezligi ko‘paytma qoidasi bilan hisoblanadi. Elektr zanjirida quvvat P = U·I ham ko‘paytma.', '<b>Физика:</b> кинетическая энергия E = mv²/2. У ракеты сгорает топливо, масса уменьшается, а скорость растёт — скорость изменения энергии считают по правилу произведения. Мощность в цепи P = U·I — тоже произведение.', '<b>Physics:</b> kinetic energy E = mv²/2. A rocket burns fuel, so its mass decreases while its speed increases — the rate of change of energy is found with the product rule. Electrical power P = U·I is also a product.'),
      L('<b>Dasturlash:</b> neyron tarmoqlarni o‘qitishda millionlab hosilalar shu qoidalar bilan avtomatik hisoblanadi («avtomatik differensiallash»). Har bir sun’iy intellekt modeli Leybnits qoidalariga tayanadi.', '<b>Программирование:</b> при обучении нейросетей миллионы производных автоматически вычисляются по этим правилам («автоматическое дифференцирование»). Каждая модель искусственного интеллекта опирается на правила Лейбница.', '<b>Programming:</b> when neural networks are trained, millions of derivatives are computed automatically by these rules (“automatic differentiation”). Every AI model relies on Leibniz’s rules.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Check yourself'), ex: [
      { q: L('(x³ − 2x² + x − 9)′ = ?', '(x³ − 2x² + x − 9)′ = ?', '(x³ − 2x² + x − 9)′ = ?'), s: L('3x² − 4x + 1.', '3x² − 4x + 1.', '3x² − 4x + 1.') },
      { q: L('(x cos x)′ = ?', '(x cos x)′ = ?', '(x cos x)′ = ?'), s: L('cos x − x sin x.', 'cos x − x sin x.', 'cos x − x sin x.') },
      { q: L('(x²/(x + 1))′ = ?', '(x²/(x + 1))′ = ?', '(x²/(x + 1))′ = ?'), s: L('(2x(x + 1) − x²)/(x + 1)² = (x² + 2x)/(x + 1)².', '(2x(x + 1) − x²)/(x + 1)² = (x² + 2x)/(x + 1)².', '(2x(x + 1) − x²)/(x + 1)² = (x² + 2x)/(x + 1)².') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('C′ = 0, (xⁿ)′ = nxⁿ⁻¹, (sin x)′ = cos x, (cos x)′ = −sin x, (eˣ)′ = eˣ, (ln x)′ = 1/x.', 'C′ = 0, (xⁿ)′ = nxⁿ⁻¹, (sin x)′ = cos x, (cos x)′ = −sin x, (eˣ)′ = eˣ, (ln x)′ = 1/x.', 'C′ = 0, (xⁿ)′ = nxⁿ⁻¹, (sin x)′ = cos x, (cos x)′ = −sin x, (eˣ)′ = eˣ, (ln x)′ = 1/x.'),
      L('(u ± v)′ = u′ ± v′, (Cu)′ = Cu′ — hosila chiziqli.', '(u ± v)′ = u′ ± v′, (Cu)′ = Cu′ — производная линейна.', '(u ± v)′ = u′ ± v′, (Cu)′ = Cu′ — the derivative is linear.'),
      L('(uv)′ = u′v + uv′ — ko‘paytma qoidasi.', '(uv)′ = u′v + uv′ — правило произведения.', '(uv)′ = u′v + uv′ — the product rule.'),
      L('(u/v)′ = (u′v − uv′)/v² — bo‘linma qoidasi.', '(u/v)′ = (u′v − uv′)/v² — правило частного.', '(u/v)′ = (u′v − uv′)/v² — the quotient rule.'),
      L('Ildiz va kasrlarni daraja ko‘rinishida yozish hisobni osonlashtiradi.', 'Запись корней и дробей в виде степеней упрощает вычисления.', 'Writing roots and fractions as powers makes the work easier.')
    ] }
  ] });

  // ---------- t4. Murakkab funksiyaning hosilasi ----------
  T.add(P, 't4', { sections: [
    { kind: 'intro', h: L('Funksiya ichida funksiya', 'Функция внутри функции', 'A function inside a function'), p: [
      L('y = (2x + 1)¹⁰ hosilasini qanday topamiz? Qavsni Nyuton binomi bilan ochib, 11 ta hadni differensiallash mumkin, lekin bu juda uzoq. y = sin(x²) yoki y = √(1 + x³) uchun esa umuman ochadigan qavs yo‘q. Bu funksiyalarning umumiy jihati — ular <b>murakkab</b>: bir funksiyaning «ichiga» boshqa funksiya qo‘yilgan.', 'Как найти производную y = (2x + 1)¹⁰? Можно раскрыть скобку по биному Ньютона и продифференцировать 11 слагаемых, но это очень долго. А для y = sin(x²) или y = √(1 + x³) раскрывать вообще нечего. Общее у этих функций то, что они <b>сложные</b>: в одну функцию «вложена» другая.', 'How do we differentiate y = (2x + 1)¹⁰? We could expand by the binomial theorem and differentiate 11 terms, but that is very long. And for y = sin(x²) or y = √(1 + x³) there is nothing to expand at all. What these functions share is that they are <b>composite</b>: one function is “nested” inside another.'),
      L('Hayotiy o‘xshatish: velosiped zanjiri. Pedal tishli g‘ildirakni aylantiradi, u esa zanjir orqali orqa g‘ildirakni aylantiradi. Agar orqa g‘ildirak tishli g‘ildirakdan 3 marta tez, tishli g‘ildirak esa pedaldan 2 marta tez aylansa, orqa g‘ildirak pedaldan 3·2 = 6 marta tez aylanadi. O‘zgarish tezliklari <b>ko‘paytiriladi</b> — bu «zanjir qoidasi»ning mohiyati.', 'Жизненная аналогия: велосипедная цепь. Педаль вращает звёздочку, а та через цепь — заднее колесо. Если заднее колесо крутится в 3 раза быстрее звёздочки, а звёздочка в 2 раза быстрее педали, то колесо крутится в 3·2 = 6 раз быстрее педали. Скорости изменения <b>перемножаются</b> — в этом суть «цепного правила».', 'An everyday analogy: a bicycle chain. The pedal turns the sprocket, and the sprocket turns the rear wheel through the chain. If the wheel turns 3 times faster than the sprocket and the sprocket 2 times faster than the pedal, the wheel turns 3·2 = 6 times faster than the pedal. Rates of change <b>multiply</b> — that is the essence of the “chain rule”.'),
      L('Bu mavzuda murakkab funksiyani «qatlamlarga» ajratishni va zanjir qoidasi yordamida uning hosilasini bir qatorda topishni o‘rganamiz. Bu qoida — differensiallashdagi eng ko‘p ishlatiladigan qoida.', 'В этой теме мы научимся раскладывать сложную функцию на «слои» и находить её производную в одну строку по цепному правилу. Это правило — самое употребительное в дифференцировании.', 'In this topic we learn to split a composite function into “layers” and differentiate it in one line with the chain rule — the most frequently used rule in differentiation.')
    ] },
    { kind: 'def', h: L('Murakkab funksiya', 'Сложная функция', 'Composite function'), p: [
      L('Agar u = g(x) va y = f(u) bo‘lsa, y = f(g(x)) funksiya <b>murakkab funksiya</b> (yoki funksiyalar <b>kompozitsiyasi</b>) deyiladi. g — <b>ichki funksiya</b>, f — <b>tashqi funksiya</b>, u — oraliq o‘zgaruvchi.', 'Если u = g(x) и y = f(u), то функция y = f(g(x)) называется <b>сложной функцией</b> (или <b>композицией</b> функций). g — <b>внутренняя функция</b>, f — <b>внешняя функция</b>, u — промежуточная переменная.', 'If u = g(x) and y = f(u), the function y = f(g(x)) is called a <b>composite function</b> (or a <b>composition</b> of functions). g is the <b>inner function</b>, f the <b>outer function</b>, u the intermediate variable.'),
      L('Qatlamni aniqlash uchun x berilganda qiymat qanday tartibda hisoblanishini o‘ylang. y = sin(x²) uchun: avval x² (ichki), keyin sinus (tashqi). y = sin² x = (sin x)² uchun esa aksincha: avval sin x (ichki), keyin kvadrat (tashqi). Ko‘rinishi o‘xshash, ammo tuzilishi butunlay boshqa!', 'Чтобы определить слои, подумайте, в каком порядке вычисляется значение при данном x. Для y = sin(x²): сначала x² (внутренняя), затем синус (внешняя). Для y = sin² x = (sin x)² — наоборот: сначала sin x (внутренняя), затем квадрат (внешняя). Вид похож, а строение совсем другое!', 'To find the layers, think about the order in which the value is computed for a given x. For y = sin(x²): first x² (inner), then sine (outer). For y = sin² x = (sin x)² it is the reverse: first sin x (inner), then squaring (outer). They look alike, but their structure is completely different!'),
      L('Qatlamlar ikkitadan ko‘p bo‘lishi mumkin: y = e<sup>cos 3x</sup> da uchta qatlam bor — 3x, so‘ng kosinus, so‘ng ko‘rsatkichli funksiya.', 'Слоёв может быть больше двух: у y = e<sup>cos 3x</sup> три слоя — 3x, затем косинус, затем экспонента.', 'There may be more than two layers: y = e<sup>cos 3x</sup> has three — 3x, then cosine, then the exponential.')
    ] },
    { kind: 'rule', h: L('Zanjir qoidasi', 'Цепное правило', 'The chain rule'), p: [
      L('<b>Teorema.</b> Agar u = g(x) funksiya x nuqtada, y = f(u) funksiya esa u = g(x) nuqtada differensiallanuvchi bo‘lsa, murakkab funksiya ham differensiallanuvchi va', '<b>Теорема.</b> Если функция u = g(x) дифференцируема в точке x, а y = f(u) — в точке u = g(x), то сложная функция дифференцируема и', '<b>Theorem.</b> If u = g(x) is differentiable at x and y = f(u) is differentiable at u = g(x), then the composite function is differentiable and'),
      L('<b>(f(g(x)))′ = f′(g(x))·g′(x)</b>, yoki Leybnits belgilarida <b>dy/dx = dy/du · du/dx</b>.', '<b>(f(g(x)))′ = f′(g(x))·g′(x)</b>, или в обозначениях Лейбница <b>dy/dx = dy/du · du/dx</b>.', '<b>(f(g(x)))′ = f′(g(x))·g′(x)</b>, or in Leibniz notation <b>dy/dx = dy/du · du/dx</b>.'),
      L('So‘z bilan: <i>tashqi funksiyaning hosilasi (ichkisi o‘zgarmagan holda) ichki funksiyaning hosilasiga ko‘paytiriladi.</i> <b>Isbot g‘oyasi:</b> Δu ≠ 0 bo‘lsa, Δy/Δx = (Δy/Δu)·(Δu/Δx). Δx → 0 da Δu → 0 (g uzluksiz), shuning uchun birinchi ko‘paytuvchi f′(u) ga, ikkinchisi g′(x) ga intiladi.', 'Словами: <i>производная внешней функции (с неизменённым внутренним аргументом) умножается на производную внутренней.</i> <b>Идея доказательства:</b> при Δu ≠ 0 Δy/Δx = (Δy/Δu)·(Δu/Δx). При Δx → 0 Δu → 0 (g непрерывна), поэтому первый множитель стремится к f′(u), второй — к g′(x).', 'In words: <i>the derivative of the outer function (with the inner argument left untouched) is multiplied by the derivative of the inner one.</i> <b>Proof idea:</b> if Δu ≠ 0, Δy/Δx = (Δy/Δu)·(Δu/Δx). As Δx → 0, Δu → 0 (g is continuous), so the first factor tends to f′(u) and the second to g′(x).'),
      L('Leybnits belgilari qoidani «kasrlarni qisqartirish» kabi eslab qolishga yordam beradi: du «qisqaradi». Bu qat’iy isbot emas, ammo ajoyib eslatma.', 'Обозначения Лейбница помогают запомнить правило как «сокращение дробей»: du «сокращается». Это не строгое доказательство, но прекрасная подсказка.', 'Leibniz notation lets us remember the rule as “cancelling fractions”: du “cancels”. It is not a rigorous proof, but an excellent reminder.')
    ] },
    { kind: 'table', h: L('Umumlashgan hosilalar jadvali', 'Обобщённая таблица производных', 'Generalised table of derivatives'), p: [
      L('Jadvaldagi har bir formulaga zanjir qoidasini qo‘llasak (u = u(x)):', 'Применив цепное правило к каждой формуле таблицы (u = u(x)):', 'Applying the chain rule to each table formula (u = u(x)):')
    ], table: { head: [L('Funksiya', 'Функция', 'Function'), L('Hosila', 'Производная', 'Derivative')], rows: [
      [L('uⁿ', 'uⁿ', 'uⁿ'), L('n·uⁿ⁻¹·u′', 'n·uⁿ⁻¹·u′', 'n·uⁿ⁻¹·u′')], ['√u', L('u′/(2√u)', 'u′/(2√u)', 'u′/(2√u)')], ['sin u', L('cos u · u′', 'cos u · u′', 'cos u · u′')], ['cos u', L('−sin u · u′', '−sin u · u′', '−sin u · u′')],
      [L('eᵘ', 'eᵘ', 'eᵘ'), L('eᵘ·u′', 'eᵘ·u′', 'eᵘ·u′')], ['ln u', L('u′/u', 'u′/u', 'u′/u')], [L('f(kx + b)', 'f(kx + b)', 'f(kx + b)'), L('k·f′(kx + b)', 'k·f′(kx + b)', 'k·f′(kx + b)')]
    ] }, after: [
      L('Oxirgi qator ayniqsa foydali: chiziqli ichki funksiya faqat k ko‘paytuvchisini beradi. (sin 5x)′ = 5 cos 5x, (e<sup>−2x</sup>)′ = −2e<sup>−2x</sup>, ((3x − 1)⁴)′ = 12(3x − 1)³.', 'Последняя строка особенно полезна: линейная внутренняя функция даёт лишь множитель k. (sin 5x)′ = 5 cos 5x, (e<sup>−2x</sup>)′ = −2e<sup>−2x</sup>, ((3x − 1)⁴)′ = 12(3x − 1)³.', 'The last row is especially useful: a linear inner function contributes just the factor k. (sin 5x)′ = 5 cos 5x, (e<sup>−2x</sup>)′ = −2e<sup>−2x</sup>, ((3x − 1)⁴)′ = 12(3x − 1)³.')
    ] },
    { kind: 'steps', h: L('Zanjir qoidasini qo‘llash algoritmi', 'Алгоритм применения цепного правила', 'How to apply the chain rule'), list: [
      L('1) «Oxirgi amal»ni toping — u tashqi funksiya (daraja, sinus, ildiz, eksponenta…).', '1) Найдите «последнее действие» — это внешняя функция (степень, синус, корень, экспонента…).', '1) Find the “last operation” — it is the outer function (power, sine, root, exponential…).'),
      L('2) Uning ichidagi butun ifodani u deb belgilang.', '2) Обозначьте всё выражение внутри неё через u.', '2) Call the whole expression inside it u.'),
      L('3) Tashqi funksiyani u bo‘yicha differensiallang, u ni o‘zgartirmasdan qoldiring.', '3) Продифференцируйте внешнюю функцию по u, оставив u без изменений.', '3) Differentiate the outer function with respect to u, leaving u unchanged.'),
      L('4) Natijani u′ ga ko‘paytiring; agar u ham murakkab bo‘lsa, jarayonni takrorlang.', '4) Умножьте результат на u′; если u тоже сложная, повторите процесс.', '4) Multiply by u′; if u is itself composite, repeat the process.'),
      L('5) Soddalashtiring va tekshiring: ko‘paytuvchilar soni qatlamlar soniga teng bo‘lishi kerak.', '5) Упростите и проверьте: число множителей должно равняться числу слоёв.', '5) Simplify and check: the number of factors should equal the number of layers.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('y = (2x + 1)³. y′ ni toping.', 'y = (2x + 1)³. Найдите y′.', 'y = (2x + 1)³. Find y′.'),
        s: L('Tashqi — kub, ichki — 2x + 1. y′ = 3(2x + 1)²·2 = <b>6(2x + 1)²</b>.', 'Внешняя — куб, внутренняя — 2x + 1. y′ = 3(2x + 1)²·2 = <b>6(2x + 1)²</b>.', 'Outer — cube, inner — 2x + 1. y′ = 3(2x + 1)²·2 = <b>6(2x + 1)²</b>.') },
      { q: L('y = √(x² + 9). y′(4) ni toping.', 'y = √(x² + 9). Найдите y′(4).', 'y = √(x² + 9). Find y′(4).'),
        s: L('y′ = 2x/(2√(x² + 9)) = x/√(x² + 9). y′(4) = 4/√25 = <b>4/5 = 0,8</b>.', 'y′ = 2x/(2√(x² + 9)) = x/√(x² + 9). y′(4) = 4/√25 = <b>4/5 = 0,8</b>.', 'y′ = 2x/(2√(x² + 9)) = x/√(x² + 9). y′(4) = 4/√25 = <b>4/5 = 0.8</b>.') },
      { q: L('y = cos² x. y′ ni toping.', 'y = cos² x. Найдите y′.', 'y = cos² x. Find y′.'),
        s: L('y = (cos x)². y′ = 2 cos x·(−sin x) = −2 sin x cos x = <b>−sin 2x</b>.', 'y = (cos x)². y′ = 2 cos x·(−sin x) = −2 sin x cos x = <b>−sin 2x</b>.', 'y = (cos x)². y′ = 2 cos x·(−sin x) = −2 sin x cos x = <b>−sin 2x</b>.') },
      { q: L('y = ln(x² + 1). y′ ni toping.', 'y = ln(x² + 1). Найдите y′.', 'y = ln(x² + 1). Find y′.'),
        s: L('(ln u)′ = u′/u, u = x² + 1: <b>y′ = 2x/(x² + 1)</b>.', '(ln u)′ = u′/u, u = x² + 1: <b>y′ = 2x/(x² + 1)</b>.', '(ln u)′ = u′/u, u = x² + 1: <b>y′ = 2x/(x² + 1)</b>.') },
      { q: L('y = sin³(2x). y′ ni toping (uch qatlam).', 'y = sin³(2x). Найдите y′ (три слоя).', 'y = sin³(2x). Find y′ (three layers).'),
        s: L('Kub → sinus → 2x. y′ = 3 sin²(2x)·cos(2x)·2 = <b>6 sin²(2x) cos(2x)</b>.', 'Куб → синус → 2x. y′ = 3 sin²(2x)·cos(2x)·2 = <b>6 sin²(2x) cos(2x)</b>.', 'Cube → sine → 2x. y′ = 3 sin²(2x)·cos(2x)·2 = <b>6 sin²(2x) cos(2x)</b>.') }
    ] },
    { kind: 'history', h: L('Zanjir qoidasi tarixi', 'История цепного правила', 'History of the chain rule'), p: [
      L('Zanjir qoidasi birinchi marta Leybnitsning 1676-yildagi qo‘lyozmasida uchraydi: u √(a + bz + cz²) ning hosilasini topish uchun oraliq o‘zgaruvchi kiritgan. Leybnitsning dy/dx belgisi shu qadar qulay ediki, qoida go‘yo o‘z-o‘zidan «yozilib» qolardi.', 'Цепное правило впервые встречается в рукописи Лейбница 1676 года: для нахождения производной √(a + bz + cz²) он ввёл промежуточную переменную. Обозначение dy/dx было настолько удобным, что правило будто «писалось» само.', 'The chain rule first appears in a 1676 manuscript of Leibniz: to differentiate √(a + bz + cz²) he introduced an intermediate variable. His notation dy/dx was so convenient that the rule seemed to “write itself”.'),
      L('Lopitalning 1696-yilgi darsligida bu qoida keng qo‘llangan, ammo alohida nomlanmagan. Lagranj 1797-yilda funksiyalar kompozitsiyasini aniq tushuncha sifatida ajratib, f′(g(x))·g′(x) ko‘rinishidagi yozuvga yo‘l ochgan. «Zanjir qoidasi» nomi esa XX asrda, ayniqsa ingliz tilidagi darsliklarda («chain rule») tarqalgan.', 'В учебнике Лопиталя 1696 года правило широко применяется, но отдельного названия не имеет. Лагранж в 1797 году выделил композицию функций как самостоятельное понятие, открыв дорогу записи f′(g(x))·g′(x). Название «цепное правило» распространилось в XX веке, особенно в англоязычных учебниках («chain rule»).', 'In l’Hôpital’s 1696 textbook the rule is used widely but not named. In 1797 Lagrange singled out the composition of functions as a concept, opening the way to the notation f′(g(x))·g′(x). The name “chain rule” spread in the 20th century, especially in English textbooks.'),
      L('Bugun zanjir qoidasi sun’iy intellektning yuragida: neyron tarmoqlarni o‘qitadigan «xatoni orqaga tarqatish» (backpropagation) algoritmi aynan ko‘p qatlamli zanjir qoidasidir. Uni 1986-yilda Rumelxart, Xinton va Uilyams ommalashtirgan.', 'Сегодня цепное правило — в сердце искусственного интеллекта: алгоритм «обратного распространения ошибки» (backpropagation), которым обучают нейросети, — это многослойное цепное правило. Его популяризировали в 1986 году Румельхарт, Хинтон и Уильямс.', 'Today the chain rule is at the heart of artificial intelligence: “backpropagation”, the algorithm that trains neural networks, is the many-layer chain rule. It was popularised in 1986 by Rumelhart, Hinton and Williams.')
    ] },
    { kind: 'fact', h: L('Zanjir qoidasidan olinadigan formulalar', 'Формулы, вытекающие из цепного правила', 'Formulas that follow from the chain rule'), p: [
      L('Zanjir qoidasi jadvaldagi ba’zi formulalarni isbotlashga ham yordam beradi. <b>Ko‘rsatkichli funksiya:</b> aˣ = e<sup>x ln a</sup>, ichki funksiya x ln a ning hosilasi ln a. Demak, (aˣ)′ = e<sup>x ln a</sup>·ln a = aˣ ln a. Masalan, (2ˣ)′ = 2ˣ ln 2 ≈ 0,693·2ˣ.', 'Цепное правило помогает доказать и некоторые формулы таблицы. <b>Показательная функция:</b> aˣ = e<sup>x ln a</sup>, производная внутренней функции x ln a равна ln a. Значит, (aˣ)′ = e<sup>x ln a</sup>·ln a = aˣ ln a. Например, (2ˣ)′ = 2ˣ ln 2 ≈ 0,693·2ˣ.', 'The chain rule also proves some table formulas. <b>Exponential:</b> aˣ = e<sup>x ln a</sup>, and the inner function x ln a has derivative ln a. Hence (aˣ)′ = e<sup>x ln a</sup>·ln a = aˣ ln a. For example, (2ˣ)′ = 2ˣ ln 2 ≈ 0.693·2ˣ.'),
      L('<b>Logarifm:</b> x &gt; 0 uchun e<sup>ln x</sup> = x ayniyatini differensiallaymiz. Chap tomonda zanjir qoidasi: e<sup>ln x</sup>·(ln x)′ = x·(ln x)′, o‘ng tomonda 1. Demak, (ln x)′ = 1/x. Xuddi shu usul bilan istalgan teskari funksiyaning hosilasini topish mumkin: (f⁻¹)′(y) = 1/f′(x).', '<b>Логарифм:</b> продифференцируем тождество e<sup>ln x</sup> = x при x &gt; 0. Слева по цепному правилу: e<sup>ln x</sup>·(ln x)′ = x·(ln x)′, справа 1. Значит, (ln x)′ = 1/x. Тем же способом находится производная любой обратной функции: (f⁻¹)′(y) = 1/f′(x).', '<b>Logarithm:</b> differentiate the identity e<sup>ln x</sup> = x for x &gt; 0. On the left the chain rule gives e<sup>ln x</sup>·(ln x)′ = x·(ln x)′; on the right we get 1. Hence (ln x)′ = 1/x. The same method gives the derivative of any inverse function: (f⁻¹)′(y) = 1/f′(x).'),
      L('<b>Darajali funksiya:</b> x &gt; 0 da xⁿ = e<sup>n ln x</sup>, shuning uchun (xⁿ)′ = e<sup>n ln x</sup>·n/x = nxⁿ⁻¹ — istalgan haqiqiy n uchun.', '<b>Степенная функция:</b> при x &gt; 0 xⁿ = e<sup>n ln x</sup>, поэтому (xⁿ)′ = e<sup>n ln x</sup>·n/x = nxⁿ⁻¹ — для любого действительного n.', '<b>Power function:</b> for x &gt; 0, xⁿ = e<sup>n ln x</sup>, so (xⁿ)′ = e<sup>n ln x</sup>·n/x = nxⁿ⁻¹ — for any real n.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Ichki hosilani unutish.</b> (sin 5x)′ = cos 5x — noto‘g‘ri! To‘g‘ri: 5 cos 5x. Bu eng ko‘p uchraydigan xato.', '<b>Забывать производную внутренней функции.</b> (sin 5x)′ = cos 5x — неверно! Верно: 5 cos 5x. Это самая частая ошибка.', '<b>Forgetting the inner derivative.</b> (sin 5x)′ = cos 5x is wrong! Correct: 5 cos 5x. This is the most common error.'),
      L('<b>Ichki funksiyani ham o‘zgartirib yuborish.</b> (sin(x²))′ = cos(2x) — noto‘g‘ri. Tashqi hosilada ichki ifoda o‘zgarmaydi: cos(x²)·2x.', '<b>Менять и внутреннюю функцию.</b> (sin(x²))′ = cos(2x) — неверно. Во внешней производной внутреннее выражение не меняется: cos(x²)·2x.', '<b>Changing the inner function too.</b> (sin(x²))′ = cos(2x) is wrong. The inner expression stays unchanged in the outer derivative: cos(x²)·2x.'),
      L('<b>Qatlamlar tartibini chalkashtirish.</b> sin² x va sin(x²) — turli funksiyalar: (sin² x)′ = sin 2x, (sin x²)′ = 2x cos x².', '<b>Путать порядок слоёв.</b> sin² x и sin(x²) — разные функции: (sin² x)′ = sin 2x, (sin x²)′ = 2x cos x².', '<b>Mixing up the order of layers.</b> sin² x and sin(x²) are different: (sin² x)′ = sin 2x, (sin x²)′ = 2x cos x².'),
      L('<b>(e<sup>3x</sup>)′ = 3x·e<sup>3x−1</sup> deb yozish.</b> Bu daraja qoidasini ko‘rsatkichli funksiyaga qo‘llash; to‘g‘risi 3e<sup>3x</sup>.', '<b>Писать (e<sup>3x</sup>)′ = 3x·e<sup>3x−1</sup>.</b> Это правило степени для показательной функции; верно 3e<sup>3x</sup>.', '<b>Writing (e<sup>3x</sup>)′ = 3x·e<sup>3x−1</sup>.</b> That applies the power rule to an exponential; correct is 3e<sup>3x</sup>.')
    ] },
    { kind: 'life', h: L('Zanjir qoidasi hayotda', 'Цепное правило в жизни', 'The chain rule in life'), p: [
      L('<b>Havo shari:</b> shar hajmi V = (4/3)πr³, radius esa vaqt o‘tishi bilan o‘sadi. Hajm o‘sish tezligi: V′(t) = 4πr²·r′(t). Agar r = 10 sm va radius 0,5 sm/s tezlikda o‘ssa, V′ = 4π·100·0,5 = 200π ≈ 628 sm³/s.', '<b>Воздушный шар:</b> объём шара V = (4/3)πr³, а радиус растёт со временем. Скорость роста объёма: V′(t) = 4πr²·r′(t). Если r = 10 см и радиус растёт со скоростью 0,5 см/с, то V′ = 4π·100·0,5 = 200π ≈ 628 см³/с.', '<b>Balloon:</b> its volume is V = (4/3)πr³ and the radius grows with time. The volume grows at V′(t) = 4πr²·r′(t). If r = 10 cm and the radius grows at 0.5 cm/s, V′ = 4π·100·0.5 = 200π ≈ 628 cm³/s.'),
      L('<b>Alpinist:</b> havo harorati balandlik bilan har 1 km da taxminan 6,5 °C pasayadi, alpinist esa soatiga 0,4 km ko‘tariladi. Harorat vaqt bo‘yicha qanchalik tez tushadi? dT/dt = dT/dh · dh/dt = (−6,5)·0,4 = −2,6 °C/soat.', '<b>Альпинист:</b> температура воздуха падает с высотой примерно на 6,5 °C на каждый 1 км, а альпинист поднимается на 0,4 км в час. Как быстро падает температура во времени? dT/dt = dT/dh · dh/dt = (−6,5)·0,4 = −2,6 °C/ч.', '<b>Climber:</b> air temperature drops about 6.5 °C per km of height, and a climber ascends 0.4 km per hour. How fast does the temperature fall in time? dT/dt = dT/dh · dh/dt = (−6.5)·0.4 = −2.6 °C/h.'),
      L('<b>Fizika:</b> tebranish x = A sin(ωt) bo‘lsa, tezlik v = Aω cos(ωt) — ω ko‘paytuvchisi aynan ichki funksiya hosilasidan keladi. Shu sababli tez tebranuvchi jismlarning tezligi katta bo‘ladi.', '<b>Физика:</b> при колебании x = A sin(ωt) скорость v = Aω cos(ωt) — множитель ω приходит именно от производной внутренней функции. Поэтому у быстро колеблющихся тел скорость велика.', '<b>Physics:</b> for an oscillation x = A sin(ωt) the velocity is v = Aω cos(ωt) — the factor ω comes from the inner derivative. That is why rapidly oscillating bodies move fast.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Check yourself'), ex: [
      { q: L('((5 − 3x)⁴)′ = ?', '((5 − 3x)⁴)′ = ?', '((5 − 3x)⁴)′ = ?'), s: L('4(5 − 3x)³·(−3) = −12(5 − 3x)³.', '4(5 − 3x)³·(−3) = −12(5 − 3x)³.', '4(5 − 3x)³·(−3) = −12(5 − 3x)³.') },
      { q: L('(e<sup>x²</sup>)′ = ?', '(e<sup>x²</sup>)′ = ?', '(e<sup>x²</sup>)′ = ?'), s: L('2x·e<sup>x²</sup>.', '2x·e<sup>x²</sup>.', '2x·e<sup>x²</sup>.') },
      { q: L('(tg 3x)′ = ?', '(tg 3x)′ = ?', '(tan 3x)′ = ?'), s: L('3/cos² 3x.', '3/cos² 3x.', '3/cos² 3x.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('y = f(g(x)) — murakkab funksiya: g — ichki, f — tashqi.', 'y = f(g(x)) — сложная функция: g — внутренняя, f — внешняя.', 'y = f(g(x)) is composite: g is inner, f is outer.'),
      L('Zanjir qoidasi: (f(g(x)))′ = f′(g(x))·g′(x), dy/dx = dy/du · du/dx.', 'Цепное правило: (f(g(x)))′ = f′(g(x))·g′(x), dy/dx = dy/du · du/dx.', 'Chain rule: (f(g(x)))′ = f′(g(x))·g′(x), dy/dx = dy/du · du/dx.'),
      L('Chiziqli ichki funksiya: (f(kx + b))′ = k·f′(kx + b).', 'Линейная внутренняя функция: (f(kx + b))′ = k·f′(kx + b).', 'Linear inner function: (f(kx + b))′ = k·f′(kx + b).'),
      L('Ko‘p qatlamda hosilalar ketma-ket ko‘paytiriladi, har bir qatlam bitta ko‘paytuvchi beradi.', 'При многих слоях производные перемножаются последовательно, каждый слой даёт один множитель.', 'With many layers the derivatives multiply in turn, one factor per layer.'),
      L('Eng ko‘p xato — ichki funksiya hosilasini unutish.', 'Самая частая ошибка — забыть производную внутренней функции.', 'The most common mistake is forgetting the inner derivative.')
    ] }
  ] });

  // ---------- t5. Urinma va normal tenglamalari ----------
  T.add(P, 't5', { sections: [
    { kind: 'intro', h: L('Egri chiziqqa «tegib o‘tuvchi» to‘g‘ri chiziq', 'Прямая, которая «касается» кривой', 'A line that “touches” a curve'), p: [
      L('Charxda pichoq charxlanayotganda uchqunlar qayoqqa uchadi? Ular aylanaga o‘tkazilgan urinma bo‘ylab uchadi. Bolg‘a uloqtiruvchi sportchi qo‘lini qo‘yib yuborganda, snaryad ham aylanaga urinma yo‘nalishida uchib ketadi. Burilishda avtomobil faralari ham yo‘lni emas, urinma yo‘nalishini yoritadi.', 'Куда летят искры, когда нож точат на точильном круге? По касательной к окружности. Когда метатель молота отпускает снаряд, тот улетает по касательной к окружности. На повороте фары автомобиля освещают не дорогу, а направление касательной.', 'Where do sparks fly when a knife is sharpened on a grinding wheel? Along the tangent to the circle. When a hammer thrower lets go, the hammer flies off along the tangent. On a bend, a car’s headlights light up not the road but the tangent direction.'),
      L('Aylana uchun urinmani 8-sinfdan bilasiz: u aylana bilan bitta umumiy nuqtaga ega va radiusga perpendikulyar. Ammo ixtiyoriy egri chiziq uchun «bitta umumiy nuqta» ta’rifi yaramaydi: y = x³ grafigining (1; 1) nuqtadagi urinmasi grafikni yana bir nuqtada kesib o‘tadi, y = x² ga esa Oy ga parallel to‘g‘ri chiziq bitta nuqtada kesishadi, lekin urinma emas.', 'Касательную к окружности вы знаете с 8 класса: у неё одна общая точка с окружностью и она перпендикулярна радиусу. Но для произвольной кривой определение «одна общая точка» не годится: касательная к графику y = x³ в точке (1; 1) пересекает график ещё в одной точке, а прямая, параллельная Oy, пересекает y = x² в одной точке, но касательной не является.', 'You know the tangent to a circle from grade 8: it has one common point with the circle and is perpendicular to the radius. But for an arbitrary curve “one common point” does not work: the tangent to y = x³ at (1; 1) cuts the graph at another point, while a line parallel to Oy meets y = x² at one point but is not a tangent.'),
      L('Hosila bu muammoni hal qiladi: urinma — kesuvchilarning limit holati, uning qiyaligi f′(x₀). Bu mavzuda urinma va unga perpendikulyar bo‘lgan <b>normal</b> tenglamalarini yozishni o‘rganamiz.', 'Производная решает эту проблему: касательная — предельное положение секущих, её наклон равен f′(x₀). В этой теме мы научимся записывать уравнения касательной и перпендикулярной ей <b>нормали</b>.', 'The derivative solves the problem: the tangent is the limiting position of secants and its slope is f′(x₀). In this topic we learn to write the equations of the tangent and of the <b>normal</b>, the line perpendicular to it.')
    ] },
    { kind: 'def', h: L('Urinma tenglamasi', 'Уравнение касательной', 'Equation of the tangent'), p: [
      L('y = f(x) funksiya x₀ nuqtada differensiallanuvchi bo‘lsin. Grafikning M(x₀; f(x₀)) nuqtasidagi <b>urinma</b> — M nuqtadan o‘tuvchi va burchak koeffitsiyenti k = f′(x₀) bo‘lgan to‘g‘ri chiziq.', 'Пусть функция y = f(x) дифференцируема в точке x₀. <b>Касательная</b> к графику в точке M(x₀; f(x₀)) — прямая, проходящая через M с угловым коэффициентом k = f′(x₀).', 'Let y = f(x) be differentiable at x₀. The <b>tangent</b> to the graph at M(x₀; f(x₀)) is the line through M with slope k = f′(x₀).'),
      L('Nuqta va qiyalik orqali to‘g‘ri chiziq tenglamasi y − y₀ = k(x − x₀) ekanini bilamiz. Shuning uchun urinma tenglamasi: <b>y = f(x₀) + f′(x₀)(x − x₀)</b>.', 'Мы знаем уравнение прямой по точке и наклону: y − y₀ = k(x − x₀). Поэтому уравнение касательной: <b>y = f(x₀) + f′(x₀)(x − x₀)</b>.', 'We know the point–slope equation of a line: y − y₀ = k(x − x₀). So the tangent equation is <b>y = f(x₀) + f′(x₀)(x − x₀)</b>.'),
      L('Formulada uchta son ishtirok etadi: x₀ (urinish nuqtasining abssissasi), f(x₀) (uning ordinatasi) va f′(x₀) (qiyalik). Masalaning qaysi turi bo‘lmasin, avvalo shu uchta sonni topish kerak. Agar f′(x₀) = 0 bo‘lsa, urinma gorizontal: y = f(x₀).', 'В формуле участвуют три числа: x₀ (абсцисса точки касания), f(x₀) (её ордината) и f′(x₀) (наклон). Какой бы ни была задача, сначала нужно найти эти три числа. Если f′(x₀) = 0, касательная горизонтальна: y = f(x₀).', 'The formula involves three numbers: x₀ (the abscissa of the point of tangency), f(x₀) (its ordinate) and f′(x₀) (the slope). Whatever the problem, first find these three numbers. If f′(x₀) = 0, the tangent is horizontal: y = f(x₀).')
    ] },
    { kind: 'def', h: L('Normal tenglamasi', 'Уравнение нормали', 'Equation of the normal'), p: [
      L('Grafikning M nuqtasidagi <b>normali</b> — M dan o‘tuvchi va shu nuqtadagi urinmaga perpendikulyar bo‘lgan to‘g‘ri chiziq. Ikki to‘g‘ri chiziq perpendikulyar bo‘lishi uchun ularning qiyaliklari ko‘paytmasi −1 ga teng bo‘lishi kerak: k₁·k₂ = −1.', '<b>Нормаль</b> к графику в точке M — прямая, проходящая через M перпендикулярно касательной в этой точке. Две прямые перпендикулярны, если произведение их угловых коэффициентов равно −1: k₁·k₂ = −1.', 'The <b>normal</b> to the graph at M is the line through M perpendicular to the tangent there. Two lines are perpendicular when the product of their slopes is −1: k₁·k₂ = −1.'),
      L('Demak, f′(x₀) ≠ 0 bo‘lsa, normalning qiyaligi −1/f′(x₀) va tenglamasi: <b>y = f(x₀) − (x − x₀)/f′(x₀)</b>.', 'Значит, при f′(x₀) ≠ 0 наклон нормали равен −1/f′(x₀), а уравнение: <b>y = f(x₀) − (x − x₀)/f′(x₀)</b>.', 'So if f′(x₀) ≠ 0 the normal has slope −1/f′(x₀) and equation <b>y = f(x₀) − (x − x₀)/f′(x₀)</b>.'),
      L('Agar f′(x₀) = 0 bo‘lsa (urinma gorizontal), normal vertikal bo‘ladi: x = x₀. «Normal» so‘zi lotincha <i>norma</i> — «duradgor go‘niyasi» (to‘g‘ri burchak o‘lchagich) so‘zidan olingan.', 'Если f′(x₀) = 0 (касательная горизонтальна), нормаль вертикальна: x = x₀. Слово «нормаль» происходит от латинского <i>norma</i> — «плотницкий угольник».', 'If f′(x₀) = 0 (horizontal tangent), the normal is vertical: x = x₀. The word “normal” comes from the Latin <i>norma</i>, a “carpenter’s square”.')
    ] },
    { kind: 'history', h: L('Urinma masalasi tarixi', 'История задачи о касательной', 'History of the tangent problem'), p: [
      L('Konus kesimlariga (ellips, parabola, giperbola) urinmalarni Pergalik Apolloniy mil. av. III–II asrlarda o‘rgangan, ammo har bir egri chiziq uchun alohida, murakkab geometrik usul bilan. Umumiy usul faqat XVII asrda, koordinatalar paydo bo‘lgach yaratildi.', 'Касательные к коническим сечениям (эллипсу, параболе, гиперболе) изучал Аполлоний Пергский в III–II вв. до н. э., но для каждой кривой отдельным, сложным геометрическим способом. Общий метод появился лишь в XVII веке, с появлением координат.', 'Apollonius of Perga studied tangents to the conic sections (ellipse, parabola, hyperbola) in the 3rd–2nd centuries BC, but with a separate, intricate geometric method for each curve. A general method appeared only in the 17th century, after coordinates were invented.'),
      L('Rene Dekart 1637-yilgi «Geometriya»sida normalni topish usulini taklif qildi: egri chiziqqa nuqtada «tegib turadigan» aylana chizib, uning radiusini normal deb oldi. U bu masalani «geometriyadagi eng foydali va eng umumiy masala» deb atagan. Per Ferma esa qulayroq usul — hozirgi hosilaga juda yaqin «adekvatlik» usulini qo‘llagan.', 'Рене Декарт в «Геометрии» 1637 года предложил способ нахождения нормали: он строил окружность, «касающуюся» кривой в точке, и брал её радиус за нормаль. Он называл эту задачу «самой полезной и самой общей в геометрии». Пьер Ферма применял более удобный метод «адекватности», очень близкий к современной производной.', 'René Descartes, in his 1637 “Geometry”, proposed finding the normal by drawing a circle that “touches” the curve at the point and taking its radius as the normal. He called it “the most useful and most general problem in geometry”. Pierre de Fermat used a handier “adequality” method, very close to today’s derivative.'),
      L('Nyutonning ustozi Isaak Barrou 1670-yilda urinma qiyaligini «xarakteristik uchburchak» (Δx, Δy va kesuvchi bo‘lagi) orqali topdi. Bu uchburchak Leybnitsni ham ilhomlantirib, differensial hisobning yaratilishiga turtki bo‘ldi.', 'Учитель Ньютона Исаак Барроу в 1670 году находил наклон касательной через «характеристический треугольник» (Δx, Δy и отрезок секущей). Этот треугольник вдохновил и Лейбница и дал толчок созданию дифференциального исчисления.', 'Newton’s teacher Isaac Barrow found the slope of the tangent in 1670 through the “characteristic triangle” (Δx, Δy and a piece of the secant). This triangle also inspired Leibniz and spurred the creation of differential calculus.')
    ] },
    { kind: 'steps', h: L('Urinma tenglamasini tuzish algoritmi', 'Алгоритм составления уравнения касательной', 'Algorithm for the tangent equation'), list: [
      L('1) Urinish nuqtasining abssissasi x₀ ni aniqlang (berilgan yoki shartdan topiladi).', '1) Определите абсциссу точки касания x₀ (дана или находится из условия).', '1) Determine the abscissa x₀ of the point of tangency (given or found from the condition).'),
      L('2) f(x₀) ni hisoblang.', '2) Вычислите f(x₀).', '2) Compute f(x₀).'),
      L('3) f′(x) ni toping va f′(x₀) ni hisoblang.', '3) Найдите f′(x) и вычислите f′(x₀).', '3) Find f′(x) and compute f′(x₀).'),
      L('4) Sonlarni y = f(x₀) + f′(x₀)(x − x₀) formulaga qo‘ying.', '4) Подставьте числа в формулу y = f(x₀) + f′(x₀)(x − x₀).', '4) Substitute into y = f(x₀) + f′(x₀)(x − x₀).'),
      L('5) y = kx + b ko‘rinishiga keltiring va tekshiring: x = x₀ da y = f(x₀) chiqishi kerak.', '5) Приведите к виду y = kx + b и проверьте: при x = x₀ должно получиться y = f(x₀).', '5) Bring it to the form y = kx + b and check: x = x₀ must give y = f(x₀).')
    ], after: [
      L('Agar urinma berilgan to‘g‘ri chiziqqa parallel bo‘lishi talab qilinsa, f′(x₀) = k tenglamani yechib x₀ ni topasiz. Perpendikulyar bo‘lsa — f′(x₀) = −1/k.', 'Если касательная должна быть параллельна данной прямой, решите уравнение f′(x₀) = k и найдите x₀. Если перпендикулярна — f′(x₀) = −1/k.', 'If the tangent must be parallel to a given line, solve f′(x₀) = k for x₀. If it must be perpendicular, solve f′(x₀) = −1/k.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('y = x² parabolaga x₀ = 3 nuqtada urinma va normal tenglamalarini yozing.', 'Запишите уравнения касательной и нормали к параболе y = x² в точке x₀ = 3.', 'Write the tangent and normal to y = x² at x₀ = 3.'),
        s: L('f(3) = 9, f′(x) = 2x, f′(3) = 6. Urinma: y = 9 + 6(x − 3) = <b>6x − 9</b>. Normal: y = 9 − (x − 3)/6 = <b>−x/6 + 9,5</b>.', 'f(3) = 9, f′(x) = 2x, f′(3) = 6. Касательная: y = 9 + 6(x − 3) = <b>6x − 9</b>. Нормаль: y = 9 − (x − 3)/6 = <b>−x/6 + 9,5</b>.', 'f(3) = 9, f′(x) = 2x, f′(3) = 6. Tangent: y = 9 + 6(x − 3) = <b>6x − 9</b>. Normal: y = 9 − (x − 3)/6 = <b>−x/6 + 9.5</b>.') },
      { q: L('y = x³ − 2x ga x₀ = 1 nuqtada urinma va normal.', 'Касательная и нормаль к y = x³ − 2x в точке x₀ = 1.', 'Tangent and normal to y = x³ − 2x at x₀ = 1.'),
        s: L('f(1) = 1 − 2 = −1, f′(x) = 3x² − 2, f′(1) = 1. Urinma: y = −1 + (x − 1) = <b>x − 2</b>. Normal: y = −1 − (x − 1) = <b>−x</b>.', 'f(1) = 1 − 2 = −1, f′(x) = 3x² − 2, f′(1) = 1. Касательная: y = −1 + (x − 1) = <b>x − 2</b>. Нормаль: y = −1 − (x − 1) = <b>−x</b>.', 'f(1) = 1 − 2 = −1, f′(x) = 3x² − 2, f′(1) = 1. Tangent: y = −1 + (x − 1) = <b>x − 2</b>. Normal: y = −1 − (x − 1) = <b>−x</b>.') },
      { q: L('y = x² ga y = 4x − 1 to‘g‘ri chiziqqa parallel urinma o‘tkazing.', 'Проведите к y = x² касательную, параллельную прямой y = 4x − 1.', 'Draw a tangent to y = x² parallel to y = 4x − 1.'),
        s: L('Parallel ⇒ k = 4: 2x₀ = 4, x₀ = 2, f(2) = 4. Urinma: y = 4 + 4(x − 2) = <b>4x − 4</b>.', 'Параллельна ⇒ k = 4: 2x₀ = 4, x₀ = 2, f(2) = 4. Касательная: y = 4 + 4(x − 2) = <b>4x − 4</b>.', 'Parallel ⇒ k = 4: 2x₀ = 4, x₀ = 2, f(2) = 4. Tangent: y = 4 + 4(x − 2) = <b>4x − 4</b>.') },
      { q: L('y = x² ga grafikda yotmagan A(0; −4) nuqtadan urinmalar o‘tkazing.', 'Проведите к y = x² касательные из точки A(0; −4), не лежащей на графике.', 'Draw tangents to y = x² from the point A(0; −4), which is not on the graph.'),
        s: L('x₀ dagi urinma: y = x₀² + 2x₀(x − x₀) = 2x₀x − x₀². A dan o‘tadi: −4 = −x₀², x₀ = ±2. Javob: <b>y = 4x − 4</b> va <b>y = −4x − 4</b>.', 'Касательная в x₀: y = x₀² + 2x₀(x − x₀) = 2x₀x − x₀². Проходит через A: −4 = −x₀², x₀ = ±2. Ответ: <b>y = 4x − 4</b> и <b>y = −4x − 4</b>.', 'Tangent at x₀: y = x₀² + 2x₀(x − x₀) = 2x₀x − x₀². Through A: −4 = −x₀², x₀ = ±2. Answer: <b>y = 4x − 4</b> and <b>y = −4x − 4</b>.') },
      { q: L('y = x³ − 3x grafigining qaysi nuqtalarida urinma gorizontal?', 'В каких точках графика y = x³ − 3x касательная горизонтальна?', 'At which points of y = x³ − 3x is the tangent horizontal?'),
        s: L('f′(x) = 3x² − 3 = 0 ⇒ x = ±1. f(1) = −2, f(−1) = 2. Nuqtalar <b>(1; −2)</b> va <b>(−1; 2)</b>, urinmalar y = −2 va y = 2.', 'f′(x) = 3x² − 3 = 0 ⇒ x = ±1. f(1) = −2, f(−1) = 2. Точки <b>(1; −2)</b> и <b>(−1; 2)</b>, касательные y = −2 и y = 2.', 'f′(x) = 3x² − 3 = 0 ⇒ x = ±1. f(1) = −2, f(−1) = 2. Points <b>(1; −2)</b> and <b>(−1; 2)</b>, tangents y = −2 and y = 2.') }
    ] },
    { kind: 'rule', h: L('Urinmaning qiyalik burchagi', 'Угол наклона касательной', 'Angle of inclination of the tangent'), p: [
      L('f′(x₀) = tg α bo‘lgani uchun urinmaning Ox o‘qi bilan burchagini topish mumkin: α = arctg f′(x₀). Masalan, y = sin x grafigiga x₀ = 0 da f′(0) = cos 0 = 1, demak urinma y = x va α = 45°. Ya’ni sinusoida koordinatalar boshidan 45° burchak ostida o‘tadi.', 'Поскольку f′(x₀) = tg α, можно найти угол касательной с осью Ox: α = arctg f′(x₀). Например, для y = sin x при x₀ = 0 f′(0) = cos 0 = 1, значит касательная y = x и α = 45°. То есть синусоида проходит через начало координат под углом 45°.', 'Since f′(x₀) = tan α, we can find the tangent’s angle with Ox: α = arctan f′(x₀). For y = sin x at x₀ = 0, f′(0) = cos 0 = 1, so the tangent is y = x and α = 45°: the sine curve passes through the origin at 45°.'),
      L('Ikki egri chiziq orasidagi burchak deb ularning kesishish nuqtasidagi urinmalar orasidagi burchakka aytiladi. Agar urinmalar perpendikulyar bo‘lsa (k₁k₂ = −1), egri chiziqlar «to‘g‘ri burchak ostida» kesishadi. Masalan, y = x² va y = x egri chiziqlari (1; 1) da kesishadi; qiyaliklar 2 va 1, tg φ = |2 − 1|/(1 + 2·1) = 1/3, φ ≈ 18,4°.', 'Углом между двумя кривыми называют угол между касательными к ним в точке пересечения. Если касательные перпендикулярны (k₁k₂ = −1), кривые пересекаются «под прямым углом». Например, y = x² и y = x пересекаются в (1; 1); наклоны 2 и 1, tg φ = |2 − 1|/(1 + 2·1) = 1/3, φ ≈ 18,4°.', 'The angle between two curves is the angle between their tangents at the intersection point. If the tangents are perpendicular (k₁k₂ = −1), the curves cross “at right angles”. For example, y = x² and y = x meet at (1; 1); the slopes are 2 and 1, tan φ = |2 − 1|/(1 + 2·1) = 1/3, φ ≈ 18.4°.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Formulaga f′(x) ni (umumiy ko‘rinishda) qo‘yish.</b> y = f(x₀) + f′(x)(x − x₀) — bu to‘g‘ri chiziq emas! f′ ni albatta x₀ nuqtada hisoblash kerak.', '<b>Подставлять в формулу f′(x) в общем виде.</b> y = f(x₀) + f′(x)(x − x₀) — это не прямая! f′ обязательно вычисляется в точке x₀.', '<b>Putting the general f′(x) into the formula.</b> y = f(x₀) + f′(x)(x − x₀) is not a line! f′ must be evaluated at x₀.'),
      L('<b>Normal qiyaligini −f′(x₀) yoki 1/f′(x₀) deb olish.</b> To‘g‘risi — −1/f′(x₀): ham ishora, ham teskari son.', '<b>Брать наклон нормали равным −f′(x₀) или 1/f′(x₀).</b> Верно −1/f′(x₀): и знак, и обратное число.', '<b>Taking the normal’s slope as −f′(x₀) or 1/f′(x₀).</b> It is −1/f′(x₀): both the sign and the reciprocal.'),
      L('<b>A nuqta grafikda yotmasa ham, uni urinish nuqtasi deb olish.</b> Avval tekshiring: f(x_A) = y_A mi? Yotmasa — x₀ ni noma’lum deb, urinma A dan o‘tish shartidan toping.', '<b>Считать точку A точкой касания, даже если она не лежит на графике.</b> Сначала проверьте: f(x_A) = y_A? Если нет — x₀ неизвестно, найдите его из условия прохождения касательной через A.', '<b>Treating A as the point of tangency even when it is not on the graph.</b> First check whether f(x_A) = y_A. If not, x₀ is unknown — find it from the condition that the tangent passes through A.'),
      L('<b>Qavslarni ochishda ishorani yo‘qotish.</b> y = 9 + 6(x − 3) = 6x − 9, «6x + 9» emas. Tekshiruv: x = 3 da 9 chiqishi kerak.', '<b>Терять знак при раскрытии скобок.</b> y = 9 + 6(x − 3) = 6x − 9, а не «6x + 9». Проверка: при x = 3 должно получиться 9.', '<b>Losing a sign when expanding.</b> y = 9 + 6(x − 3) = 6x − 9, not “6x + 9”. Check: x = 3 must give 9.')
    ] },
    { kind: 'life', h: L('Urinma va normal amalda', 'Касательная и нормаль на практике', 'Tangents and normals in practice'), p: [
      L('<b>Optika:</b> yorug‘likning qaytish va sinish qonunlarida burchaklar sirtga emas, <b>normal</b>ga nisbatan o‘lchanadi. Parabolik antenna va avtomobil farasining ko‘zgusi shunday yasalganki, normal bo‘yicha qaytgan nurlar bitta fokusga yig‘iladi yoki undan parallel tarqaladi.', '<b>Оптика:</b> в законах отражения и преломления света углы отсчитываются не от поверхности, а от <b>нормали</b>. Параболическая антенна и зеркало автомобильной фары устроены так, что отражённые лучи собираются в фокусе или расходятся из него параллельно.', '<b>Optics:</b> in the laws of reflection and refraction, angles are measured not from the surface but from the <b>normal</b>. A satellite dish and a car headlamp mirror are shaped so that reflected rays gather at a focus or leave it in parallel.'),
      L('<b>Yo‘l va temir yo‘l:</b> to‘g‘ri yo‘l burilishga «sakrashsiz» ulanishi uchun burilish egri chizig‘ining boshlanish nuqtasidagi urinmasi to‘g‘ri yo‘l bilan ustma-ust tushishi kerak. Aks holda poyezd yoki mashina keskin turtki oladi.', '<b>Дороги и железные дороги:</b> чтобы прямой участок переходил в поворот «без скачка», касательная к кривой поворота в начальной точке должна совпадать с прямым участком. Иначе поезд или машина получат резкий толчок.', '<b>Roads and railways:</b> for a straight section to join a bend smoothly, the tangent of the bend at its start must coincide with the straight section. Otherwise the train or car gets a sharp jolt.'),
      L('<b>Kompyuter grafikasi:</b> 3D o‘yinlarda sirt yoritilishi har bir nuqtadagi normal vektor orqali hisoblanadi; shrift va logotiplardagi silliq egri chiziqlar (Bezye egri chiziqlari) urinmalar yordamida chiziladi.', '<b>Компьютерная графика:</b> в 3D-играх освещённость поверхности рассчитывается через вектор нормали в каждой точке; плавные кривые шрифтов и логотипов (кривые Безье) строятся с помощью касательных.', '<b>Computer graphics:</b> in 3D games surface lighting is computed from the normal vector at each point; smooth curves in fonts and logos (Bézier curves) are drawn using tangents.')
    ] },
    { kind: 'fact', h: L('Giperbolaning ajoyib xossasi', 'Замечательное свойство гиперболы', 'A remarkable property of the hyperbola'), p: [
      L('y = 1/x giperbolaga x₀ = 1 da urinma: f(1) = 1, f′(1) = −1, y = 2 − x. U o‘qlarni (2; 0) va (0; 2) da kesadi va ular bilan yuzi 2 ga teng uchburchak hosil qiladi. Umuman, x₀ dagi urinma y = 2/x₀ − x/x₀² o‘qlarni 2x₀ va 2/x₀ da kesadi, yuz (1/2)·2x₀·(2/x₀) = 2.', 'Касательная к гиперболе y = 1/x при x₀ = 1: f(1) = 1, f′(1) = −1, y = 2 − x. Она пересекает оси в (2; 0) и (0; 2) и образует с ними треугольник площади 2. Вообще касательная в x₀: y = 2/x₀ − x/x₀² пересекает оси в 2x₀ и 2/x₀, площадь (1/2)·2x₀·(2/x₀) = 2.', 'The tangent to y = 1/x at x₀ = 1: f(1) = 1, f′(1) = −1, y = 2 − x. It cuts the axes at (2; 0) and (0; 2), forming a triangle of area 2. In general the tangent at x₀, y = 2/x₀ − x/x₀², cuts the axes at 2x₀ and 2/x₀, area (1/2)·2x₀·(2/x₀) = 2.'),
      L('Demak, giperbolaning <b>istalgan</b> urinmasi o‘qlar bilan bir xil yuzli (2) uchburchak hosil qiladi, urinish nuqtasi esa gipotenuzaning o‘rtasida yotadi! Bunday «yashirin» xossalarni hosila yordamida kashf etish juda qiziqarli.', 'Значит, <b>любая</b> касательная к гиперболе образует с осями треугольник одной и той же площади (2), а точка касания лежит в середине гипотенузы! Открывать такие «скрытые» свойства с помощью производной очень интересно.', 'So <b>every</b> tangent to the hyperbola forms a triangle of the same area (2) with the axes, and the point of tangency is the midpoint of the hypotenuse! Discovering such “hidden” properties with the derivative is great fun.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Check yourself'), ex: [
      { q: L('y = √x ga x₀ = 4 da urinma tenglamasi?', 'Уравнение касательной к y = √x при x₀ = 4?', 'Tangent to y = √x at x₀ = 4?'), s: L('f(4) = 2, f′(4) = 1/4: y = 2 + (x − 4)/4 = x/4 + 1.', 'f(4) = 2, f′(4) = 1/4: y = 2 + (x − 4)/4 = x/4 + 1.', 'f(4) = 2, f′(4) = 1/4: y = 2 + (x − 4)/4 = x/4 + 1.') },
      { q: L('y = eˣ ga x₀ = 0 da urinma va normal?', 'Касательная и нормаль к y = eˣ при x₀ = 0?', 'Tangent and normal to y = eˣ at x₀ = 0?'), s: L('f(0) = 1, f′(0) = 1: urinma y = x + 1, normal y = −x + 1.', 'f(0) = 1, f′(0) = 1: касательная y = x + 1, нормаль y = −x + 1.', 'f(0) = 1, f′(0) = 1: tangent y = x + 1, normal y = −x + 1.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Urinma: y = f(x₀) + f′(x₀)(x − x₀); qiyaligi k = f′(x₀) = tg α.', 'Касательная: y = f(x₀) + f′(x₀)(x − x₀); наклон k = f′(x₀) = tg α.', 'Tangent: y = f(x₀) + f′(x₀)(x − x₀); slope k = f′(x₀) = tan α.'),
      L('Normal: y = f(x₀) − (x − x₀)/f′(x₀); qiyaligi −1/f′(x₀).', 'Нормаль: y = f(x₀) − (x − x₀)/f′(x₀); наклон −1/f′(x₀).', 'Normal: y = f(x₀) − (x − x₀)/f′(x₀); slope −1/f′(x₀).'),
      L('Uchta son kerak: x₀, f(x₀), f′(x₀).', 'Нужны три числа: x₀, f(x₀), f′(x₀).', 'Three numbers are needed: x₀, f(x₀), f′(x₀).'),
      L('Parallel urinma: f′(x₀) = k; perpendikulyar: f′(x₀) = −1/k; gorizontal: f′(x₀) = 0.', 'Параллельная касательная: f′(x₀) = k; перпендикулярная: f′(x₀) = −1/k; горизонтальная: f′(x₀) = 0.', 'Parallel tangent: f′(x₀) = k; perpendicular: f′(x₀) = −1/k; horizontal: f′(x₀) = 0.'),
      L('Grafikdan tashqaridagi nuqtadan urinma: x₀ noma’lum, tenglamadan topiladi.', 'Касательная из точки вне графика: x₀ неизвестно и находится из уравнения.', 'Tangent from a point off the graph: x₀ is unknown and found from an equation.')
    ] }
  ] });

  // ---------- t6. Hosila yordamida funksiyani tekshirish va grafik yasash ----------
  T.add(P, 't6', { sections: [
    { kind: 'intro', h: L('Grafikni «ko‘rmasdan» chizish', 'Нарисовать график, «не видя» его', 'Drawing a graph “without seeing” it'), p: [
      L('y = x³ − 3x funksiyasining grafigini chizish uchun nechta nuqta kerak? Agar tasodifiy 5–6 nuqtani olsak, eng muhim joylarni — grafik «tepalik» va «chuqurlik» hosil qiladigan nuqtalarni — o‘tkazib yuborishimiz mumkin. Natijada chizma butunlay noto‘g‘ri chiqadi.', 'Сколько точек нужно, чтобы построить график y = x³ − 3x? Если взять 5–6 случайных точек, можно пропустить самые важные места — точки, где график образует «горку» и «ямку». Тогда рисунок получится совершенно неверным.', 'How many points do you need to sketch y = x³ − 3x? If you take 5–6 random points, you may miss the most important places — where the graph forms a “hill” and a “valley”. Then the sketch will be completely wrong.'),
      L('Hosila bizga funksiyaning «xarakterini» aytib beradi: qayerda o‘sadi, qayerda kamayadi, qayerda burilib, eng yuqori yoki eng past qiymatga erishadi. Tog‘ yo‘lida ketayotgan sayyohni tasavvur qiling: oyog‘i ostidagi qiyalik musbat bo‘lsa — u ko‘tarilmoqda, manfiy bo‘lsa — tushmoqda, nol bo‘lsa — u cho‘qqida yoki vodiy tubida.', 'Производная рассказывает нам о «характере» функции: где она возрастает, где убывает, где поворачивает и достигает наибольшего или наименьшего значения. Представьте туриста на горной тропе: если уклон под ногами положителен — он поднимается, отрицателен — спускается, равен нулю — он на вершине или на дне долины.', 'The derivative tells us the “character” of a function: where it increases, where it decreases, where it turns and reaches its highest or lowest value. Picture a hiker on a mountain path: if the slope underfoot is positive he is climbing, if negative he is descending, if zero he is at a summit or at the bottom of a valley.'),
      L('Bu mavzuda hosila ishorasi bo‘yicha funksiyaning o‘sish va kamayish oraliqlarini, ekstremum nuqtalarini topishni va to‘liq tekshirish rejasi asosida grafik yasashni o‘rganamiz.', 'В этой теме мы научимся по знаку производной находить промежутки возрастания и убывания, точки экстремума и строить график по полному плану исследования.', 'In this topic we learn to find intervals of increase and decrease and extreme points from the sign of the derivative, and to sketch graphs following a full study plan.')
    ] },
    { kind: 'rule', h: L('Monotonlik alomati', 'Признак монотонности', 'Test for monotonicity'), p: [
      L('<b>Teorema.</b> Agar (a; b) oraliqning har bir nuqtasida f′(x) &gt; 0 bo‘lsa, f funksiya shu oraliqda <b>o‘sadi</b>; agar f′(x) &lt; 0 bo‘lsa — <b>kamayadi</b>; agar f′(x) = 0 bo‘lsa — o‘zgarmas.', '<b>Теорема.</b> Если в каждой точке промежутка (a; b) f′(x) &gt; 0, то f на этом промежутке <b>возрастает</b>; если f′(x) &lt; 0 — <b>убывает</b>; если f′(x) = 0 — постоянна.', '<b>Theorem.</b> If f′(x) &gt; 0 at every point of (a; b), then f <b>increases</b> on that interval; if f′(x) &lt; 0 it <b>decreases</b>; if f′(x) = 0 it is constant.'),
      L('<b>Isbot g‘oyasi</b> Lagranjning o‘rta qiymat haqidagi teoremasiga tayanadi: x₁ &lt; x₂ uchun (x₁; x₂) da shunday c nuqta topiladiki, f(x₂) − f(x₁) = f′(c)(x₂ − x₁). Agar f′(c) &gt; 0 bo‘lsa, o‘ng tomon musbat, ya’ni f(x₂) &gt; f(x₁) — funksiya o‘smoqda. Geometrik ma’nosi: grafikda kesuvchiga parallel urinma albatta mavjud.', '<b>Идея доказательства</b> опирается на теорему Лагранжа о среднем значении: для x₁ &lt; x₂ на (x₁; x₂) найдётся точка c, такая что f(x₂) − f(x₁) = f′(c)(x₂ − x₁). Если f′(c) &gt; 0, правая часть положительна, т. е. f(x₂) &gt; f(x₁) — функция возрастает. Геометрически: на графике обязательно есть касательная, параллельная секущей.', 'The <b>proof idea</b> relies on Lagrange’s mean value theorem: for x₁ &lt; x₂ there is a point c in (x₁; x₂) with f(x₂) − f(x₁) = f′(c)(x₂ − x₁). If f′(c) &gt; 0, the right side is positive, so f(x₂) &gt; f(x₁) — the function increases. Geometrically: there is always a tangent parallel to the secant.'),
      L('Eslatma: alomat yetarli, lekin zarur emas. y = x³ hamma joyda o‘sadi, ammo x = 0 da f′(0) = 0. Alohida nuqtalarda hosila nolga teng bo‘lishi o‘sishga xalaqit bermaydi.', 'Замечание: признак достаточный, но не необходимый. y = x³ возрастает всюду, но f′(0) = 0. Обращение производной в нуль в отдельных точках не мешает возрастанию.', 'Note: the test is sufficient but not necessary. y = x³ increases everywhere, yet f′(0) = 0. A derivative vanishing at isolated points does not prevent increase.')
    ] },
    { kind: 'def', h: L('Kritik nuqta va ekstremum', 'Критическая точка и экстремум', 'Critical point and extremum'), p: [
      L('x₀ nuqtaning biror atrofidagi barcha x uchun f(x) ≤ f(x₀) bo‘lsa, x₀ — <b>maksimum nuqtasi</b>; f(x) ≥ f(x₀) bo‘lsa — <b>minimum nuqtasi</b>. Ular birgalikda <b>ekstremum nuqtalari</b>, funksiyaning ulardagi qiymatlari esa <b>ekstremumlar</b> deyiladi. Bu «mahalliy» tushuncha: maksimum funksiyaning eng katta qiymati bo‘lishi shart emas.', 'Если для всех x из некоторой окрестности точки x₀ f(x) ≤ f(x₀), то x₀ — <b>точка максимума</b>; если f(x) ≥ f(x₀) — <b>точка минимума</b>. Вместе они — <b>точки экстремума</b>, а значения функции в них — <b>экстремумы</b>. Это «местное» понятие: максимум не обязан быть наибольшим значением функции.', 'If f(x) ≤ f(x₀) for all x in some neighbourhood of x₀, then x₀ is a <b>maximum point</b>; if f(x) ≥ f(x₀), a <b>minimum point</b>. Together they are <b>extreme points</b>, and the function values there are <b>extrema</b>. This is a “local” notion: a maximum need not be the greatest value of the function.'),
      L('<b>Ferma teoremasi (zaruriy shart).</b> Agar x₀ ekstremum nuqtasi bo‘lsa va f′(x₀) mavjud bo‘lsa, f′(x₀) = 0. Ya’ni silliq «cho‘qqi»da urinma gorizontal.', '<b>Теорема Ферма (необходимое условие).</b> Если x₀ — точка экстремума и f′(x₀) существует, то f′(x₀) = 0. То есть на гладкой «вершине» касательная горизонтальна.', '<b>Fermat’s theorem (necessary condition).</b> If x₀ is an extreme point and f′(x₀) exists, then f′(x₀) = 0: at a smooth “peak” the tangent is horizontal.'),
      L('f′(x) = 0 bo‘lgan yoki f′(x) mavjud bo‘lmagan ichki nuqtalar <b>kritik nuqtalar</b> deyiladi. Ekstremumlar faqat kritik nuqtalar orasidan izlanadi, lekin har bir kritik nuqta ekstremum emas.', 'Внутренние точки, где f′(x) = 0 или f′(x) не существует, называются <b>критическими</b>. Экстремумы ищут только среди критических точек, но не всякая критическая точка — экстремум.', 'Interior points where f′(x) = 0 or f′(x) does not exist are called <b>critical points</b>. Extrema are sought only among critical points, but not every critical point is an extremum.')
    ] },
    { kind: 'rule', h: L('Ekstremumning yetarli sharti', 'Достаточное условие экстремума', 'Sufficient condition for an extremum'), p: [
      L('f funksiya x₀ kritik nuqtada uzluksiz bo‘lsin. x₀ dan o‘tishda (chapdan o‘ngga):', 'Пусть f непрерывна в критической точке x₀. При переходе через x₀ (слева направо):', 'Let f be continuous at a critical point x₀. When passing through x₀ (left to right):')
    ], list: [
      L('f′ ishorasi «+» dan «−» ga o‘zgarsa — x₀ <b>maksimum</b> nuqtasi (avval o‘sib, keyin kamayadi);', 'знак f′ меняется с «+» на «−» — x₀ точка <b>максимума</b> (сначала возрастает, затем убывает);', 'if f′ changes sign from “+” to “−”, x₀ is a <b>maximum</b> (first increasing, then decreasing);'),
      L('f′ ishorasi «−» dan «+» ga o‘zgarsa — x₀ <b>minimum</b> nuqtasi;', 'знак f′ меняется с «−» на «+» — x₀ точка <b>минимума</b>;', 'if from “−” to “+”, x₀ is a <b>minimum</b>;'),
      L('ishora o‘zgarmasa — ekstremum yo‘q (masalan, y = x³ da x = 0).', 'знак не меняется — экстремума нет (например, y = x³ при x = 0).', 'if the sign does not change, there is no extremum (e.g. y = x³ at x = 0).')
    ], after: [
      L('Ikkinchi hosila bo‘yicha alomat ham bor: f′(x₀) = 0 va f″(x₀) &lt; 0 bo‘lsa — maksimum, f″(x₀) &gt; 0 bo‘lsa — minimum. f″ &gt; 0 bo‘lgan oraliqda grafik pastga qavariq («kosa»), f″ &lt; 0 da — yuqoriga qavariq («gumbaz»).', 'Есть и признак по второй производной: если f′(x₀) = 0 и f″(x₀) &lt; 0 — максимум, f″(x₀) &gt; 0 — минимум. Где f″ &gt; 0, график выпуклый вниз («чаша»), где f″ &lt; 0 — выпуклый вверх («купол»).', 'There is also a second-derivative test: if f′(x₀) = 0 and f″(x₀) &lt; 0 it is a maximum, if f″(x₀) &gt; 0 a minimum. Where f″ &gt; 0 the graph is convex (“a bowl”), where f″ &lt; 0 it is concave (“a dome”).')
    ] },
    { kind: 'steps', h: L('Funksiyani tekshirish rejasi', 'План исследования функции', 'Plan for studying a function'), list: [
      L('1) Aniqlanish sohasi D(f).', '1) Область определения D(f).', '1) Domain D(f).'),
      L('2) Juft-toqligi, davriyligi (simmetriya ishni ikki baravar qisqartiradi).', '2) Чётность, нечётность, периодичность (симметрия вдвое сокращает работу).', '2) Even/odd, periodicity (symmetry halves the work).'),
      L('3) O‘qlar bilan kesishish nuqtalari (f(x) = 0 ning ildizlari va f(0)).', '3) Точки пересечения с осями (корни f(x) = 0 и f(0)).', '3) Intercepts with the axes (roots of f(x) = 0 and f(0)).'),
      L('4) f′(x) ni topish, kritik nuqtalar.', '4) Нахождение f′(x), критические точки.', '4) Find f′(x) and the critical points.'),
      L('5) Ishoralar jadvali: o‘sish va kamayish oraliqlari, ekstremumlar va ularning qiymatlari.', '5) Таблица знаков: промежутки возрастания и убывания, экстремумы и их значения.', '5) Sign chart: intervals of increase and decrease, extrema and their values.'),
      L('6) Chegaraviy xatti-harakat: x → ±∞ da va uzilish nuqtalari yaqinida (asimptotalar).', '6) Поведение на границах: при x → ±∞ и около точек разрыва (асимптоты).', '6) Behaviour at the ends: as x → ±∞ and near breaks (asymptotes).'),
      L('7) Topilgan nuqtalar bo‘yicha grafikni chizish.', '7) Построение графика по найденным точкам.', '7) Sketch the graph from the points found.')
    ] },
    { kind: 'table', h: L('Ishoralar jadvali: f(x) = x³ − 3x', 'Таблица знаков: f(x) = x³ − 3x', 'Sign chart: f(x) = x³ − 3x'), p: [
      L('f′(x) = 3x² − 3 = 3(x − 1)(x + 1), kritik nuqtalar x = −1 va x = 1.', 'f′(x) = 3x² − 3 = 3(x − 1)(x + 1), критические точки x = −1 и x = 1.', 'f′(x) = 3x² − 3 = 3(x − 1)(x + 1), critical points x = −1 and x = 1.')
    ], table: { head: [L('x', 'x', 'x'), L('(−∞; −1)', '(−∞; −1)', '(−∞; −1)'), L('−1', '−1', '−1'), L('(−1; 1)', '(−1; 1)', '(−1; 1)'), L('1', '1', '1'), L('(1; +∞)', '(1; +∞)', '(1; +∞)')], rows: [
      [L('f′(x)', 'f′(x)', 'f′(x)'), '+', '0', '−', '0', '+'],
      [L('f(x)', 'f(x)', 'f(x)'), L('o‘sadi ↗', 'возрастает ↗', 'increases ↗'), L('max = 2', 'max = 2', 'max = 2'), L('kamayadi ↘', 'убывает ↘', 'decreases ↘'), L('min = −2', 'min = −2', 'min = −2'), L('o‘sadi ↗', 'возрастает ↗', 'increases ↗')]
    ] }, after: [
      L('Funksiya toq (grafik koordinatalar boshiga nisbatan simmetrik), nollari x = 0 va x = ±√3 ≈ ±1,73. Endi «tepalik» (−1; 2), «chuqurlik» (1; −2) va nollar orqali silliq egri chiziq chizamiz.', 'Функция нечётная (график симметричен относительно начала координат), нули x = 0 и x = ±√3 ≈ ±1,73. Теперь проводим плавную кривую через «горку» (−1; 2), «ямку» (1; −2) и нули.', 'The function is odd (symmetric about the origin), with zeros x = 0 and x = ±√3 ≈ ±1.73. Now draw a smooth curve through the “hill” (−1; 2), the “valley” (1; −2) and the zeros.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('f(x) = x⁴ − 2x² funksiyani tekshiring.', 'Исследуйте функцию f(x) = x⁴ − 2x².', 'Study f(x) = x⁴ − 2x².'),
        s: L('D = R, funksiya juft. f′ = 4x³ − 4x = 4x(x − 1)(x + 1); kritik: −1, 0, 1. Ishoralar: −, +, −, +. Minimumlar x = ±1 da, f = <b>−1</b>; maksimum x = 0 da, f = <b>0</b>. Nollar: x = 0, x = ±√2. Grafik «W» harfiga o‘xshaydi.', 'D = R, функция чётная. f′ = 4x³ − 4x = 4x(x − 1)(x + 1); критические: −1, 0, 1. Знаки: −, +, −, +. Минимумы при x = ±1, f = <b>−1</b>; максимум при x = 0, f = <b>0</b>. Нули: x = 0, x = ±√2. График похож на букву «W».', 'D = R, the function is even. f′ = 4x³ − 4x = 4x(x − 1)(x + 1); critical: −1, 0, 1. Signs: −, +, −, +. Minima at x = ±1, f = <b>−1</b>; maximum at x = 0, f = <b>0</b>. Zeros: x = 0, x = ±√2. The graph looks like a “W”.') },
      { q: L('f(x) = x + 4/x ning ekstremumlarini toping.', 'Найдите экстремумы f(x) = x + 4/x.', 'Find the extrema of f(x) = x + 4/x.'),
        s: L('D: x ≠ 0. f′ = 1 − 4/x² = (x² − 4)/x²; kritik x = ±2. x &lt; −2: +, (−2; 0): −, (0; 2): −, x &gt; 2: +. Maksimum x = −2 da f = <b>−4</b>, minimum x = 2 da f = <b>4</b>. Qiziq: maksimum minimumdan kichik — chunki ular turli tarmoqlarda!', 'D: x ≠ 0. f′ = 1 − 4/x² = (x² − 4)/x²; критические x = ±2. x &lt; −2: +, (−2; 0): −, (0; 2): −, x &gt; 2: +. Максимум при x = −2, f = <b>−4</b>, минимум при x = 2, f = <b>4</b>. Интересно: максимум меньше минимума — они на разных ветвях!', 'D: x ≠ 0. f′ = 1 − 4/x² = (x² − 4)/x²; critical x = ±2. x &lt; −2: +, (−2; 0): −, (0; 2): −, x &gt; 2: +. Maximum at x = −2, f = <b>−4</b>; minimum at x = 2, f = <b>4</b>. Curiously the maximum is less than the minimum — they lie on different branches!') },
      { q: L('f(x) = x³ funksiyasining ekstremumi bormi?', 'Есть ли экстремум у f(x) = x³?', 'Does f(x) = x³ have an extremum?'),
        s: L('f′ = 3x² = 0 ⇒ x = 0 — kritik nuqta. Ammo f′ ikki tomonda ham musbat, ishora o‘zgarmaydi. <b>Ekstremum yo‘q</b>, funksiya butun to‘g‘ri chiziqda o‘sadi; x = 0 — egilish nuqtasi.', 'f′ = 3x² = 0 ⇒ x = 0 — критическая точка. Но f′ с обеих сторон положительна, знак не меняется. <b>Экстремума нет</b>, функция возрастает на всей прямой; x = 0 — точка перегиба.', 'f′ = 3x² = 0 ⇒ x = 0 is critical. But f′ is positive on both sides; the sign does not change. <b>No extremum</b>: the function increases on the whole line; x = 0 is an inflection point.') },
      { q: L('f(x) = 2x³ − 9x² + 12x − 4 ning o‘sish va kamayish oraliqlari.', 'Промежутки возрастания и убывания f(x) = 2x³ − 9x² + 12x − 4.', 'Intervals of increase and decrease of f(x) = 2x³ − 9x² + 12x − 4.'),
        s: L('f′ = 6x² − 18x + 12 = 6(x − 1)(x − 2). O‘sadi: (−∞; 1] va [2; +∞), kamayadi: [1; 2]. f(1) = 2 − 9 + 12 − 4 = <b>1</b> (max), f(2) = 16 − 36 + 24 − 4 = <b>0</b> (min).', 'f′ = 6x² − 18x + 12 = 6(x − 1)(x − 2). Возрастает: (−∞; 1] и [2; +∞), убывает: [1; 2]. f(1) = 2 − 9 + 12 − 4 = <b>1</b> (max), f(2) = 16 − 36 + 24 − 4 = <b>0</b> (min).', 'f′ = 6x² − 18x + 12 = 6(x − 1)(x − 2). Increasing on (−∞; 1] and [2; +∞), decreasing on [1; 2]. f(1) = 2 − 9 + 12 − 4 = <b>1</b> (max), f(2) = 16 − 36 + 24 − 4 = <b>0</b> (min).') }
    ] },
    { kind: 'history', h: L('Fermadan Lagranjgacha', 'От Ферма до Лагранжа', 'From Fermat to Lagrange'), p: [
      L('Tuluzalik huquqshunos Per Ferma matematika bilan bo‘sh vaqtida shug‘ullangan, ammo XVII asrning eng buyuk matematiklaridan biri bo‘lgan. 1636-yil atrofida yozgan «Maksimum va minimumlarni topish usuli»da u: «maksimum yaqinida funksiya deyarli o‘zgarmaydi» degan g‘oyani ilgari surdi — bu hozirgi f′(x₀) = 0 shartining o‘zi.', 'Тулузский юрист Пьер Ферма занимался математикой в свободное время, но стал одним из величайших математиков XVII века. В «Методе нахождения максимумов и минимумов» (около 1636 года) он выдвинул идею: «вблизи максимума функция почти не меняется» — это и есть современное условие f′(x₀) = 0.', 'Pierre de Fermat, a lawyer from Toulouse, did mathematics in his spare time, yet became one of the greatest mathematicians of the 17th century. In his “Method for Finding Maxima and Minima” (around 1636) he put forward the idea that “near a maximum the function hardly changes” — exactly today’s condition f′(x₀) = 0.'),
      L('Fransuz Mishel Roll 1691-yilda ko‘phadlar uchun teorema isbotladi: agar f(a) = f(b) bo‘lsa, ular orasida f′(c) = 0 bo‘lgan nuqta bor. Lagranj 1797-yilda uni umumlashtirib, o‘rta qiymat teoremasini yaratdi — monotonlik alomatining asosi shu.', 'Француз Мишель Ролль в 1691 году доказал для многочленов теорему: если f(a) = f(b), то между ними есть точка, где f′(c) = 0. Лагранж в 1797 году обобщил её, создав теорему о среднем значении — основу признака монотонности.', 'The Frenchman Michel Rolle proved in 1691, for polynomials, that if f(a) = f(b) there is a point between them with f′(c) = 0. In 1797 Lagrange generalised it into the mean value theorem — the basis of the monotonicity test.'),
      L('Funksiyani to‘liq tekshirish rejasi XIX asr darsliklarida shakllangan. Bugun bu ishni kompyuter soniyalarda bajaradi, ammo natijani to‘g‘ri tushunish uchun inson baribir shu tahlilni bilishi kerak.', 'Полный план исследования функции сложился в учебниках XIX века. Сегодня компьютер делает эту работу за секунды, но чтобы правильно понимать результат, человек всё равно должен владеть таким анализом.', 'The full plan for studying a function took shape in 19th-century textbooks. Today a computer does it in seconds, but to understand the result correctly a person still needs to master this analysis.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>f′(x₀) = 0 bo‘lsa, albatta ekstremum deb hisoblash.</b> y = x³ da x = 0 kritik, lekin ekstremum emas. Ishora o‘zgarishini tekshiring!', '<b>Считать, что при f′(x₀) = 0 обязательно экстремум.</b> У y = x³ точка x = 0 критическая, но не экстремум. Проверяйте смену знака!', '<b>Assuming f′(x₀) = 0 always means an extremum.</b> For y = x³, x = 0 is critical but not an extremum. Check the sign change!'),
      L('<b>Hosila mavjud bo‘lmagan nuqtalarni unutish.</b> y = |x| ning minimumi x = 0 da, garchi u yerda f′ yo‘q.', '<b>Забывать точки, где производная не существует.</b> У y = |x| минимум при x = 0, хотя f′ там нет.', '<b>Forgetting points where the derivative does not exist.</b> y = |x| has its minimum at x = 0, although f′ does not exist there.'),
      L('<b>Aniqlanish sohasini hisobga olmaslik.</b> x + 4/x da x = 0 kritik nuqta emas — u sohaga kirmaydi, lekin ishora jadvalida chegarasi bo‘lib qoladi.', '<b>Не учитывать область определения.</b> У x + 4/x точка x = 0 не критическая — она не входит в область, но остаётся границей в таблице знаков.', '<b>Ignoring the domain.</b> For x + 4/x, x = 0 is not a critical point — it is outside the domain, yet it remains a boundary in the sign chart.'),
      L('<b>Ekstremum nuqtasi va ekstremum qiymatini aralashtirish.</b> «Maksimum nuqtasi x = −1, maksimum qiymati f(−1) = 2» — ikkalasini ham aniq yozing.', '<b>Путать точку экстремума и значение экстремума.</b> «Точка максимума x = −1, максимум f(−1) = 2» — пишите оба чётко.', '<b>Confusing the extreme point with the extreme value.</b> “The maximum point is x = −1, the maximum value is f(−1) = 2” — state both clearly.')
    ] },
    { kind: 'life', h: L('Grafik tahlili hayotda', 'Анализ графиков в жизни', 'Graph analysis in life'), p: [
      L('<b>Tibbiyot:</b> dori ichilgandan keyin qondagi konsentratsiya C(t) avval o‘sadi, maksimumga yetadi, so‘ng kamayadi. Shifokorlar maksimum vaqtini (C′(t) = 0) bilib, dorini qachon qayta ichish kerakligini belgilaydi.', '<b>Медицина:</b> после приёма лекарства его концентрация в крови C(t) сначала растёт, достигает максимума, затем убывает. Зная момент максимума (C′(t) = 0), врачи определяют, когда принимать следующую дозу.', '<b>Medicine:</b> after a pill is taken, the blood concentration C(t) rises, peaks and then falls. Knowing the time of the peak (C′(t) = 0), doctors decide when to take the next dose.'),
      L('<b>Iqtisod va birja:</b> tahlilchilar narx grafigidagi o‘sish va kamayish davrlarini, «cho‘qqi» va «tub»larni aniqlaydi. Moliyada trend o‘zgarishi aynan hosila ishorasining o‘zgarishidir.', '<b>Экономика и биржа:</b> аналитики выделяют на графике цены периоды роста и падения, «пики» и «дно». Смена тренда в финансах — это и есть смена знака производной.', '<b>Economics and markets:</b> analysts identify periods of rise and fall, “peaks” and “troughs” on price charts. A trend reversal in finance is exactly a change in the sign of the derivative.'),
      L('<b>Ob-havo:</b> sutkalik harorat grafigida maksimum odatda soat 14–15 larda, minimum esa tong otishidan oldin bo‘ladi. Meteorologlar shu nuqtalarni modellardan hosila orqali topadi.', '<b>Погода:</b> на суточном графике температуры максимум обычно около 14–15 часов, а минимум — перед рассветом. Метеорологи находят эти точки в моделях с помощью производной.', '<b>Weather:</b> on a daily temperature chart the maximum is usually around 2–3 p.m. and the minimum just before dawn. Meteorologists find these points in their models using the derivative.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Check yourself'), ex: [
      { q: L('f(x) = x² − 6x + 5 ning ekstremumi?', 'Экстремум f(x) = x² − 6x + 5?', 'Extremum of f(x) = x² − 6x + 5?'), s: L('f′ = 2x − 6 = 0, x = 3; ishora «−» dan «+» ga: minimum f(3) = −4.', 'f′ = 2x − 6 = 0, x = 3; знак с «−» на «+»: минимум f(3) = −4.', 'f′ = 2x − 6 = 0, x = 3; sign from “−” to “+”: minimum f(3) = −4.') },
      { q: L('f(x) = 12x − x³ qaysi oraliqda o‘sadi?', 'На каком промежутке возрастает f(x) = 12x − x³?', 'Where does f(x) = 12x − x³ increase?'), s: L('f′ = 12 − 3x² &gt; 0 ⇔ x² &lt; 4: [−2; 2] da o‘sadi; f(2) = 16 — maksimum, f(−2) = −16 — minimum.', 'f′ = 12 − 3x² &gt; 0 ⇔ x² &lt; 4: возрастает на [−2; 2]; f(2) = 16 — максимум, f(−2) = −16 — минимум.', 'f′ = 12 − 3x² &gt; 0 ⇔ x² &lt; 4: increasing on [−2; 2]; f(2) = 16 is a maximum, f(−2) = −16 a minimum.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('f′ &gt; 0 — funksiya o‘sadi, f′ &lt; 0 — kamayadi (Lagranj teoremasi asosida).', 'f′ &gt; 0 — функция возрастает, f′ &lt; 0 — убывает (на основе теоремы Лагранжа).', 'f′ &gt; 0 — increasing, f′ &lt; 0 — decreasing (based on Lagrange’s theorem).'),
      L('Kritik nuqtalar: f′(x) = 0 yoki f′ mavjud emas.', 'Критические точки: f′(x) = 0 или f′ не существует.', 'Critical points: f′(x) = 0 or f′ does not exist.'),
      L('Ferma: ekstremumda f′ = 0 (zaruriy shart).', 'Ферма: в экстремуме f′ = 0 (необходимое условие).', 'Fermat: f′ = 0 at an extremum (necessary condition).'),
      L('«+» → «−» — maksimum, «−» → «+» — minimum, ishora o‘zgarmasa — ekstremum yo‘q.', '«+» → «−» — максимум, «−» → «+» — минимум, без смены знака — экстремума нет.', '“+” → “−” is a maximum, “−” → “+” a minimum, no sign change — no extremum.'),
      L('Reja: soha, simmetriya, nollar, hosila, ishora jadvali, chegaraviy holat, grafik.', 'План: область, симметрия, нули, производная, таблица знаков, поведение на границах, график.', 'Plan: domain, symmetry, zeros, derivative, sign chart, end behaviour, graph.')
    ] }
  ] });

  // ---------- t7. Ekstremal masalalar: eng katta va eng kichik qiymat ----------
  T.add(P, 't7', { sections: [
    { kind: 'intro', h: L('Eng yaxshisini tanlash', 'Выбрать наилучшее', 'Choosing the best'), p: [
      L('Hayotda biz doimo «eng»larni izlaymiz: eng qisqa yo‘l, eng arzon material, eng katta foyda, eng kam vaqt. Fermer 400 metr sim to‘r bilan iloji boricha katta yer maydonini o‘rab olmoqchi. Zavod konserva bankasini shunday yasamoqchiki, hajmi berilgan bo‘lsin, tunuka esa eng kam sarflansin. Logistika kompaniyasi yuk mashinasining eng tejamkor tezligini qidiradi.', 'В жизни мы постоянно ищем «самое»: самый короткий путь, самый дешёвый материал, наибольшую прибыль, наименьшее время. Фермер хочет огородить 400 метрами сетки как можно большую площадь. Завод хочет сделать консервную банку заданного объёма, расходуя как можно меньше жести. Логистическая компания ищет самую экономичную скорость грузовика.', 'In life we constantly look for the “most”: the shortest route, the cheapest material, the greatest profit, the least time. A farmer wants to fence the largest possible area with 400 metres of netting. A factory wants a tin can of given volume that uses the least metal. A logistics company looks for a lorry’s most economical speed.'),
      L('Bunday masalalar <b>ekstremal masalalar</b> yoki <b>optimallashtirish masalalari</b> deyiladi. Ularni hal qilishning universal usuli — kerakli kattalikni bitta o‘zgaruvchining funksiyasi sifatida ifodalash va uning eng katta yoki eng kichik qiymatini hosila yordamida topish.', 'Такие задачи называются <b>экстремальными</b> или <b>задачами оптимизации</b>. Универсальный способ их решения — выразить нужную величину как функцию одной переменной и найти её наибольшее или наименьшее значение с помощью производной.', 'Such problems are called <b>extremal</b> or <b>optimisation problems</b>. The universal way to solve them is to express the required quantity as a function of one variable and find its greatest or least value with the derivative.'),
      L('Oldingi mavzuda mahalliy ekstremumlarni topdik. Endi butun kesmadagi <b>eng katta</b> va <b>eng kichik</b> qiymatlarni topishni va amaliy masalalarni matematik tilga o‘girishni o‘rganamiz.', 'В прошлой теме мы находили локальные экстремумы. Теперь научимся находить <b>наибольшее</b> и <b>наименьшее</b> значения на всём отрезке и переводить практические задачи на математический язык.', 'In the previous topic we found local extrema. Now we learn to find the <b>greatest</b> and <b>least</b> values on a whole interval and to translate practical problems into mathematics.')
    ] },
    { kind: 'def', h: L('Kesmadagi eng katta va eng kichik qiymat', 'Наибольшее и наименьшее значения на отрезке', 'Greatest and least values on an interval'), p: [
      L('Agar [a; b] dagi barcha x uchun f(x) ≤ f(x₀) bo‘lsa, f(x₀) funksiyaning kesmadagi <b>eng katta qiymati</b> deyiladi: max<sub>[a; b]</sub> f = f(x₀). Xuddi shunday <b>eng kichik qiymat</b> min<sub>[a; b]</sub> f ta’riflanadi. Bular «global» tushunchalar: butun kesma bo‘yicha taqqoslanadi.', 'Если f(x) ≤ f(x₀) для всех x из [a; b], то f(x₀) называется <b>наибольшим значением</b> функции на отрезке: max<sub>[a; b]</sub> f = f(x₀). Аналогично определяется <b>наименьшее значение</b> min<sub>[a; b]</sub> f. Это «глобальные» понятия: сравнение идёт по всему отрезку.', 'If f(x) ≤ f(x₀) for all x in [a; b], then f(x₀) is the <b>greatest value</b> of the function on the interval: max<sub>[a; b]</sub> f = f(x₀). The <b>least value</b> min<sub>[a; b]</sub> f is defined similarly. These are “global” notions: the comparison is over the whole interval.'),
      L('<b>Veyershtrass teoremasi.</b> [a; b] kesmada uzluksiz funksiya shu kesmada o‘zining eng katta va eng kichik qiymatlariga erishadi. Ochiq oraliqda bu kafolatlanmaydi: (0; 1) da f(x) = x ning eng katta qiymati yo‘q — 1 ga istalgancha yaqinlashadi, lekin yetmaydi.', '<b>Теорема Вейерштрасса.</b> Функция, непрерывная на отрезке [a; b], достигает на нём своего наибольшего и наименьшего значений. На интервале это не гарантировано: на (0; 1) у f(x) = x нет наибольшего значения — она сколь угодно близка к 1, но не достигает его.', '<b>Weierstrass theorem.</b> A function continuous on a closed interval [a; b] attains its greatest and least values there. On an open interval this is not guaranteed: on (0; 1), f(x) = x has no greatest value — it gets arbitrarily close to 1 but never reaches it.'),
      L('Eng katta qiymat yoki kritik nuqtada (mahalliy maksimumda), yoki kesmaning uchida erishiladi. Shuning uchun algoritm juda sodda bo‘ladi.', 'Наибольшее значение достигается либо в критической точке (локальном максимуме), либо на конце отрезка. Поэтому алгоритм очень прост.', 'The greatest value is attained either at a critical point (a local maximum) or at an endpoint. That makes the algorithm very simple.')
    ] },
    { kind: 'steps', h: L('Algoritm: kritik nuqtalar + kesma uchlari', 'Алгоритм: критические точки + концы отрезка', 'Algorithm: critical points + endpoints'), list: [
      L('1) f′(x) ni toping.', '1) Найдите f′(x).', '1) Find f′(x).'),
      L('2) (a; b) ichidagi kritik nuqtalarni toping (kesmadan tashqaridagilarni tashlab yuboring!).', '2) Найдите критические точки внутри (a; b) (лежащие вне отрезка отбросьте!).', '2) Find the critical points inside (a; b) (discard those outside!).'),
      L('3) f ni kritik nuqtalarda va kesma uchlari a, b da hisoblang.', '3) Вычислите f в критических точках и на концах a, b.', '3) Evaluate f at the critical points and at the endpoints a, b.'),
      L('4) Hosil bo‘lgan sonlardan eng kattasi — max, eng kichigi — min.', '4) Наибольшее из полученных чисел — max, наименьшее — min.', '4) The largest of these numbers is the max, the smallest the min.')
    ], after: [
      L('Amaliy masalada qo‘shimcha bosqichlar bor: (0) o‘zgaruvchini tanlash va uning mumkin bo‘lgan qiymatlar oralig‘ini aniqlash; (0′) optimallashtiriladigan kattalikni shu o‘zgaruvchi orqali ifodalash; (5) javobni masala tiliga qaytarish va mantiqan tekshirish.', 'В прикладной задаче добавляются шаги: (0) выбрать переменную и определить промежуток её допустимых значений; (0′) выразить оптимизируемую величину через эту переменную; (5) вернуть ответ на язык задачи и проверить его на здравый смысл.', 'An applied problem adds steps: (0) choose a variable and its admissible range; (0′) express the quantity to optimise through that variable; (5) translate the answer back into the problem and sanity-check it.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('f(x) = x³ − 3x funksiyaning [0; 2] kesmadagi eng katta va eng kichik qiymatlari.', 'Наибольшее и наименьшее значения f(x) = x³ − 3x на [0; 2].', 'Greatest and least values of f(x) = x³ − 3x on [0; 2].'),
        s: L('f′ = 3x² − 3 = 0 ⇒ x = ±1; kesmaga faqat x = 1 tegishli. f(0) = 0, f(1) = −2, f(2) = 2. <b>max = 2</b> (x = 2 da, uchda!), <b>min = −2</b> (x = 1 da).', 'f′ = 3x² − 3 = 0 ⇒ x = ±1; отрезку принадлежит лишь x = 1. f(0) = 0, f(1) = −2, f(2) = 2. <b>max = 2</b> (при x = 2, на конце!), <b>min = −2</b> (при x = 1).', 'f′ = 3x² − 3 = 0 ⇒ x = ±1; only x = 1 lies in the interval. f(0) = 0, f(1) = −2, f(2) = 2. <b>max = 2</b> (at x = 2, an endpoint!), <b>min = −2</b> (at x = 1).') },
      { q: L('Perimetri P bo‘lgan to‘g‘ri to‘rtburchaklar ichida yuzi eng kattasini toping.', 'Среди прямоугольников периметра P найдите прямоугольник наибольшей площади.', 'Among rectangles of perimeter P, find the one with the largest area.'),
        s: L('Tomonlar x va P/2 − x, 0 &lt; x &lt; P/2. S(x) = x(P/2 − x), S′ = P/2 − 2x = 0 ⇒ x = P/4. Ikkinchi tomon ham P/4 — <b>kvadrat</b>, S<sub>max</sub> = (P/4)². P = 40 da 10 × 10, S = 100.', 'Стороны x и P/2 − x, 0 &lt; x &lt; P/2. S(x) = x(P/2 − x), S′ = P/2 − 2x = 0 ⇒ x = P/4. Вторая сторона тоже P/4 — <b>квадрат</b>, S<sub>max</sub> = (P/4)². При P = 40: 10 × 10, S = 100.', 'Sides x and P/2 − x, 0 &lt; x &lt; P/2. S(x) = x(P/2 − x), S′ = P/2 − 2x = 0 ⇒ x = P/4. The other side is also P/4 — a <b>square</b>, S<sub>max</sub> = (P/4)². For P = 40: 10 × 10, S = 100.') },
      { q: L('12 × 12 sm karton burchaklaridan x tomonli kvadratlar kesib, qopqoqsiz quti yasaladi. Qaysi x da hajm eng katta?', 'Из картона 12 × 12 см по углам вырезают квадраты со стороной x и делают коробку без крышки. При каком x объём наибольший?', 'Squares of side x are cut from the corners of a 12 × 12 cm card to make an open box. Which x gives the largest volume?'),
        s: L('V = x(12 − 2x)², 0 &lt; x &lt; 6. V′ = (12 − 2x)² − 4x(12 − 2x) = (12 − 2x)(12 − 6x) = 0 ⇒ x = 2. V(2) = 2·8² = <b>128 sm³</b>.', 'V = x(12 − 2x)², 0 &lt; x &lt; 6. V′ = (12 − 2x)² − 4x(12 − 2x) = (12 − 2x)(12 − 6x) = 0 ⇒ x = 2. V(2) = 2·8² = <b>128 см³</b>.', 'V = x(12 − 2x)², 0 &lt; x &lt; 6. V′ = (12 − 2x)² − 4x(12 − 2x) = (12 − 2x)(12 − 6x) = 0 ⇒ x = 2. V(2) = 2·8² = <b>128 cm³</b>.') },
      { q: L('Daryo bo‘yidagi to‘g‘ri to‘rtburchak maydonni uch tomondan 400 m to‘r bilan o‘rash kerak (daryo tomoni o‘ralmaydi). Eng katta yuz?', 'Прямоугольный участок у реки огораживают с трёх сторон сеткой длиной 400 м (со стороны реки забора нет). Наибольшая площадь?', 'A rectangular plot by a river is fenced on three sides with 400 m of netting (no fence along the river). Largest area?'),
        s: L('Daryoga perpendikulyar tomonlar x, parallel tomon 400 − 2x. S = x(400 − 2x), S′ = 400 − 4x = 0 ⇒ x = 100. S = 100·200 = <b>20 000 m² = 2 ga</b>.', 'Стороны, перпендикулярные реке, — x, параллельная — 400 − 2x. S = x(400 − 2x), S′ = 400 − 4x = 0 ⇒ x = 100. S = 100·200 = <b>20 000 м² = 2 га</b>.', 'Sides perpendicular to the river are x, the parallel side 400 − 2x. S = x(400 − 2x), S′ = 400 − 4x = 0 ⇒ x = 100. S = 100·200 = <b>20,000 m² = 2 ha</b>.') },
      { q: L('Ko‘paytmasi 16 ga teng ikki musbat sonning yig‘indisi eng kichik bo‘lishi uchun ular qanday bo‘lishi kerak?', 'Произведение двух положительных чисел равно 16. При каких числах их сумма наименьшая?', 'Two positive numbers have product 16. When is their sum smallest?'),
        s: L('Sonlar x va 16/x. S(x) = x + 16/x, S′ = 1 − 16/x² = 0 ⇒ x = 4 (ishora «−» → «+», minimum). Sonlar <b>4 va 4</b>, yig‘indi 8.', 'Числа x и 16/x. S(x) = x + 16/x, S′ = 1 − 16/x² = 0 ⇒ x = 4 (знак «−» → «+», минимум). Числа <b>4 и 4</b>, сумма 8.', 'Numbers x and 16/x. S(x) = x + 16/x, S′ = 1 − 16/x² = 0 ⇒ x = 4 (sign “−” → “+”, a minimum). The numbers are <b>4 and 4</b>, sum 8.') }
    ] },
    { kind: 'rule', h: L('Foydali umumiy natijalar', 'Полезные общие результаты', 'Useful general results'), list: [
      L('Yig‘indisi S bo‘lgan ikki sonning ko‘paytmasi ular teng bo‘lganda (S/2 dan) eng katta: (S/2)².', 'Произведение двух чисел с суммой S наибольшее, когда они равны (по S/2): (S/2)².', 'Two numbers with sum S have the largest product when equal (S/2 each): (S/2)².'),
      L('Ko‘paytmasi Q bo‘lgan ikki musbat sonning yig‘indisi ular teng bo‘lganda eng kichik: 2√Q. Bu o‘rta arifmetik va o‘rta geometrik haqidagi Koshi tengsizligining natijasi.', 'Сумма двух положительных чисел с произведением Q наименьшая, когда они равны: 2√Q. Это следствие неравенства Коши о среднем арифметическом и среднем геометрическом.', 'Two positive numbers with product Q have the smallest sum when equal: 2√Q — a consequence of Cauchy’s AM–GM inequality.'),
      L('Perimetri berilgan to‘g‘ri to‘rtburchaklardan kvadrat, uchburchaklardan teng tomonli uchburchak, umuman barcha figuralardan doira eng katta yuzga ega.', 'Среди прямоугольников данного периметра наибольшую площадь имеет квадрат, среди треугольников — равносторонний, а среди всех фигур — круг.', 'Of rectangles with a given perimeter the square has the largest area, of triangles the equilateral one, and of all figures the circle.'),
      L('Hajmi berilgan silindrlardan to‘liq sirti eng kichigi — balandligi diametriga teng (h = 2r) silindr.', 'Среди цилиндров данного объёма наименьшую полную поверхность имеет цилиндр с высотой, равной диаметру (h = 2r).', 'Of cylinders with a given volume, the smallest total surface belongs to the one whose height equals its diameter (h = 2r).')
    ] },
    { kind: 'history', h: L('Optimallashtirish tarixi', 'История оптимизации', 'History of optimisation'), p: [
      L('Rivoyatga ko‘ra, mil. av. IX asrda finikiyalik malika Didona «ho‘kiz terisi qoplay oladigan» yer sotib oldi. U terini ingichka tasmalarga kesib, dengiz qirg‘og‘ida yarim doira shaklida katta yerni o‘rab oldi — shunday qilib Karfagen shahri paydo bo‘lgan. «Didona masalasi» — tarixdagi birinchi izoperimetrik masala.', 'По преданию, в IX веке до н. э. финикийская царевна Дидона купила землю, «которую можно покрыть бычьей шкурой». Она разрезала шкуру на тонкие ремни и огородила у морского берега большой участок в форме полукруга — так возник Карфаген. «Задача Дидоны» — первая в истории изопериметрическая задача.', 'Legend says that in the 9th century BC the Phoenician princess Dido bought land “that an ox hide could cover”. She cut the hide into thin strips and enclosed a large semicircular plot on the seashore — and so Carthage was founded. “Dido’s problem” is the first isoperimetric problem in history.'),
      L('Iogann Kepler 1615-yilda vino bochkalarining hajmini o‘rganib, avstriyalik bochkasozlar intuitiv ravishda eng tejamkor shaklni tanlaganini aniqladi; u «maksimum yaqinida o‘zgarish sezilmaydi» degan muhim kuzatuvni yozib qoldirdi. Ferma 1662-yilda yorug‘lik eng kam vaqt talab qiladigan yo‘ldan yuradi degan tamoyilni ilgari surib, sinish qonunini keltirib chiqardi.', 'Иоганн Кеплер в 1615 году, изучая объём винных бочек, обнаружил, что австрийские бочары интуитивно выбирали самую экономную форму; он записал важное наблюдение: «вблизи максимума изменения незаметны». Ферма в 1662 году выдвинул принцип, что свет идёт по пути, требующему наименьшего времени, и вывел закон преломления.', 'In 1615 Johannes Kepler, studying the volume of wine barrels, found that Austrian coopers intuitively chose the most economical shape; he recorded the key observation that “near a maximum changes are imperceptible”. In 1662 Fermat proposed that light travels along the path of least time and derived the law of refraction.'),
      L('XX asrda optimallashtirish alohida fanga aylandi. Sovet matematigi Leonid Kantorovich 1939-yilda chiziqli dasturlashni yaratdi va bu ishi uchun 1975-yilda iqtisod bo‘yicha Nobel mukofotini oldi.', 'В XX веке оптимизация стала отдельной наукой. Советский математик Леонид Канторович в 1939 году создал линейное программирование и в 1975 году получил за это Нобелевскую премию по экономике.', 'In the 20th century optimisation became a science of its own. The Soviet mathematician Leonid Kantorovich created linear programming in 1939 and received the 1975 Nobel Prize in Economics for it.')
    ] },
    { kind: 'fact', h: L('Konserva bankasi sirri', 'Секрет консервной банки', 'The secret of the tin can'), p: [
      L('Hajmi V bo‘lgan silindr uchun h = 2r ekanini isbotlaymiz. V = πr²h ⇒ h = V/(πr²). To‘liq sirt S = 2πr² + 2πrh = 2πr² + 2V/r. Hosila: S′(r) = 4πr − 2V/r². S′ = 0 ⇒ V = 2πr³. Lekin V = πr²h, demak πr²h = 2πr³, ya’ni <b>h = 2r</b>. S′ ishorasi «−» dan «+» ga o‘zgaradi — bu haqiqatan minimum.', 'Докажем, что для цилиндра объёма V нужно h = 2r. V = πr²h ⇒ h = V/(πr²). Полная поверхность S = 2πr² + 2πrh = 2πr² + 2V/r. Производная: S′(r) = 4πr − 2V/r². S′ = 0 ⇒ V = 2πr³. Но V = πr²h, значит πr²h = 2πr³, т. е. <b>h = 2r</b>. Знак S′ меняется с «−» на «+» — это действительно минимум.', 'Let us prove that a cylinder of volume V needs h = 2r. V = πr²h ⇒ h = V/(πr²). The total surface is S = 2πr² + 2πrh = 2πr² + 2V/r. Derivative: S′(r) = 4πr − 2V/r². S′ = 0 ⇒ V = 2πr³. But V = πr²h, so πr²h = 2πr³, i.e. <b>h = 2r</b>. The sign of S′ goes from “−” to “+”, so it is indeed a minimum.'),
      L('Masalan, 1 litr (1000 sm³) hajmli banka uchun r³ = 1000/(2π) ≈ 159, r ≈ 5,42 sm, h ≈ 10,84 sm. Real bankalar ko‘pincha bundan balandroq: tunuka narxidan tashqari, qo‘lda ushlash qulayligi va qopqoq narxi ham hisobga olinadi.', 'Например, для банки объёмом 1 литр (1000 см³) r³ = 1000/(2π) ≈ 159, r ≈ 5,42 см, h ≈ 10,84 см. Реальные банки часто выше: кроме цены жести, учитывают удобство держать в руке и стоимость крышки.', 'For example, for a 1-litre (1000 cm³) can r³ = 1000/(2π) ≈ 159, r ≈ 5.42 cm, h ≈ 10.84 cm. Real cans are often taller: besides the cost of metal, ease of holding and the price of the lid also count.'),
      L('Yana bir qadimiy natija: Iskandariyalik Geron (I asr) ko‘zgudan qaytgan nur ikki nuqta orasidagi <b>eng qisqa</b> yo‘lni tanlashini isbotlagan — shuning uchun tushish burchagi qaytish burchagiga teng.', 'Ещё один древний результат: Герон Александрийский (I в.) доказал, что отражённый от зеркала луч выбирает <b>кратчайший</b> путь между двумя точками — поэтому угол падения равен углу отражения.', 'Another ancient result: Heron of Alexandria (1st century) proved that a ray reflected by a mirror takes the <b>shortest</b> path between two points — which is why the angle of incidence equals the angle of reflection.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Kesma uchlarini tekshirmaslik.</b> Birinchi namunada eng katta qiymat aynan x = 2 uchida edi — kritik nuqtada emas.', '<b>Не проверять концы отрезка.</b> В первом примере наибольшее значение было именно на конце x = 2, а не в критической точке.', '<b>Not checking the endpoints.</b> In the first example the greatest value was exactly at the endpoint x = 2, not at a critical point.'),
      L('<b>Kesmadan tashqaridagi kritik nuqtani hisobga olish.</b> x = −1 nuqta [0; 2] ga tegishli emas, uni tashlab yuborish kerak.', '<b>Учитывать критическую точку вне отрезка.</b> Точка x = −1 не принадлежит [0; 2] и должна быть отброшена.', '<b>Including a critical point outside the interval.</b> x = −1 does not belong to [0; 2] and must be discarded.'),
      L('<b>O‘zgaruvchining mumkin bo‘lgan qiymatlarini aniqlamaslik.</b> Quti masalasida x = 6 ham V′ = 0 beradi, lekin unda hajm nol va x &lt; 6 bo‘lishi shart.', '<b>Не определять допустимые значения переменной.</b> В задаче о коробке x = 6 тоже даёт V′ = 0, но объём при этом ноль, и нужно x &lt; 6.', '<b>Not fixing the admissible range.</b> In the box problem x = 6 also gives V′ = 0, but the volume is zero and we need x &lt; 6.'),
      L('<b>Javobni to‘liq bermaslik.</b> Savol «qaysi x da?» bo‘lsa — x ni, «eng katta yuz qancha?» bo‘lsa — S ni yozing; birliklarni unutmang.', '<b>Давать неполный ответ.</b> Если спрашивают «при каком x?» — пишите x, если «какова наибольшая площадь?» — S; не забывайте единицы.', '<b>Giving an incomplete answer.</b> If asked “for which x?” give x; if “what is the largest area?” give S; do not forget units.')
    ] },
    { kind: 'life', h: L('Optimallashtirish atrofimizda', 'Оптимизация вокруг нас', 'Optimisation around us'), p: [
      L('<b>Qadoqlash:</b> ko‘plab konserva bankalarining balandligi diametriga yaqin — bu tunukani tejaydi. Sut va sharbat qutilari esa tashish va tokchaga terish qulayligi uchun to‘g‘ri burchakli: optimallashtirishda hamma shartlar hisobga olinadi.', '<b>Упаковка:</b> у многих консервных банок высота близка к диаметру — так экономится жесть. А пакеты для молока и сока прямоугольные ради удобства перевозки и укладки на полки: при оптимизации учитываются все условия.', '<b>Packaging:</b> many tin cans have a height close to their diameter — this saves metal. Milk and juice cartons are rectangular for easy transport and shelving: optimisation takes every condition into account.'),
      L('<b>Tabiat:</b> asalarilar uyasining olti burchakli kataklari mumdan eng kam sarflab eng ko‘p asal saqlash imkonini beradi (bu «asalari uyasi gipotezasi»ni Tomas Heyls 1999-yilda isbotlagan). Sovun pufagi esa berilgan hajm uchun eng kichik sirtga ega — shar shakli.', '<b>Природа:</b> шестиугольные ячейки пчелиных сот позволяют хранить больше всего мёда при наименьшем расходе воска («гипотезу о сотах» доказал Томас Хейлс в 1999 году). Мыльный пузырь имеет наименьшую поверхность при данном объёме — форму шара.', '<b>Nature:</b> the hexagonal cells of a honeycomb store the most honey using the least wax (Thomas Hales proved this “honeycomb conjecture” in 1999). A soap bubble has the smallest surface for its volume — a sphere.'),
      L('<b>Biznes va texnika:</b> korxona foyda funksiyasining maksimumini qidiradi; navigator ilovasi eng tez yo‘lni hisoblaydi; muhandislar ko‘prik va samolyot qanotini eng yengil, lekin mustahkam qilib loyihalaydi.', '<b>Бизнес и техника:</b> предприятие ищет максимум функции прибыли; навигатор рассчитывает самый быстрый маршрут; инженеры проектируют мосты и крылья самолётов как можно более лёгкими, но прочными.', '<b>Business and engineering:</b> a firm seeks the maximum of its profit function; a navigation app computes the fastest route; engineers design bridges and aircraft wings to be as light as possible yet strong.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Check yourself'), ex: [
      { q: L('f(x) = x² − 4x + 1 ning [0; 5] dagi eng katta va eng kichik qiymatlari?', 'Наибольшее и наименьшее значения f(x) = x² − 4x + 1 на [0; 5]?', 'Greatest and least values of f(x) = x² − 4x + 1 on [0; 5]?'),
        s: L('f′ = 2x − 4 = 0, x = 2. f(0) = 1, f(2) = −3, f(5) = 6. max = 6, min = −3.', 'f′ = 2x − 4 = 0, x = 2. f(0) = 1, f(2) = −3, f(5) = 6. max = 6, min = −3.', 'f′ = 2x − 4 = 0, x = 2. f(0) = 1, f(2) = −3, f(5) = 6. max = 6, min = −3.') },
      { q: L('Yig‘indisi 30 bo‘lgan ikki sonning ko‘paytmasi eng ko‘pi bilan qancha?', 'Каково наибольшее произведение двух чисел с суммой 30?', 'What is the largest product of two numbers with sum 30?'),
        s: L('15·15 = 225.', '15·15 = 225.', '15·15 = 225.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Kesmada uzluksiz funksiya eng katta va eng kichik qiymatga erishadi (Veyershtrass).', 'Непрерывная на отрезке функция достигает наибольшего и наименьшего значений (Вейерштрасс).', 'A function continuous on a closed interval attains its greatest and least values (Weierstrass).'),
      L('Algoritm: kritik nuqtalar + kesma uchlari, so‘ng qiymatlarni taqqoslash.', 'Алгоритм: критические точки + концы отрезка, затем сравнение значений.', 'Algorithm: critical points + endpoints, then compare the values.'),
      L('Amaliy masala: o‘zgaruvchi → funksiya → hosila → tekshiruv → javob.', 'Прикладная задача: переменная → функция → производная → проверка → ответ.', 'Applied problem: variable → function → derivative → check → answer.'),
      L('Perimetri P bo‘lgan to‘g‘ri to‘rtburchaklardan kvadrat eng katta yuzli: (P/4)².', 'Из прямоугольников периметра P наибольшую площадь (P/4)² имеет квадрат.', 'Of rectangles with perimeter P the square has the largest area, (P/4)².'),
      L('Yig‘indisi o‘zgarmas ikki son teng bo‘lganda ko‘paytma eng katta.', 'При постоянной сумме произведение двух чисел наибольшее, когда они равны.', 'With a fixed sum, the product of two numbers is largest when they are equal.')
    ] }
  ] });

  // ---------- t8. Taqribiy hisoblashlar ----------
  T.add(P, 't8', { sections: [
    { kind: 'intro', h: L('Kalkulyatorsiz √101 ni hisoblash', 'Вычислить √101 без калькулятора', 'Computing √101 without a calculator'), p: [
      L('√101 qancha? Kalkulyatorsiz ham aytish mumkin: 10 dan sal kattaroq. Lekin «sal» qancha? Hosila bu savolga juda aniq javob beradi: √101 ≈ 10,05. Haqiqiy qiymat 10,0499… — xato o‘n mingdan bir ulushdan ham kichik!', 'Сколько будет √101? И без калькулятора ясно: чуть больше 10. Но насколько «чуть»? Производная даёт очень точный ответ: √101 ≈ 10,05. Истинное значение 10,0499… — ошибка меньше одной десятитысячной!', 'What is √101? Even without a calculator it is clearly a little more than 10. But how much is “a little”? The derivative gives a very precise answer: √101 ≈ 10.05. The true value is 10.0499… — an error of less than one ten-thousandth!'),
      L('G‘oya oddiy: kichik masofada har qanday silliq egri chiziq deyarli to‘g‘ri chiziq — urinmasi bilan ustma-ust tushadi. Yer sharsimon, lekin futbol maydonida biz uni tekis deb hisoblaymiz. Xuddi shunday, x₀ yaqinida funksiyani urinma bilan almashtirib, murakkab qiymatlarni oson topamiz.', 'Идея проста: на малом участке любая гладкая кривая почти прямая — она совпадает со своей касательной. Земля шарообразна, но на футбольном поле мы считаем её плоской. Точно так же, заменив функцию вблизи x₀ касательной, мы легко находим сложные значения.', 'The idea is simple: over a short stretch any smooth curve is almost straight — it merges with its tangent. The Earth is round, but on a football pitch we treat it as flat. In the same way, replacing a function near x₀ by its tangent lets us find awkward values easily.'),
      L('Kalkulyatorlar paydo bo‘lishidan oldin muhandislar, dengizchilar va astronomlar aynan shu usul bilan hisoblashgan. Bugun ham fizika, texnika va iqtisodda taqribiy formulalar kundalik qurol hisoblanadi.', 'До появления калькуляторов инженеры, мореплаватели и астрономы считали именно так. И сегодня в физике, технике и экономике приближённые формулы — повседневный инструмент.', 'Before calculators, engineers, navigators and astronomers computed exactly this way. Even today approximate formulas are an everyday tool in physics, engineering and economics.')
    ] },
    { kind: 'def', h: L('Funksiya differensiali', 'Дифференциал функции', 'The differential of a function'), p: [
      L('Hosila ta’rifidan Δy/Δx ≈ f′(x₀) (Δx kichik bo‘lganda). Demak, <b>Δy ≈ f′(x₀)·Δx</b>. O‘ng tomondagi ifoda funksiyaning <b>differensiali</b> deyiladi va <b>dy = f′(x)dx</b> deb belgilanadi (dx = Δx).', 'Из определения производной Δy/Δx ≈ f′(x₀) (при малом Δx). Значит, <b>Δy ≈ f′(x₀)·Δx</b>. Выражение справа называется <b>дифференциалом</b> функции и обозначается <b>dy = f′(x)dx</b> (dx = Δx).', 'From the definition of the derivative, Δy/Δx ≈ f′(x₀) for small Δx. Hence <b>Δy ≈ f′(x₀)·Δx</b>. The right-hand side is called the <b>differential</b> of the function, written <b>dy = f′(x)dx</b> (dx = Δx).'),
      L('Geometrik ma’nosi: Δy — grafik bo‘ylab ko‘tarilish, dy — urinma bo‘ylab ko‘tarilish. Ularning farqi Δy − dy Δx ga nisbatan juda tez kichrayadi: masalan, y = x² uchun Δy = 2x₀Δx + Δx², dy = 2x₀Δx, farq Δx² — Δx = 0,01 da atigi 0,0001.', 'Геометрический смысл: Δy — подъём по графику, dy — подъём по касательной. Их разность Δy − dy убывает гораздо быстрее Δx: например, для y = x² Δy = 2x₀Δx + Δx², dy = 2x₀Δx, разность Δx² — при Δx = 0,01 всего 0,0001.', 'Geometric meaning: Δy is the rise along the graph, dy the rise along the tangent. Their difference Δy − dy shrinks much faster than Δx: for y = x², Δy = 2x₀Δx + Δx² and dy = 2x₀Δx, so the difference is Δx² — just 0.0001 when Δx = 0.01.'),
      L('Bundan asosiy formula kelib chiqadi: <b>f(x₀ + Δx) ≈ f(x₀) + f′(x₀)·Δx</b>. Bu — urinma tenglamasining o‘zi! Funksiyaning x₀ yaqinidagi «chiziqli yaqinlashishi» deyiladi.', 'Отсюда основная формула: <b>f(x₀ + Δx) ≈ f(x₀) + f′(x₀)·Δx</b>. Это и есть уравнение касательной! Его называют «линейным приближением» функции вблизи x₀.', 'This gives the main formula: <b>f(x₀ + Δx) ≈ f(x₀) + f′(x₀)·Δx</b>. It is exactly the tangent equation! It is called the “linear approximation” of the function near x₀.')
    ] },
    { kind: 'table', h: L('Asosiy taqribiy formulalar (|x| kichik)', 'Основные приближённые формулы (|x| мало)', 'Main approximate formulas (small |x|)'), table: { head: [L('Formula', 'Формула', 'Formula'), L('Misol', 'Пример', 'Example')], rows: [
      [L('(1 + x)ⁿ ≈ 1 + nx', '(1 + x)ⁿ ≈ 1 + nx', '(1 + x)ⁿ ≈ 1 + nx'), L('1,02⁵ ≈ 1,1 (aniq 1,104)', '1,02⁵ ≈ 1,1 (точно 1,104)', '1.02⁵ ≈ 1.1 (exact 1.104)')],
      [L('√(a² + Δ) ≈ a + Δ/(2a)', '√(a² + Δ) ≈ a + Δ/(2a)', '√(a² + Δ) ≈ a + Δ/(2a)'), L('√101 ≈ 10,05', '√101 ≈ 10,05', '√101 ≈ 10.05')],
      [L('∛(a³ + Δ) ≈ a + Δ/(3a²)', '∛(a³ + Δ) ≈ a + Δ/(3a²)', '∛(a³ + Δ) ≈ a + Δ/(3a²)'), L('∛8,12 ≈ 2,01', '∛8,12 ≈ 2,01', '∛8.12 ≈ 2.01')],
      [L('1/(1 + x) ≈ 1 − x', '1/(1 + x) ≈ 1 − x', '1/(1 + x) ≈ 1 − x'), L('1/1,03 ≈ 0,97', '1/1,03 ≈ 0,97', '1/1.03 ≈ 0.97')],
      [L('sin x ≈ x, tg x ≈ x (radian)', 'sin x ≈ x, tg x ≈ x (радианы)', 'sin x ≈ x, tan x ≈ x (radians)'), L('sin 0,05 ≈ 0,05', 'sin 0,05 ≈ 0,05', 'sin 0.05 ≈ 0.05')],
      [L('eˣ ≈ 1 + x', 'eˣ ≈ 1 + x', 'eˣ ≈ 1 + x'), L('e<sup>0,01</sup> ≈ 1,01', 'e<sup>0,01</sup> ≈ 1,01', 'e<sup>0.01</sup> ≈ 1.01')],
      [L('ln(1 + x) ≈ x', 'ln(1 + x) ≈ x', 'ln(1 + x) ≈ x'), L('ln 1,02 ≈ 0,02', 'ln 1,02 ≈ 0,02', 'ln 1.02 ≈ 0.02')]
    ] }, after: [
      L('Har bir formula f(0 + x) ≈ f(0) + f′(0)·x dan olinadi. Masalan, f(x) = (1 + x)ⁿ: f(0) = 1, f′(0) = n, demak (1 + x)ⁿ ≈ 1 + nx.', 'Каждая формула получается из f(0 + x) ≈ f(0) + f′(0)·x. Например, f(x) = (1 + x)ⁿ: f(0) = 1, f′(0) = n, значит (1 + x)ⁿ ≈ 1 + nx.', 'Each formula comes from f(0 + x) ≈ f(0) + f′(0)·x. For f(x) = (1 + x)ⁿ: f(0) = 1, f′(0) = n, so (1 + x)ⁿ ≈ 1 + nx.')
    ] },
    { kind: 'steps', h: L('Taqribiy hisoblash tartibi', 'Порядок приближённого вычисления', 'How to approximate step by step'), list: [
      L('1) Hisoblanadigan sonni f(x₀ + Δx) ko‘rinishida yozing: f ni tanlang, x₀ ni f(x₀) oson hisoblanadigan qilib oling.', '1) Запишите искомое число как f(x₀ + Δx): выберите f, а x₀ возьмите так, чтобы f(x₀) легко считалось.', '1) Write the number as f(x₀ + Δx): choose f and pick x₀ so that f(x₀) is easy.'),
      L('2) Δx ni toping (u kichik bo‘lishi kerak!). Burchaklarni radianga o‘tkazing.', '2) Найдите Δx (оно должно быть малым!). Углы переведите в радианы.', '2) Find Δx (it must be small!). Convert angles to radians.'),
      L('3) f′(x) va f′(x₀) ni hisoblang.', '3) Вычислите f′(x) и f′(x₀).', '3) Compute f′(x) and f′(x₀).'),
      L('4) f(x₀ + Δx) ≈ f(x₀) + f′(x₀)Δx formulaga qo‘ying.', '4) Подставьте в формулу f(x₀ + Δx) ≈ f(x₀) + f′(x₀)Δx.', '4) Substitute into f(x₀ + Δx) ≈ f(x₀) + f′(x₀)Δx.'),
      L('5) Natijani mantiqan baholang: f(x₀) dan to‘g‘ri tomonga va oz miqdorga siljidimi?', '5) Оцените результат: сместился ли он от f(x₀) в нужную сторону и на малую величину?', '5) Sanity-check: did the result move from f(x₀) in the right direction and by a small amount?')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('√101 ni taqribiy hisoblang.', 'Вычислите приближённо √101.', 'Approximate √101.'),
        s: L('f(x) = √x, x₀ = 100, Δx = 1. f(100) = 10, f′(x) = 1/(2√x), f′(100) = 1/20 = 0,05. √101 ≈ 10 + 0,05 = <b>10,05</b> (aniq 10,04988…).', 'f(x) = √x, x₀ = 100, Δx = 1. f(100) = 10, f′(x) = 1/(2√x), f′(100) = 1/20 = 0,05. √101 ≈ 10 + 0,05 = <b>10,05</b> (точно 10,04988…).', 'f(x) = √x, x₀ = 100, Δx = 1. f(100) = 10, f′(x) = 1/(2√x), f′(100) = 1/20 = 0.05. √101 ≈ 10 + 0.05 = <b>10.05</b> (exact 10.04988…).') },
      { q: L('sin 31° ni taqribiy hisoblang.', 'Вычислите приближённо sin 31°.', 'Approximate sin 31°.'),
        s: L('x₀ = 30°, Δx = 1° = π/180 ≈ 0,01745. sin 31° ≈ sin 30° + cos 30°·0,01745 ≈ 0,5 + 0,8660·0,01745 ≈ <b>0,5151</b> (aniq 0,5150…).', 'x₀ = 30°, Δx = 1° = π/180 ≈ 0,01745. sin 31° ≈ sin 30° + cos 30°·0,01745 ≈ 0,5 + 0,8660·0,01745 ≈ <b>0,5151</b> (точно 0,5150…).', 'x₀ = 30°, Δx = 1° = π/180 ≈ 0.01745. sin 31° ≈ sin 30° + cos 30°·0.01745 ≈ 0.5 + 0.8660·0.01745 ≈ <b>0.5151</b> (exact 0.5150…).') },
      { q: L('0,98¹⁰ ni taqribiy hisoblang.', 'Вычислите приближённо 0,98¹⁰.', 'Approximate 0.98¹⁰.'),
        s: L('(1 + x)ⁿ ≈ 1 + nx, x = −0,02, n = 10: 1 − 0,2 = <b>0,8</b>. Aniq qiymat 0,817 — x·n = 0,2 unchalik kichik bo‘lmagani uchun xato sezilarliroq.', '(1 + x)ⁿ ≈ 1 + nx, x = −0,02, n = 10: 1 − 0,2 = <b>0,8</b>. Точное значение 0,817 — ошибка заметнее, так как nx = 0,2 не так уж мало.', '(1 + x)ⁿ ≈ 1 + nx with x = −0.02, n = 10: 1 − 0.2 = <b>0.8</b>. The exact value is 0.817 — the error is larger because nx = 0.2 is not that small.') },
      { q: L('Kub qirrasi 10 sm, o‘lchash xatosi 0,1 sm. Hajm xatosini baholang.', 'Ребро куба 10 см, погрешность измерения 0,1 см. Оцените погрешность объёма.', 'A cube’s edge is 10 cm with a measurement error of 0.1 cm. Estimate the error in the volume.'),
        s: L('V = a³, dV = 3a²·da = 3·100·0,1 = <b>30 sm³</b>. Hajm 1000 sm³, nisbiy xato 3 % — qirradagi nisbiy xatodan (1 %) 3 marta katta.', 'V = a³, dV = 3a²·da = 3·100·0,1 = <b>30 см³</b>. Объём 1000 см³, относительная погрешность 3 % — в 3 раза больше относительной погрешности ребра (1 %).', 'V = a³, dV = 3a²·da = 3·100·0.1 = <b>30 cm³</b>. The volume is 1000 cm³, so the relative error is 3 % — three times the relative error of the edge (1 %).') },
      { q: L('∛8,12 ni taqribiy hisoblang.', 'Вычислите приближённо ∛8,12.', 'Approximate ∛8.12.'),
        s: L('f(x) = ∛x, x₀ = 8, Δx = 0,12. f′(x) = 1/(3∛x²), f′(8) = 1/12. ∛8,12 ≈ 2 + 0,12/12 = <b>2,01</b> (aniq 2,00995…).', 'f(x) = ∛x, x₀ = 8, Δx = 0,12. f′(x) = 1/(3∛x²), f′(8) = 1/12. ∛8,12 ≈ 2 + 0,12/12 = <b>2,01</b> (точно 2,00995…).', 'f(x) = ∛x, x₀ = 8, Δx = 0.12. f′(x) = 1/(3∛x²), f′(8) = 1/12. ∛8.12 ≈ 2 + 0.12/12 = <b>2.01</b> (exact 2.00995…).') }
    ] },
    { kind: 'rule', h: L('Xatolarni baholash', 'Оценка погрешностей', 'Estimating errors'), p: [
      L('Differensial nafaqat qiymatlarni, balki o‘lchash xatolarining natijaga ta’sirini ham baholaydi. Agar x kattalik Δx xato bilan o‘lchangan bo‘lsa, y = f(x) ning absolyut xatosi taxminan |f′(x)|·Δx.', 'Дифференциал оценивает не только значения, но и влияние погрешностей измерений на результат. Если величина x измерена с погрешностью Δx, абсолютная погрешность y = f(x) примерно равна |f′(x)|·Δx.', 'The differential estimates not only values but also how measurement errors affect results. If x is measured with error Δx, the absolute error of y = f(x) is about |f′(x)|·Δx.'),
      L('Nisbiy xatolar uchun qulay qoida: y = xⁿ bo‘lsa, Δy/y ≈ n·Δx/x. Ya’ni kvadratga ko‘tarishda nisbiy xato 2 marta, kubga ko‘tarishda 3 marta oshadi, kvadrat ildiz chiqarishda esa 2 marta kamayadi. Doira radiusi 2 % xato bilan o‘lchansa, yuzi taxminan 4 % xato bilan topiladi.', 'Удобное правило для относительных погрешностей: если y = xⁿ, то Δy/y ≈ n·Δx/x. То есть при возведении в квадрат относительная погрешность удваивается, в куб — утраивается, а при извлечении квадратного корня уменьшается вдвое. Если радиус круга измерен с погрешностью 2 %, площадь найдена с погрешностью около 4 %.', 'A handy rule for relative errors: if y = xⁿ, then Δy/y ≈ n·Δx/x. Squaring doubles the relative error, cubing triples it, and taking a square root halves it. If a circle’s radius is measured with a 2 % error, its area has about a 4 % error.'),
      L('Bu qoida tajriba rejalashtirishda juda muhim: qaysi kattalikni eng aniq o‘lchash kerakligini ko‘rsatadi — natijaga eng yuqori darajada kirgan kattalikni.', 'Это правило очень важно при планировании эксперимента: оно показывает, какую величину нужно измерять точнее всего — ту, что входит в результат в наибольшей степени.', 'This rule matters greatly in planning experiments: it shows which quantity must be measured most precisely — the one entering the result with the highest power.')
    ] },
    { kind: 'history', h: L('Bobil ildizidan Nyuton usuligacha', 'От вавилонского корня до метода Ньютона', 'From Babylonian roots to Newton’s method'), p: [
      L('Bobil sopol taxtachasi YBC 7289 (mil. av. 1800–1600-yillar) da √2 ≈ 1,414213 deb yozilgan — olti xonagacha aniq! Bobilliklar va keyinroq Iskandariyalik Geron quyidagi usuldan foydalangan: agar x — √a ning taxmini bo‘lsa, (x + a/x)/2 yanada yaxshi taxmin.', 'На вавилонской глиняной табличке YBC 7289 (1800–1600 гг. до н. э.) записано √2 ≈ 1,414213 — верно до шести знаков! Вавилоняне, а позже Герон Александрийский пользовались способом: если x — приближение √a, то (x + a/x)/2 — ещё лучшее приближение.', 'The Babylonian clay tablet YBC 7289 (1800–1600 BC) records √2 ≈ 1.414213 — correct to six places! The Babylonians, and later Heron of Alexandria, used this method: if x approximates √a, then (x + a/x)/2 is a better approximation.'),
      L('1669-yilda Nyuton tenglamalarni taqribiy yechishning umumiy usulini taklif qildi: urinma bilan Ox o‘qining kesishgan nuqtasi yangi yaqinlashish bo‘ladi: x<sub>n+1</sub> = x<sub>n</sub> − f(x<sub>n</sub>)/f′(x<sub>n</sub>). f(x) = x² − a uchun bu aynan Geron formulasi! Masalan, √2 uchun 1,5 dan boshlasak: 1,5 → 1,41667 → 1,414216 — ikki qadamda 5 ta to‘g‘ri xona.', 'В 1669 году Ньютон предложил общий метод приближённого решения уравнений: точка пересечения касательной с осью Ox даёт новое приближение: x<sub>n+1</sub> = x<sub>n</sub> − f(x<sub>n</sub>)/f′(x<sub>n</sub>). Для f(x) = x² − a это в точности формула Герона! Например, для √2, начиная с 1,5: 1,5 → 1,41667 → 1,414216 — за два шага 5 верных знаков.', 'In 1669 Newton proposed a general method for solving equations approximately: where the tangent meets the Ox axis gives the next approximation, x<sub>n+1</sub> = x<sub>n</sub> − f(x<sub>n</sub>)/f′(x<sub>n</sub>). For f(x) = x² − a this is exactly Heron’s formula! For √2 starting from 1.5: 1.5 → 1.41667 → 1.414216 — five correct digits in two steps.'),
      L('1715-yilda ingliz Bruk Teylor chiziqli yaqinlashishni ko‘phadlar qatoriga kengaytirdi: f(x₀ + h) ≈ f(x₀) + f′(x₀)h + f″(x₀)h²/2 + … Kalkulyator va kompyuterlar sin, eˣ, ln ni aynan shunday qatorlar bilan hisoblaydi.', 'В 1715 году англичанин Брук Тейлор расширил линейное приближение до ряда многочленов: f(x₀ + h) ≈ f(x₀) + f′(x₀)h + f″(x₀)h²/2 + … Калькуляторы и компьютеры вычисляют sin, eˣ, ln именно такими рядами.', 'In 1715 the Englishman Brook Taylor extended the linear approximation to a polynomial series: f(x₀ + h) ≈ f(x₀) + f′(x₀)h + f″(x₀)h²/2 + … Calculators and computers evaluate sin, eˣ and ln with exactly such series.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Yer yuzasida 1 km masofada «egrilik» atigi taxminan 8 sm ga teng — shuning uchun qisqa masofada Yerni tekis deb hisoblash xato bermaydi. Bu ham chiziqli yaqinlashish g‘oyasi.', 'На поверхности Земли на расстоянии 1 км «кривизна» составляет всего около 8 см — поэтому на малых расстояниях Землю можно считать плоской. Это тоже идея линейного приближения.', 'On the Earth’s surface the “curvature drop” over 1 km is only about 8 cm — so over short distances the Earth can be treated as flat. This too is the idea of linear approximation.'),
      L('Muhandislar orasida hazil bor: «sin x = x, cos x = 1, π = 3». Albatta, bu faqat kichik x da va qo‘pol baholashda o‘rinli, ammo ko‘p tez hisoblar shunday boshlanadi.', 'Среди инженеров есть шутка: «sin x = x, cos x = 1, π = 3». Конечно, это верно лишь при малых x и для грубой оценки, но многие быстрые расчёты начинаются именно так.', 'Engineers joke: “sin x = x, cos x = 1, π = 3”. Of course this holds only for small x and rough estimates, but many quick calculations start exactly this way.'),
      L('Nyuton usuli kompyuterlarda bo‘lish va ildiz chiqarishni tezlashtirish uchun bugun ham ishlatiladi: har qadamda to‘g‘ri xonalar soni taxminan ikki baravar oshadi.', 'Метод Ньютона и сегодня используется в компьютерах для быстрого деления и извлечения корней: на каждом шаге число верных знаков примерно удваивается.', 'Newton’s method is still used in computers for fast division and square roots: each step roughly doubles the number of correct digits.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Burchakni gradusda qoldirish.</b> sin 31° ≈ 0,5 + cos 30°·1 — mutlaqo noto‘g‘ri. (sin x)′ = cos x formulasi faqat radianda to‘g‘ri, shuning uchun Δx = π/180.', '<b>Оставлять угол в градусах.</b> sin 31° ≈ 0,5 + cos 30°·1 — совершенно неверно. Формула (sin x)′ = cos x верна только в радианах, поэтому Δx = π/180.', '<b>Leaving the angle in degrees.</b> sin 31° ≈ 0.5 + cos 30°·1 is completely wrong. (sin x)′ = cos x holds only in radians, so Δx = π/180.'),
      L('<b>Δx katta bo‘lganda formulani qo‘llash.</b> √120 ni x₀ = 100 dan hisoblasak, 11 chiqadi (aniq 10,954). x₀ = 121 dan olish to‘g‘ri: 11 − 1/22 ≈ 10,955.', '<b>Применять формулу при большом Δx.</b> Если считать √120 от x₀ = 100, получится 11 (точно 10,954). Правильно брать x₀ = 121: 11 − 1/22 ≈ 10,955.', '<b>Using the formula with a large Δx.</b> Computing √120 from x₀ = 100 gives 11 (exact 10.954). Take x₀ = 121 instead: 11 − 1/22 ≈ 10.955.'),
      L('<b>f′(x₀) o‘rniga f′(x₀ + Δx) ni olish.</b> Hosila ma’lum nuqtada hisoblanadi — aynan qiymati oson topiladigan x₀ da.', '<b>Брать f′(x₀ + Δx) вместо f′(x₀).</b> Производная вычисляется в известной точке — в x₀, где значение легко найти.', '<b>Using f′(x₀ + Δx) instead of f′(x₀).</b> The derivative is taken at the known point x₀, where values are easy.'),
      L('<b>Manfiy Δx da ishorani unutish.</b> √99: Δx = −1, √99 ≈ 10 − 0,05 = 9,95.', '<b>Забывать знак при отрицательном Δx.</b> √99: Δx = −1, √99 ≈ 10 − 0,05 = 9,95.', '<b>Forgetting the sign for a negative Δx.</b> √99: Δx = −1, √99 ≈ 10 − 0.05 = 9.95.')
    ] },
    { kind: 'life', h: L('Taqribiy hisob hayotda', 'Приближённые вычисления в жизни', 'Approximations in life'), p: [
      L('<b>Fizika:</b> mayatnik tebranish davri T = 2π√(l/g) formulasi sin x ≈ x yaqinlashishiga asoslangan va faqat kichik og‘ish burchaklarida (taxminan 10° gacha) aniq. Optikada linzalar formulasi ham kichik burchaklar uchun chiqarilgan.', '<b>Физика:</b> формула периода маятника T = 2π√(l/g) основана на приближении sin x ≈ x и точна только при малых углах отклонения (примерно до 10°). В оптике формула линзы тоже выведена для малых углов.', '<b>Physics:</b> the pendulum period formula T = 2π√(l/g) rests on sin x ≈ x and is accurate only for small swings (up to about 10°). The thin-lens formula in optics is also derived for small angles.'),
      L('<b>Moliya:</b> «72 qoidasi» — yillik foiz r % bo‘lsa, omonat taxminan 72/r yilda ikki baravar oshadi. U ln(1 + x) ≈ x va ln 2 ≈ 0,693 dan kelib chiqadi. Masalan, 8 % da 9 yilda.', '<b>Финансы:</b> «правило 72» — при годовой ставке r % вклад удваивается примерно за 72/r лет. Оно следует из ln(1 + x) ≈ x и ln 2 ≈ 0,693. Например, при 8 % — за 9 лет.', '<b>Finance:</b> the “rule of 72” — at r % per year a deposit doubles in about 72/r years. It follows from ln(1 + x) ≈ x and ln 2 ≈ 0.693. At 8 %, about 9 years.'),
      L('<b>Muhandislik va GPS:</b> chizmalarda «10 ± 0,1 mm» kabi dopusklar differensial yordamida hisoblanadi. GPS sun’iy yo‘ldoshlari soatlariga nisbiylik nazariyasi tuzatishlari ham (1 + x)ⁿ ≈ 1 + nx kabi yaqinlashishlar bilan kiritiladi.', '<b>Инженерия и GPS:</b> допуски на чертежах вида «10 ± 0,1 мм» рассчитываются с помощью дифференциала. Релятивистские поправки к часам спутников GPS тоже вводятся через приближения вида (1 + x)ⁿ ≈ 1 + nx.', '<b>Engineering and GPS:</b> tolerances like “10 ± 0.1 mm” on drawings are computed with differentials. Relativistic corrections to GPS satellite clocks are also made with approximations like (1 + x)ⁿ ≈ 1 + nx.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Check yourself'), ex: [
      { q: L('√49,7 ≈ ?', '√49,7 ≈ ?', '√49.7 ≈ ?'), s: L('7 + 0,7/14 = 7 + 0,05 = 7,05 (aniq 7,04982…).', '7 + 0,7/14 = 7 + 0,05 = 7,05 (точно 7,04982…).', '7 + 0.7/14 = 7 + 0.05 = 7.05 (exact 7.04982…).') },
      { q: L('1,003²⁰ ≈ ?', '1,003²⁰ ≈ ?', '1.003²⁰ ≈ ?'), s: L('1 + 20·0,003 = 1,06 (aniq 1,0617).', '1 + 20·0,003 = 1,06 (точно 1,0617).', '1 + 20·0.003 = 1.06 (exact 1.0617).') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('dy = f′(x)dx — differensial; kichik Δx da Δy ≈ dy.', 'dy = f′(x)dx — дифференциал; при малом Δx Δy ≈ dy.', 'dy = f′(x)dx is the differential; for small Δx, Δy ≈ dy.'),
      L('Asosiy formula: f(x₀ + Δx) ≈ f(x₀) + f′(x₀)Δx (urinma bilan almashtirish).', 'Основная формула: f(x₀ + Δx) ≈ f(x₀) + f′(x₀)Δx (замена касательной).', 'Main formula: f(x₀ + Δx) ≈ f(x₀) + f′(x₀)Δx (replacing by the tangent).'),
      L('(1 + x)ⁿ ≈ 1 + nx, √(a² + Δ) ≈ a + Δ/(2a), sin x ≈ x, eˣ ≈ 1 + x.', '(1 + x)ⁿ ≈ 1 + nx, √(a² + Δ) ≈ a + Δ/(2a), sin x ≈ x, eˣ ≈ 1 + x.', '(1 + x)ⁿ ≈ 1 + nx, √(a² + Δ) ≈ a + Δ/(2a), sin x ≈ x, eˣ ≈ 1 + x.'),
      L('x₀ ni f(x₀) oson hisoblanadigan va Δx kichik bo‘ladigan qilib tanlang; burchaklar — radianda.', 'Выбирайте x₀ так, чтобы f(x₀) легко считалось, а Δx было малым; углы — в радианах.', 'Choose x₀ so that f(x₀) is easy and Δx is small; angles in radians.'),
      L('y = xⁿ da nisbiy xato n marta oshadi.', 'Для y = xⁿ относительная погрешность увеличивается в n раз.', 'For y = xⁿ the relative error is multiplied by n.')
    ] }
  ] });

  // ---------- t9. Hosila yordamida modellashtirish ----------
  T.add(P, 't9', { sections: [
    { kind: 'intro', h: L('O‘zgarish tili', 'Язык изменений', 'The language of change'), p: [
      L('Dunyo doimo o‘zgaradi: avtomobil tezlashadi, shahar aholisi ko‘payadi, choy soviydi, narxlar oshadi, dori qonda tarqaladi. Bu jarayonlarning barchasida bitta umumiy savol bor: «Qanchalik tez o‘zgarmoqda?». Hosila aynan shu savolga javob beruvchi universal matematik vositadir.', 'Мир постоянно меняется: автомобиль разгоняется, население города растёт, чай остывает, цены растут, лекарство распространяется в крови. Во всех этих процессах есть общий вопрос: «Как быстро это меняется?». Производная — универсальный математический инструмент, отвечающий именно на него.', 'The world is always changing: a car accelerates, a city’s population grows, tea cools, prices rise, a drug spreads through the blood. All these processes share one question: “How fast is it changing?”. The derivative is the universal mathematical tool that answers it.'),
      L('<b>Matematik model</b> — real jarayonning formulalar tilidagi soddalashtirilgan tasviri. Model qurilgach, hosila yordamida jarayonning tezligini, eng yuqori nuqtasini, to‘xtash vaqtini va boshqa muhim xususiyatlarini oldindan aytib berish mumkin. Fizik, iqtisodchi, biolog va muhandis aynan shunday ishlaydi.', '<b>Математическая модель</b> — упрощённое описание реального процесса на языке формул. Построив модель, с помощью производной можно заранее предсказать скорость процесса, его высшую точку, момент остановки и другие важные свойства. Так работают физик, экономист, биолог и инженер.', 'A <b>mathematical model</b> is a simplified description of a real process in the language of formulas. Once a model is built, the derivative lets us predict the speed of the process, its peak, the moment it stops and other key features. This is how physicists, economists, biologists and engineers work.'),
      L('Bu mavzuda bob davomida o‘rganganlarimizni turli fanlarga qo‘llaymiz: harakat, iqtisod, biologiya, elektr va «bog‘langan tezliklar» masalalari.', 'В этой теме мы применим изученное в главе к разным наукам: движение, экономика, биология, электричество и задачи о «связанных скоростях».', 'In this topic we apply what we have learned in this chapter to different sciences: motion, economics, biology, electricity and “related rates” problems.')
    ] },
    { kind: 'def', h: L('O‘zgarish tezligi — umumiy tushuncha', 'Скорость изменения — общее понятие', 'Rate of change — a general notion'), p: [
      L('Agar y kattalik x ga bog‘liq bo‘lsa (y = f(x)), <b>f′(x)</b> — y ning x ga nisbatan <b>oniy o‘zgarish tezligi</b>. U x bir birlikka oshganda y taxminan qanchaga o‘zgarishini ko‘rsatadi. Birligi — [y birligi]/[x birligi].', 'Если величина y зависит от x (y = f(x)), то <b>f′(x)</b> — <b>мгновенная скорость изменения</b> y по x. Она показывает, на сколько примерно изменится y при увеличении x на единицу. Единица — [единица y]/[единица x].', 'If a quantity y depends on x (y = f(x)), then <b>f′(x)</b> is the <b>instantaneous rate of change</b> of y with respect to x. It shows roughly how much y changes when x increases by one unit. Its unit is [unit of y]/[unit of x].'),
      L('Ishora ham ma’noga ega: f′ &gt; 0 — kattalik o‘smoqda, f′ &lt; 0 — kamaymoqda. Ikkinchi hosila f″ esa o‘sish tezlashyaptimi yoki sekinlashyaptimi, shuni bildiradi. Masalan, «inflyatsiya pasaymoqda» degani narxlar arzonlashmoqda degani emas — narxlar o‘sishda davom etmoqda (f′ &gt; 0), faqat sekinroq (f″ &lt; 0).', 'Знак тоже имеет смысл: f′ &gt; 0 — величина растёт, f′ &lt; 0 — убывает. Вторая производная f″ показывает, ускоряется рост или замедляется. Например, «инфляция снижается» не значит, что цены падают — цены продолжают расти (f′ &gt; 0), только медленнее (f″ &lt; 0).', 'The sign matters too: f′ &gt; 0 means the quantity grows, f′ &lt; 0 that it shrinks. The second derivative f″ tells whether growth is speeding up or slowing down. For example, “inflation is falling” does not mean prices are falling — prices keep rising (f′ &gt; 0), only more slowly (f″ &lt; 0).'),
      L('<b>Nisbiy o‘sish tezligi</b> f′/f — foizlarda ifodalanadi. Iqtisodda YaIM o‘sishi, biologiyada aholining o‘sish sur’ati shunday o‘lchanadi.', '<b>Относительная скорость роста</b> f′/f выражается в процентах. Так измеряют рост ВВП в экономике и темп роста популяции в биологии.', 'The <b>relative growth rate</b> f′/f is expressed in percent. GDP growth in economics and population growth rate in biology are measured this way.')
    ] },
    { kind: 'table', h: L('Turli fanlarda hosila', 'Производная в разных науках', 'The derivative across sciences'), table: { head: [L('Kattalik', 'Величина', 'Quantity'), L('Hosilasi', 'Её производная', 'Its derivative'), L('Fan', 'Наука', 'Science')], rows: [
      [L('yo‘l s(t)', 'путь s(t)', 'distance s(t)'), L('tezlik v = s′', 'скорость v = s′', 'velocity v = s′'), L('fizika', 'физика', 'physics')],
      [L('tezlik v(t)', 'скорость v(t)', 'velocity v(t)'), L('tezlanish a = v′', 'ускорение a = v′', 'acceleration a = v′'), L('fizika', 'физика', 'physics')],
      [L('zaryad q(t)', 'заряд q(t)', 'charge q(t)'), L('tok kuchi I = q′', 'сила тока I = q′', 'current I = q′'), L('elektrotexnika', 'электротехника', 'electrical engineering')],
      [L('xarajat C(x)', 'издержки C(x)', 'cost C(x)'), L('marjinal xarajat C′', 'предельные издержки C′', 'marginal cost C′'), L('iqtisod', 'экономика', 'economics')],
      [L('aholi soni N(t)', 'численность N(t)', 'population N(t)'), L('o‘sish tezligi N′', 'скорость роста N′', 'growth rate N′'), L('biologiya', 'биология', 'biology')],
      [L('konsentratsiya c(t)', 'концентрация c(t)', 'concentration c(t)'), L('reaksiya tezligi c′', 'скорость реакции c′', 'reaction rate c′'), L('kimyo', 'химия', 'chemistry')]
    ] } },
    { kind: 'steps', h: L('Modellashtirish bosqichlari', 'Этапы моделирования', 'Stages of modelling'), list: [
      L('1) O‘zgaruvchilarni aniqlang va belgilang (vaqt, miqdor, narx…), birliklarini yozing.', '1) Определите и обозначьте переменные (время, количество, цена…), запишите их единицы.', '1) Identify and name the variables (time, quantity, price…) and write their units.'),
      L('2) Ular orasidagi bog‘lanishni formula bilan ifodalang (berilgan yoki fizik qonundan).', '2) Выразите связь между ними формулой (данной или из физического закона).', '2) Express the relationship by a formula (given, or from a physical law).'),
      L('3) Savolga mos hosilani toping: tezlik, tezlanish, marjinal kattalik yoki ekstremum.', '3) Найдите производную, отвечающую вопросу: скорость, ускорение, предельная величина или экстремум.', '3) Find the derivative the question needs: rate, acceleration, marginal quantity or extremum.'),
      L('4) Sonlarni qo‘yib hisoblang.', '4) Подставьте числа и вычислите.', '4) Substitute numbers and compute.'),
      L('5) Natijani real hayot tilida izohlang va birlik hamda ma’nosini tekshiring.', '5) Истолкуйте результат на языке реальной ситуации, проверьте единицы и смысл.', '5) Interpret the result in real-life terms; check units and meaning.')
    ] },
    { kind: 'example', h: L('Harakat masalalari', 'Задачи о движении', 'Motion problems'), ex: [
      { q: L('Nuqta s(t) = t³ − 6t² (m) qonun bo‘yicha harakatlanadi. Tezlik, tezlanish va t = 2 s dagi holatni toping.', 'Точка движется по закону s(t) = t³ − 6t² (м). Найдите скорость, ускорение и состояние при t = 2 с.', 'A point moves by s(t) = t³ − 6t² (m). Find the velocity, the acceleration and the state at t = 2 s.'),
        s: L('v = 3t² − 12t, a = 6t − 12. t = 2 da <b>a = 0</b>, v = 12 − 24 = −12 m/s (nuqta orqaga harakatlanmoqda, tezligining moduli eng katta). v = 0 bo‘ladi t = 0 va t = 4 da — shu paytlarda nuqta to‘xtab, yo‘nalishini o‘zgartiradi.', 'v = 3t² − 12t, a = 6t − 12. При t = 2 <b>a = 0</b>, v = 12 − 24 = −12 м/с (точка движется назад, модуль скорости наибольший). v = 0 при t = 0 и t = 4 — в эти моменты точка останавливается и меняет направление.', 'v = 3t² − 12t, a = 6t − 12. At t = 2, <b>a = 0</b> and v = 12 − 24 = −12 m/s (moving backwards at its greatest speed). v = 0 at t = 0 and t = 4 — at these moments the point stops and reverses.') },
      { q: L('Koptok yuqoriga 20 m/s tezlik bilan otildi: h(t) = 20t − 5t² (m). Eng katta balandlik va yerga tushish tezligi?', 'Мяч брошен вверх со скоростью 20 м/с: h(t) = 20t − 5t² (м). Наибольшая высота и скорость при падении на землю?', 'A ball is thrown up at 20 m/s: h(t) = 20t − 5t² (m). Maximum height and landing speed?'),
        s: L('v = h′ = 20 − 10t = 0 ⇒ t = 2 s, h(2) = 40 − 20 = <b>20 m</b>. h = 0 ⇒ t = 4 s, v(4) = −20 m/s — koptok yerga <b>20 m/s</b> tezlik bilan qaytadi.', 'v = h′ = 20 − 10t = 0 ⇒ t = 2 с, h(2) = 40 − 20 = <b>20 м</b>. h = 0 ⇒ t = 4 с, v(4) = −20 м/с — мяч возвращается на землю со скоростью <b>20 м/с</b>.', 'v = h′ = 20 − 10t = 0 ⇒ t = 2 s, h(2) = 40 − 20 = <b>20 m</b>. h = 0 ⇒ t = 4 s, v(4) = −20 m/s — the ball returns at <b>20 m/s</b>.') },
      { q: L('O‘tkazgichdan o‘tgan zaryad q(t) = 3t² + t (Kl). t = 2 s dagi tok kuchi?', 'Заряд, прошедший через проводник, q(t) = 3t² + t (Кл). Сила тока при t = 2 с?', 'The charge through a conductor is q(t) = 3t² + t (C). The current at t = 2 s?'),
        s: L('I = q′ = 6t + 1, I(2) = <b>13 A</b>.', 'I = q′ = 6t + 1, I(2) = <b>13 А</b>.', 'I = q′ = 6t + 1, I(2) = <b>13 A</b>.') }
    ] },
    { kind: 'example', h: L('Iqtisod va biologiya masalalari', 'Задачи из экономики и биологии', 'Economics and biology problems'), ex: [
      { q: L('Korxonaning x dona mahsulot uchun xarajati C(x) = 1000 + 5x + 0,01x² (ming so‘m). 100-donadagi marjinal xarajat?', 'Издержки предприятия на x изделий C(x) = 1000 + 5x + 0,01x² (тыс. сумов). Предельные издержки при 100 изделиях?', 'A firm’s cost for x items is C(x) = 1000 + 5x + 0.01x² (thousand sum). The marginal cost at 100 items?'),
        s: L('C′(x) = 5 + 0,02x, C′(100) = <b>7 ming so‘m</b>: 101-mahsulot taxminan 7 ming so‘mga tushadi. Tekshiruv: C(101) − C(100) = 7,01.', 'C′(x) = 5 + 0,02x, C′(100) = <b>7 тыс. сумов</b>: 101-е изделие обойдётся примерно в 7 тыс. сумов. Проверка: C(101) − C(100) = 7,01.', 'C′(x) = 5 + 0.02x, C′(100) = <b>7 thousand sum</b>: the 101st item costs about 7 thousand. Check: C(101) − C(100) = 7.01.') },
      { q: L('Har bir mahsulot 15 ming so‘mdan sotilsa, qancha ishlab chiqarish eng foydali?', 'Если каждое изделие продаётся по 15 тыс. сумов, сколько выгоднее всего производить?', 'If each item sells for 15 thousand sum, how many should be produced for maximum profit?'),
        s: L('Foyda P(x) = 15x − C(x) = 10x − 0,01x² − 1000. P′ = 10 − 0,02x = 0 ⇒ x = <b>500</b> dona; P(500) = 5000 − 2500 − 1000 = 1500 ming so‘m. Bu nuqtada marjinal xarajat narxga teng: C′(500) = 15.', 'Прибыль P(x) = 15x − C(x) = 10x − 0,01x² − 1000. P′ = 10 − 0,02x = 0 ⇒ x = <b>500</b> изделий; P(500) = 5000 − 2500 − 1000 = 1500 тыс. сумов. В этой точке предельные издержки равны цене: C′(500) = 15.', 'Profit P(x) = 15x − C(x) = 10x − 0.01x² − 1000. P′ = 10 − 0.02x = 0 ⇒ x = <b>500</b> items; P(500) = 5000 − 2500 − 1000 = 1500 thousand sum. Here marginal cost equals price: C′(500) = 15.') },
      { q: L('Bakteriyalar soni N(t) = 1000·e<sup>0,03t</sup> (t — soat). O‘sish tezligi va nisbiy tezlik?', 'Число бактерий N(t) = 1000·e<sup>0,03t</sup> (t — часы). Скорость роста и относительная скорость?', 'The number of bacteria is N(t) = 1000·e<sup>0.03t</sup> (t in hours). Growth rate and relative rate?'),
        s: L('N′ = 30·e<sup>0,03t</sup> = 0,03·N. t = 0 da 30 ta/soat. Nisbiy tezlik N′/N = <b>0,03 = 3 % soatiga</b> — har doim bir xil: eksponensial o‘sishning belgisi shu.', 'N′ = 30·e<sup>0,03t</sup> = 0,03·N. При t = 0 — 30 штук/ч. Относительная скорость N′/N = <b>0,03 = 3 % в час</b> — всегда одна и та же: это признак экспоненциального роста.', 'N′ = 30·e<sup>0.03t</sup> = 0.03·N. At t = 0 it is 30 per hour. The relative rate N′/N = <b>0.03 = 3 % per hour</b> — always the same: the hallmark of exponential growth.') }
    ] },
    { kind: 'rule', h: L('Bog‘langan tezliklar', 'Связанные скорости', 'Related rates'), p: [
      L('Ko‘pincha ikki kattalik bir-biriga formula orqali bog‘langan bo‘ladi va ikkalasi ham vaqt bo‘yicha o‘zgaradi. Formulani t bo‘yicha zanjir qoidasi bilan differensiallab, bir kattalik tezligidan ikkinchisining tezligini topamiz.', 'Часто две величины связаны формулой, и обе меняются со временем. Продифференцировав формулу по t по цепному правилу, мы находим скорость одной величины по скорости другой.', 'Often two quantities are linked by a formula and both change in time. Differentiating the formula with respect to t by the chain rule, we find one rate from the other.'),
      L('<b>Misol.</b> Ko‘lga tosh tashlandi, to‘lqin doirasi radiusi 2 m/s tezlikda kengaymoqda. r = 5 m bo‘lganda doira yuzi qanchalik tez o‘sadi? S = πr², S′ = 2πr·r′ = 2π·5·2 = 20π ≈ <b>62,8 m²/s</b>. E’tibor bering: radius bir xil tezlikda o‘ssa ham, yuz tobora tezroq o‘sadi.', '<b>Пример.</b> В озеро бросили камень, радиус круговой волны растёт со скоростью 2 м/с. Как быстро растёт площадь круга при r = 5 м? S = πr², S′ = 2πr·r′ = 2π·5·2 = 20π ≈ <b>62,8 м²/с</b>. Заметьте: радиус растёт равномерно, а площадь — всё быстрее.', '<b>Example.</b> A stone is dropped into a lake and the circular ripple’s radius grows at 2 m/s. How fast does the area grow when r = 5 m? S = πr², S′ = 2πr·r′ = 2π·5·2 = 20π ≈ <b>62.8 m²/s</b>. Note: the radius grows steadily, but the area grows ever faster.'),
      L('<b>Yana bir misol.</b> Kub qirrasi 0,1 sm/s tezlikda qizib kengaymoqda. a = 10 sm da hajm o‘sish tezligi: V′ = 3a²·a′ = 3·100·0,1 = 30 sm³/s.', '<b>Ещё пример.</b> Ребро куба при нагревании растёт со скоростью 0,1 см/с. При a = 10 см скорость роста объёма: V′ = 3a²·a′ = 3·100·0,1 = 30 см³/с.', '<b>Another example.</b> A heated cube’s edge grows at 0.1 cm/s. At a = 10 cm the volume grows at V′ = 3a²·a′ = 3·100·0.1 = 30 cm³/s.')
    ] },
    { kind: 'history', h: L('Modellar tarixi', 'История моделей', 'A history of models'), p: [
      L('1687-yilda Nyuton «Natural falsafaning matematik asoslari» (Principia) asarida harakat qonunlarini e’lon qildi. Ikkinchi qonun F = ma aslida F = m·v′ — hosila tilidagi tenglama. Shu bilan fizika differensial tenglamalar faniga aylandi va Nyuton sayyoralar harakatini hamda dengiz suvining ko‘tarilishi va qaytishini tushuntirib berdi.', 'В 1687 году Ньютон опубликовал законы движения в «Математических началах натуральной философии». Второй закон F = ma — на самом деле F = m·v′, уравнение на языке производных. С этого физика стала наукой дифференциальных уравнений, и Ньютон объяснил движение планет и приливы.', 'In 1687 Newton published the laws of motion in his “Mathematical Principles of Natural Philosophy” (Principia). The second law F = ma is really F = m·v′, an equation in the language of derivatives. From then on physics became a science of differential equations, and Newton explained planetary motion and the tides.'),
      L('1798-yilda ingliz iqtisodchisi Tomas Maltus aholi eksponensial o‘sadi degan modelni taklif qildi (N′ = kN). Belgiyalik Per Ferxyulst 1838-yilda resurslar cheklanganini hisobga olib, «logistik» modelni yaratdi: N′ = kN(1 − N/M).', 'В 1798 году английский экономист Томас Мальтус предложил модель экспоненциального роста населения (N′ = kN). Бельгиец Пьер Ферхюльст в 1838 году, учтя ограниченность ресурсов, создал «логистическую» модель: N′ = kN(1 − N/M).', 'In 1798 the English economist Thomas Malthus proposed that population grows exponentially (N′ = kN). In 1838 the Belgian Pierre Verhulst, allowing for limited resources, created the “logistic” model: N′ = kN(1 − N/M).'),
      L('Iqtisodda «marjinal» tahlilni 1838-yilda fransuz Antuan Kurno boshlagan, 1870-yillarda Jevons, Menger va Valras «marjinalistik inqilob»ni amalga oshirdi: qiymat oxirgi qo‘shimcha birlikning foydaliligi bilan belgilanadi — bu hosilaning iqtisodiy talqini.', 'Предельный анализ в экономике начал француз Антуан Курно в 1838 году, а в 1870-х Джевонс, Менгер и Вальрас совершили «маржиналистскую революцию»: ценность определяется полезностью последней добавочной единицы — это экономическое истолкование производной.', 'Marginal analysis in economics was begun by the Frenchman Antoine Cournot in 1838, and in the 1870s Jevons, Menger and Walras carried out the “marginal revolution”: value is set by the usefulness of the last additional unit — an economic reading of the derivative.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Tezlik va tezlanishni aralashtirish.</b> a = 0 bo‘lsa, jism to‘xtagan emas — u o‘zgarmas tezlik bilan harakatlanmoqda. To‘xtash sharti — v = 0.', '<b>Путать скорость и ускорение.</b> Если a = 0, тело не остановилось — оно движется с постоянной скоростью. Условие остановки — v = 0.', '<b>Confusing velocity and acceleration.</b> If a = 0 the body has not stopped — it moves at constant velocity. Stopping means v = 0.'),
      L('<b>Birliklarni unutish.</b> C′(100) = 7 — bu «7» emas, «7 ming so‘m/dona». Birliksiz javob ma’nosiz.', '<b>Забывать единицы.</b> C′(100) = 7 — это не «7», а «7 тыс. сумов за изделие». Ответ без единиц бессмыслен.', '<b>Forgetting units.</b> C′(100) = 7 is not “7” but “7 thousand sum per item”. An answer without units is meaningless.'),
      L('<b>Tezlik ishorasini e’tiborsiz qoldirish.</b> v = −12 m/s — nuqta teskari yo‘nalishda harakatlanmoqda; tezlik moduli 12 m/s.', '<b>Игнорировать знак скорости.</b> v = −12 м/с — точка движется в обратном направлении; модуль скорости 12 м/с.', '<b>Ignoring the sign of velocity.</b> v = −12 m/s means motion in the opposite direction; the speed is 12 m/s.'),
      L('<b>Bog‘langan tezliklarda sonlarni oldinroq qo‘yish.</b> S = πr² ga r = 5 ni qo‘ysak, S = 25π o‘zgarmas bo‘lib, hosilasi 0 chiqadi. Avval differensiallang, keyin qo‘ying!', '<b>В связанных скоростях подставлять числа слишком рано.</b> Подставив r = 5 в S = πr², получим постоянную 25π с производной 0. Сначала дифференцируйте, потом подставляйте!', '<b>Substituting numbers too early in related rates.</b> Putting r = 5 into S = πr² gives the constant 25π with derivative 0. Differentiate first, then substitute!')
    ] },
    { kind: 'life', h: L('Modellar kundalik hayotda', 'Модели в повседневной жизни', 'Models in everyday life'), p: [
      L('<b>Avtomobil xavfsizligi:</b> havo yostiqchasi tezlanish keskin o‘zgarganda (soniyaning mingdan bir ulushida) ochiladi — datchik tezlikning hosilasini kuzatadi. Yo‘l harakati qoidalaridagi tormozlanish masofasi ham tezlik va tezlanish modeli asosida hisoblanadi.', '<b>Безопасность автомобиля:</b> подушка безопасности раскрывается при резком изменении ускорения (за тысячные доли секунды) — датчик следит за производной скорости. Тормозной путь в правилах дорожного движения тоже рассчитан по модели скорости и ускорения.', '<b>Car safety:</b> an airbag opens when the acceleration changes sharply (within milliseconds) — a sensor watches the derivative of velocity. Braking distances in the highway code are also computed from a velocity–acceleration model.'),
      L('<b>Epidemiologiya:</b> 2020-yilda butun dunyo «egri chiziqni yassilash» haqida gapirdi — bu kasallanish o‘sish tezligini (hosilani) kamaytirish degani edi. Epidemiya modellari (SIR) hosilalar orqali yoziladi.', '<b>Эпидемиология:</b> в 2020 году весь мир говорил о «сглаживании кривой» — это означало уменьшение скорости роста заболеваемости (производной). Модели эпидемий (SIR) записываются через производные.', '<b>Epidemiology:</b> in 2020 the whole world talked about “flattening the curve” — reducing the growth rate (the derivative) of infections. Epidemic models (SIR) are written in terms of derivatives.'),
      L('<b>Kundalik moliya:</b> oylik maoshning o‘sishi, kredit qarzining kamayish tezligi, telefon batareyasining zaryadsizlanish tezligi (% soatiga) — bularning hammasi hosila tilida tushuniladi.', '<b>Повседневные финансы:</b> рост зарплаты, скорость погашения кредита, скорость разрядки батареи телефона (% в час) — всё это понимается на языке производной.', '<b>Everyday finance:</b> salary growth, how fast a loan is paid off, how fast a phone battery drains (% per hour) — all are understood in the language of derivatives.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Check yourself'), ex: [
      { q: L('s(t) = 2t³ − 3t² + 4 (m). t = 3 s dagi tezlik va tezlanish?', 's(t) = 2t³ − 3t² + 4 (м). Скорость и ускорение при t = 3 с?', 's(t) = 2t³ − 3t² + 4 (m). Velocity and acceleration at t = 3 s?'), s: L('v = 6t² − 6t, v(3) = 36 m/s; a = 12t − 6, a(3) = 30 m/s².', 'v = 6t² − 6t, v(3) = 36 м/с; a = 12t − 6, a(3) = 30 м/с².', 'v = 6t² − 6t, v(3) = 36 m/s; a = 12t − 6, a(3) = 30 m/s².') },
      { q: L('Shar radiusi 1 sm/s tezlikda o‘smoqda. r = 3 sm da hajm qanchalik tez o‘sadi?', 'Радиус шара растёт со скоростью 1 см/с. Как быстро растёт объём при r = 3 см?', 'A sphere’s radius grows at 1 cm/s. How fast does the volume grow at r = 3 cm?'), s: L('V′ = 4πr²·r′ = 4π·9·1 = 36π ≈ 113 sm³/s.', 'V′ = 4πr²·r′ = 4π·9·1 = 36π ≈ 113 см³/с.', 'V′ = 4πr²·r′ = 4π·9·1 = 36π ≈ 113 cm³/s.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Hosila — har qanday jarayonning oniy o‘zgarish tezligi; birligi [y]/[x].', 'Производная — мгновенная скорость изменения любого процесса; единица [y]/[x].', 'The derivative is the instantaneous rate of change of any process; unit [y]/[x].'),
      L('Fizika: v = s′, a = v′, I = q′.', 'Физика: v = s′, a = v′, I = q′.', 'Physics: v = s′, a = v′, I = q′.'),
      L('Iqtisod: C′ — marjinal xarajat; foyda maksimumida marjinal xarajat narxga teng.', 'Экономика: C′ — предельные издержки; при максимуме прибыли предельные издержки равны цене.', 'Economics: C′ is marginal cost; at maximum profit marginal cost equals price.'),
      L('Biologiya: N′ — o‘sish tezligi; eksponensial o‘sishda N′/N o‘zgarmas.', 'Биология: N′ — скорость роста; при экспоненциальном росте N′/N постоянно.', 'Biology: N′ is the growth rate; in exponential growth N′/N is constant.'),
      L('Bog‘langan tezliklar: formulani t bo‘yicha differensiallang, keyin sonlarni qo‘ying.', 'Связанные скорости: продифференцируйте формулу по t, затем подставляйте числа.', 'Related rates: differentiate the formula with respect to t, then substitute numbers.')
    ] }
  ] });

  // ---------- t10. Boshlang‘ich funksiya va aniqmas integral ----------
  T.add(P, 't10', { sections: [
    { kind: 'intro', h: L('Teskari yo‘l: tezlikdan yo‘lga', 'Обратный путь: от скорости к пути', 'The way back: from speed to distance'), p: [
      L('Butun bob davomida biz bitta yo‘nalishda harakatlandik: funksiya berilgan — uning hosilasini topdik. Yo‘l s(t) ma’lum bo‘lsa, tezlik v(t) = s′(t). Ammo hayotda ko‘pincha teskari masala uchraydi: spidometr har lahzadagi tezlikni ko‘rsatib turadi, biz esa bosib o‘tilgan yo‘lni bilmoqchimiz. Samolyot yoki suv osti kemasining inersial navigatsiya tizimi faqat tezlanishni o‘lchaydi, lekin kema qayerda ekanini aniqlashi kerak.', 'На протяжении всей главы мы двигались в одном направлении: дана функция — находим её производную. Если известен путь s(t), то скорость v(t) = s′(t). Но в жизни часто встречается обратная задача: спидометр показывает скорость в каждый момент, а мы хотим знать пройденный путь. Инерциальная навигационная система самолёта или подводной лодки измеряет только ускорение, но должна определить, где находится судно.', 'Throughout this chapter we moved in one direction: given a function, find its derivative. If the distance s(t) is known, the velocity is v(t) = s′(t). But in life the reverse problem is common: the speedometer shows the speed at every instant, and we want the distance travelled. The inertial navigation system of an aircraft or submarine measures only acceleration, yet must determine where the vessel is.'),
      L('Bu — differensiallashga <b>teskari amal</b>, u <b>integrallash</b> deyiladi. Xuddi qo‘shishga ayirish, ko‘paytirishga bo‘lish, darajaga ko‘tarishga ildiz chiqarish teskari bo‘lgani kabi, hosila olishga integrallash teskari.', 'Это действие, <b>обратное</b> дифференцированию, оно называется <b>интегрированием</b>. Как вычитание обратно сложению, деление — умножению, извлечение корня — возведению в степень, так и интегрирование обратно взятию производной.', 'This is the <b>inverse</b> operation of differentiation, called <b>integration</b>. Just as subtraction undoes addition, division undoes multiplication and taking roots undoes raising to a power, integration undoes differentiation.'),
      L('Bu mavzu ikkinchi bobni — integral hisobni ochib beradi. Unda boshlang‘ich funksiya, aniqmas integral va ularning asosiy xossalari bilan tanishamiz.', 'Эта тема открывает вторую главу — интегральное исчисление. В ней мы познакомимся с первообразной, неопределённым интегралом и их основными свойствами.', 'This topic opens the second chapter — integral calculus. Here we meet the antiderivative, the indefinite integral and their main properties.')
    ] },
    { kind: 'def', h: L('Boshlang‘ich funksiya', 'Первообразная', 'Antiderivative'), p: [
      L('Agar biror oraliqdagi barcha x uchun <b>F′(x) = f(x)</b> bo‘lsa, F funksiya shu oraliqda f ning <b>boshlang‘ich funksiyasi</b> deyiladi.', 'Если для всех x из некоторого промежутка <b>F′(x) = f(x)</b>, то функция F называется <b>первообразной</b> для f на этом промежутке.', 'If <b>F′(x) = f(x)</b> for all x in some interval, the function F is called an <b>antiderivative</b> of f on that interval.'),
      L('Masalan, x² funksiyasi 2x ning boshlang‘ichi, chunki (x²)′ = 2x. sin x — cos x ning boshlang‘ichi, chunki (sin x)′ = cos x. −cos x — sin x ning boshlang‘ichi. eˣ — o‘zining boshlang‘ichi.', 'Например, x² — первообразная для 2x, так как (x²)′ = 2x. sin x — первообразная для cos x, так как (sin x)′ = cos x. −cos x — первообразная для sin x. eˣ — первообразная сама для себя.', 'For example, x² is an antiderivative of 2x because (x²)′ = 2x. sin x is an antiderivative of cos x because (sin x)′ = cos x. −cos x is an antiderivative of sin x. eˣ is its own antiderivative.'),
      L('Lekin x² + 5, x² − 3, x² + π ham 2x ning boshlang‘ichlari, chunki o‘zgarmasning hosilasi nol. Demak, boshlang‘ich funksiya yagona emas: agar F — boshlang‘ich bo‘lsa, istalgan C son uchun F + C ham boshlang‘ich.', 'Но x² + 5, x² − 3, x² + π — тоже первообразные для 2x, ведь производная константы равна нулю. Значит, первообразная не единственна: если F — первообразная, то F + C — тоже первообразная при любом числе C.', 'But x² + 5, x² − 3 and x² + π are also antiderivatives of 2x, since a constant has zero derivative. So an antiderivative is not unique: if F is one, then F + C is one for any number C.')
    ] },
    { kind: 'rule', h: L('Boshlang‘ich funksiyaning asosiy xossasi', 'Основное свойство первообразной', 'The main property of antiderivatives'), p: [
      L('<b>Teorema.</b> Agar F — f ning oraliqdagi boshlang‘ich funksiyasi bo‘lsa, f ning shu oraliqdagi <b>barcha</b> boshlang‘ich funksiyalari F(x) + C ko‘rinishida bo‘ladi, bu yerda C — ixtiyoriy o‘zgarmas.', '<b>Теорема.</b> Если F — первообразная для f на промежутке, то <b>все</b> первообразные для f на этом промежутке имеют вид F(x) + C, где C — произвольная постоянная.', '<b>Theorem.</b> If F is an antiderivative of f on an interval, then <b>all</b> antiderivatives of f on that interval have the form F(x) + C, where C is an arbitrary constant.'),
      L('<b>Isbot g‘oyasi.</b> G — boshqa boshlang‘ich bo‘lsin. U holda (G − F)′ = f − f = 0. Hosilasi oraliqning hamma nuqtasida nol bo‘lgan funksiya o‘zgarmas (bu Lagranj teoremasidan kelib chiqadi: istalgan ikki nuqtadagi qiymatlar ayirmasi f′(c)·(x₂ − x₁) = 0). Demak, G − F = C.', '<b>Идея доказательства.</b> Пусть G — другая первообразная. Тогда (G − F)′ = f − f = 0. Функция, производная которой равна нулю во всех точках промежутка, постоянна (это следует из теоремы Лагранжа: разность значений в любых двух точках равна f′(c)·(x₂ − x₁) = 0). Значит, G − F = C.', '<b>Proof idea.</b> Let G be another antiderivative. Then (G − F)′ = f − f = 0. A function whose derivative is zero at every point of an interval is constant (by Lagrange’s theorem the difference of its values at any two points is f′(c)·(x₂ − x₁) = 0). Hence G − F = C.'),
      L('Geometrik ma’nosi: barcha boshlang‘ichlarning grafiklari bir-biridan Oy o‘qi bo‘ylab siljitish orqali hosil bo‘ladi. Ularning har bir vertikal chiziq bilan kesishgan nuqtalaridagi urinmalari parallel — chunki qiyaliklari bir xil, f(x) ga teng.', 'Геометрический смысл: графики всех первообразных получаются друг из друга сдвигом вдоль оси Oy. В точках пересечения с любой вертикальной прямой их касательные параллельны — ведь наклоны одинаковы и равны f(x).', 'Geometric meaning: the graphs of all antiderivatives are vertical shifts of one another along Oy. Where they cross any vertical line, their tangents are parallel — their slopes are all equal to f(x).')
    ] },
    { kind: 'def', h: L('Aniqmas integral', 'Неопределённый интеграл', 'The indefinite integral'), p: [
      L('f funksiyaning barcha boshlang‘ich funksiyalari to‘plami uning <b>aniqmas integrali</b> deyiladi va <b>∫ f(x) dx = F(x) + C</b> deb yoziladi. ∫ — integral belgisi, f(x) — integral ostidagi funksiya, f(x)dx — integral ostidagi ifoda, x — integrallash o‘zgaruvchisi, C — integrallash o‘zgarmasi.', 'Множество всех первообразных функции f называется её <b>неопределённым интегралом</b> и обозначается <b>∫ f(x) dx = F(x) + C</b>. ∫ — знак интеграла, f(x) — подынтегральная функция, f(x)dx — подынтегральное выражение, x — переменная интегрирования, C — постоянная интегрирования.', 'The set of all antiderivatives of f is called its <b>indefinite integral</b>, written <b>∫ f(x) dx = F(x) + C</b>. ∫ is the integral sign, f(x) the integrand, f(x)dx the integrand expression, x the variable of integration and C the constant of integration.'),
      L('Ta’rifdan ikki muhim tenglik kelib chiqadi: <b>(∫ f(x) dx)′ = f(x)</b> va <b>∫ F′(x) dx = F(x) + C</b>. Ya’ni differensiallash va integrallash bir-birini «yo‘q qiladi» (o‘zgarmas aniqligida). Bu integrallash natijasini tekshirishning ishonchli usulini beradi: javobni differensiallang — integral ostidagi funksiya chiqishi kerak.', 'Из определения следуют два важных равенства: <b>(∫ f(x) dx)′ = f(x)</b> и <b>∫ F′(x) dx = F(x) + C</b>. То есть дифференцирование и интегрирование «уничтожают» друг друга (с точностью до постоянной). Это даёт надёжный способ проверки: продифференцируйте ответ — должна получиться подынтегральная функция.', 'Two important equalities follow: <b>(∫ f(x) dx)′ = f(x)</b> and <b>∫ F′(x) dx = F(x) + C</b>. Differentiation and integration “cancel” each other (up to a constant). This gives a reliable check: differentiate your answer — you should get the integrand back.')
    ] },
    { kind: 'table', h: L('Birinchi boshlang‘ichlar', 'Первые первообразные', 'First antiderivatives'), p: [
      L('Hosilalar jadvalini «teskari o‘qib», quyidagilarni olamiz (to‘liq jadval keyingi mavzuda):', '«Прочитав наоборот» таблицу производных, получим (полная таблица — в следующей теме):', 'Reading the table of derivatives “backwards” gives (the full table comes in the next topic):')
    ], table: { head: [L('f(x)', 'f(x)', 'f(x)'), L('∫ f(x) dx', '∫ f(x) dx', '∫ f(x) dx'), L('Tekshiruv', 'Проверка', 'Check')], rows: [
      ['0', 'C', L('C′ = 0', 'C′ = 0', 'C′ = 0')],
      ['k', L('kx + C', 'kx + C', 'kx + C'), L('(kx)′ = k', '(kx)′ = k', '(kx)′ = k')],
      [L('xⁿ (n ≠ −1)', 'xⁿ (n ≠ −1)', 'xⁿ (n ≠ −1)'), L('xⁿ⁺¹/(n + 1) + C', 'xⁿ⁺¹/(n + 1) + C', 'xⁿ⁺¹/(n + 1) + C'), L('(xⁿ⁺¹)′/(n + 1) = xⁿ', '(xⁿ⁺¹)′/(n + 1) = xⁿ', '(xⁿ⁺¹)′/(n + 1) = xⁿ')],
      ['cos x', L('sin x + C', 'sin x + C', 'sin x + C'), L('(sin x)′ = cos x', '(sin x)′ = cos x', '(sin x)′ = cos x')],
      ['sin x', L('−cos x + C', '−cos x + C', '−cos x + C'), L('(−cos x)′ = sin x', '(−cos x)′ = sin x', '(−cos x)′ = sin x')],
      [L('eˣ', 'eˣ', 'eˣ'), L('eˣ + C', 'eˣ + C', 'eˣ + C'), L('(eˣ)′ = eˣ', '(eˣ)′ = eˣ', '(eˣ)′ = eˣ')],
      ['1/x', L('ln |x| + C', 'ln |x| + C', 'ln |x| + C'), L('(ln |x|)′ = 1/x', '(ln |x|)′ = 1/x', '(ln |x|)′ = 1/x')]
    ] }, after: [
      L('Integralning chiziqlilik xossalari: ∫ (f ± g) dx = ∫ f dx ± ∫ g dx va ∫ k·f dx = k·∫ f dx. Ular hosilaning tegishli qoidalaridan kelib chiqadi.', 'Свойства линейности интеграла: ∫ (f ± g) dx = ∫ f dx ± ∫ g dx и ∫ k·f dx = k·∫ f dx. Они следуют из соответствующих правил для производной.', 'Linearity of the integral: ∫ (f ± g) dx = ∫ f dx ± ∫ g dx and ∫ k·f dx = k·∫ f dx. They follow from the corresponding derivative rules.')
    ] },
    { kind: 'steps', h: L('Berilgan nuqtadan o‘tuvchi boshlang‘ichni topish', 'Нахождение первообразной, проходящей через данную точку', 'Finding the antiderivative through a given point'), list: [
      L('1) Umumiy ko‘rinishni toping: F(x) + C.', '1) Найдите общий вид: F(x) + C.', '1) Find the general form F(x) + C.'),
      L('2) Shartdagi nuqta M(x₀; y₀) koordinatalarini qo‘ying: F(x₀) + C = y₀.', '2) Подставьте координаты точки M(x₀; y₀) из условия: F(x₀) + C = y₀.', '2) Substitute the point M(x₀; y₀): F(x₀) + C = y₀.'),
      L('3) C ni toping: C = y₀ − F(x₀).', '3) Найдите C: C = y₀ − F(x₀).', '3) Find C = y₀ − F(x₀).'),
      L('4) Javobni yozing va tekshiring: hosilasi f ga teng va grafik M dan o‘tadi.', '4) Запишите ответ и проверьте: производная равна f и график проходит через M.', '4) Write the answer and check: its derivative is f and the graph passes through M.')
    ], after: [
      L('Fizikada bu «boshlang‘ich shartlar» deyiladi: tezlanish ma’lum bo‘lsa, tezlikni topish uchun v(0) ni, yo‘lni topish uchun s(0) ni bilish kerak.', 'В физике это называют «начальными условиями»: если известно ускорение, для нахождения скорости нужно знать v(0), а для пути — s(0).', 'In physics these are called “initial conditions”: knowing the acceleration, we need v(0) to find the velocity and s(0) to find the position.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('F(x) = sin x + x³ funksiya f(x) = cos x + 3x² ning boshlang‘ichi ekanini tekshiring.', 'Проверьте, что F(x) = sin x + x³ — первообразная для f(x) = cos x + 3x².', 'Check that F(x) = sin x + x³ is an antiderivative of f(x) = cos x + 3x².'),
        s: L('F′(x) = cos x + 3x² = f(x) — barcha x uchun. <b>Ha, boshlang‘ich.</b>', 'F′(x) = cos x + 3x² = f(x) — для всех x. <b>Да, первообразная.</b>', 'F′(x) = cos x + 3x² = f(x) for all x. <b>Yes, it is an antiderivative.</b>') },
      { q: L('∫ (3x² − 4x + 5) dx ni toping.', 'Найдите ∫ (3x² − 4x + 5) dx.', 'Find ∫ (3x² − 4x + 5) dx.'),
        s: L('Hadma-had: ∫ 3x² dx = x³, ∫ 4x dx = 2x², ∫ 5 dx = 5x. Javob: <b>x³ − 2x² + 5x + C</b>. Tekshiruv: (x³ − 2x² + 5x)′ = 3x² − 4x + 5 ✓.', 'Почленно: ∫ 3x² dx = x³, ∫ 4x dx = 2x², ∫ 5 dx = 5x. Ответ: <b>x³ − 2x² + 5x + C</b>. Проверка: (x³ − 2x² + 5x)′ = 3x² − 4x + 5 ✓.', 'Term by term: ∫ 3x² dx = x³, ∫ 4x dx = 2x², ∫ 5 dx = 5x. Answer: <b>x³ − 2x² + 5x + C</b>. Check: (x³ − 2x² + 5x)′ = 3x² − 4x + 5 ✓.') },
      { q: L('f(x) = 4x³ ning M(1; 3) nuqtadan o‘tuvchi boshlang‘ichini toping.', 'Найдите первообразную для f(x) = 4x³, проходящую через M(1; 3).', 'Find the antiderivative of f(x) = 4x³ passing through M(1; 3).'),
        s: L('F(x) = x⁴ + C. 1 + C = 3 ⇒ C = 2. <b>F(x) = x⁴ + 2</b>.', 'F(x) = x⁴ + C. 1 + C = 3 ⇒ C = 2. <b>F(x) = x⁴ + 2</b>.', 'F(x) = x⁴ + C. 1 + C = 3 ⇒ C = 2. <b>F(x) = x⁴ + 2</b>.') },
      { q: L('Jism tezlanishi a(t) = 6t (m/s²), v(0) = 2 m/s, s(0) = 1 m. s(t) ni toping.', 'Ускорение тела a(t) = 6t (м/с²), v(0) = 2 м/с, s(0) = 1 м. Найдите s(t).', 'A body has acceleration a(t) = 6t (m/s²), v(0) = 2 m/s, s(0) = 1 m. Find s(t).'),
        s: L('v = ∫ 6t dt = 3t² + C₁, v(0) = C₁ = 2 ⇒ v = 3t² + 2. s = ∫ (3t² + 2) dt = t³ + 2t + C₂, s(0) = C₂ = 1. <b>s(t) = t³ + 2t + 1</b>; masalan, s(2) = 13 m.', 'v = ∫ 6t dt = 3t² + C₁, v(0) = C₁ = 2 ⇒ v = 3t² + 2. s = ∫ (3t² + 2) dt = t³ + 2t + C₂, s(0) = C₂ = 1. <b>s(t) = t³ + 2t + 1</b>; например, s(2) = 13 м.', 'v = ∫ 6t dt = 3t² + C₁, v(0) = C₁ = 2 ⇒ v = 3t² + 2. s = ∫ (3t² + 2) dt = t³ + 2t + C₂, s(0) = C₂ = 1. <b>s(t) = t³ + 2t + 1</b>; e.g. s(2) = 13 m.') },
      { q: L('∫ (2 cos x − 1/x²) dx ni toping (x &gt; 0).', 'Найдите ∫ (2 cos x − 1/x²) dx (x &gt; 0).', 'Find ∫ (2 cos x − 1/x²) dx (x &gt; 0).'),
        s: L('∫ 2 cos x dx = 2 sin x; −1/x² = −x<sup>−2</sup>, ∫ −x<sup>−2</sup> dx = x<sup>−1</sup> = 1/x. Javob: <b>2 sin x + 1/x + C</b>. Tekshiruv: (2 sin x + 1/x)′ = 2 cos x − 1/x² ✓.', '∫ 2 cos x dx = 2 sin x; −1/x² = −x<sup>−2</sup>, ∫ −x<sup>−2</sup> dx = x<sup>−1</sup> = 1/x. Ответ: <b>2 sin x + 1/x + C</b>. Проверка: (2 sin x + 1/x)′ = 2 cos x − 1/x² ✓.', '∫ 2 cos x dx = 2 sin x; −1/x² = −x<sup>−2</sup>, ∫ −x<sup>−2</sup> dx = x<sup>−1</sup> = 1/x. Answer: <b>2 sin x + 1/x + C</b>. Check: (2 sin x + 1/x)′ = 2 cos x − 1/x² ✓.') }
    ] },
    { kind: 'history', h: L('Integral belgisi va nomi tarixi', 'История знака и названия интеграла', 'History of the integral sign and name'), p: [
      L('Yuzalarni cheksiz ko‘p bo‘laklarga bo‘lib hisoblash g‘oyasi Arximeddan boshlanadi: u parabola segmentining yuzini topgan. XVII asrda italiyalik Bonaventura Kavalyeri «bo‘linmaslar usuli»ni yaratdi. Lekin yuza masalasi va urinma masalasi o‘zaro teskari ekanini — ya’ni integrallash differensiallashga teskari ekanini — Nyuton va Leybnits kashf etdi. Bu kashfiyot analizning asosiy teoremasi deyiladi.', 'Идея вычислять площади, деля их на бесконечно много частей, восходит к Архимеду: он нашёл площадь параболического сегмента. В XVII веке итальянец Бонавентура Кавальери создал «метод неделимых». Но то, что задачи о площади и о касательной взаимно обратны — т. е. интегрирование обратно дифференцированию, — открыли Ньютон и Лейбниц. Это открытие называют основной теоремой анализа.', 'The idea of computing areas by splitting them into infinitely many parts goes back to Archimedes, who found the area of a parabolic segment. In the 17th century the Italian Bonaventura Cavalieri created the “method of indivisibles”. But the discovery that the area and tangent problems are inverse to each other — that integration undoes differentiation — was made by Newton and Leibniz. It is called the fundamental theorem of calculus.'),
      L('∫ belgisini Leybnits 1675-yil 29-oktabrdagi qo‘lyozmasida kiritgan: bu cho‘zilgan lotincha S harfi — <i>summa</i> (yig‘indi) so‘zining bosh harfi. «Integral» atamasini esa 1690-yilda Yakob Bernulli taklif qilgan (lotincha <i>integer</i> — «butun»). Leybnits avval «summalar hisobi» degan nomni ishlatgan edi.', 'Знак ∫ Лейбниц ввёл в рукописи от 29 октября 1675 года: это вытянутая латинская буква S — первая буква слова <i>summa</i> (сумма). Термин «интеграл» предложил Якоб Бернулли в 1690 году (лат. <i>integer</i> — «целый»). Сам Лейбниц сначала говорил «исчисление сумм».', 'Leibniz introduced the sign ∫ in a manuscript dated 29 October 1675: it is an elongated Latin S, the first letter of <i>summa</i> (sum). The term “integral” was proposed by Jacob Bernoulli in 1690 (Latin <i>integer</i>, “whole”). Leibniz himself first spoke of a “calculus of sums”.'),
      L('«Aniqmas integral» nomi C o‘zgarmasning noaniqligini ko‘rsatadi. Fransuz Jozef Furye XIX asr boshida integral chegaralarini belgi ostiga va ustiga yozishni kiritdi — bu keyingi mavzulardagi aniq integralga olib keladi.', 'Название «неопределённый интеграл» указывает на неопределённость постоянной C. Француз Жозеф Фурье в начале XIX века ввёл запись пределов интегрирования снизу и сверху знака — это приведёт нас к определённому интегралу в следующих темах.', 'The name “indefinite integral” reflects the undetermined constant C. In the early 19th century the Frenchman Joseph Fourier introduced writing the limits of integration below and above the sign — leading to the definite integral in later topics.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>+C ni unutish.</b> ∫ 2x dx = x² — to‘liq emas. Aniqmas integral — butun funksiyalar oilasi: x² + C.', '<b>Забывать +C.</b> ∫ 2x dx = x² — неполно. Неопределённый интеграл — целое семейство функций: x² + C.', '<b>Forgetting +C.</b> ∫ 2x dx = x² is incomplete. The indefinite integral is a whole family of functions: x² + C.'),
      L('<b>Daraja formulasini n = −1 da qo‘llash.</b> ∫ x<sup>−1</sup> dx = x⁰/0 — ma’nosiz. To‘g‘risi: ln |x| + C.', '<b>Применять формулу для степени при n = −1.</b> ∫ x<sup>−1</sup> dx = x⁰/0 — бессмысленно. Верно: ln |x| + C.', '<b>Using the power formula with n = −1.</b> ∫ x<sup>−1</sup> dx = x⁰/0 is meaningless. Correct: ln |x| + C.'),
      L('<b>Ko‘paytmani ko‘paytuvchilar bo‘yicha integrallash.</b> ∫ x·x dx ≠ (x²/2)·(x²/2). Avval soddalashtiring: ∫ x² dx = x³/3 + C.', '<b>Интегрировать произведение по множителям.</b> ∫ x·x dx ≠ (x²/2)·(x²/2). Сначала упростите: ∫ x² dx = x³/3 + C.', '<b>Integrating a product factor by factor.</b> ∫ x·x dx ≠ (x²/2)·(x²/2). Simplify first: ∫ x² dx = x³/3 + C.'),
      L('<b>∫ sin x dx = cos x deb yozish.</b> Ishora: (cos x)′ = −sin x, shuning uchun ∫ sin x dx = −cos x + C. Har doim differensiallab tekshiring!', '<b>Писать ∫ sin x dx = cos x.</b> Знак: (cos x)′ = −sin x, поэтому ∫ sin x dx = −cos x + C. Всегда проверяйте дифференцированием!', '<b>Writing ∫ sin x dx = cos x.</b> Sign: (cos x)′ = −sin x, so ∫ sin x dx = −cos x + C. Always check by differentiating!')
    ] },
    { kind: 'life', h: L('Integrallash hayotda', 'Интегрирование в жизни', 'Integration in life'), p: [
      L('<b>Avtomobil va navigatsiya:</b> odometr (yo‘l hisoblagich) aslida tezlikni vaqt bo‘yicha «yig‘adi» — integrallaydi. Smartfonlar va dronlarning inersial datchiklari tezlanishni ikki marta integrallab, joylashuvni aniqlaydi; GPS signali yo‘q tunnelda navigator shunday ishlaydi.', '<b>Автомобиль и навигация:</b> одометр по сути «суммирует» — интегрирует — скорость по времени. Инерциальные датчики смартфонов и дронов дважды интегрируют ускорение, определяя положение; так работает навигатор в тоннеле без сигнала GPS.', '<b>Cars and navigation:</b> an odometer essentially “sums up” — integrates — speed over time. The inertial sensors of phones and drones integrate acceleration twice to find position; that is how a navigator works in a tunnel without GPS.'),
      L('<b>Suv va energiya:</b> suv quvuridan oqim tezligi (litr/sekund) ma’lum bo‘lsa, havzaga tushgan suv hajmini integral beradi. Elektr hisoblagich quvvatni vaqt bo‘yicha integrallab, kVt·soat sonini ko‘rsatadi.', '<b>Вода и энергия:</b> если известна скорость потока в трубе (литр/секунда), объём воды в бассейне даёт интеграл. Электросчётчик интегрирует мощность по времени и показывает число кВт·ч.', '<b>Water and energy:</b> if the flow rate in a pipe (litres per second) is known, the integral gives the volume of water in a pool. An electricity meter integrates power over time and shows kilowatt-hours.'),
      L('<b>Iqtisod:</b> marjinal xarajat C′(x) ma’lum bo‘lsa, umumiy xarajat C(x) integrallash orqali tiklanadi; o‘zgarmas C esa doimiy xarajatlar (ijara, uskunalar) — ishlab chiqarish nol bo‘lganda ham to‘lanadigan pul.', '<b>Экономика:</b> если известны предельные издержки C′(x), общие издержки C(x) восстанавливаются интегрированием; а постоянная C — это постоянные издержки (аренда, оборудование), которые платятся даже при нулевом выпуске.', '<b>Economics:</b> given the marginal cost C′(x), the total cost C(x) is recovered by integration; the constant C is the fixed cost (rent, equipment), paid even when output is zero.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Har qanday elementar funksiyaning hosilasi yana elementar funksiya, ammo integral uchun bu to‘g‘ri emas! Masalan, ∫ e<sup>−x²</sup> dx ni elementar funksiyalar orqali yozib bo‘lmaydi — buni fransuz Jozef Liuvill 1830-yillarda isbotlagan. Holbuki aynan shu funksiya ehtimollar nazariyasidagi normal taqsimotning asosi.', 'Производная любой элементарной функции снова элементарна, а для интеграла это неверно! Например, ∫ e<sup>−x²</sup> dx нельзя записать через элементарные функции — это доказал француз Жозеф Лиувилль в 1830-х годах. А ведь именно эта функция лежит в основе нормального распределения в теории вероятностей.', 'The derivative of any elementary function is elementary, but this is not true for integrals! For example, ∫ e<sup>−x²</sup> dx cannot be written with elementary functions — the Frenchman Joseph Liouville proved this in the 1830s. Yet this very function underlies the normal distribution in probability.'),
      L('Shuning uchun matematiklar aytadi: «Differensiallash — hunar, integrallash — san’at». Hosilani algoritm bo‘yicha topish mumkin, integral esa ko‘pincha zukkolik talab qiladi.', 'Поэтому математики говорят: «Дифференцирование — ремесло, интегрирование — искусство». Производную можно найти по алгоритму, а интеграл часто требует смекалки.', 'That is why mathematicians say: “Differentiation is a craft, integration is an art”. A derivative can be found by algorithm, while an integral often needs ingenuity.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('F′(x) = f(x) bo‘lsa, F — f ning boshlang‘ich funksiyasi.', 'Если F′(x) = f(x), то F — первообразная для f.', 'If F′(x) = f(x), F is an antiderivative of f.'),
      L('Barcha boshlang‘ichlar F(x) + C ko‘rinishida; ular grafiklari Oy bo‘ylab siljigan.', 'Все первообразные имеют вид F(x) + C; их графики сдвинуты вдоль Oy.', 'All antiderivatives have the form F(x) + C; their graphs are shifted along Oy.'),
      L('∫ f(x) dx = F(x) + C — aniqmas integral; integrallash differensiallashga teskari.', '∫ f(x) dx = F(x) + C — неопределённый интеграл; интегрирование обратно дифференцированию.', '∫ f(x) dx = F(x) + C is the indefinite integral; integration undoes differentiation.'),
      L('∫ xⁿ dx = xⁿ⁺¹/(n + 1) + C (n ≠ −1), ∫ dx/x = ln |x| + C, ∫ cos x dx = sin x + C.', '∫ xⁿ dx = xⁿ⁺¹/(n + 1) + C (n ≠ −1), ∫ dx/x = ln |x| + C, ∫ cos x dx = sin x + C.', '∫ xⁿ dx = xⁿ⁺¹/(n + 1) + C (n ≠ −1), ∫ dx/x = ln |x| + C, ∫ cos x dx = sin x + C.'),
      L('C ni boshlang‘ich shartdan (nuqtadan) topish mumkin; javobni har doim differensiallab tekshiring.', 'C находят из начального условия (точки); ответ всегда проверяйте дифференцированием.', 'C is found from an initial condition (a point); always check the answer by differentiating.')
    ] }
  ] });
})(this);

// Nuvemath — 11-sinf, I qism (Algebra 11) nazariyasi, t11–t20
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '11-1';
  function S(x) { return L(x, x, x); }

  // ---------- t11. Integrallar jadvali. Integrallashning sodda qoidalari ----------
  T.add(P, 't11', { sections: [
    { kind: 'intro', h: L('Hosilaning teskarisi', 'Обратная операция к производной', 'The reverse of differentiation'), p: [
      L('Tasavvur qiling: avtomobilning spidometri har bir lahzadagi tezlikni ko‘rsatadi, lekin yo‘l hisoblagichi buzilgan. Tezlik ma’lum bo‘lsa, bosib o‘tilgan yo‘lni qanday tiklash mumkin? Hosila yo‘ldan tezlikni topar edi; endi esa teskari ish kerak — tezlikdan yo‘lni topish. Bu amal <b>integrallash</b> deyiladi.', 'Представьте: спидометр автомобиля показывает скорость в каждый момент, а счётчик пробега сломан. Как по известной скорости восстановить пройденный путь? Производная находила по пути скорость; теперь нужна обратная операция — по скорости найти путь. Она называется <b>интегрированием</b>.', 'Imagine a car whose speedometer shows the speed at every moment, but whose odometer is broken. How can we recover the distance from the known speed? Differentiation turned distance into speed; now we need the reverse — turning speed back into distance. This operation is called <b>integration</b>.'),
      L('Oldingi mavzuda biz boshlang‘ich funksiya bilan tanishdik: F′(x) = f(x) bo‘lsa, F funksiya f ning boshlang‘ichi. Bu mavzuda esa boshlang‘ichlarni tez topishga o‘rganamiz: asosiy funksiyalar uchun tayyor <b>integrallar jadvali</b>ni va murakkab ifodalarni shu jadvalga keltiradigan uchta sodda qoidani o‘zlashtiramiz. Ular aniq integral, yuzlar va hajmlarni hisoblash uchun poydevor bo‘ladi.', 'В предыдущей теме мы познакомились с первообразной: если F′(x) = f(x), то F — первообразная для f. В этой теме научимся быстро находить первообразные: освоим готовую <b>таблицу интегралов</b> основных функций и три простых правила, которые сводят сложные выражения к таблице. Это фундамент для определённого интеграла, площадей и объёмов.', 'In the previous topic we met the antiderivative: if F′(x) = f(x), then F is an antiderivative of f. Here we learn to find antiderivatives quickly: we master a ready <b>table of integrals</b> for the basic functions and three simple rules that reduce complicated expressions to the table. This is the foundation for definite integrals, areas and volumes.')
    ] },
    { kind: 'def', h: L('Aniqmas integral', 'Неопределённый интеграл', 'The indefinite integral'), p: [
      L('f funksiyaning barcha boshlang‘ichlari to‘plami <b>aniqmas integral</b> deyiladi va ∫ f(x) dx bilan belgilanadi: ∫ f(x) dx = F(x) + C, bunda F — biror boshlang‘ich, C — ixtiyoriy o‘zgarmas son. Bu yerda ∫ — integral belgisi, f(x) — integral ostidagi funksiya, f(x) dx — integral ostidagi ifoda, x — integrallash o‘zgaruvchisi.', 'Множество всех первообразных функции f называется <b>неопределённым интегралом</b> и обозначается ∫ f(x) dx: ∫ f(x) dx = F(x) + C, где F — какая-либо первообразная, C — произвольная постоянная. Здесь ∫ — знак интеграла, f(x) — подынтегральная функция, f(x) dx — подынтегральное выражение, x — переменная интегрирования.', 'The set of all antiderivatives of f is called the <b>indefinite integral</b> and is written ∫ f(x) dx: ∫ f(x) dx = F(x) + C, where F is any antiderivative and C is an arbitrary constant. Here ∫ is the integral sign, f(x) is the integrand, f(x) dx is the integrand expression and x is the variable of integration.'),
      L('Nega «+ C» shart? Chunki o‘zgarmasning hosilasi nolga teng: (x² + 5)′ = (x² − 7)′ = 2x. Demak, 2x ning boshlang‘ichlari cheksiz ko‘p va ularning grafiklari bir-biridan Oy o‘qi bo‘ylab siljitish bilan hosil bo‘ladi. Tekshirish qoidasi oddiy: javobni differensiallang — integral ostidagi funksiya chiqishi kerak.', 'Зачем «+ C»? Потому что производная постоянной равна нулю: (x² + 5)′ = (x² − 7)′ = 2x. Значит, первообразных у 2x бесконечно много, и их графики получаются друг из друга сдвигом вдоль оси Oy. Правило проверки простое: продифференцируйте ответ — должна получиться подынтегральная функция.', 'Why is “+ C” needed? Because the derivative of a constant is zero: (x² + 5)′ = (x² − 7)′ = 2x. So 2x has infinitely many antiderivatives, and their graphs are vertical shifts of each other along the Oy axis. The checking rule is simple: differentiate your answer — you must get the integrand back.')
    ] },
    { kind: 'history', h: L('∫ belgisi qanday paydo bo‘lgan', 'Как появился знак ∫', 'How the ∫ sign appeared'), p: [
      L('XVII asrning 60–80-yillarida ingliz <b>Isaak Nyuton</b> va nemis <b>Gotfrid Leybnits</b> bir-biridan mustaqil ravishda differensial va integral hisobni yaratdilar. Nyuton boshlang‘ichni «flyuenta» deb atagan bo‘lsa, Leybnits qulay belgilar tizimini o‘ylab topdi. 1675-yil 29-oktabrdagi qo‘lyozmasida u birinchi marta cho‘zilgan S harfi — ∫ belgisini yozdi. Bu lotincha <i>summa</i> (yig‘indi) so‘zining bosh harfi edi: Leybnits integralni cheksiz kichik qo‘shiluvchilar yig‘indisi deb tushungan.', 'В 1660–1680-х годах англичанин <b>Исаак Ньютон</b> и немец <b>Готфрид Лейбниц</b> независимо друг от друга создали дифференциальное и интегральное исчисление. Ньютон называл первообразную «флюентой», а Лейбниц придумал удобную систему обозначений. В рукописи от 29 октября 1675 года он впервые написал вытянутую букву S — знак ∫. Это первая буква латинского <i>summa</i> (сумма): Лейбниц понимал интеграл как сумму бесконечно малых слагаемых.', 'In the 1660s–1680s the Englishman <b>Isaac Newton</b> and the German <b>Gottfried Leibniz</b> independently created differential and integral calculus. Newton called the antiderivative a “fluent”, while Leibniz invented a convenient notation. In a manuscript dated 29 October 1675 he first wrote an elongated letter S — the sign ∫. It is the first letter of the Latin <i>summa</i> (sum): Leibniz thought of an integral as a sum of infinitely small terms.'),
      L('«Integral» atamasini esa shveytsariyalik aka-uka Bernullilar ommalashtirdi: Yakob Bernulli 1690-yilda uni bosma asarda ishlatdi. XIX asrda fransuz <b>Jozef Liuvill</b> isbotladiki, ba’zi oddiy ko‘rinishdagi funksiyalarning, masalan e<sup>−x²</sup> ning, boshlang‘ichi elementar funksiyalar orqali umuman ifodalanmaydi. Shuning uchun jadval va qoidalar hamma narsani hal qilmaydi — bu haqda «Taqribiy integrallash» mavzusida gaplashamiz.', 'Термин «интеграл» популяризировали швейцарские братья Бернулли: Якоб Бернулли употребил его в печати в 1690 году. В XIX веке француз <b>Жозеф Лиувилль</b> доказал, что первообразные некоторых простых на вид функций, например e<sup>−x²</sup>, вообще не выражаются через элементарные функции. Поэтому таблица и правила решают не всё — об этом поговорим в теме «Приближённое интегрирование».', 'The term “integral” was popularised by the Swiss Bernoulli brothers: Jacob Bernoulli used it in print in 1690. In the 19th century the Frenchman <b>Joseph Liouville</b> proved that the antiderivatives of some innocent-looking functions, such as e<sup>−x²</sup>, cannot be expressed by elementary functions at all. So the table and rules do not solve everything — we return to this in the topic “Approximate integration”.')
    ] },
    { kind: 'table', h: L('Asosiy integrallar jadvali', 'Таблица основных интегралов', 'Table of basic integrals'), p: [
      L('Har bir qator hosilalar jadvalini «teskari o‘qish»dan kelib chiqadi. Masalan, (sin x)′ = cos x bo‘lgani uchun ∫ cos x dx = sin x + C. Jadvalni yodlash shart emas — uni hosilalardan bir daqiqada tiklash mumkin, lekin tez ishlash uchun eslab qolgan ma’qul.', 'Каждая строка получается «обратным чтением» таблицы производных. Например, так как (sin x)′ = cos x, то ∫ cos x dx = sin x + C. Таблицу не обязательно зубрить — её можно восстановить из производных за минуту, но для быстрой работы её лучше помнить.', 'Each row comes from reading the derivative table “backwards”. For example, since (sin x)′ = cos x, we get ∫ cos x dx = sin x + C. You need not cram the table — it can be rebuilt from derivatives in a minute — but for fast work it is better to remember it.')
    ], table: { head: [L('Funksiya f(x)', 'Функция f(x)', 'Function f(x)'), L('∫ f(x) dx', '∫ f(x) dx', '∫ f(x) dx'), L('Shart', 'Условие', 'Condition')], rows: [
      [S('xⁿ'), S('xⁿ⁺¹/(n + 1) + C'), L('n ≠ −1', 'n ≠ −1', 'n ≠ −1')],
      [S('1/x'), S('ln|x| + C'), L('x ≠ 0', 'x ≠ 0', 'x ≠ 0')],
      [S('eˣ'), S('eˣ + C'), L('har qanday x', 'любое x', 'any x')],
      [S('aˣ'), S('aˣ/ln a + C'), L('a &gt; 0, a ≠ 1', 'a &gt; 0, a ≠ 1', 'a &gt; 0, a ≠ 1')],
      [S('sin x'), S('−cos x + C'), L('har qanday x', 'любое x', 'any x')],
      [S('cos x'), S('sin x + C'), L('har qanday x', 'любое x', 'any x')],
      [S('1/cos²x'), S('tg x + C'), L('cos x ≠ 0', 'cos x ≠ 0', 'cos x ≠ 0')],
      [S('1/sin²x'), S('−ctg x + C'), L('sin x ≠ 0', 'sin x ≠ 0', 'sin x ≠ 0')],
      [S('1/(1 + x²)'), S('arctg x + C'), L('har qanday x', 'любое x', 'any x')],
      [S('1/√(1 − x²)'), S('arcsin x + C'), L('|x| &lt; 1', '|x| &lt; 1', '|x| &lt; 1')]
    ] } },
    { kind: 'rule', h: L('Integrallashning uchta qoidasi', 'Три правила интегрирования', 'Three rules of integration'), p: [
      L('<b>1-qoida (yig‘indi).</b> ∫ (f(x) ± g(x)) dx = ∫ f(x) dx ± ∫ g(x) dx. Isbot g‘oyasi: agar F′ = f va G′ = g bo‘lsa, (F ± G)′ = f ± g. Demak, ko‘phadni hadma-had integrallash mumkin.', '<b>Правило 1 (сумма).</b> ∫ (f(x) ± g(x)) dx = ∫ f(x) dx ± ∫ g(x) dx. Идея доказательства: если F′ = f и G′ = g, то (F ± G)′ = f ± g. Значит, многочлен можно интегрировать почленно.', '<b>Rule 1 (sum).</b> ∫ (f(x) ± g(x)) dx = ∫ f(x) dx ± ∫ g(x) dx. Proof idea: if F′ = f and G′ = g, then (F ± G)′ = f ± g. So a polynomial can be integrated term by term.'),
      L('<b>2-qoida (o‘zgarmas ko‘paytuvchi).</b> ∫ k·f(x) dx = k·∫ f(x) dx, k — son. Sababi: (kF)′ = kF′ = kf. Masalan, ∫ 6x² dx = 6·x³/3 + C = 2x³ + C.', '<b>Правило 2 (постоянный множитель).</b> ∫ k·f(x) dx = k·∫ f(x) dx, k — число. Причина: (kF)′ = kF′ = kf. Например, ∫ 6x² dx = 6·x³/3 + C = 2x³ + C.', '<b>Rule 2 (constant factor).</b> ∫ k·f(x) dx = k·∫ f(x) dx, where k is a number. Reason: (kF)′ = kF′ = kf. For example, ∫ 6x² dx = 6·x³/3 + C = 2x³ + C.'),
      L('<b>3-qoida (chiziqli argument).</b> Agar ∫ f(x) dx = F(x) + C bo‘lsa, ∫ f(kx + b) dx = (1/k)·F(kx + b) + C, k ≠ 0. Isbot: murakkab funksiya hosilasi bo‘yicha (F(kx + b))′ = k·f(kx + b), shuning uchun 1/k ko‘paytuvchi ortiqcha k ni yo‘qotadi. Masalan, ∫ e<sup>3x</sup> dx = e<sup>3x</sup>/3 + C.', '<b>Правило 3 (линейный аргумент).</b> Если ∫ f(x) dx = F(x) + C, то ∫ f(kx + b) dx = (1/k)·F(kx + b) + C, k ≠ 0. Доказательство: по правилу производной сложной функции (F(kx + b))′ = k·f(kx + b), поэтому множитель 1/k убирает лишний k. Например, ∫ e<sup>3x</sup> dx = e<sup>3x</sup>/3 + C.', '<b>Rule 3 (linear argument).</b> If ∫ f(x) dx = F(x) + C, then ∫ f(kx + b) dx = (1/k)·F(kx + b) + C, k ≠ 0. Proof: by the chain rule (F(kx + b))′ = k·f(kx + b), so the factor 1/k cancels the extra k. For example, ∫ e<sup>3x</sup> dx = e<sup>3x</sup>/3 + C.'),
      L('Diqqat: ko‘paytmaning yoki bo‘linmaning integrali uchun bunday sodda qoida <b>yo‘q</b>. ∫ f·g dx ≠ ∫ f dx · ∫ g dx. Bunday hollarda avval ifodani soddalashtirish (qavslarni ochish, bo‘lish) kerak.', 'Внимание: для интеграла произведения или частного такого простого правила <b>нет</b>. ∫ f·g dx ≠ ∫ f dx · ∫ g dx. В таких случаях сначала упрощают выражение (раскрывают скобки, делят почленно).', 'Note: there is <b>no</b> such simple rule for the integral of a product or a quotient. ∫ f·g dx ≠ ∫ f dx · ∫ g dx. In such cases first simplify the expression (expand brackets, divide term by term).')
    ] },
    { kind: 'steps', h: L('Integralni topish algoritmi', 'Алгоритм нахождения интеграла', 'Algorithm for finding an integral'), list: [
      L('Ifodani jadvalga mos shaklga keltiring: qavslarni oching, kasrni hadlarga bo‘ling, ildizni daraja ko‘rinishida yozing (√x = x<sup>1/2</sup>, 1/x³ = x<sup>−3</sup>).', 'Приведите выражение к табличному виду: раскройте скобки, разделите дробь почленно, запишите корень как степень (√x = x<sup>1/2</sup>, 1/x³ = x<sup>−3</sup>).', 'Bring the expression to table form: expand brackets, split a fraction into terms, write roots as powers (√x = x<sup>1/2</sup>, 1/x³ = x<sup>−3</sup>).'),
      L('Yig‘indini alohida integrallarga ajrating va o‘zgarmas ko‘paytuvchilarni integral belgisidan chiqaring.', 'Разбейте сумму на отдельные интегралы и вынесите постоянные множители за знак интеграла.', 'Split the sum into separate integrals and take constant factors outside the integral sign.'),
      L('Har bir hadga jadval formulasini qo‘llang; argument kx + b bo‘lsa, 1/k ko‘paytuvchini unutmang.', 'К каждому слагаемому примените табличную формулу; если аргумент kx + b, не забудьте множитель 1/k.', 'Apply the table formula to each term; if the argument is kx + b, do not forget the factor 1/k.'),
      L('Oxirida bitta umumiy «+ C» yozing.', 'В конце запишите одну общую «+ C».', 'At the end write a single common “+ C”.'),
      L('Javobni differensiallab tekshiring: hosila integral ostidagi funksiyaga teng bo‘lishi shart.', 'Проверьте ответ дифференцированием: производная должна совпасть с подынтегральной функцией.', 'Check the answer by differentiating: the derivative must equal the integrand.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar: ko‘phadlar va darajalar', 'Решённые примеры: многочлены и степени', 'Solved examples: polynomials and powers'), ex: [
      { q: L('∫ (3x² − 4x + 5) dx ni toping.', 'Найдите ∫ (3x² − 4x + 5) dx.', 'Find ∫ (3x² − 4x + 5) dx.'), s: L('Hadma-had: ∫ 3x² dx = 3·x³/3 = x³; ∫ 4x dx = 4·x²/2 = 2x²; ∫ 5 dx = 5x. Javob: x³ − 2x² + 5x + C. Tekshiruv: (x³ − 2x² + 5x)′ = 3x² − 4x + 5 ✓.', 'Почленно: ∫ 3x² dx = 3·x³/3 = x³; ∫ 4x dx = 4·x²/2 = 2x²; ∫ 5 dx = 5x. Ответ: x³ − 2x² + 5x + C. Проверка: (x³ − 2x² + 5x)′ = 3x² − 4x + 5 ✓.', 'Term by term: ∫ 3x² dx = 3·x³/3 = x³; ∫ 4x dx = 4·x²/2 = 2x²; ∫ 5 dx = 5x. Answer: x³ − 2x² + 5x + C. Check: (x³ − 2x² + 5x)′ = 3x² − 4x + 5 ✓.') },
      { q: L('∫ (2√x + 1/x²) dx ni toping.', 'Найдите ∫ (2√x + 1/x²) dx.', 'Find ∫ (2√x + 1/x²) dx.'), s: L('Darajalarga o‘tamiz: 2x<sup>1/2</sup> + x<sup>−2</sup>. ∫ 2x<sup>1/2</sup> dx = 2·x<sup>3/2</sup>/(3/2) = (4/3)x√x; ∫ x<sup>−2</sup> dx = x<sup>−1</sup>/(−1) = −1/x. Javob: (4/3)x√x − 1/x + C.', 'Переходим к степеням: 2x<sup>1/2</sup> + x<sup>−2</sup>. ∫ 2x<sup>1/2</sup> dx = 2·x<sup>3/2</sup>/(3/2) = (4/3)x√x; ∫ x<sup>−2</sup> dx = x<sup>−1</sup>/(−1) = −1/x. Ответ: (4/3)x√x − 1/x + C.', 'Switch to powers: 2x<sup>1/2</sup> + x<sup>−2</sup>. ∫ 2x<sup>1/2</sup> dx = 2·x<sup>3/2</sup>/(3/2) = (4/3)x√x; ∫ x<sup>−2</sup> dx = x<sup>−1</sup>/(−1) = −1/x. Answer: (4/3)x√x − 1/x + C.') },
      { q: L('∫ (x + 1)²/x dx ni toping (x &gt; 0).', 'Найдите ∫ (x + 1)²/x dx (x &gt; 0).', 'Find ∫ (x + 1)²/x dx (x &gt; 0).'), s: L('Qavsni ochib, hadlarga bo‘lamiz: (x² + 2x + 1)/x = x + 2 + 1/x. Integral: x²/2 + 2x + ln x + C.', 'Раскрываем скобки и делим почленно: (x² + 2x + 1)/x = x + 2 + 1/x. Интеграл: x²/2 + 2x + ln x + C.', 'Expand and divide term by term: (x² + 2x + 1)/x = x + 2 + 1/x. Integral: x²/2 + 2x + ln x + C.') },
      { q: L('F′(x) = 2x + 3 va F(1) = 6 bo‘lsa, F(x) ni toping.', 'Найдите F(x), если F′(x) = 2x + 3 и F(1) = 6.', 'Find F(x) if F′(x) = 2x + 3 and F(1) = 6.'), s: L('F(x) = x² + 3x + C. Shartdan: 1 + 3 + C = 6, C = 2. Javob: F(x) = x² + 3x + 2. Boshlang‘ich shart C ni yagona qilib tanlaydi.', 'F(x) = x² + 3x + C. Из условия: 1 + 3 + C = 6, C = 2. Ответ: F(x) = x² + 3x + 2. Начальное условие однозначно выбирает C.', 'F(x) = x² + 3x + C. From the condition: 1 + 3 + C = 6, C = 2. Answer: F(x) = x² + 3x + 2. The initial condition picks a unique C.') }
    ] },
    { kind: 'example', h: L('Yechilgan misollar: ko‘rsatkichli va trigonometrik', 'Решённые примеры: показательные и тригонометрические', 'Solved examples: exponential and trigonometric'), ex: [
      { q: L('∫ (eˣ − 3cos x) dx ni toping.', 'Найдите ∫ (eˣ − 3cos x) dx.', 'Find ∫ (eˣ − 3cos x) dx.'), s: L('Jadvaldan: ∫ eˣ dx = eˣ, ∫ cos x dx = sin x. Javob: eˣ − 3sin x + C.', 'По таблице: ∫ eˣ dx = eˣ, ∫ cos x dx = sin x. Ответ: eˣ − 3sin x + C.', 'From the table: ∫ eˣ dx = eˣ, ∫ cos x dx = sin x. Answer: eˣ − 3sin x + C.') },
      { q: L('∫ cos(3x + 1) dx va ∫ (2x − 1)⁴ dx ni toping.', 'Найдите ∫ cos(3x + 1) dx и ∫ (2x − 1)⁴ dx.', 'Find ∫ cos(3x + 1) dx and ∫ (2x − 1)⁴ dx.'), s: L('3-qoida: ∫ cos(3x + 1) dx = (1/3)sin(3x + 1) + C. Ikkinchisida k = 2, F(t) = t⁵/5: ∫ (2x − 1)⁴ dx = (1/2)·(2x − 1)⁵/5 = (2x − 1)⁵/10 + C. Qavsni ochish shart emas!', 'Правило 3: ∫ cos(3x + 1) dx = (1/3)sin(3x + 1) + C. Во втором k = 2, F(t) = t⁵/5: ∫ (2x − 1)⁴ dx = (1/2)·(2x − 1)⁵/5 = (2x − 1)⁵/10 + C. Раскрывать скобки не нужно!', 'Rule 3: ∫ cos(3x + 1) dx = (1/3)sin(3x + 1) + C. In the second, k = 2 and F(t) = t⁵/5: ∫ (2x − 1)⁴ dx = (1/2)·(2x − 1)⁵/5 = (2x − 1)⁵/10 + C. No need to expand the bracket!') },
      { q: L('∫ sin²x dx ni toping.', 'Найдите ∫ sin²x dx.', 'Find ∫ sin²x dx.'), s: L('Jadvalda sin²x yo‘q, lekin darajani pasaytirish formulasi yordam beradi: sin²x = (1 − cos 2x)/2. Shunda ∫ sin²x dx = x/2 − (1/2)·(sin 2x)/2 = x/2 − sin 2x/4 + C.', 'В таблице нет sin²x, но помогает формула понижения степени: sin²x = (1 − cos 2x)/2. Тогда ∫ sin²x dx = x/2 − (1/2)·(sin 2x)/2 = x/2 − sin 2x/4 + C.', 'The table has no sin²x, but the power-reduction formula helps: sin²x = (1 − cos 2x)/2. Then ∫ sin²x dx = x/2 − (1/2)·(sin 2x)/2 = x/2 − sin 2x/4 + C.') },
      { q: L('∫ 2ˣ dx va ∫ dx/(5x + 2) ni toping.', 'Найдите ∫ 2ˣ dx и ∫ dx/(5x + 2).', 'Find ∫ 2ˣ dx and ∫ dx/(5x + 2).'), s: L('∫ 2ˣ dx = 2ˣ/ln 2 + C. Ikkinchisida 1/t ning boshlang‘ichi ln|t|, k = 5: ∫ dx/(5x + 2) = (1/5)ln|5x + 2| + C.', '∫ 2ˣ dx = 2ˣ/ln 2 + C. Во втором первообразная 1/t есть ln|t|, k = 5: ∫ dx/(5x + 2) = (1/5)ln|5x + 2| + C.', '∫ 2ˣ dx = 2ˣ/ln 2 + C. In the second, the antiderivative of 1/t is ln|t| and k = 5: ∫ dx/(5x + 2) = (1/5)ln|5x + 2| + C.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>«+ C» ni unutish.</b> Aniqmas integral — bitta funksiya emas, funksiyalar oilasi. C siz javob to‘liq emas.', '<b>Забыть «+ C».</b> Неопределённый интеграл — не одна функция, а семейство. Без C ответ неполный.', '<b>Forgetting “+ C”.</b> An indefinite integral is a family of functions, not one function. Without C the answer is incomplete.'),
      L('<b>n = −1 holiga darajalar formulasini qo‘llash.</b> ∫ x<sup>−1</sup> dx ≠ x⁰/0. To‘g‘ri javob: ln|x| + C.', '<b>Применять формулу степени при n = −1.</b> ∫ x<sup>−1</sup> dx ≠ x⁰/0. Верно: ln|x| + C.', '<b>Using the power formula for n = −1.</b> ∫ x<sup>−1</sup> dx ≠ x⁰/0. Correct: ln|x| + C.'),
      L('<b>sin va cos ishoralarini almashtirish.</b> ∫ sin x dx = −cos x + C (minus bilan!), ∫ cos x dx = sin x + C. Shubha bo‘lsa — differensiallab tekshiring.', '<b>Путать знаки у sin и cos.</b> ∫ sin x dx = −cos x + C (с минусом!), ∫ cos x dx = sin x + C. Сомневаетесь — проверьте дифференцированием.', '<b>Mixing up the signs for sin and cos.</b> ∫ sin x dx = −cos x + C (with a minus!), ∫ cos x dx = sin x + C. When in doubt, differentiate.'),
      L('<b>1/k ni unutish.</b> ∫ e<sup>2x</sup> dx ≠ e<sup>2x</sup> + C, chunki (e<sup>2x</sup>)′ = 2e<sup>2x</sup>. To‘g‘risi: e<sup>2x</sup>/2 + C.', '<b>Забыть 1/k.</b> ∫ e<sup>2x</sup> dx ≠ e<sup>2x</sup> + C, ведь (e<sup>2x</sup>)′ = 2e<sup>2x</sup>. Верно: e<sup>2x</sup>/2 + C.', '<b>Forgetting 1/k.</b> ∫ e<sup>2x</sup> dx ≠ e<sup>2x</sup> + C, since (e<sup>2x</sup>)′ = 2e<sup>2x</sup>. Correct: e<sup>2x</sup>/2 + C.'),
      L('<b>Ko‘paytmani ko‘paytuvchilar bo‘yicha integrallash.</b> ∫ x·x dx ≠ (x²/2)·(x²/2). Avval x·x = x², so‘ng ∫ x² dx = x³/3 + C.', '<b>Интегрировать произведение по множителям.</b> ∫ x·x dx ≠ (x²/2)·(x²/2). Сначала x·x = x², потом ∫ x² dx = x³/3 + C.', '<b>Integrating a product factor by factor.</b> ∫ x·x dx ≠ (x²/2)·(x²/2). First x·x = x², then ∫ x² dx = x³/3 + C.')
    ] },
    { kind: 'life', h: L('Hayotda integrallash', 'Интегрирование в жизни', 'Integration in real life'), p: [
      L('<b>Fizika.</b> Tezlik v(t) ma’lum bo‘lsa, yo‘l s(t) = ∫ v(t) dt; tezlanish a(t) ma’lum bo‘lsa, tezlik v(t) = ∫ a(t) dt. Erkin tushishda a = g ≈ 9,8 m/s², shuning uchun v = gt + v₀, s = gt²/2 + v₀t + s₀. O‘zgarmaslar v₀ va s₀ — boshlang‘ich tezlik va boshlang‘ich holat: «+ C» ning jismoniy ma’nosi aynan shu.', '<b>Физика.</b> Если известна скорость v(t), то путь s(t) = ∫ v(t) dt; если известно ускорение a(t), то скорость v(t) = ∫ a(t) dt. При свободном падении a = g ≈ 9,8 м/с², поэтому v = gt + v₀, s = gt²/2 + v₀t + s₀. Постоянные v₀ и s₀ — начальная скорость и начальное положение: вот физический смысл «+ C».', '<b>Physics.</b> If the speed v(t) is known, the distance is s(t) = ∫ v(t) dt; if the acceleration a(t) is known, the speed is v(t) = ∫ a(t) dt. In free fall a = g ≈ 9.8 m/s², so v = gt + v₀ and s = gt²/2 + v₀t + s₀. The constants v₀ and s₀ are the initial speed and initial position: this is the physical meaning of “+ C”.'),
      L('<b>Iqtisod.</b> Korxona marjinal xarajatni (har bir qo‘shimcha mahsulot narxini) biladi; umumiy xarajat — uning boshlang‘ichi, C esa doimiy xarajatlar (ijara, uskunalar). <b>Biologiya va tibbiyot.</b> Bakteriyalar soni o‘sish tezligidan, dori konsentratsiyasi esa so‘rilish tezligidan integrallash orqali tiklanadi. <b>Muhandislik.</b> Smartfondagi akselerometr tezlanishni o‘lchaydi, dastur esa uni ikki marta integrallab, qadamlar va harakatni baholaydi.', '<b>Экономика.</b> Предприятие знает предельные издержки (стоимость каждой дополнительной единицы продукции); общие издержки — их первообразная, а C — постоянные издержки (аренда, оборудование). <b>Биология и медицина.</b> Число бактерий восстанавливают по скорости роста, концентрацию лекарства — по скорости всасывания интегрированием. <b>Инженерия.</b> Акселерометр в смартфоне измеряет ускорение, а программа дважды интегрирует его, оценивая шаги и движение.', '<b>Economics.</b> A company knows its marginal cost (the cost of each extra unit); total cost is its antiderivative, and C stands for fixed costs (rent, equipment). <b>Biology and medicine.</b> The number of bacteria is recovered from the growth rate, and drug concentration from the absorption rate, by integration. <b>Engineering.</b> A smartphone accelerometer measures acceleration, and software integrates it twice to estimate steps and motion.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Differensiallash — «qoida bo‘yicha ish»: har qanday elementar funksiyaning hosilasi yana elementar. Integrallash esa san’at: ∫ sin x/x dx yoki ∫ e<sup>−x²</sup> dx ni hech qanday formulaga keltirib bo‘lmaydi.', 'Дифференцирование — «работа по правилам»: производная любой элементарной функции снова элементарна. Интегрирование — искусство: ∫ sin x/x dx или ∫ e<sup>−x²</sup> dx ни к какой формуле не сводятся.', 'Differentiation is “work by the rules”: the derivative of any elementary function is again elementary. Integration is an art: ∫ sin x/x dx or ∫ e<sup>−x²</sup> dx cannot be reduced to any formula.'),
      L('XIX–XX asrlarda muhandislar uchun minglab integrallarni o‘z ichiga olgan qalin ma’lumotnomalar chiqarilgan. Bugun bu ishni kompyuter algebra tizimlari (Risch algoritmi asosida) bajaradi.', 'В XIX–XX веках для инженеров выпускали толстые справочники с тысячами интегралов. Сегодня эту работу выполняют системы компьютерной алгебры (на основе алгоритма Риша).', 'In the 19th–20th centuries thick handbooks with thousands of integrals were printed for engineers. Today computer algebra systems (based on the Risch algorithm) do this job.'),
      L('Bir xil integral turli ko‘rinishda chiqishi mumkin: ∫ 2sin x cos x dx = sin²x + C ham, −cos²x + C ham, −cos 2x/2 + C ham to‘g‘ri — ular faqat o‘zgarmasga farq qiladi.', 'Один и тот же интеграл может выглядеть по-разному: ∫ 2sin x cos x dx = sin²x + C, и −cos²x + C, и −cos 2x/2 + C — все верны, они отличаются лишь постоянной.', 'The same integral may look different: ∫ 2sin x cos x dx = sin²x + C, or −cos²x + C, or −cos 2x/2 + C — all correct, they differ only by a constant.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('∫ (4x³ − 6x + 1) dx = ?', '∫ (4x³ − 6x + 1) dx = ?', '∫ (4x³ − 6x + 1) dx = ?'),
      L('∫ (1/x + eˣ) dx = ?', '∫ (1/x + eˣ) dx = ?', '∫ (1/x + eˣ) dx = ?'),
      L('∫ sin 4x dx = ?', '∫ sin 4x dx = ?', '∫ sin 4x dx = ?'),
      L('Grafigi (0; 3) nuqtadan o‘tadigan f(x) = 6x² ning boshlang‘ichini toping.', 'Найдите первообразную f(x) = 6x², график которой проходит через (0; 3).', 'Find the antiderivative of f(x) = 6x² whose graph passes through (0; 3).')
    ], after: [
      L('Javoblar: x⁴ − 3x² + x + C; ln|x| + eˣ + C; −cos 4x/4 + C; F(x) = 2x³ + 3.', 'Ответы: x⁴ − 3x² + x + C; ln|x| + eˣ + C; −cos 4x/4 + C; F(x) = 2x³ + 3.', 'Answers: x⁴ − 3x² + x + C; ln|x| + eˣ + C; −cos 4x/4 + C; F(x) = 2x³ + 3.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('∫ f(x) dx = F(x) + C, bunda F′ = f; C — ixtiyoriy o‘zgarmas.', '∫ f(x) dx = F(x) + C, где F′ = f; C — произвольная постоянная.', '∫ f(x) dx = F(x) + C, where F′ = f; C is an arbitrary constant.'),
      L('Jadval hosilalar jadvalini teskari o‘qishdan olinadi: ∫ xⁿ dx = xⁿ⁺¹/(n + 1) + C, ∫ dx/x = ln|x| + C.', 'Таблица — обратное чтение таблицы производных: ∫ xⁿ dx = xⁿ⁺¹/(n + 1) + C, ∫ dx/x = ln|x| + C.', 'The table is the derivative table read backwards: ∫ xⁿ dx = xⁿ⁺¹/(n + 1) + C, ∫ dx/x = ln|x| + C.'),
      L('Yig‘indi hadma-had integrallanadi, o‘zgarmas ko‘paytuvchi chiqariladi.', 'Сумма интегрируется почленно, постоянный множитель выносится.', 'Sums are integrated term by term; constant factors come out.'),
      L('∫ f(kx + b) dx = F(kx + b)/k + C.', '∫ f(kx + b) dx = F(kx + b)/k + C.', '∫ f(kx + b) dx = F(kx + b)/k + C.'),
      L('Ko‘paytma va bo‘linma uchun umumiy sodda qoida yo‘q — avval soddalashtiring.', 'Для произведения и частного общего простого правила нет — сначала упрощайте.', 'There is no simple general rule for products and quotients — simplify first.'),
      L('Har doim differensiallab tekshiring.', 'Всегда проверяйте дифференцированием.', 'Always check by differentiating.')
    ] }
  ] });

  // ---------- t12. Aniq integral. Nyuton–Leybnits formulasi ----------
  T.add(P, 't12', { sections: [
    { kind: 'intro', h: L('Tezlikdan yo‘lga', 'От скорости к пути', 'From speed to distance'), p: [
      L('Agar avtomobil 2 soat davomida 60 km/soat o‘zgarmas tezlikda yursa, yo‘l 60·2 = 120 km. Tezlik-vaqt grafigida bu son — balandligi 60 va asosi 2 bo‘lgan to‘g‘ri to‘rtburchak yuzi. Tezlik o‘zgarib tursa-chi? Unda grafik egri chiziq bo‘ladi, yo‘l esa shu egri chiziq ostidagi yuzga teng. Bunday yuzni hisoblash vositasi — <b>aniq integral</b>.', 'Если автомобиль 2 часа едет с постоянной скоростью 60 км/ч, путь равен 60·2 = 120 км. На графике скорости это число — площадь прямоугольника с высотой 60 и основанием 2. А если скорость меняется? Тогда график — кривая, а путь равен площади под этой кривой. Инструмент для вычисления такой площади — <b>определённый интеграл</b>.', 'If a car drives for 2 hours at a constant 60 km/h, the distance is 60·2 = 120 km. On the speed–time graph this number is the area of a rectangle of height 60 and base 2. What if the speed changes? Then the graph is a curve, and the distance equals the area under that curve. The tool for computing such an area is the <b>definite integral</b>.'),
      L('Bu mavzuning eng hayratlanarli natijasi — <b>Nyuton–Leybnits formulasi</b>. U ikki butunlay boshqa masalani bog‘laydi: egri chiziq ostidagi yuzni topish (cheksiz ko‘p kichik bo‘laklarni qo‘shish) va boshlang‘ich funksiyani topish (hosilaga teskari amal). Shu bog‘lanish tufayli murakkab yig‘indilar ikki sonning ayirmasiga aylanadi.', 'Самый поразительный результат темы — <b>формула Ньютона–Лейбница</b>. Она связывает две совершенно разные задачи: нахождение площади под кривой (сложение бесконечно многих маленьких частей) и нахождение первообразной (операции, обратной производной). Благодаря этой связи сложные суммы превращаются в разность двух чисел.', 'The most striking result of this topic is the <b>Newton–Leibniz formula</b>. It links two completely different problems: finding the area under a curve (adding infinitely many small pieces) and finding an antiderivative (the reverse of differentiation). Thanks to this link, complicated sums turn into the difference of two numbers.')
    ] },
    { kind: 'def', h: L('Egri chiziqli trapetsiya va integral yig‘indi', 'Криволинейная трапеция и интегральная сумма', 'Curvilinear trapezium and Riemann sum'), p: [
      L('[a; b] kesmada uzluksiz va manfiy bo‘lmagan f funksiya berilgan bo‘lsin. y = f(x) grafigi, Ox o‘qi hamda x = a va x = b to‘g‘ri chiziqlar bilan chegaralangan figura <b>egri chiziqli trapetsiya</b> deyiladi. Uning yuzini taqriban topish uchun [a; b] ni n ta teng bo‘lakka bo‘lamiz: Δx = (b − a)/n, har bir bo‘lakda biror ξᵢ nuqta tanlab, balandligi f(ξᵢ) bo‘lgan to‘g‘ri to‘rtburchak quramiz.', 'Пусть на отрезке [a; b] дана непрерывная неотрицательная функция f. Фигура, ограниченная графиком y = f(x), осью Ox и прямыми x = a и x = b, называется <b>криволинейной трапецией</b>. Чтобы приближённо найти её площадь, делим [a; b] на n равных частей: Δx = (b − a)/n, на каждой выбираем точку ξᵢ и строим прямоугольник высотой f(ξᵢ).', 'Let f be continuous and non-negative on [a; b]. The figure bounded by the graph y = f(x), the Ox axis and the lines x = a and x = b is called a <b>curvilinear trapezium</b>. To approximate its area, split [a; b] into n equal parts: Δx = (b − a)/n; in each part choose a point ξᵢ and build a rectangle of height f(ξᵢ).'),
      L('To‘g‘ri to‘rtburchaklar yuzlarining yig‘indisi Sₙ = f(ξ₁)Δx + f(ξ₂)Δx + … + f(ξₙ)Δx <b>integral yig‘indi</b> deyiladi. n cheksiz o‘sganda (Δx → 0) bu yig‘indi bitta songa intiladi. Shu limit f funksiyaning a dan b gacha <b>aniq integrali</b> deyiladi: ∫ₐᵇ f(x) dx. Bu yerda a — quyi chegara, b — yuqori chegara. Aniq integral — funksiyalar oilasi emas, balki <b>son</b>.', 'Сумма площадей прямоугольников Sₙ = f(ξ₁)Δx + f(ξ₂)Δx + … + f(ξₙ)Δx называется <b>интегральной суммой</b>. При неограниченном росте n (Δx → 0) эта сумма стремится к одному числу. Этот предел называется <b>определённым интегралом</b> функции f от a до b: ∫ₐᵇ f(x) dx. Здесь a — нижний предел, b — верхний. Определённый интеграл — не семейство функций, а <b>число</b>.', 'The sum of the rectangle areas Sₙ = f(ξ₁)Δx + f(ξ₂)Δx + … + f(ξₙ)Δx is called a <b>Riemann (integral) sum</b>. As n grows without bound (Δx → 0), this sum tends to a single number. That limit is called the <b>definite integral</b> of f from a to b: ∫ₐᵇ f(x) dx. Here a is the lower limit and b the upper limit. A definite integral is not a family of functions but a <b>number</b>.')
    ] },
    { kind: 'history', h: L('Arximeddan Rimangacha', 'От Архимеда до Римана', 'From Archimedes to Riemann'), p: [
      L('Miloddan avvalgi III asrda <b>Arximed</b> «tugatish usuli» bilan parabola segmentining yuzini topdi: u ichki chizilgan uchburchak yuzining aniq 4/3 qismiga teng. Arximed figurani cheksiz ko‘p uchburchaklar bilan to‘ldirgan va geometrik progressiya yig‘indisini hisoblagan — bu integralning ilk g‘oyasi edi. XVII asrda italyan <b>Bonaventura Kavalyeri</b> «bo‘linmaslar usuli»ni rivojlantirdi, Ferma esa x<sup>n</sup> egri chizig‘i ostidagi yuzni topdi.', 'В III веке до н. э. <b>Архимед</b> «методом исчерпывания» нашёл площадь параболического сегмента: она ровно в 4/3 раза больше площади вписанного треугольника. Архимед заполнял фигуру бесконечным числом треугольников и суммировал геометрическую прогрессию — это была первая идея интеграла. В XVII веке итальянец <b>Бонавентура Кавальери</b> развил «метод неделимых», а Ферма нашёл площадь под кривой x<sup>n</sup>.', 'In the 3rd century BC <b>Archimedes</b> used the “method of exhaustion” to find the area of a parabolic segment: exactly 4/3 of the area of the inscribed triangle. He filled the figure with infinitely many triangles and summed a geometric progression — the first idea of the integral. In the 17th century the Italian <b>Bonaventura Cavalieri</b> developed the “method of indivisibles”, and Fermat found the area under the curve x<sup>n</sup>.'),
      L('Nyutonning ustozi <b>Isaak Barrou</b> yuz va urinma masalalari o‘zaro teskari ekanini sezgan edi. Nyuton va Leybnits bu g‘oyani umumiy usulga aylantirdilar — shuning uchun formula ularning nomi bilan ataladi. 1854-yilda nemis matematigi <b>Bernxard Riman</b> integral yig‘indilar orqali aniq integralning qat’iy ta’rifini berdi; bugun integral yig‘indilar uning sharafiga «Riman yig‘indilari» deyiladi.', 'Учитель Ньютона <b>Исаак Барроу</b> заметил, что задачи о площади и о касательной взаимно обратны. Ньютон и Лейбниц превратили эту идею в общий метод — поэтому формула носит их имена. В 1854 году немецкий математик <b>Бернхард Риман</b> дал строгое определение определённого интеграла через интегральные суммы; сегодня их в его честь называют «суммами Римана».', 'Newton’s teacher <b>Isaac Barrow</b> noticed that the area problem and the tangent problem are inverse to each other. Newton and Leibniz turned this idea into a general method — hence the formula bears their names. In 1854 the German mathematician <b>Bernhard Riemann</b> gave a rigorous definition of the definite integral through integral sums; today they are called “Riemann sums” in his honour.')
    ] },
    { kind: 'rule', h: L('Nyuton–Leybnits formulasi', 'Формула Ньютона–Лейбница', 'The Newton–Leibniz formula'), p: [
      L('Agar f funksiya [a; b] da uzluksiz va F uning biror boshlang‘ichi bo‘lsa, <b>∫ₐᵇ f(x) dx = F(b) − F(a)</b>. Qisqacha yozuv: F(x)|ₐᵇ = F(b) − F(a).', 'Если функция f непрерывна на [a; b] и F — какая-либо её первообразная, то <b>∫ₐᵇ f(x) dx = F(b) − F(a)</b>. Краткая запись: F(x)|ₐᵇ = F(b) − F(a).', 'If f is continuous on [a; b] and F is any of its antiderivatives, then <b>∫ₐᵇ f(x) dx = F(b) − F(a)</b>. Short notation: F(x)|ₐᵇ = F(b) − F(a).'),
      L('<b>Isbot g‘oyasi.</b> S(x) bilan a dan x gacha bo‘lgan egri chiziqli trapetsiya yuzini belgilaymiz. x ga kichik Δx orttirma bersak, yuz taxminan f(x)·Δx ga — ingichka ustun yuziga ortadi. Demak, ΔS/Δx → f(x), ya’ni S′(x) = f(x): yuz funksiyasi f ning boshlang‘ichi! Ikki boshlang‘ich o‘zgarmasga farq qiladi: S(x) = F(x) + C. S(a) = 0 dan C = −F(a), shuning uchun S(b) = F(b) − F(a).', '<b>Идея доказательства.</b> Обозначим S(x) площадь криволинейной трапеции от a до x. Если дать x малое приращение Δx, площадь увеличится примерно на f(x)·Δx — площадь узкого столбика. Значит, ΔS/Δx → f(x), то есть S′(x) = f(x): функция площади — первообразная для f! Две первообразные отличаются на постоянную: S(x) = F(x) + C. Из S(a) = 0 получаем C = −F(a), поэтому S(b) = F(b) − F(a).', '<b>Proof idea.</b> Let S(x) be the area of the curvilinear trapezium from a to x. If x gets a small increment Δx, the area grows by about f(x)·Δx — the area of a thin strip. So ΔS/Δx → f(x), i.e. S′(x) = f(x): the area function is an antiderivative of f! Two antiderivatives differ by a constant: S(x) = F(x) + C. From S(a) = 0 we get C = −F(a), hence S(b) = F(b) − F(a).'),
      L('E’tibor bering: qaysi boshlang‘ichni olish farqsiz — C ayirmada qisqarib ketadi. Shuning uchun aniq integralda «+ C» yozilmaydi.', 'Обратите внимание: неважно, какую первообразную взять, — C сокращается в разности. Поэтому в определённом интеграле «+ C» не пишут.', 'Note: it does not matter which antiderivative you take — C cancels in the difference. That is why “+ C” is not written in a definite integral.')
    ] },
    { kind: 'rule', h: L('Aniq integralning xossalari', 'Свойства определённого интеграла', 'Properties of the definite integral'), list: [
      L('∫ₐᵃ f(x) dx = 0 — kengligi nol bo‘lgan figura yuzi nol.', '∫ₐᵃ f(x) dx = 0 — фигура нулевой ширины имеет нулевую площадь.', '∫ₐᵃ f(x) dx = 0 — a figure of zero width has zero area.'),
      L('∫ₐᵇ f(x) dx = −∫<sub>b</sub><sup>a</sup> f(x) dx — chegaralar almashsa, ishora o‘zgaradi.', '∫ₐᵇ f(x) dx = −∫<sub>b</sub><sup>a</sup> f(x) dx — при перестановке пределов знак меняется.', '∫ₐᵇ f(x) dx = −∫<sub>b</sub><sup>a</sup> f(x) dx — swapping the limits changes the sign.'),
      L('∫ₐᵇ (αf + βg) dx = α∫ₐᵇ f dx + β∫ₐᵇ g dx — chiziqlilik.', '∫ₐᵇ (αf + βg) dx = α∫ₐᵇ f dx + β∫ₐᵇ g dx — линейность.', '∫ₐᵇ (αf + βg) dx = α∫ₐᵇ f dx + β∫ₐᵇ g dx — linearity.'),
      L('∫ₐᵇ f dx = ∫ₐᶜ f dx + ∫<sub>c</sub><sup>b</sup> f dx — additivlik: yuzni bo‘laklarga ajratish mumkin.', '∫ₐᵇ f dx = ∫ₐᶜ f dx + ∫<sub>c</sub><sup>b</sup> f dx — аддитивность: площадь можно делить на части.', '∫ₐᵇ f dx = ∫ₐᶜ f dx + ∫<sub>c</sub><sup>b</sup> f dx — additivity: an area can be split into parts.'),
      L('Agar [a; b] da f(x) ≤ 0 bo‘lsa, integral manfiy: u yuzning minus ishorali qiymatiga teng.', 'Если на [a; b] f(x) ≤ 0, интеграл отрицателен: он равен площади со знаком минус.', 'If f(x) ≤ 0 on [a; b], the integral is negative: it equals minus the area.'),
      L('Toq funksiya uchun ∫₋ₐᵃ f dx = 0; juft funksiya uchun ∫₋ₐᵃ f dx = 2∫₀ᵃ f dx.', 'Для нечётной функции ∫₋ₐᵃ f dx = 0; для чётной ∫₋ₐᵃ f dx = 2∫₀ᵃ f dx.', 'For an odd function ∫₋ₐᵃ f dx = 0; for an even one ∫₋ₐᵃ f dx = 2∫₀ᵃ f dx.')
    ] },
    { kind: 'steps', h: L('Aniq integralni hisoblash tartibi', 'Порядок вычисления определённого интеграла', 'How to evaluate a definite integral'), list: [
      L('Funksiya [a; b] da uzluksiz ekaniga ishonch hosil qiling (masalan, ∫₋₁¹ dx/x² ni formula bilan hisoblab bo‘lmaydi — x = 0 da uzilish bor).', 'Убедитесь, что функция непрерывна на [a; b] (например, ∫₋₁¹ dx/x² по формуле считать нельзя — в x = 0 разрыв).', 'Make sure the function is continuous on [a; b] (for example, ∫₋₁¹ dx/x² cannot be computed by the formula — there is a break at x = 0).'),
      L('Boshlang‘ich F ni toping (C siz).', 'Найдите первообразную F (без C).', 'Find an antiderivative F (without C).'),
      L('F(b) va F(a) ni alohida hisoblang — ayniqsa manfiy chegaralarda qavslardan foydalaning.', 'Вычислите F(b) и F(a) отдельно — особенно при отрицательных пределах пользуйтесь скобками.', 'Compute F(b) and F(a) separately — use brackets, especially with negative limits.'),
      L('Ayirmani oling: F(b) − F(a). Tartib muhim: yuqori chegara minus quyi chegara.', 'Возьмите разность F(b) − F(a). Порядок важен: верхний предел минус нижний.', 'Take the difference F(b) − F(a). Order matters: upper limit minus lower limit.'),
      L('Natijani ma’no bo‘yicha tekshiring: musbat funksiya uchun integral musbat bo‘lishi kerak.', 'Проверьте результат по смыслу: для положительной функции интеграл должен быть положительным.', 'Check the result for sense: for a positive function the integral must be positive.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar', 'Решённые примеры', 'Solved examples'), ex: [
      { q: L('∫₀³ x² dx ni hisoblang.', 'Вычислите ∫₀³ x² dx.', 'Evaluate ∫₀³ x² dx.'), s: L('F(x) = x³/3. ∫₀³ x² dx = 27/3 − 0/3 = 9. Bu — y = x² parabola, Ox o‘qi va x = 3 to‘g‘ri chiziq orasidagi yuz.', 'F(x) = x³/3. ∫₀³ x² dx = 27/3 − 0/3 = 9. Это площадь между параболой y = x², осью Ox и прямой x = 3.', 'F(x) = x³/3. ∫₀³ x² dx = 27/3 − 0/3 = 9. This is the area between the parabola y = x², the Ox axis and the line x = 3.') },
      { q: L('∫₁² (3x² − 2x) dx ni hisoblang.', 'Вычислите ∫₁² (3x² − 2x) dx.', 'Evaluate ∫₁² (3x² − 2x) dx.'), s: L('F(x) = x³ − x². F(2) = 8 − 4 = 4, F(1) = 1 − 1 = 0. Javob: 4 − 0 = 4.', 'F(x) = x³ − x². F(2) = 8 − 4 = 4, F(1) = 1 − 1 = 0. Ответ: 4 − 0 = 4.', 'F(x) = x³ − x². F(2) = 8 − 4 = 4, F(1) = 1 − 1 = 0. Answer: 4 − 0 = 4.') },
      { q: L('∫₀<sup>π</sup> sin x dx ni hisoblang.', 'Вычислите ∫₀<sup>π</sup> sin x dx.', 'Evaluate ∫₀<sup>π</sup> sin x dx.'), s: L('F(x) = −cos x. F(π) − F(0) = −cos π − (−cos 0) = 1 + 1 = 2. Sinusoidaning bitta «do‘ngi» ostidagi yuz aniq 2 ga teng!', 'F(x) = −cos x. F(π) − F(0) = −cos π − (−cos 0) = 1 + 1 = 2. Площадь под одной «аркой» синусоиды ровно 2!', 'F(x) = −cos x. F(π) − F(0) = −cos π − (−cos 0) = 1 + 1 = 2. The area under one “arch” of the sine curve is exactly 2!') },
      { q: L('∫₁<sup>e</sup> dx/x va ∫₀⁴ √x dx ni hisoblang.', 'Вычислите ∫₁<sup>e</sup> dx/x и ∫₀⁴ √x dx.', 'Evaluate ∫₁<sup>e</sup> dx/x and ∫₀⁴ √x dx.'), s: L('Birinchisi: ln e − ln 1 = 1 − 0 = 1. Ikkinchisi: F(x) = (2/3)x<sup>3/2</sup>, F(4) = (2/3)·8 = 16/3, F(0) = 0. Javob: 16/3.', 'Первый: ln e − ln 1 = 1 − 0 = 1. Второй: F(x) = (2/3)x<sup>3/2</sup>, F(4) = (2/3)·8 = 16/3, F(0) = 0. Ответ: 16/3.', 'First: ln e − ln 1 = 1 − 0 = 1. Second: F(x) = (2/3)x<sup>3/2</sup>, F(4) = (2/3)·8 = 16/3, F(0) = 0. Answer: 16/3.') },
      { q: L('∫₋₂² (x³ + 3x²) dx ni hisoblang.', 'Вычислите ∫₋₂² (x³ + 3x²) dx.', 'Evaluate ∫₋₂² (x³ + 3x²) dx.'), s: L('x³ — toq, uning integrali simmetrik oraliqda 0. 3x² — juft: 2∫₀² 3x² dx = 2·x³|₀² = 2·8 = 16. Javob: 16.', 'x³ — нечётная, её интеграл по симметричному промежутку равен 0. 3x² — чётная: 2∫₀² 3x² dx = 2·x³|₀² = 2·8 = 16. Ответ: 16.', 'x³ is odd, so its integral over a symmetric interval is 0. 3x² is even: 2∫₀² 3x² dx = 2·x³|₀² = 2·8 = 16. Answer: 16.') }
    ] },
    { kind: 'example', h: L('Integral yig‘indi va fizik masalalar', 'Интегральная сумма и физические задачи', 'Riemann sums and physics problems'), ex: [
      { q: L('∫₀¹ x² dx ni n = 4 bo‘lakli o‘ng to‘g‘ri to‘rtburchaklar bilan baholang va aniq qiymat bilan solishtiring.', 'Оцените ∫₀¹ x² dx правыми прямоугольниками при n = 4 и сравните с точным значением.', 'Estimate ∫₀¹ x² dx with n = 4 right rectangles and compare with the exact value.'), s: L('Δx = 1/4, o‘ng uchlar: 1/4, 1/2, 3/4, 1. S₄ = (1/4)(1/16 + 4/16 + 9/16 + 16/16) = 30/64 = 0,46875. Aniq qiymat 1/3 ≈ 0,333. n oshgani sari Sₙ = (n + 1)(2n + 1)/(6n²) → 1/3.', 'Δx = 1/4, правые концы: 1/4, 1/2, 3/4, 1. S₄ = (1/4)(1/16 + 4/16 + 9/16 + 16/16) = 30/64 = 0,46875. Точное значение 1/3 ≈ 0,333. С ростом n Sₙ = (n + 1)(2n + 1)/(6n²) → 1/3.', 'Δx = 1/4, right endpoints: 1/4, 1/2, 3/4, 1. S₄ = (1/4)(1/16 + 4/16 + 9/16 + 16/16) = 30/64 = 0.46875. The exact value is 1/3 ≈ 0.333. As n grows, Sₙ = (n + 1)(2n + 1)/(6n²) → 1/3.') },
      { q: L('Jism tezligi v(t) = 3t² + 2 (m/s). U birinchi 2 sekundda qancha yo‘l bosadi?', 'Скорость тела v(t) = 3t² + 2 (м/с). Какой путь оно пройдёт за первые 2 секунды?', 'A body moves with speed v(t) = 3t² + 2 (m/s). How far does it travel in the first 2 seconds?'), s: L('s = ∫₀² (3t² + 2) dt = (t³ + 2t)|₀² = 8 + 4 = 12 m.', 's = ∫₀² (3t² + 2) dt = (t³ + 2t)|₀² = 8 + 4 = 12 м.', 's = ∫₀² (3t² + 2) dt = (t³ + 2t)|₀² = 8 + 4 = 12 m.') },
      { q: L('Bikrligi k = 100 N/m bo‘lgan prujinani 0,1 m ga cho‘zish uchun qancha ish bajariladi?', 'Какую работу нужно совершить, чтобы растянуть пружину жёсткостью k = 100 Н/м на 0,1 м?', 'How much work is needed to stretch a spring with stiffness k = 100 N/m by 0.1 m?'), s: L('Kuch o‘zgaruvchan: F = kx (Guk qonuni). A = ∫₀<sup>0,1</sup> 100x dx = 50x²|₀<sup>0,1</sup> = 50·0,01 = 0,5 J.', 'Сила переменная: F = kx (закон Гука). A = ∫₀<sup>0,1</sup> 100x dx = 50x²|₀<sup>0,1</sup> = 50·0,01 = 0,5 Дж.', 'The force varies: F = kx (Hooke’s law). W = ∫₀<sup>0.1</sup> 100x dx = 50x²|₀<sup>0.1</sup> = 50·0.01 = 0.5 J.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Ayirma tartibini almashtirish:</b> F(a) − F(b) yozish. Har doim yuqori chegaradagi qiymatdan quyi chegaradagisini ayiring.', '<b>Перепутать порядок разности:</b> писать F(a) − F(b). Всегда из значения на верхнем пределе вычитайте значение на нижнем.', '<b>Reversing the difference:</b> writing F(a) − F(b). Always subtract the value at the lower limit from the value at the upper limit.'),
      L('<b>F(0) = 0 deb o‘ylash.</b> ∫₀<sup>π/2</sup> sin x dx da F(0) = −cos 0 = −1, shuning uchun javob 0 − (−1) = 1, nol emas.', '<b>Считать, что F(0) = 0.</b> В ∫₀<sup>π/2</sup> sin x dx F(0) = −cos 0 = −1, поэтому ответ 0 − (−1) = 1, а не 0.', '<b>Assuming F(0) = 0.</b> In ∫₀<sup>π/2</sup> sin x dx, F(0) = −cos 0 = −1, so the answer is 0 − (−1) = 1, not 0.'),
      L('<b>Manfiy chegarada qavssiz hisoblash:</b> x³/3 da x = −2 → (−2)³/3 = −8/3, lekin −2³/3 deb yozib, ishorani yo‘qotish oson.', '<b>Считать без скобок при отрицательном пределе:</b> в x³/3 при x = −2 → (−2)³/3 = −8/3; легко потерять знак.', '<b>Computing without brackets at a negative limit:</b> for x³/3 at x = −2 we get (−2)³/3 = −8/3; it is easy to lose the sign.'),
      L('<b>Integralni har doim yuz deb hisoblash.</b> ∫₀<sup>2π</sup> sin x dx = 0, lekin sinusoida va Ox orasidagi yuz 4 ga teng. Yuz va integral faqat f ≥ 0 bo‘lganda bir xil.', '<b>Всегда считать интеграл площадью.</b> ∫₀<sup>2π</sup> sin x dx = 0, но площадь между синусоидой и Ox равна 4. Площадь и интеграл совпадают лишь при f ≥ 0.', '<b>Always treating the integral as an area.</b> ∫₀<sup>2π</sup> sin x dx = 0, yet the area between the sine curve and Ox is 4. Area and integral coincide only when f ≥ 0.'),
      L('<b>Uzilishli funksiyaga formulani qo‘llash.</b> ∫₋₁¹ dx/x² = −1/x|₋₁¹ = −2 — absurd: musbat funksiya integrali manfiy chiqdi. Sababi: x = 0 da funksiya uzilgan.', '<b>Применять формулу к разрывной функции.</b> ∫₋₁¹ dx/x² = −1/x|₋₁¹ = −2 — абсурд: интеграл положительной функции вышел отрицательным. Причина: разрыв в x = 0.', '<b>Applying the formula to a discontinuous function.</b> ∫₋₁¹ dx/x² = −1/x|₋₁¹ = −2 — absurd: a positive function got a negative integral. The reason: the break at x = 0.')
    ] },
    { kind: 'life', h: L('Aniq integral hayotda', 'Определённый интеграл в жизни', 'The definite integral in real life'), p: [
      L('Aniq integral «o‘zgaruvchan miqdorni yig‘ish» kerak bo‘lgan hamma joyda ishlatiladi. <b>Fizika:</b> o‘zgaruvchan kuch bajargan ish A = ∫ F(x) dx, o‘zgaruvchan tok o‘tkazgan zaryad q = ∫ I(t) dt, notekis sterjen massasi m = ∫ ρ(x) dx. <b>Energetika:</b> elektr hisoblagich quvvatni vaqt bo‘yicha integrallaydi — kVt·soat aynan shu integral.', 'Определённый интеграл используется везде, где нужно «накопить переменную величину». <b>Физика:</b> работа переменной силы A = ∫ F(x) dx, заряд, перенесённый переменным током, q = ∫ I(t) dt, масса неоднородного стержня m = ∫ ρ(x) dx. <b>Энергетика:</b> электросчётчик интегрирует мощность по времени — кВт·ч и есть этот интеграл.', 'The definite integral is used wherever a “varying quantity must be accumulated”. <b>Physics:</b> the work of a varying force W = ∫ F(x) dx, the charge carried by a varying current q = ∫ I(t) dt, the mass of a non-uniform rod m = ∫ ρ(x) dx. <b>Energy:</b> an electricity meter integrates power over time — a kWh is exactly this integral.'),
      L('<b>Tibbiyot:</b> farmakologiyada qondagi dori konsentratsiyasi egri chizig‘i ostidagi yuz (AUC) organizm olgan dori miqdorini ko‘rsatadi. <b>Ekologiya:</b> daryodan bir sutkada o‘tgan suv hajmi — oqim tezligining vaqt bo‘yicha integrali. <b>Iqtisod:</b> o‘zgaruvchan daromad oqimining yil davomidagi yig‘indisi ham integral bilan topiladi.', '<b>Медицина:</b> в фармакологии площадь под кривой концентрации лекарства в крови (AUC) показывает количество лекарства, полученное организмом. <b>Экология:</b> объём воды, прошедший через реку за сутки, — интеграл расхода по времени. <b>Экономика:</b> сумма переменного потока доходов за год тоже находится интегралом.', '<b>Medicine:</b> in pharmacology the area under the blood concentration curve (AUC) shows how much drug the body received. <b>Ecology:</b> the volume of water passing through a river in a day is the integral of the flow rate over time. <b>Economics:</b> the yearly total of a varying income stream is also found by an integral.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Nyuton va Leybnits o‘rtasida «kim birinchi?» degan qattiq bahs bo‘lgan. 1712-yilda London qirollik jamiyati Nyuton foydasiga qaror chiqardi — lekin hisobotni Nyutonning o‘zi yozgan edi!', 'Между Ньютоном и Лейбницем шёл ожесточённый спор «кто первый?». В 1712 году Лондонское королевское общество вынесло решение в пользу Ньютона — но отчёт написал сам Ньютон!', 'Newton and Leibniz had a fierce “who was first?” dispute. In 1712 the Royal Society of London ruled in Newton’s favour — but the report was written by Newton himself!'),
      L('Formulaning boshqa nomi — <b>analizning asosiy teoremasi</b>. U matematikaning eng muhim teoremalaridan biri hisoblanadi.', 'Другое название формулы — <b>основная теорема анализа</b>. Она считается одной из важнейших теорем математики.', 'Another name for the formula is the <b>fundamental theorem of calculus</b>. It is considered one of the most important theorems in mathematics.'),
      L('Arximedning parabola haqidagi natijasi integral tilida: ∫₋₁¹ (1 − x²) dx = 4/3, ichki uchburchak yuzi esa 1. Nisbat aynan 4/3!', 'Результат Архимеда о параболе на языке интегралов: ∫₋₁¹ (1 − x²) dx = 4/3, а площадь вписанного треугольника равна 1. Отношение ровно 4/3!', 'Archimedes’ parabola result in the language of integrals: ∫₋₁¹ (1 − x²) dx = 4/3, while the inscribed triangle has area 1. The ratio is exactly 4/3!')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('∫₀² (2x + 1) dx = ?', '∫₀² (2x + 1) dx = ?', '∫₀² (2x + 1) dx = ?'),
      L('∫₀<sup>π/2</sup> cos x dx = ?', '∫₀<sup>π/2</sup> cos x dx = ?', '∫₀<sup>π/2</sup> cos x dx = ?'),
      L('∫₀¹ eˣ dx = ?', '∫₀¹ eˣ dx = ?', '∫₀¹ eˣ dx = ?'),
      L('∫₁ᵃ 2x dx = 8 bo‘lsa, a &gt; 1 ni toping.', 'Найдите a &gt; 1, если ∫₁ᵃ 2x dx = 8.', 'Find a &gt; 1 if ∫₁ᵃ 2x dx = 8.')
    ], after: [
      L('Javoblar: 6; 1; e − 1 ≈ 1,718; a² − 1 = 8, a = 3.', 'Ответы: 6; 1; e − 1 ≈ 1,718; a² − 1 = 8, a = 3.', 'Answers: 6; 1; e − 1 ≈ 1.718; a² − 1 = 8, a = 3.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Aniq integral — integral yig‘indilar limiti; u son, funksiya emas.', 'Определённый интеграл — предел интегральных сумм; это число, а не функция.', 'A definite integral is the limit of Riemann sums; it is a number, not a function.'),
      L('f ≥ 0 bo‘lsa, ∫ₐᵇ f dx — egri chiziqli trapetsiya yuzi.', 'При f ≥ 0 ∫ₐᵇ f dx — площадь криволинейной трапеции.', 'If f ≥ 0, ∫ₐᵇ f dx is the area of the curvilinear trapezium.'),
      L('Nyuton–Leybnits: ∫ₐᵇ f(x) dx = F(b) − F(a).', 'Ньютон–Лейбниц: ∫ₐᵇ f(x) dx = F(b) − F(a).', 'Newton–Leibniz: ∫ₐᵇ f(x) dx = F(b) − F(a).'),
      L('Isbot g‘oyasi: yuz funksiyasining hosilasi f ga teng.', 'Идея доказательства: производная функции площади равна f.', 'Proof idea: the derivative of the area function equals f.'),
      L('Xossalar: chiziqlilik, additivlik, chegaralar almashsa ishora o‘zgaradi.', 'Свойства: линейность, аддитивность, смена знака при перестановке пределов.', 'Properties: linearity, additivity, sign change when limits are swapped.'),
      L('Funksiya oraliqda uzluksiz bo‘lishi shart.', 'Функция должна быть непрерывна на промежутке.', 'The function must be continuous on the interval.')
    ] }
  ] });

  // ---------- t13. Aniq integralning tatbiqlari: yuzlar ----------
  T.add(P, 't13', { sections: [
    { kind: 'intro', h: L('Egri chiziqli figuralar yuzi', 'Площади криволинейных фигур', 'Areas of curved figures'), p: [
      L('Kvadrat, uchburchak, trapetsiya yuzlarini maktabda oddiy formulalar bilan topamiz. Lekin dunyodagi shakllarning aksariyati egri chiziqli: daryo bo‘yidagi yer uchastkasi, samolyot qanoti, ko‘prik ravog‘i, futbol to‘pi. Doira yuzi uchun πr² formulasini ham kimdir qachondir chiqarishi kerak edi. Aniq integral bunday figuralarning yuzini — va hatto jismlarning hajmini — hisoblashning universal usulini beradi.', 'Площади квадрата, треугольника, трапеции в школе находят простыми формулами. Но большинство форм в мире криволинейны: участок у реки, крыло самолёта, арка моста, футбольный мяч. Формулу πr² для круга тоже кто-то когда-то должен был вывести. Определённый интеграл даёт универсальный способ вычислять площади таких фигур — и даже объёмы тел.', 'At school we find the areas of squares, triangles and trapezia with simple formulas. But most shapes in the world are curved: a plot by a river, an aircraft wing, a bridge arch, a football. Even the formula πr² for a circle had to be derived by someone. The definite integral gives a universal way to compute the areas of such figures — and even the volumes of solids.'),
      L('Bu mavzuda uchta asosiy holatni ko‘ramiz: grafik Ox o‘qidan yuqorida, pastda yoki uni kesib o‘tgan holat; ikki egri chiziq orasidagi figura; va nihoyat, figura o‘q atrofida aylanganda hosil bo‘ladigan jism hajmi.', 'В этой теме рассмотрим три основных случая: график выше оси Ox, ниже или пересекает её; фигура между двумя кривыми; и, наконец, объём тела, получающегося при вращении фигуры вокруг оси.', 'In this topic we look at three main cases: a graph above the Ox axis, below it or crossing it; a figure between two curves; and finally the volume of a solid formed when a figure rotates about an axis.')
    ] },
    { kind: 'def', h: L('Yuz formulalari', 'Формулы площади', 'Area formulas'), p: [
      L('<b>1-hol.</b> [a; b] da f(x) ≥ 0: S = ∫ₐᵇ f(x) dx. <b>2-hol.</b> [a; b] da f(x) ≤ 0: figura Ox dan pastda, integral manfiy, shuning uchun S = −∫ₐᵇ f(x) dx = ∫ₐᵇ |f(x)| dx. <b>3-hol.</b> f ishorasini o‘zgartirsa, oraliqni ildizlar bo‘yicha bo‘laklarga ajratamiz va har bir bo‘lak yuzini alohida (musbat qilib) qo‘shamiz.', '<b>Случай 1.</b> На [a; b] f(x) ≥ 0: S = ∫ₐᵇ f(x) dx. <b>Случай 2.</b> На [a; b] f(x) ≤ 0: фигура под осью Ox, интеграл отрицателен, поэтому S = −∫ₐᵇ f(x) dx = ∫ₐᵇ |f(x)| dx. <b>Случай 3.</b> Если f меняет знак, делим промежуток по корням на части и складываем площади частей отдельно (положительными).', '<b>Case 1.</b> f(x) ≥ 0 on [a; b]: S = ∫ₐᵇ f(x) dx. <b>Case 2.</b> f(x) ≤ 0 on [a; b]: the figure lies below Ox, the integral is negative, so S = −∫ₐᵇ f(x) dx = ∫ₐᵇ |f(x)| dx. <b>Case 3.</b> If f changes sign, split the interval at the roots and add the areas of the parts separately (as positive numbers).'),
      L('<b>Ikki egri chiziq orasidagi yuz.</b> Agar [a; b] da f₂(x) ≥ f₁(x) bo‘lsa, S = ∫ₐᵇ (f₂(x) − f₁(x)) dx — «yuqori minus pastki». Bu formula grafiklar Ox dan pastda bo‘lsa ham to‘g‘ri, chunki ikkala funksiyaga bir xil son qo‘shsak, ayirma o‘zgarmaydi. Chegaralar ko‘pincha berilmaydi — ular f₁(x) = f₂(x) tenglamaning ildizlari, ya’ni <b>kesishish nuqtalari</b>.', '<b>Площадь между двумя кривыми.</b> Если на [a; b] f₂(x) ≥ f₁(x), то S = ∫ₐᵇ (f₂(x) − f₁(x)) dx — «верхняя минус нижняя». Формула верна, даже если графики ниже Ox: если прибавить к обеим функциям одно число, разность не изменится. Пределы часто не даны — это корни уравнения f₁(x) = f₂(x), то есть <b>точки пересечения</b>.', '<b>Area between two curves.</b> If f₂(x) ≥ f₁(x) on [a; b], then S = ∫ₐᵇ (f₂(x) − f₁(x)) dx — “top minus bottom”. The formula holds even if the graphs lie below Ox: adding the same number to both functions does not change the difference. The limits are often not given — they are the roots of f₁(x) = f₂(x), i.e. the <b>intersection points</b>.')
    ] },
    { kind: 'history', h: L('Bochkalar, bo‘linmaslar va sharlar', 'Бочки, неделимые и шары', 'Barrels, indivisibles and spheres'), p: [
      L('Arximed (mil. av. 287–212) parabola segmenti yuzidan tashqari shar hajmi va sirtini ham topgan: shar hajmi unga tashqi chizilgan silindr hajmining 2/3 qismiga teng. Bu kashfiyotdan shunchalik faxrlanganki, qabr toshiga silindr ichidagi shar tasvirini o‘yishni vasiyat qilgan. Rim notig‘i Tsitseron bu qabrni miloddan avvalgi 75-yilda Sirakuzada topgani haqida yozib qoldirgan.', 'Архимед (287–212 до н. э.), кроме площади параболического сегмента, нашёл объём и поверхность шара: объём шара равен 2/3 объёма описанного цилиндра. Он так гордился этим открытием, что завещал высечь на надгробии шар в цилиндре. Римский оратор Цицерон записал, что нашёл эту могилу в Сиракузах в 75 году до н. э.', 'Archimedes (287–212 BC), besides the parabolic segment, found the volume and surface of a sphere: the volume of a sphere is 2/3 of the volume of the circumscribed cylinder. He was so proud of this discovery that he asked for a sphere inside a cylinder to be carved on his tombstone. The Roman orator Cicero wrote that he found this grave in Syracuse in 75 BC.'),
      L('1613-yilda astronom <b>Iogann Kepler</b> to‘yi uchun vino sotib olayotib, savdogarlar bochka hajmini bitta tayoq bilan o‘lchashini ko‘rdi va bu usulning to‘g‘riligiga shubha qildi. Natijada 1615-yilda «Vino bochkalarining yangi stereometriyasi» kitobi paydo bo‘ldi: Kepler jismlarni juda yupqa qatlamlarga «kesib», hajmlarni ularning yig‘indisi sifatida hisobladi. Keyinroq Kavalyeri prinsipi (1635) bu g‘oyani umumlashtirdi.', 'В 1613 году астроном <b>Иоганн Кеплер</b>, покупая вино к своей свадьбе, увидел, что торговцы измеряют объём бочки одной палкой, и усомнился в правильности способа. В итоге в 1615 году вышла книга «Новая стереометрия винных бочек»: Кеплер «разрезал» тела на тончайшие слои и считал объём как их сумму. Позже принцип Кавальери (1635) обобщил эту идею.', 'In 1613 the astronomer <b>Johannes Kepler</b>, buying wine for his wedding, saw merchants measure the volume of a barrel with a single rod and doubted the method. The result was his 1615 book “New Stereometry of Wine Barrels”: Kepler “sliced” solids into very thin layers and computed volumes as their sum. Later Cavalieri’s principle (1635) generalised this idea.')
    ] },
    { kind: 'steps', h: L('Yuzni topish algoritmi', 'Алгоритм нахождения площади', 'Algorithm for finding an area'), list: [
      L('Grafiklarni taxminiy chizing — bu qaysi funksiya yuqorida ekanini va figuraning shaklini ko‘rsatadi.', 'Сделайте эскиз графиков — он покажет, какая функция выше и какова форма фигуры.', 'Sketch the graphs — this shows which function is on top and what the figure looks like.'),
      L('Kesishish nuqtalarini toping: f₁(x) = f₂(x) tenglamani yeching (yoki f(x) = 0, agar ikkinchi chegara Ox bo‘lsa).', 'Найдите точки пересечения: решите уравнение f₁(x) = f₂(x) (или f(x) = 0, если вторая граница — ось Ox).', 'Find the intersection points: solve f₁(x) = f₂(x) (or f(x) = 0 if the other boundary is the Ox axis).'),
      L('Har bir oraliqda qaysi funksiya katta ekanini aniqlang (ichki nuqtada tekshirish yetarli).', 'На каждом промежутке определите, какая функция больше (достаточно проверить внутреннюю точку).', 'On each interval determine which function is larger (checking an interior point is enough).'),
      L('S = ∫ (yuqori − pastki) dx integralini tuzing va Nyuton–Leybnits formulasi bilan hisoblang.', 'Составьте S = ∫ (верхняя − нижняя) dx и вычислите по формуле Ньютона–Лейбница.', 'Set up S = ∫ (top − bottom) dx and evaluate with the Newton–Leibniz formula.'),
      L('Tekshiring: yuz musbat bo‘lishi va chizmaga mos kelishi kerak.', 'Проверьте: площадь должна быть положительной и соответствовать чертежу.', 'Check: the area must be positive and agree with the sketch.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar: asosiy hollar', 'Решённые примеры: основные случаи', 'Solved examples: basic cases'), ex: [
      { q: L('y = 4 − x² parabola va Ox o‘qi bilan chegaralangan figura yuzini toping.', 'Найдите площадь фигуры, ограниченной параболой y = 4 − x² и осью Ox.', 'Find the area bounded by the parabola y = 4 − x² and the Ox axis.'), s: L('Ildizlar: 4 − x² = 0, x = ±2. S = ∫₋₂² (4 − x²) dx = (4x − x³/3)|₋₂² = (8 − 8/3) − (−8 + 8/3) = 16 − 16/3 = 32/3.', 'Корни: 4 − x² = 0, x = ±2. S = ∫₋₂² (4 − x²) dx = (4x − x³/3)|₋₂² = (8 − 8/3) − (−8 + 8/3) = 16 − 16/3 = 32/3.', 'Roots: 4 − x² = 0, x = ±2. S = ∫₋₂² (4 − x²) dx = (4x − x³/3)|₋₂² = (8 − 8/3) − (−8 + 8/3) = 16 − 16/3 = 32/3.') },
      { q: L('y = x va y = x² chiziqlar orasidagi yuzni toping.', 'Найдите площадь между линиями y = x и y = x².', 'Find the area between y = x and y = x².'), s: L('x = x² → x = 0 yoki x = 1. (0; 1) da x &gt; x² (masalan, 0,5 &gt; 0,25). S = ∫₀¹ (x − x²) dx = 1/2 − 1/3 = 1/6.', 'x = x² → x = 0 или x = 1. На (0; 1) x &gt; x² (например, 0,5 &gt; 0,25). S = ∫₀¹ (x − x²) dx = 1/2 − 1/3 = 1/6.', 'x = x² gives x = 0 or x = 1. On (0; 1), x &gt; x² (e.g. 0.5 &gt; 0.25). S = ∫₀¹ (x − x²) dx = 1/2 − 1/3 = 1/6.') },
      { q: L('y = x² va y = 2x + 3 orasidagi yuzni toping.', 'Найдите площадь между y = x² и y = 2x + 3.', 'Find the area between y = x² and y = 2x + 3.'), s: L('x² = 2x + 3 → x² − 2x − 3 = 0 → x = −1, x = 3. To‘g‘ri chiziq yuqorida (x = 0 da 3 &gt; 0). S = ∫₋₁³ (2x + 3 − x²) dx = (x² + 3x − x³/3)|₋₁³ = (9 + 9 − 9) − (1 − 3 + 1/3) = 9 + 5/3 = 32/3.', 'x² = 2x + 3 → x² − 2x − 3 = 0 → x = −1, x = 3. Прямая выше (при x = 0: 3 &gt; 0). S = ∫₋₁³ (2x + 3 − x²) dx = (x² + 3x − x³/3)|₋₁³ = (9 + 9 − 9) − (1 − 3 + 1/3) = 9 + 5/3 = 32/3.', 'x² = 2x + 3 gives x² − 2x − 3 = 0, so x = −1 or x = 3. The line is on top (at x = 0: 3 &gt; 0). S = ∫₋₁³ (2x + 3 − x²) dx = (x² + 3x − x³/3)|₋₁³ = (9 + 9 − 9) − (1 − 3 + 1/3) = 9 + 5/3 = 32/3.') },
      { q: L('y = 1/x giperbola, Ox o‘qi, x = 1 va x = e chiziqlar bilan chegaralangan yuzni toping.', 'Найдите площадь, ограниченную гиперболой y = 1/x, осью Ox и прямыми x = 1, x = e.', 'Find the area bounded by y = 1/x, the Ox axis and the lines x = 1, x = e.'), s: L('S = ∫₁<sup>e</sup> dx/x = ln e − ln 1 = 1. Aynan shu xossa natural logarifmni ta’riflash uchun ishlatiladi: ln a — giperbola ostidagi 1 dan a gacha bo‘lgan yuz.', 'S = ∫₁<sup>e</sup> dx/x = ln e − ln 1 = 1. Именно это свойство используют для определения натурального логарифма: ln a — площадь под гиперболой от 1 до a.', 'S = ∫₁<sup>e</sup> dx/x = ln e − ln 1 = 1. This very property is used to define the natural logarithm: ln a is the area under the hyperbola from 1 to a.') }
    ] },
    { kind: 'example', h: L('Ishora o‘zgaradigan hollar', 'Случаи смены знака', 'Cases with a sign change'), ex: [
      { q: L('[0; 2π] da y = sin x va Ox orasidagi yuzni toping.', 'Найдите площадь между y = sin x и Ox на [0; 2π].', 'Find the area between y = sin x and Ox on [0; 2π].'), s: L('[0; π] da sin x ≥ 0, [π; 2π] da ≤ 0. S = ∫₀<sup>π</sup> sin x dx − ∫<sub>π</sub><sup>2π</sup> sin x dx = 2 − (−2) = 4. Agar bitta integral olinsa, 0 chiqardi — xato.', 'На [0; π] sin x ≥ 0, на [π; 2π] ≤ 0. S = ∫₀<sup>π</sup> sin x dx − ∫<sub>π</sub><sup>2π</sup> sin x dx = 2 − (−2) = 4. Если взять один интеграл, получится 0 — ошибка.', 'On [0; π] sin x ≥ 0, on [π; 2π] it is ≤ 0. S = ∫₀<sup>π</sup> sin x dx − ∫<sub>π</sub><sup>2π</sup> sin x dx = 2 − (−2) = 4. Taking one integral would give 0 — a mistake.') },
      { q: L('[−1; 2] da y = x³ va Ox orasidagi yuzni toping.', 'Найдите площадь между y = x³ и Ox на [−1; 2].', 'Find the area between y = x³ and Ox on [−1; 2].'), s: L('[−1; 0] da x³ ≤ 0: −∫₋₁⁰ x³ dx = −(0 − 1/4) = 1/4. [0; 2] da: ∫₀² x³ dx = 16/4 = 4. S = 1/4 + 4 = 17/4. (Bitta integral 4 − 1/4 = 15/4 berardi.)', 'На [−1; 0] x³ ≤ 0: −∫₋₁⁰ x³ dx = −(0 − 1/4) = 1/4. На [0; 2]: ∫₀² x³ dx = 16/4 = 4. S = 1/4 + 4 = 17/4. (Один интеграл дал бы 4 − 1/4 = 15/4.)', 'On [−1; 0], x³ ≤ 0: −∫₋₁⁰ x³ dx = −(0 − 1/4) = 1/4. On [0; 2]: ∫₀² x³ dx = 16/4 = 4. S = 1/4 + 4 = 17/4. (A single integral would give 4 − 1/4 = 15/4.)') },
      { q: L('y = x² − 4 va Ox orasidagi yuzni toping.', 'Найдите площадь между y = x² − 4 и Ox.', 'Find the area between y = x² − 4 and Ox.'), s: L('Ildizlar ±2, oraliqda funksiya manfiy. S = −∫₋₂² (x² − 4) dx = 32/3 — birinchi misoldagi figuraning ko‘zgudagi aksi.', 'Корни ±2, на промежутке функция отрицательна. S = −∫₋₂² (x² − 4) dx = 32/3 — зеркальное отражение фигуры из первого примера.', 'Roots ±2; between them the function is negative. S = −∫₋₂² (x² − 4) dx = 32/3 — the mirror image of the figure in the first example.') }
    ] },
    { kind: 'rule', h: L('Aylanish jismlari hajmi', 'Объёмы тел вращения', 'Volumes of solids of revolution'), p: [
      L('Egri chiziqli trapetsiya Ox o‘qi atrofida aylansa, jism hosil bo‘ladi. Uni x nuqtada o‘qqa perpendikulyar tekislik bilan kessak, radiusi f(x) bo‘lgan doira chiqadi, uning yuzi πf²(x). Jismni qalinligi dx bo‘lgan yupqa «tangalarga» bo‘lib, hajmlarini qo‘shsak: <b>V = π∫ₐᵇ f²(x) dx</b>.', 'Если криволинейная трапеция вращается вокруг оси Ox, получается тело. Сечение плоскостью, перпендикулярной оси в точке x, — круг радиуса f(x) площадью πf²(x). Разбив тело на тонкие «монетки» толщиной dx и сложив их объёмы, получаем: <b>V = π∫ₐᵇ f²(x) dx</b>.', 'When a curvilinear trapezium rotates about the Ox axis, a solid is formed. Its cross-section by a plane perpendicular to the axis at x is a disc of radius f(x) and area πf²(x). Cutting the solid into thin “coins” of thickness dx and adding their volumes gives: <b>V = π∫ₐᵇ f²(x) dx</b>.')
    ], ex: [
      { q: L('Konus hajmini chiqaring: y = (r/h)x, 0 ≤ x ≤ h kesma Ox atrofida aylanadi.', 'Выведите объём конуса: отрезок y = (r/h)x, 0 ≤ x ≤ h, вращается вокруг Ox.', 'Derive the volume of a cone: the segment y = (r/h)x, 0 ≤ x ≤ h, rotates about Ox.'), s: L('V = π∫₀ʰ (r²/h²)x² dx = π(r²/h²)·h³/3 = πr²h/3 — maktabdan ma’lum formula.', 'V = π∫₀ʰ (r²/h²)x² dx = π(r²/h²)·h³/3 = πr²h/3 — известная школьная формула.', 'V = π∫₀ʰ (r²/h²)x² dx = π(r²/h²)·h³/3 = πr²h/3 — the familiar school formula.') },
      { q: L('Shar hajmini chiqaring: y = √(R² − x²) yarim aylana Ox atrofida aylanadi.', 'Выведите объём шара: полуокружность y = √(R² − x²) вращается вокруг Ox.', 'Derive the volume of a ball: the semicircle y = √(R² − x²) rotates about Ox.'), s: L('V = π∫<sub>−R</sub><sup>R</sup> (R² − x²) dx = π(R²x − x³/3)|<sub>−R</sub><sup>R</sup> = π(2R³ − 2R³/3) = 4πR³/3. Arximed natijasi!', 'V = π∫<sub>−R</sub><sup>R</sup> (R² − x²) dx = π(R²x − x³/3)|<sub>−R</sub><sup>R</sup> = π(2R³ − 2R³/3) = 4πR³/3. Результат Архимеда!', 'V = π∫<sub>−R</sub><sup>R</sup> (R² − x²) dx = π(R²x − x³/3)|<sub>−R</sub><sup>R</sup> = π(2R³ − 2R³/3) = 4πR³/3. Archimedes’ result!') },
      { q: L('y = √x, 0 ≤ x ≤ 4 grafigining Ox atrofida aylanishidan hosil bo‘lgan jism hajmi?', 'Объём тела, полученного вращением графика y = √x, 0 ≤ x ≤ 4, вокруг Ox?', 'Volume of the solid formed by rotating y = √x, 0 ≤ x ≤ 4, about Ox?'), s: L('V = π∫₀⁴ x dx = π·16/2 = 8π ≈ 25,1. Bu — paraboloid (sun’iy yo‘ldosh antennasi shakli).', 'V = π∫₀⁴ x dx = π·16/2 = 8π ≈ 25,1. Это параболоид (форма спутниковой антенны).', 'V = π∫₀⁴ x dx = π·16/2 = 8π ≈ 25.1. This is a paraboloid (the shape of a satellite dish).') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Ishora o‘zgarishini e’tiborsiz qoldirish.</b> Grafik Ox ni kesib o‘tsa, bitta integral yuzlarning ayirmasini beradi, yig‘indisini emas.', '<b>Игнорировать смену знака.</b> Если график пересекает Ox, один интеграл даёт разность площадей, а не сумму.', '<b>Ignoring a sign change.</b> If the graph crosses Ox, a single integral gives the difference of the areas, not their sum.'),
      L('<b>«Pastki minus yuqori» olish.</b> Natija manfiy chiqsa — funksiyalar o‘rni almashgan. Chizma yoki ichki nuqtada tekshirish bunga yo‘l qo‘ymaydi.', '<b>Брать «нижняя минус верхняя».</b> Если результат отрицателен — функции перепутаны. Чертёж или проверка во внутренней точке это предотвращают.', '<b>Taking “bottom minus top”.</b> If the result is negative, the functions were swapped. A sketch or a check at an interior point prevents this.'),
      L('<b>Kesishish nuqtalarini noto‘g‘ri topish.</b> x² = x tenglamani x ga bo‘lib, x = 0 ildizini yo‘qotish — keng tarqalgan xato.', '<b>Неверно найти точки пересечения.</b> Разделить уравнение x² = x на x и потерять корень x = 0 — частая ошибка.', '<b>Finding the intersection points incorrectly.</b> Dividing x² = x by x and losing the root x = 0 is a common error.'),
      L('<b>Hajm formulasida kvadratni unutish:</b> V = π∫ f(x) dx emas, V = π∫ f²(x) dx.', '<b>Забыть квадрат в формуле объёма:</b> не V = π∫ f(x) dx, а V = π∫ f²(x) dx.', '<b>Forgetting the square in the volume formula:</b> not V = π∫ f(x) dx but V = π∫ f²(x) dx.'),
      L('<b>Ikki funksiya orasidagi hajmda (f₂ − f₁)² olish.</b> To‘g‘risi: V = π∫ (f₂² − f₁²) dx — «katta doira minus kichik doira».', '<b>Брать (f₂ − f₁)² для объёма между двумя функциями.</b> Верно: V = π∫ (f₂² − f₁²) dx — «большой круг минус малый».', '<b>Using (f₂ − f₁)² for the volume between two functions.</b> Correct: V = π∫ (f₂² − f₁²) dx — “big disc minus small disc”.')
    ] },
    { kind: 'life', h: L('Hayotda yuz va hajmlar', 'Площади и объёмы в жизни', 'Areas and volumes in real life'), p: [
      L('<b>Qurilish va arxitektura:</b> parabola shaklidagi ravoq yoki ko‘prik ostidagi devor yuzini hisoblash, gumbaz uchun material miqdorini topish. <b>Mashinasozlik:</b> tokarlik stanogida yasalgan detallar — aylanish jismlari; ularning hajmi va massasi aynan V = π∫ f² dx bilan topiladi. Vazalar, shishalar, lampochkalar, raketaning burun qismi ham shunday.', '<b>Строительство и архитектура:</b> расчёт площади стены под параболической аркой или мостом, количества материала для купола. <b>Машиностроение:</b> детали, выточенные на токарном станке, — тела вращения; их объём и массу находят именно по V = π∫ f² dx. Так же — вазы, бутылки, лампочки, носовой обтекатель ракеты.', '<b>Construction and architecture:</b> computing the area of a wall under a parabolic arch or bridge, the amount of material for a dome. <b>Mechanical engineering:</b> parts turned on a lathe are solids of revolution; their volume and mass are found exactly with V = π∫ f² dx. The same goes for vases, bottles, light bulbs and rocket nose cones.'),
      L('<b>Iqtisod:</b> talab va taklif egri chiziqlari orasidagi yuz «iste’molchi yutug‘i» va «ishlab chiqaruvchi yutug‘i»ni o‘lchaydi. Lorens egri chizig‘i va diagonal orasidagi yuz esa Jini koeffitsiyentini beradi — u mamlakatdagi daromad tengsizligini ko‘rsatadi. <b>Geodeziya:</b> egri chegarali yer uchastkasining maydoni kadastr hujjatlarida shu tarzda hisoblanadi.', '<b>Экономика:</b> площадь между кривыми спроса и предложения измеряет «излишек потребителя» и «излишек производителя». Площадь между кривой Лоренца и диагональю даёт коэффициент Джини — показатель неравенства доходов в стране. <b>Геодезия:</b> так рассчитывают площадь участка с криволинейной границей в кадастровых документах.', '<b>Economics:</b> the area between the demand and supply curves measures “consumer surplus” and “producer surplus”. The area between the Lorenz curve and the diagonal gives the Gini coefficient, a measure of income inequality in a country. <b>Surveying:</b> the area of a plot with a curved boundary is computed this way in land registry documents.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('«Gabriel karnayi»: y = 1/x (x ≥ 1) grafigini Ox atrofida aylantirsak, jism hajmi chekli (π ga teng), sirtining yuzi esa cheksiz! Uni bo‘yoq bilan to‘ldirish mumkin, lekin sirtini bo‘yab bo‘lmaydi — bu paradoksni Evanjelista Torrichelli 1643-yilda kashf etgan.', '«Труба Габриэля»: вращая график y = 1/x (x ≥ 1) вокруг Ox, получаем тело конечного объёма (π), но с бесконечной площадью поверхности! Его можно наполнить краской, но нельзя покрасить — парадокс открыл Эванджелиста Торричелли в 1643 году.', '“Gabriel’s horn”: rotating y = 1/x (x ≥ 1) about Ox gives a solid of finite volume (π) but infinite surface area! It can be filled with paint but not painted — the paradox was discovered by Evangelista Torricelli in 1643.'),
      L('Ellips x²/a² + y²/b² = 1 yuzi integral yordamida πab ga teng chiqadi; a = b = r bo‘lsa, doira yuzi πr².', 'Площадь эллипса x²/a² + y²/b² = 1 с помощью интеграла получается πab; при a = b = r — площадь круга πr².', 'The area of the ellipse x²/a² + y²/b² = 1 comes out as πab by integration; with a = b = r it is the circle area πr².'),
      L('Planimetr — XIX asrda ixtiro qilingan mexanik asbob: uning ignasini figura chegarasi bo‘ylab yurgizsangiz, g‘ildirakcha yuzni ko‘rsatadi. U integral hisobning «temir» ko‘rinishi.', 'Планиметр — механический прибор XIX века: если провести его иглой по границе фигуры, колёсико покажет площадь. Это «железное» воплощение интегрального исчисления.', 'The planimeter is a 19th-century mechanical device: trace the boundary of a figure with its needle and a small wheel shows the area. It is integral calculus made of metal.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('y = x², Ox, x = 1 va x = 2 bilan chegaralangan yuz?', 'Площадь, ограниченная y = x², Ox, x = 1 и x = 2?', 'Area bounded by y = x², Ox, x = 1 and x = 2?'),
      L('y = 2x − x² va Ox orasidagi yuz?', 'Площадь между y = 2x − x² и Ox?', 'Area between y = 2x − x² and Ox?'),
      L('y = x² va y = 4 orasidagi yuz?', 'Площадь между y = x² и y = 4?', 'Area between y = x² and y = 4?'),
      L('y = x, 0 ≤ x ≤ 3 kesmaning Ox atrofida aylanishidan hosil bo‘lgan konus hajmi?', 'Объём конуса от вращения отрезка y = x, 0 ≤ x ≤ 3, вокруг Ox?', 'Volume of the cone from rotating y = x, 0 ≤ x ≤ 3, about Ox?')
    ], after: [
      L('Javoblar: 7/3; 4/3; ∫₋₂² (4 − x²) dx = 32/3; π·27/3 = 9π.', 'Ответы: 7/3; 4/3; ∫₋₂² (4 − x²) dx = 32/3; π·27/3 = 9π.', 'Answers: 7/3; 4/3; ∫₋₂² (4 − x²) dx = 32/3; π·27/3 = 9π.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('f ≥ 0: S = ∫ₐᵇ f dx; f ≤ 0: S = −∫ₐᵇ f dx.', 'f ≥ 0: S = ∫ₐᵇ f dx; f ≤ 0: S = −∫ₐᵇ f dx.', 'f ≥ 0: S = ∫ₐᵇ f dx; f ≤ 0: S = −∫ₐᵇ f dx.'),
      L('Ishora o‘zgarsa, oraliqni ildizlarda bo‘ling va yuzlarni qo‘shing.', 'При смене знака делите промежуток по корням и складывайте площади.', 'If the sign changes, split at the roots and add the areas.'),
      L('Ikki egri chiziq orasida: S = ∫ₐᵇ (yuqori − pastki) dx, a va b — kesishish nuqtalari.', 'Между двумя кривыми: S = ∫ₐᵇ (верхняя − нижняя) dx, a и b — точки пересечения.', 'Between two curves: S = ∫ₐᵇ (top − bottom) dx, where a and b are the intersection points.'),
      L('Aylanish jismi hajmi: V = π∫ₐᵇ f²(x) dx.', 'Объём тела вращения: V = π∫ₐᵇ f²(x) dx.', 'Volume of revolution: V = π∫ₐᵇ f²(x) dx.'),
      L('Bu formulalar konus, shar, paraboloid hajmlarini beradi.', 'Эти формулы дают объёмы конуса, шара, параболоида.', 'These formulas give the volumes of the cone, ball and paraboloid.'),
      L('Har doim chizmadan boshlang.', 'Всегда начинайте с чертежа.', 'Always start with a sketch.')
    ] }
  ] });

  // ---------- t14. Taqribiy integrallash ----------
  T.add(P, 't14', { sections: [
    { kind: 'intro', h: L('Formula topilmasa nima qilamiz?', 'Что делать, если формулы нет?', 'What if there is no formula?'), p: [
      L('Nyuton–Leybnits formulasi ajoyib, lekin u boshlang‘ich funksiya ma’lum bo‘lgandagina ishlaydi. ∫₀¹ e<sup>−x²</sup> dx, ∫ sin x/x dx yoki ∫ √(1 + x⁴) dx kabi integrallarning boshlang‘ichi elementar funksiyalar orqali umuman ifodalanmaydi. Bundan tashqari, amalda funksiya ko‘pincha formula bilan emas, balki <b>o‘lchovlar jadvali</b> bilan beriladi: har 10 sekundda yozilgan tezlik, har 5 metrda o‘lchangan daryo chuqurligi.', 'Формула Ньютона–Лейбница прекрасна, но работает, только если известна первообразная. Первообразные интегралов вроде ∫₀¹ e<sup>−x²</sup> dx, ∫ sin x/x dx или ∫ √(1 + x⁴) dx вообще не выражаются через элементарные функции. Кроме того, на практике функцию часто задают не формулой, а <b>таблицей измерений</b>: скорость, записанная каждые 10 секунд, глубина реки, измеренная каждые 5 метров.', 'The Newton–Leibniz formula is wonderful, but it works only when an antiderivative is known. Integrals such as ∫₀¹ e<sup>−x²</sup> dx, ∫ sin x/x dx or ∫ √(1 + x⁴) dx have no antiderivatives expressible by elementary functions. Moreover, in practice a function is often given not by a formula but by a <b>table of measurements</b>: speed recorded every 10 seconds, river depth measured every 5 metres.'),
      L('Bunday hollarda integralni <b>taqribiy</b> hisoblaymiz: egri chiziq ostidagi yuzni oddiy figuralar — to‘g‘ri to‘rtburchaklar, trapetsiyalar yoki parabola bo‘laklari bilan almashtiramiz. Kompyuterlar va kalkulyatorlar integralni aynan shu usullar bilan hisoblaydi. Bu mavzuda uchta klassik usulni va ularning aniqligini o‘rganamiz.', 'В таких случаях интеграл вычисляют <b>приближённо</b>: площадь под кривой заменяют простыми фигурами — прямоугольниками, трапециями или кусочками парабол. Именно так интегралы считают компьютеры и калькуляторы. В этой теме изучим три классических метода и их точность.', 'In such cases we compute the integral <b>approximately</b>: we replace the area under the curve by simple shapes — rectangles, trapezia or pieces of parabolas. This is exactly how computers and calculators evaluate integrals. In this topic we study three classical methods and their accuracy.')
    ] },
    { kind: 'def', h: L('Bo‘linish, qadam va tugunlar', 'Разбиение, шаг и узлы', 'Partition, step and nodes'), p: [
      L('[a; b] kesmani n ta teng bo‘lakka bo‘lamiz. Har bir bo‘lak uzunligi — <b>qadam</b>: h = (b − a)/n. Bo‘linish nuqtalari — <b>tugunlar</b>: x₀ = a, x₁ = a + h, x₂ = a + 2h, …, xₙ = b. Tugunlardagi funksiya qiymatlarini y₀ = f(x₀), y₁ = f(x₁), …, yₙ = f(xₙ) bilan belgilaymiz. Barcha taqribiy formulalar faqat shu yᵢ sonlar bilan ishlaydi — shuning uchun ular jadval ko‘rinishidagi ma’lumotlar uchun ham yaroqli.', 'Делим отрезок [a; b] на n равных частей. Длина каждой части — <b>шаг</b>: h = (b − a)/n. Точки деления — <b>узлы</b>: x₀ = a, x₁ = a + h, x₂ = a + 2h, …, xₙ = b. Значения функции в узлах обозначаем y₀ = f(x₀), y₁ = f(x₁), …, yₙ = f(xₙ). Все приближённые формулы работают только с числами yᵢ — поэтому они годятся и для табличных данных.', 'Split [a; b] into n equal parts. The length of each part is the <b>step</b>: h = (b − a)/n. The division points are the <b>nodes</b>: x₀ = a, x₁ = a + h, x₂ = a + 2h, …, xₙ = b. The function values at the nodes are y₀ = f(x₀), y₁ = f(x₁), …, yₙ = f(xₙ). All approximate formulas use only these numbers yᵢ — so they also work for tabulated data.'),
      L('Usul sifati <b>xatolik</b> bilan o‘lchanadi: aniq qiymat va taqribiy qiymat orasidagi farq. Yaxshi usulda n oshganda xatolik tez kamayadi. Muhim savol: n ni ikki marta oshirsak, xatolik necha marta kamayadi? Javob usulga bog‘liq: 2, 4 yoki 16 marta.', 'Качество метода измеряется <b>погрешностью</b>: разницей между точным и приближённым значением. У хорошего метода погрешность быстро убывает с ростом n. Главный вопрос: во сколько раз уменьшится погрешность, если удвоить n? Ответ зависит от метода: в 2, 4 или 16 раз.', 'The quality of a method is measured by its <b>error</b>: the difference between the exact and the approximate value. In a good method the error shrinks quickly as n grows. The key question: if we double n, by what factor does the error shrink? The answer depends on the method: 2, 4 or 16 times.')
    ] },
    { kind: 'history', h: L('Keplerdan Simpson va Gaussgacha', 'От Кеплера до Симпсона и Гаусса', 'From Kepler to Simpson and Gauss'), p: [
      L('Taqribiy integrallash integral hisobdan ham qadimiy. Bobil astronomlari miloddan avvalgi IV–I asrlarda Yupiterning bosib o‘tgan yo‘lini tezlik-vaqt grafigi ostidagi trapetsiya yuzi sifatida hisoblashgan — bu 2016-yilda tarixchi Matyo Osendrijver tomonidan o‘qilgan loy taxtachalarda aniqlandi. 1615-yilda <b>Kepler</b> bochka hajmi uchun formulani taklif qildi, u bugun «Kepler bochka qoidasi» deb ataladi.', 'Приближённое интегрирование древнее самого интегрального исчисления. Вавилонские астрономы в IV–I веках до н. э. вычисляли путь Юпитера как площадь трапеции под графиком скорости — это установил в 2016 году историк Матье Оссендрейвер, прочитав глиняные таблички. В 1615 году <b>Кеплер</b> предложил формулу для объёма бочки, которую сегодня называют «правилом бочки Кеплера».', 'Approximate integration is older than calculus itself. Babylonian astronomers in the 4th–1st centuries BC computed the path of Jupiter as the area of a trapezium under a speed–time graph — as historian Mathieu Ossendrijver showed in 2016 by reading clay tablets. In 1615 <b>Kepler</b> proposed a formula for the volume of a barrel, now known as “Kepler’s barrel rule”.'),
      L('Ingliz matematigi <b>Tomas Simpson</b> 1743-yilda parabolalar usulini mashhur qildi, garchi undan oldin Kavalyeri va Jeyms Gregori ham bu formulani bilgan bo‘lsa-da. Nyuton va Rodjer Kotes teng oraliqli tugunlar uchun umumiy formulalar oilasini yaratdilar (Nyuton–Kotes formulalari). 1814-yilda <b>Karl Fridrix Gauss</b> tugunlarni maxsus tanlab, bir xil sondagi hisoblashlarda ancha yuqori aniqlikka erishish mumkinligini ko‘rsatdi (Gauss kvadraturasi).', 'Английский математик <b>Томас Симпсон</b> в 1743 году сделал знаменитым метод парабол, хотя до него эту формулу знали Кавальери и Джеймс Грегори. Ньютон и Роджер Котс создали семейство формул для равноотстоящих узлов (формулы Ньютона–Котса). В 1814 году <b>Карл Фридрих Гаусс</b> показал, что при особом выборе узлов можно при том же числе вычислений достичь гораздо большей точности (квадратура Гаусса).', 'The English mathematician <b>Thomas Simpson</b> popularised the parabola method in 1743, although Cavalieri and James Gregory had known the formula before him. Newton and Roger Cotes created a family of formulas for equally spaced nodes (the Newton–Cotes formulas). In 1814 <b>Carl Friedrich Gauss</b> showed that by choosing the nodes cleverly one can reach much higher accuracy with the same number of computations (Gaussian quadrature).')
    ] },
    { kind: 'rule', h: L('To‘g‘ri to‘rtburchaklar usuli', 'Метод прямоугольников', 'The rectangle method'), p: [
      L('Har bir bo‘lakda funksiyani o‘zgarmas son bilan almashtiramiz. <b>Chap to‘g‘ri to‘rtburchaklar:</b> ∫ₐᵇ f dx ≈ h(y₀ + y₁ + … + yₙ₋₁). <b>O‘ng to‘g‘ri to‘rtburchaklar:</b> ∫ₐᵇ f dx ≈ h(y₁ + y₂ + … + yₙ). O‘suvchi funksiya uchun chap usul kamaytirib, o‘ng usul oshirib baholaydi; ularning xatoligi h ga proporsional, ya’ni n ni 2 marta oshirsak, xatolik taxminan 2 marta kamayadi.', 'На каждой части заменяем функцию постоянной. <b>Левые прямоугольники:</b> ∫ₐᵇ f dx ≈ h(y₀ + y₁ + … + yₙ₋₁). <b>Правые прямоугольники:</b> ∫ₐᵇ f dx ≈ h(y₁ + y₂ + … + yₙ). Для возрастающей функции левый метод даёт недостаток, правый — избыток; их погрешность пропорциональна h, то есть при удвоении n погрешность уменьшается примерно вдвое.', 'On each part we replace the function by a constant. <b>Left rectangles:</b> ∫ₐᵇ f dx ≈ h(y₀ + y₁ + … + yₙ₋₁). <b>Right rectangles:</b> ∫ₐᵇ f dx ≈ h(y₁ + y₂ + … + yₙ). For an increasing function the left method underestimates and the right one overestimates; their error is proportional to h, so doubling n roughly halves the error.'),
      L('<b>O‘rta to‘g‘ri to‘rtburchaklar</b> usuli ancha yaxshi: balandlik sifatida bo‘lak o‘rtasidagi qiymat olinadi, ∫ₐᵇ f dx ≈ h(f(x₀ + h/2) + f(x₁ + h/2) + … ). Bunda ortiqcha va kam qismlar bir-birini qisman to‘ldiradi, xatolik h² ga proporsional bo‘ladi: |E| ≤ (b − a)h²M₂/24, bunda M₂ — |f″| ning eng katta qiymati.', 'Метод <b>средних прямоугольников</b> гораздо лучше: высотой берут значение в середине части, ∫ₐᵇ f dx ≈ h(f(x₀ + h/2) + f(x₁ + h/2) + … ). Избыточные и недостающие куски частично компенсируют друг друга, погрешность пропорциональна h²: |E| ≤ (b − a)h²M₂/24, где M₂ — наибольшее значение |f″|.', 'The <b>midpoint rectangle</b> method is much better: the height is the value at the middle of each part, ∫ₐᵇ f dx ≈ h(f(x₀ + h/2) + f(x₁ + h/2) + … ). The extra and missing pieces partly cancel, and the error is proportional to h²: |E| ≤ (b − a)h²M₂/24, where M₂ is the largest value of |f″|.')
    ] },
    { kind: 'rule', h: L('Trapetsiyalar va Simpson formulalari', 'Формулы трапеций и Симпсона', 'The trapezium and Simpson rules'), p: [
      L('<b>Trapetsiyalar formulasi.</b> Grafikning har bir bo‘lagini vatar bilan almashtiramiz; har bir bo‘lakda trapetsiya hosil bo‘ladi, yuzi h(yᵢ + yᵢ₊₁)/2. Hammasini qo‘shsak: <b>∫ₐᵇ f dx ≈ h((y₀ + yₙ)/2 + y₁ + y₂ + … + yₙ₋₁)</b>. Bu chap va o‘ng to‘g‘ri to‘rtburchaklar natijalarining o‘rta arifmetigi. Xatolik bahosi: |E| ≤ (b − a)h²M₂/12.', '<b>Формула трапеций.</b> Каждый кусок графика заменяем хордой; на каждой части получается трапеция площадью h(yᵢ + yᵢ₊₁)/2. Складывая: <b>∫ₐᵇ f dx ≈ h((y₀ + yₙ)/2 + y₁ + y₂ + … + yₙ₋₁)</b>. Это среднее арифметическое левых и правых прямоугольников. Оценка погрешности: |E| ≤ (b − a)h²M₂/12.', '<b>Trapezium rule.</b> Replace each piece of the graph by a chord; each part becomes a trapezium of area h(yᵢ + yᵢ₊₁)/2. Adding up: <b>∫ₐᵇ f dx ≈ h((y₀ + yₙ)/2 + y₁ + y₂ + … + yₙ₋₁)</b>. It is the average of the left and right rectangle sums. Error bound: |E| ≤ (b − a)h²M₂/12.'),
      L('<b>Simpson (parabolalar) formulasi.</b> n juft bo‘lsin. Har ikki qo‘shni bo‘lakda grafikni uchta nuqta orqali o‘tuvchi parabola bilan almashtiramiz. Natija: <b>∫ₐᵇ f dx ≈ (h/3)(y₀ + 4y₁ + 2y₂ + 4y₃ + … + 2yₙ₋₂ + 4yₙ₋₁ + yₙ)</b> — toq indeksli qiymatlar 4 ga, ichki juft indeksli qiymatlar 2 ga ko‘paytiriladi. Xatolik |E| ≤ (b − a)h⁴M₄/180 — h⁴ ga proporsional, shuning uchun n ni 2 marta oshirsak, xatolik taxminan 16 marta kamayadi. Simpson formulasi 3-darajagacha bo‘lgan ko‘phadlar uchun aniq natija beradi.', '<b>Формула Симпсона (парабол).</b> Пусть n чётно. На каждой паре соседних частей заменяем график параболой через три точки. Результат: <b>∫ₐᵇ f dx ≈ (h/3)(y₀ + 4y₁ + 2y₂ + 4y₃ + … + 2yₙ₋₂ + 4yₙ₋₁ + yₙ)</b> — значения с нечётными индексами умножаются на 4, внутренние с чётными — на 2. Погрешность |E| ≤ (b − a)h⁴M₄/180 — пропорциональна h⁴, поэтому при удвоении n она уменьшается примерно в 16 раз. Формула Симпсона точна для многочленов до 3-й степени.', '<b>Simpson’s (parabola) rule.</b> Let n be even. On each pair of neighbouring parts replace the graph by a parabola through three points. Result: <b>∫ₐᵇ f dx ≈ (h/3)(y₀ + 4y₁ + 2y₂ + 4y₃ + … + 2yₙ₋₂ + 4yₙ₋₁ + yₙ)</b> — values with odd indices are multiplied by 4, inner values with even indices by 2. The error |E| ≤ (b − a)h⁴M₄/180 is proportional to h⁴, so doubling n cuts it about 16 times. Simpson’s rule is exact for polynomials of degree up to 3.')
    ] },
    { kind: 'steps', h: L('Hisoblash tartibi', 'Порядок вычислений', 'Computation procedure'), list: [
      L('n ni tanlang (Simpson uchun juft) va qadamni toping: h = (b − a)/n.', 'Выберите n (для Симпсона чётное) и найдите шаг h = (b − a)/n.', 'Choose n (even for Simpson) and find the step h = (b − a)/n.'),
      L('Tugunlar jadvalini tuzing: x₀, x₁, …, xₙ va y₀, y₁, …, yₙ (kamida 4 xona aniqlikda).', 'Составьте таблицу узлов: x₀, x₁, …, xₙ и y₀, y₁, …, yₙ (с точностью не менее 4 знаков).', 'Make a table of nodes: x₀, x₁, …, xₙ and y₀, y₁, …, yₙ (to at least 4 decimal places).'),
      L('Formulaga qo‘ying: koeffitsiyentlarni (1/2 yoki 4, 2) to‘g‘ri joylashtiring.', 'Подставьте в формулу, правильно расставив коэффициенты (1/2 или 4, 2).', 'Substitute into the formula, placing the coefficients (1/2 or 4, 2) correctly.'),
      L('Aniqlikni tekshiring: n ni ikki marta oshirib qayta hisoblang; natijalar yaqin bo‘lsa, javobga ishonish mumkin.', 'Проверьте точность: пересчитайте с удвоенным n; если результаты близки, ответу можно доверять.', 'Check the accuracy: recompute with n doubled; if the results agree, the answer can be trusted.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar: usullarni solishtirish', 'Решённые примеры: сравнение методов', 'Solved examples: comparing methods'), ex: [
      { q: L('∫₀² x² dx ni n = 2 da turli usullar bilan hisoblang (aniq qiymat 8/3 ≈ 2,667).', 'Вычислите ∫₀² x² dx при n = 2 разными методами (точное значение 8/3 ≈ 2,667).', 'Compute ∫₀² x² dx with n = 2 by various methods (exact value 8/3 ≈ 2.667).'), s: L('h = 1, y₀ = 0, y₁ = 1, y₂ = 4. Chap: 1·(0 + 1) = 1. O‘ng: 1·(1 + 4) = 5. O‘rta: f(0,5) + f(1,5) = 0,25 + 2,25 = 2,5. Trapetsiya: 1·(0/2 + 1 + 4/2) = 3. Simpson: (1/3)(0 + 4·1 + 4) = 8/3 — aniq javob, chunki x² — ko‘phad.', 'h = 1, y₀ = 0, y₁ = 1, y₂ = 4. Левые: 1·(0 + 1) = 1. Правые: 1·(1 + 4) = 5. Средние: f(0,5) + f(1,5) = 0,25 + 2,25 = 2,5. Трапеции: 1·(0/2 + 1 + 4/2) = 3. Симпсон: (1/3)(0 + 4·1 + 4) = 8/3 — точный ответ, так как x² — многочлен.', 'h = 1, y₀ = 0, y₁ = 1, y₂ = 4. Left: 1·(0 + 1) = 1. Right: 1·(1 + 4) = 5. Midpoint: f(0.5) + f(1.5) = 0.25 + 2.25 = 2.5. Trapezium: 1·(0/2 + 1 + 4/2) = 3. Simpson: (1/3)(0 + 4·1 + 4) = 8/3 — exact, because x² is a polynomial.') },
      { q: L('Xuddi shu integralni trapetsiyalar bilan n = 4 da hisoblang.', 'Вычислите тот же интеграл трапециями при n = 4.', 'Compute the same integral by trapezia with n = 4.'), s: L('h = 0,5; y: 0; 0,25; 1; 2,25; 4. Natija: 0,5·(0/2 + 0,25 + 1 + 2,25 + 4/2) = 0,5·5,5 = 2,75. Xatolik 3 − 8/3 ≈ 0,333 dan 2,75 − 8/3 ≈ 0,083 ga tushdi — aniq 4 marta kamaydi, chunki xatolik h² ga proporsional.', 'h = 0,5; y: 0; 0,25; 1; 2,25; 4. Результат: 0,5·(0/2 + 0,25 + 1 + 2,25 + 4/2) = 0,5·5,5 = 2,75. Погрешность упала с 3 − 8/3 ≈ 0,333 до 2,75 − 8/3 ≈ 0,083 — ровно в 4 раза, так как она пропорциональна h².', 'h = 0.5; y: 0; 0.25; 1; 2.25; 4. Result: 0.5·(0/2 + 0.25 + 1 + 2.25 + 4/2) = 0.5·5.5 = 2.75. The error dropped from 3 − 8/3 ≈ 0.333 to 2.75 − 8/3 ≈ 0.083 — exactly 4 times, because it is proportional to h².') },
      { q: L('ln 2 = ∫₁² dx/x ni n = 4 da trapetsiyalar va Simpson bilan hisoblang (ln 2 ≈ 0,693147).', 'Вычислите ln 2 = ∫₁² dx/x при n = 4 трапециями и Симпсоном (ln 2 ≈ 0,693147).', 'Compute ln 2 = ∫₁² dx/x with n = 4 by trapezia and by Simpson (ln 2 ≈ 0.693147).'), s: L('h = 0,25; y = 1; 0,8; 0,666667; 0,571429; 0,5. Trapetsiya: 0,25·(0,75 + 0,8 + 0,666667 + 0,571429) = 0,25·2,788095 ≈ 0,697024 (xato ≈ 0,0039). Simpson: (0,25/3)(1 + 4·0,8 + 2·0,666667 + 4·0,571429 + 0,5) = (0,25/3)·8,319048 ≈ 0,693254 (xato ≈ 0,0001). Simpson taxminan 36 marta aniqroq!', 'h = 0,25; y = 1; 0,8; 0,666667; 0,571429; 0,5. Трапеции: 0,25·(0,75 + 0,8 + 0,666667 + 0,571429) = 0,25·2,788095 ≈ 0,697024 (ошибка ≈ 0,0039). Симпсон: (0,25/3)(1 + 4·0,8 + 2·0,666667 + 4·0,571429 + 0,5) = (0,25/3)·8,319048 ≈ 0,693254 (ошибка ≈ 0,0001). Симпсон примерно в 36 раз точнее!', 'h = 0.25; y = 1; 0.8; 0.666667; 0.571429; 0.5. Trapezium: 0.25·(0.75 + 0.8 + 0.666667 + 0.571429) = 0.25·2.788095 ≈ 0.697024 (error ≈ 0.0039). Simpson: (0.25/3)(1 + 4·0.8 + 2·0.666667 + 4·0.571429 + 0.5) = (0.25/3)·8.319048 ≈ 0.693254 (error ≈ 0.0001). Simpson is about 36 times more accurate!') }
    ] },
    { kind: 'example', h: L('Formulasiz integrallar va jadval ma’lumotlari', 'Интегралы без формулы и табличные данные', 'Integrals without a formula and tabulated data'), ex: [
      { q: L('∫₀¹ e<sup>−x²</sup> dx ni n = 2 da trapetsiyalar va Simpson bilan baholang (aniq qiymat ≈ 0,746824).', 'Оцените ∫₀¹ e<sup>−x²</sup> dx при n = 2 трапециями и Симпсоном (точное значение ≈ 0,746824).', 'Estimate ∫₀¹ e<sup>−x²</sup> dx with n = 2 by trapezia and Simpson (exact ≈ 0.746824).'), s: L('h = 0,5; y₀ = 1, y₁ = e<sup>−0,25</sup> ≈ 0,778801, y₂ = e<sup>−1</sup> ≈ 0,367879. Trapetsiya: 0,5·(0,683940 + 0,778801) ≈ 0,731370. Simpson: (0,5/3)(1 + 3,115203 + 0,367879) ≈ 0,747180. Atigi uchta qiymat bilan Simpson 3 xona aniqlik berdi.', 'h = 0,5; y₀ = 1, y₁ = e<sup>−0,25</sup> ≈ 0,778801, y₂ = e<sup>−1</sup> ≈ 0,367879. Трапеции: 0,5·(0,683940 + 0,778801) ≈ 0,731370. Симпсон: (0,5/3)(1 + 3,115203 + 0,367879) ≈ 0,747180. Всего по трём значениям Симпсон дал 3 верных знака.', 'h = 0.5; y₀ = 1, y₁ = e<sup>−0.25</sup> ≈ 0.778801, y₂ = e<sup>−1</sup> ≈ 0.367879. Trapezium: 0.5·(0.683940 + 0.778801) ≈ 0.731370. Simpson: (0.5/3)(1 + 3.115203 + 0.367879) ≈ 0.747180. With only three values Simpson gave 3 correct decimals.') },
      { q: L('Ariq bo‘yidagi uchastkaning kengligi har 10 m da o‘lchangan: 6, 9, 11, 10, 7 m. Maydonni toping.', 'Ширину участка вдоль арыка измерили через каждые 10 м: 6, 9, 11, 10, 7 м. Найдите площадь.', 'The width of a plot along a canal was measured every 10 m: 6, 9, 11, 10, 7 m. Find its area.'), s: L('h = 10, n = 4. Trapetsiya: 10·((6 + 7)/2 + 9 + 11 + 10) = 10·36,5 = 365 m². Simpson: (10/3)(6 + 4·9 + 2·11 + 4·10 + 7) = (10/3)·111 = 370 m². Formula yo‘q — faqat o‘lchovlar, lekin javob bor.', 'h = 10, n = 4. Трапеции: 10·((6 + 7)/2 + 9 + 11 + 10) = 10·36,5 = 365 м². Симпсон: (10/3)(6 + 4·9 + 2·11 + 4·10 + 7) = (10/3)·111 = 370 м². Формулы нет — только измерения, но ответ есть.', 'h = 10, n = 4. Trapezium: 10·((6 + 7)/2 + 9 + 11 + 10) = 10·36.5 = 365 m². Simpson: (10/3)(6 + 4·9 + 2·11 + 4·10 + 7) = (10/3)·111 = 370 m². No formula — only measurements, yet we have an answer.') },
      { q: L('[0; 1] da ∫ x² dx ni trapetsiyalar bilan 0,001 aniqlikda hisoblash uchun qancha bo‘lak kerak?', 'Сколько частей нужно, чтобы вычислить ∫₀¹ x² dx трапециями с точностью 0,001?', 'How many parts are needed to compute ∫₀¹ x² dx by trapezia to within 0.001?'), s: L('f″ = 2, M₂ = 2. |E| ≤ 1·h²·2/12 = h²/6 ≤ 0,001 → h² ≤ 0,006 → h ≤ 0,0775. h = 1/n bo‘lgani uchun n ≥ 12,9, ya’ni n = 13 yetarli.', 'f″ = 2, M₂ = 2. |E| ≤ 1·h²·2/12 = h²/6 ≤ 0,001 → h² ≤ 0,006 → h ≤ 0,0775. Так как h = 1/n, n ≥ 12,9, то есть достаточно n = 13.', 'f″ = 2, M₂ = 2. |E| ≤ 1·h²·2/12 = h²/6 ≤ 0.001, so h² ≤ 0.006 and h ≤ 0.0775. Since h = 1/n, n ≥ 12.9, so n = 13 is enough.') }
    ] },
    { kind: 'table', h: L('Usullarni taqqoslash', 'Сравнение методов', 'Comparison of methods'), table: { head: [L('Usul', 'Метод', 'Method'), L('Almashtirish', 'Замена', 'Replacement'), L('Xatolik tartibi', 'Порядок погрешности', 'Error order'), L('n×2 da xato', 'Ошибка при n×2', 'Error when n×2')], rows: [
      [L('Chap / o‘ng to‘rtburchak', 'Левые / правые прямоугольники', 'Left / right rectangles'), L('gorizontal kesma', 'горизонтальный отрезок', 'horizontal segment'), S('h'), L('≈ 2 marta kam', '≈ в 2 раза меньше', '≈ 2 times smaller')],
      [L('O‘rta to‘rtburchak', 'Средние прямоугольники', 'Midpoint rectangles'), L('o‘rtadagi qiymat', 'значение в середине', 'value at the middle'), S('h²'), L('≈ 4 marta kam', '≈ в 4 раза меньше', '≈ 4 times smaller')],
      [L('Trapetsiyalar', 'Трапеции', 'Trapezia'), L('vatar', 'хорда', 'chord'), S('h²'), L('≈ 4 marta kam', '≈ в 4 раза меньше', '≈ 4 times smaller')],
      [L('Simpson', 'Симпсон', 'Simpson'), L('parabola', 'парабола', 'parabola'), S('h⁴'), L('≈ 16 marta kam', '≈ в 16 раз меньше', '≈ 16 times smaller')]
    ] }, after: [
      L('Qiziq: o‘rta to‘rtburchaklar xatoligi trapetsiyalar xatoligidan taxminan 2 marta kichik va qarama-qarshi ishorali. Simpson formulasi aslida ularning «og‘irlikli o‘rtachasi»: n bo‘lakli o‘rta va trapetsiya natijalaridan 2n bo‘lakli Simpson chiqadi: S = (2·O‘rta + Trapetsiya)/3.', 'Интересно: погрешность средних прямоугольников примерно вдвое меньше погрешности трапеций и противоположна по знаку. Формула Симпсона — по сути их «взвешенное среднее»: из средних и трапеций на n частях получается Симпсон на 2n частях: S = (2·Средние + Трапеции)/3.', 'Interesting: the midpoint error is about half the trapezium error and of opposite sign. Simpson’s rule is in fact their “weighted average”: the midpoint and trapezium results on n parts give Simpson on 2n parts: S = (2·Midpoint + Trapezium)/3.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Trapetsiya formulasida chetki qiymatlarni yarmiga bo‘lmaslik.</b> Faqat y₀ va yₙ yarim og‘irlikka ega, ichki qiymatlar to‘liq.', '<b>Не делить крайние значения пополам в формуле трапеций.</b> Только y₀ и yₙ имеют половинный вес, внутренние — полный.', '<b>Not halving the end values in the trapezium rule.</b> Only y₀ and yₙ have half weight; the inner values have full weight.'),
      L('<b>Simpson formulasini toq n bilan qo‘llash.</b> Parabolalar juft-juft bo‘laklarga quriladi, shuning uchun n juft bo‘lishi shart.', '<b>Применять формулу Симпсона с нечётным n.</b> Параболы строятся на парах частей, поэтому n обязано быть чётным.', '<b>Using Simpson’s rule with odd n.</b> Parabolas are built on pairs of parts, so n must be even.'),
      L('<b>Simpsonda koeffitsiyentlarni chalkashtirish.</b> Ketma-ketlik doim 1, 4, 2, 4, 2, …, 4, 1 va oldida h/3 turadi (h/2 emas).', '<b>Путать коэффициенты Симпсона.</b> Последовательность всегда 1, 4, 2, 4, 2, …, 4, 1, а впереди h/3 (не h/2).', '<b>Mixing up Simpson’s coefficients.</b> The pattern is always 1, 4, 2, 4, 2, …, 4, 1 with h/3 in front (not h/2).'),
      L('<b>Oraliq natijalarni haddan tashqari yaxlitlash.</b> yᵢ ni 1–2 xonagacha yaxlitlash usulning aniqligini butunlay yo‘qqa chiqaradi.', '<b>Слишком сильно округлять промежуточные результаты.</b> Округление yᵢ до 1–2 знаков сводит на нет точность метода.', '<b>Rounding intermediate results too much.</b> Rounding yᵢ to 1–2 decimals destroys the accuracy of the method.'),
      L('<b>Qadamni noto‘g‘ri topish:</b> h = (b − a)/n, tugunlar soni esa n + 1. 4 ta bo‘lak — 5 ta qiymat.', '<b>Неверно найти шаг:</b> h = (b − a)/n, а число узлов n + 1. 4 части — 5 значений.', '<b>Getting the step wrong:</b> h = (b − a)/n, while the number of nodes is n + 1. Four parts mean five values.')
    ] },
    { kind: 'life', h: L('Hayotda taqribiy integrallash', 'Приближённое интегрирование в жизни', 'Approximate integration in real life'), p: [
      L('<b>Kompyuterlar va texnika.</b> Kalkulyatordagi ∫ tugmasi, Excel, Python yoki MATLAB integralni aynan sonli usullar (ko‘pincha Gauss–Kronrod yoki adaptiv Simpson) bilan hisoblaydi. Avtomobil navigatori va fitnes-braslet tezlanish datchigidan kelgan sonlarni har soniyada trapetsiyalar usuli bilan integrallab, tezlik va masofani baholaydi.', '<b>Компьютеры и техника.</b> Кнопка ∫ на калькуляторе, Excel, Python или MATLAB вычисляют интегралы именно численными методами (часто Гаусса–Кронрода или адаптивным Симпсоном). Навигатор и фитнес-браслет каждую секунду интегрируют числа от датчика ускорения методом трапеций, оценивая скорость и расстояние.', '<b>Computers and devices.</b> The ∫ key on a calculator, Excel, Python or MATLAB evaluate integrals with exactly these numerical methods (often Gauss–Kronrod or adaptive Simpson). A car navigator or fitness band integrates numbers from an accelerometer every second with the trapezium rule to estimate speed and distance.'),
      L('<b>Muhandislik va tabiat.</b> Kemasozlikda korpusning suv ostidagi hajmi chizmadagi kesimlar bo‘yicha Simpson qoidasi bilan hisoblanadi — dengizchilar uni «Simpson qoidalari» deb atashadi. Gidrologlar daryo chuqurligini bir necha nuqtada o‘lchab, ko‘ndalang kesim yuzini va suv sarfini topadi. Tibbiyotda yurak ultratovushida qorincha hajmi ham kesimlar bo‘yicha taqribiy integral bilan baholanadi.', '<b>Инженерия и природа.</b> В кораблестроении подводный объём корпуса вычисляют по сечениям на чертеже правилом Симпсона — моряки так и говорят: «правила Симпсона». Гидрологи, измерив глубину реки в нескольких точках, находят площадь поперечного сечения и расход воды. В медицине при УЗИ сердца объём желудочка тоже оценивают приближённым интегралом по сечениям.', '<b>Engineering and nature.</b> In shipbuilding the underwater volume of a hull is computed from drawing sections by Simpson’s rule — naval architects literally call them “Simpson’s rules”. Hydrologists measure a river’s depth at several points to find the cross-section area and the water discharge. In medicine, heart ultrasound estimates ventricle volume by an approximate integral over slices.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('∫₀⁴ x dx ni trapetsiyalar bilan n = 4 da hisoblang. Nega javob aniq chiqadi?', 'Вычислите ∫₀⁴ x dx трапециями при n = 4. Почему ответ точный?', 'Compute ∫₀⁴ x dx by trapezia with n = 4. Why is the answer exact?'),
      L('∫₀² x³ dx ni Simpson bilan n = 2 da hisoblang.', 'Вычислите ∫₀² x³ dx по Симпсону при n = 2.', 'Compute ∫₀² x³ dx by Simpson with n = 2.'),
      L('Trapetsiyalar bilan n = 10 da xato 0,02 bo‘ldi. n = 20 da taxminan qancha bo‘ladi?', 'Трапециями при n = 10 ошибка 0,02. Какой она будет примерно при n = 20?', 'With trapezia and n = 10 the error was 0.02. About what will it be with n = 20?')
    ], after: [
      L('Javoblar: 1·(0 + 1 + 2 + 3 + 2) = 8 — chiziqli funksiya uchun vatar grafikning o‘zi; (1/3)(0 + 4·1 + 8) = 4 — aniq; ≈ 0,005 (4 marta kam).', 'Ответы: 1·(0 + 1 + 2 + 3 + 2) = 8 — для линейной функции хорда совпадает с графиком; (1/3)(0 + 4·1 + 8) = 4 — точно; ≈ 0,005 (в 4 раза меньше).', 'Answers: 1·(0 + 1 + 2 + 3 + 2) = 8 — for a linear function the chord is the graph itself; (1/3)(0 + 4·1 + 8) = 4 — exact; ≈ 0.005 (4 times smaller).')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Boshlang‘ich topilmasa yoki funksiya jadval bilan berilsa, integral taqribiy hisoblanadi.', 'Если первообразной нет или функция задана таблицей, интеграл считают приближённо.', 'If there is no antiderivative or the function is tabulated, the integral is computed approximately.'),
      L('h = (b − a)/n, tugunlar x₀ = a, …, xₙ = b.', 'h = (b − a)/n, узлы x₀ = a, …, xₙ = b.', 'h = (b − a)/n, nodes x₀ = a, …, xₙ = b.'),
      L('Trapetsiyalar: h((y₀ + yₙ)/2 + y₁ + … + yₙ₋₁), xatolik ~ h².', 'Трапеции: h((y₀ + yₙ)/2 + y₁ + … + yₙ₋₁), погрешность ~ h².', 'Trapezia: h((y₀ + yₙ)/2 + y₁ + … + yₙ₋₁), error ~ h².'),
      L('Simpson: (h/3)(y₀ + 4y₁ + 2y₂ + … + 4yₙ₋₁ + yₙ), n juft, xatolik ~ h⁴.', 'Симпсон: (h/3)(y₀ + 4y₁ + 2y₂ + … + 4yₙ₋₁ + yₙ), n чётно, погрешность ~ h⁴.', 'Simpson: (h/3)(y₀ + 4y₁ + 2y₂ + … + 4yₙ₋₁ + yₙ), n even, error ~ h⁴.'),
      L('Simpson 3-darajagacha ko‘phadlar uchun aniq.', 'Симпсон точен для многочленов до 3-й степени.', 'Simpson is exact for polynomials up to degree 3.'),
      L('Aniqlikni n ni ikki marta oshirib tekshiring.', 'Проверяйте точность удвоением n.', 'Check the accuracy by doubling n.')
    ] }
  ] });

  // ---------- t15. Kombinatorika masalalari ----------
  T.add(P, 't15', { sections: [
    { kind: 'intro', h: L('Sanamasdan sanash san’ati', 'Искусство считать, не перебирая', 'The art of counting without listing'), p: [
      L('Telefoningizdagi 4 xonali PIN-kodni nechta usulda tanlash mumkin? Futbol jamoasidan sardor va uning o‘rinbosarini-chi? 45 ta sondan 6 tasini tanlaydigan lotereyada nechta chipta bor? Bu savollarga barcha variantlarni yozib chiqib javob berish deyarli imkonsiz — lotereyada variantlar 8 milliondan oshadi. <b>Kombinatorika</b> — to‘plamlarni ro‘yxatga olmasdan, ularning elementlari sonini hisoblash haqidagi fan.', 'Сколькими способами можно выбрать 4-значный PIN-код телефона? А капитана и его заместителя из футбольной команды? Сколько билетов в лотерее, где выбирают 6 чисел из 45? Ответить, выписав все варианты, почти невозможно — в лотерее их больше 8 миллионов. <b>Комбинаторика</b> — наука о том, как подсчитать число элементов множества, не перечисляя их.', 'In how many ways can you choose a 4-digit phone PIN? A captain and vice-captain from a football team? How many tickets exist in a lottery where you pick 6 numbers out of 45? Answering by listing every option is almost impossible — the lottery has over 8 million. <b>Combinatorics</b> is the science of counting the elements of a set without listing them.'),
      L('Kombinatorika — ehtimollar nazariyasining poydevori: biror hodisaning ehtimolini topish uchun avval qulay va barcha natijalarni sanash kerak. Shuningdek, u informatikada (algoritmlar murakkabligi, parollar xavfsizligi), kimyoda (izomerlar soni) va genetikada keng qo‘llanadi.', 'Комбинаторика — фундамент теории вероятностей: чтобы найти вероятность события, сначала нужно сосчитать благоприятные и все исходы. Кроме того, она широко применяется в информатике (сложность алгоритмов, стойкость паролей), химии (число изомеров) и генетике.', 'Combinatorics is the foundation of probability theory: to find the probability of an event you first have to count the favourable and all outcomes. It is also widely used in computer science (algorithm complexity, password strength), chemistry (numbers of isomers) and genetics.')
    ] },
    { kind: 'def', h: L('Yig‘indi va ko‘paytma qoidalari', 'Правила суммы и произведения', 'The sum and product rules'), p: [
      L('<b>Yig‘indi qoidasi.</b> Agar A ob’ektni m usulda, B ob’ektni n usulda tanlash mumkin bo‘lsa va bu tanlovlar bir-birini istisno qilsa, «A yoki B» ni m + n usulda tanlash mumkin. Masalan, oshxonada 4 xil sho‘rva va 3 xil salat bo‘lsa, birinchi taom sifatida bitta narsa tanlashning 4 + 3 = 7 usuli bor.', '<b>Правило суммы.</b> Если объект A можно выбрать m способами, объект B — n способами и эти выборы взаимно исключают друг друга, то «A или B» можно выбрать m + n способами. Например, если в столовой 4 вида супа и 3 вида салата, выбрать одно первое блюдо можно 4 + 3 = 7 способами.', '<b>Sum rule.</b> If object A can be chosen in m ways and object B in n ways, and these choices exclude each other, then “A or B” can be chosen in m + n ways. For example, with 4 soups and 3 salads in a canteen, there are 4 + 3 = 7 ways to choose one starter.'),
      L('<b>Ko‘paytma qoidasi.</b> Agar birinchi tanlovni m usulda, undan keyin (har qanday birinchi tanlovda) ikkinchisini n usulda qilish mumkin bo‘lsa, ikkala tanlov juftini m·n usulda qilish mumkin. 4 sho‘rva va 3 salatdan to‘liq tushlik: 4·3 = 12 usul. Qoida istalgan sondagi bosqichlarga umumlashadi: 3 ta ko‘ylak, 2 ta shim va 4 ta poyabzal — 3·2·4 = 24 xil kiyinish. Bu qoidani «variantlar daraxti» bilan tasavvur qilish qulay: har bir shoxdan bir xil sondagi shoxchalar chiqadi.', '<b>Правило произведения.</b> Если первый выбор можно сделать m способами, а затем (при любом первом выборе) второй — n способами, то пару выборов можно сделать m·n способами. Полный обед из 4 супов и 3 салатов: 4·3 = 12 способов. Правило обобщается на любое число шагов: 3 рубашки, 2 брюк и 4 пары обуви — 3·2·4 = 24 варианта. Удобно представлять «деревом вариантов»: из каждой ветки выходит одинаковое число веточек.', '<b>Product rule.</b> If the first choice can be made in m ways and then (for any first choice) the second in n ways, the pair of choices can be made in m·n ways. A full lunch from 4 soups and 3 salads: 4·3 = 12 ways. The rule extends to any number of steps: 3 shirts, 2 trousers and 4 pairs of shoes give 3·2·4 = 24 outfits. It helps to picture a “tree of options”: every branch splits into the same number of twigs.')
    ] },
    { kind: 'history', h: L('Hindistondan Paskalgacha', 'От Индии до Паскаля', 'From India to Pascal'), p: [
      L('Kombinatorik masalalar juda qadimiy. Miloddan avvalgi VI asrga oid hind tibbiyot risolasi «Sushruta samhita»da 6 ta asosiy ta’mdan (shirin, nordon, sho‘r, achchiq, taxir, burishtiruvchi) 63 xil birikma tuzish mumkinligi aytilgan: 2⁶ − 1 = 63. Hind olimi Pingala she’r vaznlarini sanashda bugungi Paskal uchburchagiga yaqin jadvaldan foydalangan. X–XII asrlarda al-Karajiy va Umar Xayyom binomial koeffitsiyentlar bilan ishlagan.', 'Комбинаторные задачи очень древние. В индийском медицинском трактате «Сушрута-самхита» (VI в. до н. э.) говорится, что из 6 основных вкусов (сладкий, кислый, солёный, острый, горький, вяжущий) можно составить 63 сочетания: 2⁶ − 1 = 63. Индийский учёный Пингала, считая стихотворные размеры, пользовался таблицей, близкой к треугольнику Паскаля. В X–XII веках с биномиальными коэффициентами работали аль-Караджи и Омар Хайям.', 'Combinatorial problems are very old. The Indian medical treatise “Sushruta Samhita” (6th century BC) says that 63 combinations can be made from 6 basic tastes (sweet, sour, salty, pungent, bitter, astringent): 2⁶ − 1 = 63. The Indian scholar Pingala, counting poetic metres, used a table close to Pascal’s triangle. In the 10th–12th centuries al-Karaji and Omar Khayyam worked with binomial coefficients.'),
      L('Yevropada kombinatorika qimor o‘yinlari bilan bog‘liq savollardan rivojlandi. 1654-yilda <b>Blez Paskal</b> va <b>Pyer Ferma</b> yozishmalarida ehtimollar nazariyasi va kombinatorikaning asoslari qo‘yildi. 1666-yilda 20 yoshli Leybnits «Kombinatorika san’ati haqida» dissertatsiyasini yozdi va «kombinatorika» atamasini fanga kiritdi. 1713-yilda Yakob Bernullining «Taxminlar san’ati» asarida o‘rin almashtirish va guruhlashlar nazariyasi tizimli bayon qilindi.', 'В Европе комбинаторика развивалась из вопросов об азартных играх. В 1654 году в переписке <b>Блеза Паскаля</b> и <b>Пьера Ферма</b> были заложены основы теории вероятностей и комбинаторики. В 1666 году 20-летний Лейбниц написал диссертацию «Об искусстве комбинаторики» и ввёл сам термин. В 1713 году в труде Якоба Бернулли «Искусство предположений» была систематически изложена теория перестановок и сочетаний.', 'In Europe combinatorics grew out of questions about games of chance. In 1654 the correspondence of <b>Blaise Pascal</b> and <b>Pierre de Fermat</b> laid the foundations of probability and combinatorics. In 1666 the 20-year-old Leibniz wrote his dissertation “On the Art of Combinations” and introduced the very term. In 1713 Jacob Bernoulli’s “The Art of Conjecturing” gave a systematic theory of permutations and combinations.')
    ] },
    { kind: 'rule', h: L('O‘rin almashtirishlar va o‘rinlashtirishlar', 'Перестановки и размещения', 'Permutations and arrangements'), p: [
      L('<b>O‘rin almashtirish</b> — n ta turli elementni qatorga tizish. Birinchi o‘ringa n ta, ikkinchisiga n − 1 ta, …, oxirgisiga 1 ta element qoladi. Ko‘paytma qoidasi bo‘yicha: <b>Pₙ = n·(n − 1)·…·2·1 = n!</b> («en faktorial»). Kelishuv bo‘yicha 0! = 1. Faktorial juda tez o‘sadi: 5! = 120, 10! = 3 628 800, 20! esa 2,4·10¹⁸ dan katta.', '<b>Перестановка</b> — расположение n различных элементов в ряд. На первое место n кандидатов, на второе n − 1, …, на последнее 1. По правилу произведения: <b>Pₙ = n·(n − 1)·…·2·1 = n!</b> («эн факториал»). По соглашению 0! = 1. Факториал растёт очень быстро: 5! = 120, 10! = 3 628 800, а 20! больше 2,4·10¹⁸.', 'A <b>permutation</b> is an arrangement of n distinct elements in a row. The first place has n candidates, the second n − 1, …, the last 1. By the product rule: <b>Pₙ = n·(n − 1)·…·2·1 = n!</b> (“n factorial”). By convention 0! = 1. Factorials grow very fast: 5! = 120, 10! = 3,628,800, and 20! exceeds 2.4·10¹⁸.'),
      L('<b>O‘rinlashtirish</b> — n ta elementdan k tasini tanlab, ularni tartib bilan joylashtirish (tartib muhim!). Birinchi o‘ringa n, ikkinchisiga n − 1, …, k-o‘ringa n − k + 1 variant: <b>Aₙᵏ = n(n − 1)…(n − k + 1) = n!/(n − k)!</b>. Masalan, 8 sportchidan oltin, kumush va bronza sovrindorlari: A₈³ = 8·7·6 = 336 usul. k = n bo‘lsa, Aₙⁿ = n! = Pₙ.', '<b>Размещение</b> — выбор k элементов из n с расстановкой по порядку (порядок важен!). На первое место n вариантов, на второе n − 1, …, на k-е n − k + 1: <b>Aₙᵏ = n(n − 1)…(n − k + 1) = n!/(n − k)!</b>. Например, золото, серебро и бронза среди 8 спортсменов: A₈³ = 8·7·6 = 336 способов. При k = n Aₙⁿ = n! = Pₙ.', 'An <b>arrangement</b> (k-permutation) is a choice of k elements out of n placed in order (order matters!). The first place has n options, the second n − 1, …, the k-th n − k + 1: <b>Aₙᵏ = n(n − 1)…(n − k + 1) = n!/(n − k)!</b>. For example, gold, silver and bronze among 8 athletes: A₈³ = 8·7·6 = 336 ways. When k = n, Aₙⁿ = n! = Pₙ.')
    ] },
    { kind: 'rule', h: L('Guruhlashlar (kombinatsiyalar)', 'Сочетания', 'Combinations'), p: [
      L('<b>Guruhlash</b> — n ta elementdan k tasini tartibsiz tanlash: faqat «kim tanlandi» muhim, «qaysi tartibda» emas. Har bir k elementli guruhni k! usulda tartiblash mumkin, shuning uchun o‘rinlashtirishlar soni guruhlashlar sonidan k! marta ko‘p: Aₙᵏ = Cₙᵏ·k!. Bundan: <b>Cₙᵏ = n!/(k!(n − k)!)</b>.', '<b>Сочетание</b> — неупорядоченный выбор k элементов из n: важно лишь «кто выбран», а не «в каком порядке». Каждую группу из k элементов можно упорядочить k! способами, поэтому размещений в k! раз больше, чем сочетаний: Aₙᵏ = Cₙᵏ·k!. Отсюда: <b>Cₙᵏ = n!/(k!(n − k)!)</b>.', 'A <b>combination</b> is an unordered choice of k elements out of n: only “who is chosen” matters, not “in what order”. Each group of k elements can be ordered in k! ways, so there are k! times more arrangements than combinations: Aₙᵏ = Cₙᵏ·k!. Hence: <b>Cₙᵏ = n!/(k!(n − k)!)</b>.'),
      L('<b>Xossalari.</b> Simmetriya: Cₙᵏ = Cₙⁿ⁻ᵏ (k tasini tanlash — qolgan n − k tasini «tashlab ketish» bilan bir xil). Cₙ⁰ = Cₙⁿ = 1, Cₙ¹ = n. Paskal qoidasi: Cₙᵏ = Cₙ₋₁ᵏ⁻¹ + Cₙ₋₁ᵏ — biror elementni ajratib olsak, u yo guruhga kiradi, yo kirmaydi. Barcha qism to‘plamlar soni: Cₙ⁰ + Cₙ¹ + … + Cₙⁿ = 2ⁿ, chunki har bir element «olinadi» yoki «olinmaydi».', '<b>Свойства.</b> Симметрия: Cₙᵏ = Cₙⁿ⁻ᵏ (выбрать k — то же, что «оставить» n − k). Cₙ⁰ = Cₙⁿ = 1, Cₙ¹ = n. Правило Паскаля: Cₙᵏ = Cₙ₋₁ᵏ⁻¹ + Cₙ₋₁ᵏ — выделенный элемент либо входит в группу, либо нет. Число всех подмножеств: Cₙ⁰ + Cₙ¹ + … + Cₙⁿ = 2ⁿ, ведь каждый элемент либо «берём», либо «не берём».', '<b>Properties.</b> Symmetry: Cₙᵏ = Cₙⁿ⁻ᵏ (choosing k is the same as “leaving out” n − k). Cₙ⁰ = Cₙⁿ = 1, Cₙ¹ = n. Pascal’s rule: Cₙᵏ = Cₙ₋₁ᵏ⁻¹ + Cₙ₋₁ᵏ — a marked element is either in the group or not. The number of all subsets: Cₙ⁰ + Cₙ¹ + … + Cₙⁿ = 2ⁿ, since each element is either “taken” or “not taken”.'),
      L('<b>Takrorli tanlovlar.</b> Elementlar takrorlanishi mumkin bo‘lsa, n ta belgidan k uzunlikdagi «so‘zlar» soni nᵏ (masalan, PIN-kodlar 10⁴). Takrorlanuvchi elementli o‘rin almashtirishlar: n!/(n₁!·n₂!·…·nₖ!), bunda nᵢ — bir xil elementlar soni.', '<b>Выборки с повторениями.</b> Если элементы могут повторяться, число «слов» длины k из n символов равно nᵏ (например, PIN-кодов 10⁴). Перестановки с повторяющимися элементами: n!/(n₁!·n₂!·…·nₖ!), где nᵢ — количества одинаковых элементов.', '<b>Choices with repetition.</b> If elements may repeat, the number of “words” of length k from n symbols is nᵏ (e.g. 10⁴ PIN codes). Permutations with repeated elements: n!/(n₁!·n₂!·…·nₖ!), where nᵢ are the counts of identical elements.')
    ] },
    { kind: 'steps', h: L('Qaysi formulani tanlash kerak?', 'Какую формулу выбрать?', 'Which formula to choose?'), list: [
      L('1-savol: barcha elementlar ishtirok etadimi? Ha va tartib muhim → o‘rin almashtirish n! (takror bo‘lsa, n!/(n₁!…nₖ!)).', 'Вопрос 1: участвуют ли все элементы? Да и порядок важен → перестановки n! (при повторах n!/(n₁!…nₖ!)).', 'Question 1: are all elements used? Yes and order matters → permutations n! (with repeats n!/(n₁!…nₖ!)).'),
      L('2-savol: k tasi tanlanadimi va tartib muhimmi (o‘rinlar, lavozimlar, raqamlar ketma-ketligi)? → o‘rinlashtirish Aₙᵏ.', 'Вопрос 2: выбираем k и порядок важен (места, должности, последовательность цифр)? → размещения Aₙᵏ.', 'Question 2: choosing k and order matters (places, roles, digit sequences)? → arrangements Aₙᵏ.'),
      L('3-savol: tartib muhim emas (komissiya, guruh, qo‘ldagi kartalar)? → guruhlash Cₙᵏ.', 'Вопрос 3: порядок не важен (комиссия, группа, карты на руках)? → сочетания Cₙᵏ.', 'Question 3: order does not matter (committee, group, cards in hand)? → combinations Cₙᵏ.'),
      L('4-savol: elementlar takrorlanishi mumkinmi? → nᵏ.', 'Вопрос 4: могут ли элементы повторяться? → nᵏ.', 'Question 4: can elements repeat? → nᵏ.'),
      L('Murakkab masalani bosqichlarga bo‘ling: bosqichlar ketma-ket bo‘lsa — ko‘paytiring, alternativ hollar bo‘lsa — qo‘shing.', 'Разбейте сложную задачу на шаги: последовательные шаги — умножайте, альтернативные случаи — складывайте.', 'Break a complex problem into steps: consecutive steps — multiply; alternative cases — add.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar', 'Решённые примеры', 'Solved examples'), ex: [
      { q: L('Javonga 5 ta turli kitobni necha usulda terish mumkin?', 'Сколькими способами можно расставить на полке 5 разных книг?', 'In how many ways can 5 different books be placed on a shelf?'), s: L('Barcha kitoblar, tartib muhim: P₅ = 5! = 120.', 'Все книги, порядок важен: P₅ = 5! = 120.', 'All books, order matters: P₅ = 5! = 120.') },
      { q: L('25 o‘quvchili sinfda sardor, uning o‘rinbosari va kotibni necha usulda saylash mumkin? Uch kishilik komissiyani-chi?', 'Сколькими способами в классе из 25 учеников можно выбрать старосту, заместителя и секретаря? А комиссию из трёх человек?', 'In how many ways can a class of 25 elect a head, a deputy and a secretary? And a three-person committee?'), s: L('Lavozimlar turli — tartib muhim: A₂₅³ = 25·24·23 = 13 800. Komissiyada lavozim yo‘q — tartib muhim emas: C₂₅³ = 13 800/3! = 13 800/6 = 2300.', 'Должности разные — порядок важен: A₂₅³ = 25·24·23 = 13 800. В комиссии должностей нет — порядок не важен: C₂₅³ = 13 800/3! = 13 800/6 = 2300.', 'The roles differ, so order matters: A₂₅³ = 25·24·23 = 13,800. A committee has no roles, so order does not matter: C₂₅³ = 13,800/3! = 13,800/6 = 2300.') },
      { q: L('«MATEMATIKA» so‘zi harflaridan nechta turli harflar ketma-ketligi tuzish mumkin?', 'Сколько различных последовательностей можно составить из букв слова «MATEMATIKA»?', 'How many different letter sequences can be made from the letters of “MATEMATIKA”?'), s: L('10 ta harf: M — 2 marta, A — 3 marta, T — 2 marta, E, I, K — bittadan. 10!/(2!·3!·2!) = 3 628 800/24 = 151 200.', '10 букв: M — 2 раза, A — 3 раза, T — 2 раза, E, I, K — по одной. 10!/(2!·3!·2!) = 3 628 800/24 = 151 200.', '10 letters: M twice, A three times, T twice, E, I, K once each. 10!/(2!·3!·2!) = 3,628,800/24 = 151,200.') },
      { q: L('6 o‘g‘il va 4 qiz bor. 3 o‘g‘il va 2 qizdan iborat guruhni necha usulda tuzish mumkin?', 'Есть 6 мальчиков и 4 девочки. Сколькими способами можно составить группу из 3 мальчиков и 2 девочек?', 'There are 6 boys and 4 girls. In how many ways can a group of 3 boys and 2 girls be formed?'), s: L('O‘g‘illar: C₆³ = 20, qizlar: C₄² = 6. Ikki tanlov ketma-ket — ko‘paytma qoidasi: 20·6 = 120.', 'Мальчики: C₆³ = 20, девочки: C₄² = 6. Два выбора подряд — правило произведения: 20·6 = 120.', 'Boys: C₆³ = 20, girls: C₄² = 6. Two consecutive choices — product rule: 20·6 = 120.') }
    ] },
    { kind: 'example', h: L('Yana misollar: raqamlar, lotereya, tenglamalar', 'Ещё примеры: цифры, лотерея, уравнения', 'More examples: digits, lottery, equations'), ex: [
      { q: L('Nechta 4 xonali PIN-kod bor? Raqamlari turlicha bo‘lganlari nechta?', 'Сколько существует 4-значных PIN-кодов? Сколько из них с различными цифрами?', 'How many 4-digit PIN codes are there? How many have all different digits?'), s: L('Takror mumkin: 10⁴ = 10 000. Takrorsiz: A₁₀⁴ = 10·9·8·7 = 5040.', 'С повторами: 10⁴ = 10 000. Без повторов: A₁₀⁴ = 10·9·8·7 = 5040.', 'With repetition: 10⁴ = 10,000. Without: A₁₀⁴ = 10·9·8·7 = 5040.') },
      { q: L('0, 1, 2, 3, 4 raqamlaridan raqamlari takrorlanmaydigan nechta uch xonali son tuzish mumkin?', 'Сколько трёхзначных чисел с неповторяющимися цифрами можно составить из цифр 0, 1, 2, 3, 4?', 'How many three-digit numbers with distinct digits can be made from 0, 1, 2, 3, 4?'), s: L('Birinchi raqam 0 bo‘lmaydi: 4 variant. Ikkinchisi — qolgan 4 tadan (endi 0 ham mumkin), uchinchisi — 3 tadan. 4·4·3 = 48. (A₅³ − A₄² = 60 − 12 = 48 bilan tekshiring.)', 'Первая цифра не 0: 4 варианта. Вторая — из оставшихся 4 (теперь можно и 0), третья — из 3. 4·4·3 = 48. (Проверка: A₅³ − A₄² = 60 − 12 = 48.)', 'The first digit cannot be 0: 4 options. The second from the remaining 4 (now 0 is allowed), the third from 3. 4·4·3 = 48. (Check: A₅³ − A₄² = 60 − 12 = 48.)') },
      { q: L('«6 dan 45» lotereyasida nechta turli chipta bor?', 'Сколько разных билетов в лотерее «6 из 45»?', 'How many different tickets exist in a “6 out of 45” lottery?'), s: L('Tartib muhim emas: C₄₅⁶ = 45·44·43·42·41·40/720 = 8 145 060. Bitta chipta bilan yutish ehtimoli — 8 milliondan bir.', 'Порядок не важен: C₄₅⁶ = 45·44·43·42·41·40/720 = 8 145 060. Вероятность выигрыша с одним билетом — один из 8 миллионов.', 'Order does not matter: C₄₅⁶ = 45·44·43·42·41·40/720 = 8,145,060. The chance of winning with one ticket is one in 8 million.') },
      { q: L('Cₙ² = 28 tenglamani yeching.', 'Решите уравнение Cₙ² = 28.', 'Solve Cₙ² = 28.'), s: L('n(n − 1)/2 = 28 → n² − n − 56 = 0 → n = 8 (n = −7 mos emas). Ma’nosi: 8 kishi o‘zaro qo‘l berib ko‘rishsa, 28 ta qo‘l siqish bo‘ladi.', 'n(n − 1)/2 = 28 → n² − n − 56 = 0 → n = 8 (n = −7 не подходит). Смысл: если 8 человек пожмут друг другу руки, будет 28 рукопожатий.', 'n(n − 1)/2 = 28 gives n² − n − 56 = 0, so n = 8 (n = −7 is rejected). Meaning: if 8 people all shake hands, there are 28 handshakes.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Tartib muhimmi — buni aniqlamaslik.</b> «Uch kishini tanlang» va «uch kishini 1-, 2-, 3-o‘ringa tanlang» — turli masalalar (2300 va 13 800).', '<b>Не определить, важен ли порядок.</b> «Выбрать трёх человек» и «выбрать трёх на 1-е, 2-е, 3-е места» — разные задачи (2300 и 13 800).', '<b>Not deciding whether order matters.</b> “Choose three people” and “choose three people for 1st, 2nd, 3rd place” are different problems (2300 vs 13,800).'),
      L('<b>Yig‘indi va ko‘paytma qoidalarini chalkashtirish.</b> «Va» (ketma-ket bosqichlar) — ko‘paytirish, «yoki» (alternativ hollar) — qo‘shish.', '<b>Путать правила суммы и произведения.</b> «И» (последовательные шаги) — умножать, «или» (альтернативные случаи) — складывать.', '<b>Confusing the sum and product rules.</b> “And” (consecutive steps) — multiply; “or” (alternative cases) — add.'),
      L('<b>Sonlarda boshlang‘ich nolni hisobga olmaslik.</b> «0123» uch xonali son emas.', '<b>Не учитывать ведущий ноль в числах.</b> «0123» — не четырёхзначное число.', '<b>Ignoring a leading zero.</b> “0123” is not a four-digit number.'),
      L('<b>Takroriy elementlarni e’tiborsiz qoldirish.</b> «AAB» harflaridan 3! = 6 emas, 3!/2! = 3 so‘z chiqadi.', '<b>Игнорировать повторяющиеся элементы.</b> Из букв «AAB» получается не 3! = 6, а 3!/2! = 3 слова.', '<b>Ignoring repeated elements.</b> The letters “AAB” give not 3! = 6 but 3!/2! = 3 words.'),
      L('<b>Faktoriallarni noto‘g‘ri qisqartirish.</b> 10!/8! = 10·9 = 90, (10/8)! emas. 0! = 1, nol emas.', '<b>Неверно сокращать факториалы.</b> 10!/8! = 10·9 = 90, а не (10/8)!. 0! = 1, а не 0.', '<b>Cancelling factorials wrongly.</b> 10!/8! = 10·9 = 90, not (10/8)!. And 0! = 1, not 0.')
    ] },
    { kind: 'life', h: L('Kombinatorika hayotda', 'Комбинаторика в жизни', 'Combinatorics in real life'), p: [
      L('<b>Xavfsizlik.</b> 8 belgili parol faqat kichik lotin harflaridan iborat bo‘lsa, 26⁸ ≈ 2·10¹¹ variant; katta harflar, raqamlar va belgilar qo‘shilsa (≈ 94 belgi), 94⁸ ≈ 6·10¹⁵ — ya’ni 30 ming baravar ko‘p. Shuning uchun murakkab parol buzib kirishni qiyinlashtiradi. <b>Genetika.</b> DNKdagi 4 ta nukleotiddan 3 tadan tuzilgan kodonlar soni 4³ = 64 — ular 20 ta aminokislotani kodlaydi.', '<b>Безопасность.</b> Если 8-символьный пароль состоит только из строчных латинских букв, вариантов 26⁸ ≈ 2·10¹¹; с заглавными, цифрами и знаками (≈ 94 символа) — 94⁸ ≈ 6·10¹⁵, то есть в 30 тысяч раз больше. Поэтому сложный пароль затрудняет взлом. <b>Генетика.</b> Число кодонов из 3 нуклеотидов при 4 видах нуклеотидов ДНК — 4³ = 64; они кодируют 20 аминокислот.', '<b>Security.</b> An 8-character password of lowercase Latin letters only has 26⁸ ≈ 2·10¹¹ variants; with capitals, digits and symbols (≈ 94 characters) it has 94⁸ ≈ 6·10¹⁵ — 30 thousand times more. That is why a complex password is harder to crack. <b>Genetics.</b> With 4 kinds of DNA nucleotides, the number of 3-letter codons is 4³ = 64; they code for 20 amino acids.'),
      L('<b>Logistika va sport.</b> Kuryer 10 ta manzilga borishi kerak bo‘lsa, marshrutlar soni 10! = 3 628 800 — eng qisqasini topish uchun maxsus algoritmlar kerak («kommivoyajer masalasi»). 16 jamoali turnirda har kim har kim bilan bir martadan o‘ynasa, C₁₆² = 120 o‘yin o‘tkaziladi. <b>Kimyo:</b> molekula izomerlari soni ham kombinatorik usullar bilan hisoblanadi.', '<b>Логистика и спорт.</b> Если курьеру нужно объехать 10 адресов, маршрутов 10! = 3 628 800 — для поиска кратчайшего нужны особые алгоритмы («задача коммивояжёра»). В турнире из 16 команд, где каждая играет с каждой по разу, проводится C₁₆² = 120 матчей. <b>Химия:</b> число изомеров молекулы тоже считают комбинаторными методами.', '<b>Logistics and sport.</b> If a courier must visit 10 addresses, there are 10! = 3,628,800 routes — finding the shortest needs special algorithms (the “travelling salesman problem”). In a 16-team round-robin tournament, C₁₆² = 120 matches are played. <b>Chemistry:</b> the number of isomers of a molecule is also counted combinatorially.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('52 ta kartali dastani aralashtirish usullari soni 52! ≈ 8·10⁶⁷. Bu shunchalik katta sonki, yaxshi aralashtirilgan har bir dasta tartibi, ehtimol, tarixda hech qachon takrorlanmagan.', 'Число способов перетасовать колоду из 52 карт 52! ≈ 8·10⁶⁷. Это так много, что порядок любой хорошо перетасованной колоды, скорее всего, никогда в истории не повторялся.', 'The number of ways to shuffle a 52-card deck is 52! ≈ 8·10⁶⁷. It is so huge that the order of any well-shuffled deck has most likely never occurred before in history.'),
      L('Rubik kubigi 43 252 003 274 489 856 000 (≈ 4,3·10¹⁹) holatga ega, lekin 2010-yilda isbotlanganki, istalgan holatdan 20 ta harakatda yechish mumkin.', 'Кубик Рубика имеет 43 252 003 274 489 856 000 (≈ 4,3·10¹⁹) состояний, но в 2010 году доказано, что из любого его можно собрать за 20 ходов.', 'A Rubik’s cube has 43,252,003,274,489,856,000 (≈ 4.3·10¹⁹) states, yet it was proved in 2010 that any of them can be solved in 20 moves.'),
      L('Shaxmatda birinchi 4 ta yurishdan (har tomondan 2 tadan) keyin 197 742 xil o‘yin (yurishlar ketma-ketligi) bo‘lishi mumkin.', 'В шахматах после первых 4 ходов (по 2 с каждой стороны) возможно 197 742 разных партии (последовательности ходов).', 'In chess, after the first 4 moves (2 by each side) there can be 197,742 different games (move sequences).')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Yig‘indi qoidasi — «yoki» (m + n), ko‘paytma qoidasi — «va» (m·n).', 'Правило суммы — «или» (m + n), правило произведения — «и» (m·n).', 'Sum rule — “or” (m + n); product rule — “and” (m·n).'),
      L('O‘rin almashtirishlar: Pₙ = n!, 0! = 1.', 'Перестановки: Pₙ = n!, 0! = 1.', 'Permutations: Pₙ = n!, 0! = 1.'),
      L('O‘rinlashtirishlar (tartib muhim): Aₙᵏ = n!/(n − k)!.', 'Размещения (порядок важен): Aₙᵏ = n!/(n − k)!.', 'Arrangements (order matters): Aₙᵏ = n!/(n − k)!.'),
      L('Guruhlashlar (tartib muhim emas): Cₙᵏ = n!/(k!(n − k)!).', 'Сочетания (порядок не важен): Cₙᵏ = n!/(k!(n − k)!).', 'Combinations (order irrelevant): Cₙᵏ = n!/(k!(n − k)!).'),
      L('Cₙᵏ = Cₙⁿ⁻ᵏ, Cₙᵏ = Cₙ₋₁ᵏ⁻¹ + Cₙ₋₁ᵏ, ΣCₙᵏ = 2ⁿ.', 'Cₙᵏ = Cₙⁿ⁻ᵏ, Cₙᵏ = Cₙ₋₁ᵏ⁻¹ + Cₙ₋₁ᵏ, ΣCₙᵏ = 2ⁿ.', 'Cₙᵏ = Cₙⁿ⁻ᵏ, Cₙᵏ = Cₙ₋₁ᵏ⁻¹ + Cₙ₋₁ᵏ, ΣCₙᵏ = 2ⁿ.'),
      L('Takrorli tanlov: nᵏ; takrorlanuvchi elementli o‘rin almashtirish: n!/(n₁!…nₖ!).', 'Выборка с повторениями: nᵏ; перестановки с повторами: n!/(n₁!…nₖ!).', 'Choice with repetition: nᵏ; permutations with repeats: n!/(n₁!…nₖ!).')
    ] }
  ] });

  // ---------- t16. Nyuton binomi ----------
  T.add(P, 't16', { sections: [
    { kind: 'intro', h: L('(a + b)¹⁰ ni qavs ochmasdan', '(a + b)¹⁰ без раскрытия скобок', '(a + b)¹⁰ without expanding brackets'), p: [
      L('(a + b)² = a² + 2ab + b² va (a + b)³ = a³ + 3a²b + 3ab² + b³ formulalarini 7-sinfdan bilasiz. (a + b)⁴ ni topish uchun (a + b)³ ni yana (a + b) ga ko‘paytirish mumkin. Ammo (a + b)¹⁰ yoki (2x − 1)²⁰ uchun bu ish soatlab cho‘ziladi va xatoga to‘la bo‘ladi. Ikki hadli ifodaning — <b>binom</b>ning — istalgan natural darajasini bir zumda yozib beradigan formula bor. U <b>Nyuton binomi</b> deyiladi.', 'Формулы (a + b)² = a² + 2ab + b² и (a + b)³ = a³ + 3a²b + 3ab² + b³ известны с 7 класса. Чтобы найти (a + b)⁴, можно умножить (a + b)³ ещё раз на (a + b). Но для (a + b)¹⁰ или (2x − 1)²⁰ эта работа займёт часы и будет полна ошибок. Есть формула, которая сразу записывает любую натуральную степень двучлена — <b>бинома</b>. Она называется <b>биномом Ньютона</b>.', 'You have known (a + b)² = a² + 2ab + b² and (a + b)³ = a³ + 3a²b + 3ab² + b³ since grade 7. To get (a + b)⁴ you could multiply (a + b)³ by (a + b) once more. But for (a + b)¹⁰ or (2x − 1)²⁰ this would take hours and be full of errors. There is a formula that writes any natural power of a two-term expression — a <b>binomial</b> — at once. It is called the <b>binomial theorem</b> (Newton’s binomial).'),
      L('Bu formulaning siri — oldingi mavzudagi guruhlashlar soni Cₙᵏ. Kombinatorika va algebra bu yerda uchrashadi: qavslarni ochish aslida «har bir qavsdan a yoki b ni tanlash» masalasidir.', 'Секрет этой формулы — числа сочетаний Cₙᵏ из предыдущей темы. Здесь встречаются комбинаторика и алгебра: раскрытие скобок — это на самом деле задача «выбрать из каждой скобки a или b».', 'The secret of this formula is the combination numbers Cₙᵏ from the previous topic. Combinatorics and algebra meet here: expanding brackets is really the problem of “choosing a or b from each bracket”.')
    ] },
    { kind: 'def', h: L('Binom formulasi va umumiy had', 'Формула бинома и общий член', 'The binomial formula and the general term'), p: [
      L('Har qanday natural n uchun: <b>(a + b)ⁿ = Cₙ⁰aⁿ + Cₙ¹aⁿ⁻¹b + Cₙ²aⁿ⁻²b² + … + Cₙᵏaⁿ⁻ᵏbᵏ + … + Cₙⁿbⁿ</b>. Cₙᵏ sonlari <b>binomial koeffitsiyentlar</b> deyiladi. Yoyilmaning (k + 1)-hadi — <b>umumiy had</b>: Tₖ₊₁ = Cₙᵏaⁿ⁻ᵏbᵏ, k = 0, 1, …, n. Diqqat: indekslar siljigan — birinchi had k = 0 ga, to‘rtinchi had k = 3 ga mos keladi.', 'Для любого натурального n: <b>(a + b)ⁿ = Cₙ⁰aⁿ + Cₙ¹aⁿ⁻¹b + Cₙ²aⁿ⁻²b² + … + Cₙᵏaⁿ⁻ᵏbᵏ + … + Cₙⁿbⁿ</b>. Числа Cₙᵏ называются <b>биномиальными коэффициентами</b>. (k + 1)-й член разложения — <b>общий член</b>: Tₖ₊₁ = Cₙᵏaⁿ⁻ᵏbᵏ, k = 0, 1, …, n. Внимание: индексы сдвинуты — первый член соответствует k = 0, четвёртый — k = 3.', 'For every natural n: <b>(a + b)ⁿ = Cₙ⁰aⁿ + Cₙ¹aⁿ⁻¹b + Cₙ²aⁿ⁻²b² + … + Cₙᵏaⁿ⁻ᵏbᵏ + … + Cₙⁿbⁿ</b>. The numbers Cₙᵏ are called <b>binomial coefficients</b>. The (k + 1)-th term of the expansion is the <b>general term</b>: Tₖ₊₁ = Cₙᵏaⁿ⁻ᵏbᵏ, k = 0, 1, …, n. Note the shift: the first term corresponds to k = 0, the fourth to k = 3.'),
      L('<b>Isbot g‘oyasi (kombinatorik).</b> (a + b)ⁿ = (a + b)(a + b)…(a + b) — n ta qavs. Qavslarni ochganda har bir qavsdan yo a, yo b olinib, ko‘paytiriladi. aⁿ⁻ᵏbᵏ hadi b ni aynan k ta qavsdan tanlaganda hosil bo‘ladi. n ta qavsdan k tasini tanlash usullari soni Cₙᵏ — demak, shu hadning koeffitsiyenti Cₙᵏ. Boshqa isbot usuli — matematik induksiya va Paskal qoidasi Cₙᵏ = Cₙ₋₁ᵏ⁻¹ + Cₙ₋₁ᵏ.', '<b>Идея доказательства (комбинаторная).</b> (a + b)ⁿ = (a + b)(a + b)…(a + b) — n скобок. При раскрытии из каждой скобки берётся либо a, либо b, и всё перемножается. Член aⁿ⁻ᵏbᵏ получается, когда b выбрано ровно из k скобок. Число способов выбрать k скобок из n равно Cₙᵏ — значит, коэффициент этого члена Cₙᵏ. Другой способ — математическая индукция и правило Паскаля Cₙᵏ = Cₙ₋₁ᵏ⁻¹ + Cₙ₋₁ᵏ.', '<b>Proof idea (combinatorial).</b> (a + b)ⁿ = (a + b)(a + b)…(a + b) — n brackets. When expanding, from each bracket we take either a or b and multiply. The term aⁿ⁻ᵏbᵏ appears when b is chosen from exactly k brackets. The number of ways to choose k brackets out of n is Cₙᵏ — so that is the coefficient. Another proof uses mathematical induction and Pascal’s rule Cₙᵏ = Cₙ₋₁ᵏ⁻¹ + Cₙ₋₁ᵏ.')
    ] },
    { kind: 'history', h: L('Karajiydan Nyutongacha', 'От аль-Караджи до Ньютона', 'From al-Karaji to Newton'), p: [
      L('Binomial koeffitsiyentlar jadvalini taxminan 1000-yilda Bag‘dodda <b>al-Karajiy</b> bayon qilgan va undan induksiyaga o‘xshash mulohazalarda foydalangan. Nishopurlik buyuk shoir va matematik <b>Umar Xayyom</b> (1048–1131) o‘zining algebraga oid risolasida istalgan darajali ildizlarni chiqarish usuli haqida alohida asar yozganini aytadi — bu usul binomial koeffitsiyentlarga asoslangan edi, afsuski, asar bizgacha yetib kelmagan. Xitoyda bu uchburchak <b>Yan Xuy</b> (1261) va Chju Shijie (1303) kitoblarida chizilgan.', 'Таблицу биномиальных коэффициентов около 1000 года описал в Багдаде <b>аль-Караджи</b> и использовал её в рассуждениях, похожих на индукцию. Великий поэт и математик из Нишапура <b>Омар Хайям</b> (1048–1131) в своём алгебраическом трактате упоминает, что написал отдельный труд об извлечении корней любой степени — метод опирался на биномиальные коэффициенты, но, к сожалению, труд не сохранился. В Китае этот треугольник нарисован в книгах <b>Ян Хуэя</b> (1261) и Чжу Шицзе (1303).', 'Around the year 1000 <b>al-Karaji</b> in Baghdad described the table of binomial coefficients and used it in arguments resembling induction. The great poet and mathematician of Nishapur <b>Omar Khayyam</b> (1048–1131) mentions in his algebra treatise that he wrote a separate work on extracting roots of any degree — the method relied on binomial coefficients, but sadly the work is lost. In China the triangle is drawn in the books of <b>Yang Hui</b> (1261) and Zhu Shijie (1303).'),
      L('Yevropada <b>Blez Paskal</b> 1654-yilda «Arifmetik uchburchak haqida risola» yozdi (1665-yilda nashr etilgan) va uning xossalarini tizimli o‘rgandi — shuning uchun G‘arbda u «Paskal uchburchagi» deb ataladi. 1665-yilda 22 yoshli <b>Isaak Nyuton</b> formulani kasr va manfiy daraja ko‘rsatkichlari uchun umumlashtirdi: (1 + x)<sup>1/2</sup> = 1 + x/2 − x²/8 + … — bu cheksiz qatorga aylanadi. Formula Nyuton nomini aynan shu buyuk umumlashtirish uchun olgan.', 'В Европе <b>Блез Паскаль</b> в 1654 году написал «Трактат об арифметическом треугольнике» (издан в 1665) и систематически изучил его свойства — поэтому на Западе он называется «треугольником Паскаля». В 1665 году 22-летний <b>Исаак Ньютон</b> обобщил формулу на дробные и отрицательные показатели: (1 + x)<sup>1/2</sup> = 1 + x/2 − x²/8 + … — это бесконечный ряд. Именно за это великое обобщение формула носит имя Ньютона.', 'In Europe <b>Blaise Pascal</b> wrote the “Treatise on the Arithmetical Triangle” in 1654 (published in 1665) and studied its properties systematically — hence the name “Pascal’s triangle” in the West. In 1665 the 22-year-old <b>Isaac Newton</b> generalised the formula to fractional and negative exponents: (1 + x)<sup>1/2</sup> = 1 + x/2 − x²/8 + … — an infinite series. The formula bears Newton’s name precisely for this great generalisation.')
    ] },
    { kind: 'table', h: L('Paskal uchburchagi', 'Треугольник Паскаля', 'Pascal’s triangle'), p: [
      L('Har bir qator 1 bilan boshlanib, 1 bilan tugaydi; ichki har bir son yuqorisidagi ikki son yig‘indisi (Paskal qoidasi). n-qator (a + b)ⁿ ning koeffitsiyentlarini beradi.', 'Каждая строка начинается и заканчивается 1; каждое внутреннее число — сумма двух чисел над ним (правило Паскаля). n-я строка даёт коэффициенты (a + b)ⁿ.', 'Each row starts and ends with 1; every inner number is the sum of the two numbers above it (Pascal’s rule). Row n gives the coefficients of (a + b)ⁿ.')
    ], table: { head: [S('n'), L('Koeffitsiyentlar', 'Коэффициенты', 'Coefficients'), L('Yig‘indi 2ⁿ', 'Сумма 2ⁿ', 'Sum 2ⁿ')], rows: [
      [S('0'), S('1'), S('1')],
      [S('1'), S('1  1'), S('2')],
      [S('2'), S('1  2  1'), S('4')],
      [S('3'), S('1  3  3  1'), S('8')],
      [S('4'), S('1  4  6  4  1'), S('16')],
      [S('5'), S('1  5  10  10  5  1'), S('32')],
      [S('6'), S('1  6  15  20  15  6  1'), S('64')],
      [S('7'), S('1  7  21  35  35  21  7  1'), S('128')]
    ] } },
    { kind: 'rule', h: L('Yoyilma xossalari', 'Свойства разложения', 'Properties of the expansion'), list: [
      L('Yoyilmada <b>n + 1</b> ta had bor.', 'В разложении <b>n + 1</b> членов.', 'The expansion has <b>n + 1</b> terms.'),
      L('a ning darajasi n dan 0 gacha kamayadi, b niki 0 dan n gacha o‘sadi; har bir hadda darajalar yig‘indisi n.', 'Степень a убывает от n до 0, степень b растёт от 0 до n; в каждом члене сумма степеней равна n.', 'The power of a falls from n to 0, the power of b rises from 0 to n; in each term the powers add up to n.'),
      L('Boshidan va oxiridan teng uzoqlikdagi koeffitsiyentlar teng: Cₙᵏ = Cₙⁿ⁻ᵏ.', 'Коэффициенты, равноудалённые от концов, равны: Cₙᵏ = Cₙⁿ⁻ᵏ.', 'Coefficients equally distant from the ends are equal: Cₙᵏ = Cₙⁿ⁻ᵏ.'),
      L('Koeffitsiyentlar o‘rtaga qadar o‘sadi, so‘ng kamayadi; n juft bo‘lsa, eng kattasi bitta (o‘rta had), toq bo‘lsa — ikkita.', 'Коэффициенты растут к середине, затем убывают; при чётном n наибольший один (средний член), при нечётном — два.', 'The coefficients grow towards the middle and then decrease; for even n there is one largest (the middle term), for odd n there are two.'),
      L('a = b = 1 deb olsak: Cₙ⁰ + Cₙ¹ + … + Cₙⁿ = 2ⁿ.', 'При a = b = 1: Cₙ⁰ + Cₙ¹ + … + Cₙⁿ = 2ⁿ.', 'With a = b = 1: Cₙ⁰ + Cₙ¹ + … + Cₙⁿ = 2ⁿ.'),
      L('a = 1, b = −1 deb olsak: Cₙ⁰ − Cₙ¹ + Cₙ² − … = 0, ya’ni juft o‘rindagi va toq o‘rindagi koeffitsiyentlar yig‘indilari teng (har biri 2ⁿ⁻¹).', 'При a = 1, b = −1: Cₙ⁰ − Cₙ¹ + Cₙ² − … = 0, то есть суммы коэффициентов на чётных и нечётных местах равны (каждая 2ⁿ⁻¹).', 'With a = 1, b = −1: Cₙ⁰ − Cₙ¹ + Cₙ² − … = 0, i.e. the sums of coefficients in even and odd places are equal (each 2ⁿ⁻¹).'),
      L('(a − b)ⁿ da ishoralar navbatlashadi: b ning toq darajali hadlari minus bilan.', 'В (a − b)ⁿ знаки чередуются: члены с нечётной степенью b — со знаком минус.', 'In (a − b)ⁿ the signs alternate: terms with odd powers of b carry a minus.')
    ] },
    { kind: 'steps', h: L('Binom bilan ishlash algoritmi', 'Алгоритм работы с биномом', 'How to work with the binomial'), list: [
      L('a va b ni aniq belgilang, ishorasi bilan birga: (2x − 1)⁵ da a = 2x, b = −1.', 'Чётко определите a и b вместе со знаком: в (2x − 1)⁵ a = 2x, b = −1.', 'Identify a and b precisely, with their signs: in (2x − 1)⁵, a = 2x and b = −1.'),
      L('To‘liq yoyilma kerak bo‘lsa — Paskal uchburchagidan n-qatorni oling.', 'Если нужно полное разложение — возьмите n-ю строку треугольника Паскаля.', 'If the full expansion is needed, take row n of Pascal’s triangle.'),
      L('Bitta had kerak bo‘lsa — umumiy had Tₖ₊₁ = Cₙᵏaⁿ⁻ᵏbᵏ ni yozing.', 'Если нужен один член — запишите общий член Tₖ₊₁ = Cₙᵏaⁿ⁻ᵏbᵏ.', 'If one term is needed, write the general term Tₖ₊₁ = Cₙᵏaⁿ⁻ᵏbᵏ.'),
      L('x ning darajasini k orqali ifodalang va shartdan (masalan, «x siz had» → daraja 0) k ni toping.', 'Выразите степень x через k и найдите k из условия (например, «член без x» → степень 0).', 'Express the power of x in terms of k and find k from the condition (e.g. “term free of x” means power 0).'),
      L('Koeffitsiyentni hisoblang: Cₙᵏ ni a va b dagi sonlarning darajalariga ko‘paytiring, ishorani tekshiring.', 'Вычислите коэффициент: умножьте Cₙᵏ на степени чисел из a и b, проверьте знак.', 'Compute the coefficient: multiply Cₙᵏ by the powers of the numbers in a and b; check the sign.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar: yoyilmalar', 'Решённые примеры: разложения', 'Solved examples: expansions'), ex: [
      { q: L('(a + b)⁴ ni yoying.', 'Разложите (a + b)⁴.', 'Expand (a + b)⁴.'), s: L('4-qator: 1, 4, 6, 4, 1. (a + b)⁴ = a⁴ + 4a³b + 6a²b² + 4ab³ + b⁴.', 'Строка 4: 1, 4, 6, 4, 1. (a + b)⁴ = a⁴ + 4a³b + 6a²b² + 4ab³ + b⁴.', 'Row 4: 1, 4, 6, 4, 1. (a + b)⁴ = a⁴ + 4a³b + 6a²b² + 4ab³ + b⁴.') },
      { q: L('(2x − 1)⁵ ni yoying.', 'Разложите (2x − 1)⁵.', 'Expand (2x − 1)⁵.'), s: L('a = 2x, b = −1, koeffitsiyentlar 1, 5, 10, 10, 5, 1. Hadlar: 32x⁵; 5·16x⁴·(−1) = −80x⁴; 10·8x³ = 80x³; 10·4x²·(−1) = −40x²; 5·2x = 10x; −1. Javob: 32x⁵ − 80x⁴ + 80x³ − 40x² + 10x − 1. Tekshiruv: x = 1 da 32 − 80 + 80 − 40 + 10 − 1 = 1 = (2 − 1)⁵ ✓.', 'a = 2x, b = −1, коэффициенты 1, 5, 10, 10, 5, 1. Члены: 32x⁵; 5·16x⁴·(−1) = −80x⁴; 10·8x³ = 80x³; 10·4x²·(−1) = −40x²; 5·2x = 10x; −1. Ответ: 32x⁵ − 80x⁴ + 80x³ − 40x² + 10x − 1. Проверка: при x = 1 32 − 80 + 80 − 40 + 10 − 1 = 1 = (2 − 1)⁵ ✓.', 'a = 2x, b = −1, coefficients 1, 5, 10, 10, 5, 1. Terms: 32x⁵; 5·16x⁴·(−1) = −80x⁴; 10·8x³ = 80x³; 10·4x²·(−1) = −40x²; 5·2x = 10x; −1. Answer: 32x⁵ − 80x⁴ + 80x³ − 40x² + 10x − 1. Check: at x = 1, 32 − 80 + 80 − 40 + 10 − 1 = 1 = (2 − 1)⁵ ✓.') },
      { q: L('(3x − 2)⁴ yoyilmasidagi koeffitsiyentlar yig‘indisini toping.', 'Найдите сумму коэффициентов разложения (3x − 2)⁴.', 'Find the sum of the coefficients of (3x − 2)⁴.'), s: L('Koeffitsiyentlar yig‘indisi ko‘phadning x = 1 dagi qiymatiga teng: (3 − 2)⁴ = 1. Qavsni ochish shart emas!', 'Сумма коэффициентов равна значению многочлена при x = 1: (3 − 2)⁴ = 1. Раскрывать скобки не нужно!', 'The sum of the coefficients equals the value of the polynomial at x = 1: (3 − 2)⁴ = 1. No need to expand!') },
      { q: L('1,01⁵ ni taqriban hisoblang.', 'Вычислите приближённо 1,01⁵.', 'Approximate 1.01⁵.'), s: L('(1 + 0,01)⁵ = 1 + 5·0,01 + 10·0,0001 + 10·0,000001 + … ≈ 1 + 0,05 + 0,001 = 1,051. Aniq qiymat 1,0510100501 — keyingi hadlar juda kichik.', '(1 + 0,01)⁵ = 1 + 5·0,01 + 10·0,0001 + 10·0,000001 + … ≈ 1 + 0,05 + 0,001 = 1,051. Точное значение 1,0510100501 — следующие члены очень малы.', '(1 + 0.01)⁵ = 1 + 5·0.01 + 10·0.0001 + 10·0.000001 + … ≈ 1 + 0.05 + 0.001 = 1.051. The exact value is 1.0510100501 — the later terms are tiny.') }
    ] },
    { kind: 'example', h: L('Yechilgan misollar: umumiy had', 'Решённые примеры: общий член', 'Solved examples: the general term'), ex: [
      { q: L('(x + 2)⁷ yoyilmasining 4-hadini toping.', 'Найдите 4-й член разложения (x + 2)⁷.', 'Find the 4th term of (x + 2)⁷.'), s: L('4-had — k = 3: T₄ = C₇³x⁴·2³ = 35·8x⁴ = 280x⁴.', '4-й член — k = 3: T₄ = C₇³x⁴·2³ = 35·8x⁴ = 280x⁴.', 'The 4th term has k = 3: T₄ = C₇³x⁴·2³ = 35·8x⁴ = 280x⁴.') },
      { q: L('(x + 1/x)⁶ yoyilmasidagi x qatnashmagan hadni toping.', 'Найдите член разложения (x + 1/x)⁶, не содержащий x.', 'Find the term of (x + 1/x)⁶ that does not contain x.'), s: L('Tₖ₊₁ = C₆ᵏx⁶⁻ᵏ(1/x)ᵏ = C₆ᵏx⁶⁻²ᵏ. 6 − 2k = 0 → k = 3. T₄ = C₆³ = 20.', 'Tₖ₊₁ = C₆ᵏx⁶⁻ᵏ(1/x)ᵏ = C₆ᵏx⁶⁻²ᵏ. 6 − 2k = 0 → k = 3. T₄ = C₆³ = 20.', 'Tₖ₊₁ = C₆ᵏx⁶⁻ᵏ(1/x)ᵏ = C₆ᵏx⁶⁻²ᵏ. 6 − 2k = 0 gives k = 3. T₄ = C₆³ = 20.') },
      { q: L('(x² − 2/x)⁶ yoyilmasidagi ozod hadni toping.', 'Найдите свободный член разложения (x² − 2/x)⁶.', 'Find the constant term of (x² − 2/x)⁶.'), s: L('Tₖ₊₁ = C₆ᵏ(x²)⁶⁻ᵏ(−2/x)ᵏ = C₆ᵏ(−2)ᵏx¹²⁻³ᵏ. 12 − 3k = 0 → k = 4. T₅ = C₆⁴·(−2)⁴ = 15·16 = 240.', 'Tₖ₊₁ = C₆ᵏ(x²)⁶⁻ᵏ(−2/x)ᵏ = C₆ᵏ(−2)ᵏx¹²⁻³ᵏ. 12 − 3k = 0 → k = 4. T₅ = C₆⁴·(−2)⁴ = 15·16 = 240.', 'Tₖ₊₁ = C₆ᵏ(x²)⁶⁻ᵏ(−2/x)ᵏ = C₆ᵏ(−2)ᵏx¹²⁻³ᵏ. 12 − 3k = 0 gives k = 4. T₅ = C₆⁴·(−2)⁴ = 15·16 = 240.') },
      { q: L('11¹⁰ − 1 son 100 ga bo‘linishini isbotlang.', 'Докажите, что 11¹⁰ − 1 делится на 100.', 'Prove that 11¹⁰ − 1 is divisible by 100.'), s: L('11¹⁰ = (1 + 10)¹⁰ = 1 + C₁₀¹·10 + C₁₀²·10² + … = 1 + 100 + 45·100 + (100 ga karrali hadlar). Demak, 11¹⁰ − 1 = 100 + 4500 + … — barcha qo‘shiluvchilar 100 ga bo‘linadi.', '11¹⁰ = (1 + 10)¹⁰ = 1 + C₁₀¹·10 + C₁₀²·10² + … = 1 + 100 + 45·100 + (члены, кратные 100). Значит, 11¹⁰ − 1 = 100 + 4500 + … — все слагаемые делятся на 100.', '11¹⁰ = (1 + 10)¹⁰ = 1 + C₁₀¹·10 + C₁₀²·10² + … = 1 + 100 + 45·100 + (multiples of 100). So 11¹⁰ − 1 = 100 + 4500 + … — every term is divisible by 100.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>«Birinchi kursant xatosi»:</b> (a + b)ⁿ = aⁿ + bⁿ. Hatto (a + b)² ham a² + b² emas — 2ab hadi yo‘qolgan.', '<b>«Мечта первокурсника»:</b> (a + b)ⁿ = aⁿ + bⁿ. Даже (a + b)² не равно a² + b² — потерян член 2ab.', '<b>The “freshman’s dream”:</b> (a + b)ⁿ = aⁿ + bⁿ. Even (a + b)² is not a² + b² — the 2ab term is lost.'),
      L('<b>Had raqamini k bilan chalkashtirish.</b> 4-had T₄ = C₇³…, C₇⁴… emas.', '<b>Путать номер члена и k.</b> 4-й член T₄ = C₇³…, а не C₇⁴….', '<b>Confusing the term number with k.</b> The 4th term is T₄ = C₇³…, not C₇⁴….'),
      L('<b>Koeffitsiyentni darajaga ko‘tarmaslik.</b> (2x)³ = 8x³, 2x³ emas. Binomial koeffitsiyent «binomdagi» sonning darajasiga ham ko‘paytiriladi.', '<b>Не возводить коэффициент в степень.</b> (2x)³ = 8x³, а не 2x³. Биномиальный коэффициент умножается и на степень числа внутри бинома.', '<b>Not raising the coefficient to the power.</b> (2x)³ = 8x³, not 2x³. The binomial coefficient is also multiplied by the power of the number inside.'),
      L('<b>Ishorani yo‘qotish.</b> (x − 2)ⁿ da b = −2, shuning uchun bᵏ = (−2)ᵏ: toq k da manfiy.', '<b>Потерять знак.</b> В (x − 2)ⁿ b = −2, поэтому bᵏ = (−2)ᵏ: при нечётном k отрицательно.', '<b>Losing the sign.</b> In (x − 2)ⁿ, b = −2, so bᵏ = (−2)ᵏ, which is negative for odd k.'),
      L('<b>«Binomial koeffitsiyent» va «had koeffitsiyenti»ni chalkashtirish.</b> (x + 2)⁷ da 4-hadning binomial koeffitsiyenti 35, had koeffitsiyenti esa 280.', '<b>Путать «биномиальный коэффициент» и «коэффициент члена».</b> В (x + 2)⁷ у 4-го члена биномиальный коэффициент 35, а коэффициент члена 280.', '<b>Confusing the “binomial coefficient” with the “coefficient of the term”.</b> In (x + 2)⁷ the 4th term has binomial coefficient 35 but term coefficient 280.')
    ] },
    { kind: 'life', h: L('Binom hayotda', 'Бином в жизни', 'The binomial in real life'), p: [
      L('<b>Moliya.</b> Murakkab foiz formulasi S = S₀(1 + r)ⁿ — binomning darajasi. Kichik r da binom taqribiy hisobni beradi: (1 + r)ⁿ ≈ 1 + nr + n(n − 1)r²/2. Masalan, yillik 10% da 3 yil: 1 + 0,3 + 0,03 + 0,001 = 1,331. <b>Fizika.</b> Eynshteynning nisbiylik nazariyasida kinetik energiya formulasidan binom yoyilmasining birinchi hadini olsak, klassik mv²/2 formulasi chiqadi.', '<b>Финансы.</b> Формула сложных процентов S = S₀(1 + r)ⁿ — степень бинома. При малых r бином даёт приближённый расчёт: (1 + r)ⁿ ≈ 1 + nr + n(n − 1)r²/2. Например, 10% годовых за 3 года: 1 + 0,3 + 0,03 + 0,001 = 1,331. <b>Физика.</b> Если в формуле кинетической энергии теории относительности Эйнштейна взять первый член биномиального разложения, получится классическая формула mv²/2.', '<b>Finance.</b> The compound interest formula S = S₀(1 + r)ⁿ is a power of a binomial. For small r the binomial gives an approximation: (1 + r)ⁿ ≈ 1 + nr + n(n − 1)r²/2. For example, 10% a year for 3 years: 1 + 0.3 + 0.03 + 0.001 = 1.331. <b>Physics.</b> Taking the first term of the binomial expansion in Einstein’s relativistic kinetic energy gives the classical formula mv²/2.'),
      L('<b>Genetika va ehtimollik.</b> Ikkala ota-ona ham geterozigot (Aa) bo‘lsa, 4 farzanddan aynan k tasida retsessiv belgi namoyon bo‘lish ehtimoli C₄ᵏ(1/4)ᵏ(3/4)⁴⁻ᵏ — bu (3/4 + 1/4)⁴ yoyilmasining hadi. Keyingi mavzularda binom ehtimollar nazariyasining asosiy quroliga aylanadi (binomial taqsimot).', '<b>Генетика и вероятность.</b> Если оба родителя гетерозиготны (Aa), вероятность, что ровно у k из 4 детей проявится рецессивный признак, равна C₄ᵏ(1/4)ᵏ(3/4)⁴⁻ᵏ — это член разложения (3/4 + 1/4)⁴. В следующих темах бином станет главным инструментом теории вероятностей (биномиальное распределение).', '<b>Genetics and probability.</b> If both parents are heterozygous (Aa), the probability that exactly k of 4 children show a recessive trait is C₄ᵏ(1/4)ᵏ(3/4)⁴⁻ᵏ — a term of the expansion of (3/4 + 1/4)⁴. In later topics the binomial becomes the main tool of probability (the binomial distribution).')
    ] },
    { kind: 'fact', h: L('Paskal uchburchagi sirlari', 'Секреты треугольника Паскаля', 'Secrets of Pascal’s triangle'), list: [
      L('11 ning darajalari: 11² = 121, 11³ = 1331, 11⁴ = 14641 — Paskal uchburchagi qatorlari (5-qatordan boshlab «ko‘chirish» kerak bo‘ladi).', 'Степени 11: 11² = 121, 11³ = 1331, 11⁴ = 14641 — строки треугольника Паскаля (с 5-й строки нужны «переносы»).', 'Powers of 11: 11² = 121, 11³ = 1331, 11⁴ = 14641 — rows of Pascal’s triangle (from row 5 on, carrying is needed).'),
      L('Uchburchakdagi toq sonlarni bo‘yasak, fraktal — Serpinskiy uchburchagi hosil bo‘ladi.', 'Если закрасить нечётные числа треугольника, получится фрактал — треугольник Серпинского.', 'Colouring the odd numbers of the triangle produces a fractal — the Sierpiński triangle.'),
      L('«Qiya» diagonallar bo‘yicha yig‘indilar Fibonachchi sonlarini beradi: 1, 1, 2, 3, 5, 8, 13, …', 'Суммы по «пологим» диагоналям дают числа Фибоначчи: 1, 1, 2, 3, 5, 8, 13, …', 'Sums along the “shallow” diagonals give the Fibonacci numbers: 1, 1, 2, 3, 5, 8, 13, …'),
      L('Ikkinchi diagonal — natural sonlar, uchinchisi — uchburchak sonlar 1, 3, 6, 10, 15, …', 'Вторая диагональ — натуральные числа, третья — треугольные числа 1, 3, 6, 10, 15, …', 'The second diagonal is the natural numbers, the third the triangular numbers 1, 3, 6, 10, 15, …')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('(x − 1)⁶ ni yoying.', 'Разложите (x − 1)⁶.', 'Expand (x − 1)⁶.'),
      L('(1 + 2x)⁶ yoyilmasida x³ oldidagi koeffitsiyent?', 'Коэффициент при x³ в разложении (1 + 2x)⁶?', 'The coefficient of x³ in (1 + 2x)⁶?'),
      L('(a + b)¹⁰ da nechta had bor va o‘rta had qaysi?', 'Сколько членов в (a + b)¹⁰ и какой средний?', 'How many terms does (a + b)¹⁰ have, and what is the middle one?')
    ], after: [
      L('Javoblar: x⁶ − 6x⁵ + 15x⁴ − 20x³ + 15x² − 6x + 1; C₆³·2³ = 20·8 = 160; 11 ta had, o‘rtasi T₆ = C₁₀⁵a⁵b⁵ = 252a⁵b⁵.', 'Ответы: x⁶ − 6x⁵ + 15x⁴ − 20x³ + 15x² − 6x + 1; C₆³·2³ = 20·8 = 160; 11 членов, средний T₆ = C₁₀⁵a⁵b⁵ = 252a⁵b⁵.', 'Answers: x⁶ − 6x⁵ + 15x⁴ − 20x³ + 15x² − 6x + 1; C₆³·2³ = 20·8 = 160; 11 terms, the middle one is T₆ = C₁₀⁵a⁵b⁵ = 252a⁵b⁵.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('(a + b)ⁿ = Σ Cₙᵏaⁿ⁻ᵏbᵏ, k = 0, …, n.', '(a + b)ⁿ = Σ Cₙᵏaⁿ⁻ᵏbᵏ, k = 0, …, n.', '(a + b)ⁿ = Σ Cₙᵏaⁿ⁻ᵏbᵏ, k = 0, …, n.'),
      L('Umumiy had: Tₖ₊₁ = Cₙᵏaⁿ⁻ᵏbᵏ (had raqami k + 1).', 'Общий член: Tₖ₊₁ = Cₙᵏaⁿ⁻ᵏbᵏ (номер члена k + 1).', 'General term: Tₖ₊₁ = Cₙᵏaⁿ⁻ᵏbᵏ (term number k + 1).'),
      L('Koeffitsiyentlar Paskal uchburchagida: har bir son — yuqoridagi ikki son yig‘indisi.', 'Коэффициенты — в треугольнике Паскаля: каждое число — сумма двух над ним.', 'Coefficients form Pascal’s triangle: each number is the sum of the two above.'),
      L('n + 1 ta had, simmetriya Cₙᵏ = Cₙⁿ⁻ᵏ, yig‘indi 2ⁿ.', 'n + 1 членов, симметрия Cₙᵏ = Cₙⁿ⁻ᵏ, сумма 2ⁿ.', 'n + 1 terms, symmetry Cₙᵏ = Cₙⁿ⁻ᵏ, sum 2ⁿ.'),
      L('Koeffitsiyentlar yig‘indisi — ko‘phadning x = 1 dagi qiymati.', 'Сумма коэффициентов — значение многочлена при x = 1.', 'The sum of coefficients is the value of the polynomial at x = 1.'),
      L('Bu jadvalni al-Karajiy, Xayyom, Yan Xuy, Paskal bilgan; Nyuton uni kasr darajalarga umumlashtirgan.', 'Эту таблицу знали аль-Караджи, Хайям, Ян Хуэй, Паскаль; Ньютон обобщил её на дробные степени.', 'Al-Karaji, Khayyam, Yang Hui and Pascal knew this table; Newton generalised it to fractional powers.')
    ] }
  ] });

  // ---------- t17. Statistik ma’lumotlar ----------
  T.add(P, 't17', { sections: [
    { kind: 'intro', h: L('Sonlar nima deydi?', 'О чём говорят числа?', 'What do the numbers say?'), p: [
      L('Har kuni biz statistikaga duch kelamiz: «o‘rtacha ish haqi», «bugungi havo harorati me’yordan 3° yuqori», «saylovchilarning 62 foizi», «smartfon batareyasi o‘rtacha 2 kun yetadi». Lekin bir xil ma’lumotlardan turli xulosalar chiqarish mumkin, ba’zan esa sonlar ataylab chalg‘itish uchun ishlatiladi. Statistikani tushunish — zamonaviy savodxonlikning bir qismi.', 'Каждый день мы сталкиваемся со статистикой: «средняя зарплата», «сегодня на 3° теплее нормы», «62 процента избирателей», «батарея смартфона в среднем держит 2 дня». Но из одних и тех же данных можно сделать разные выводы, а иногда числа используют намеренно, чтобы ввести в заблуждение. Понимать статистику — часть современной грамотности.', 'Every day we meet statistics: “the average wage”, “today is 3° warmer than normal”, “62 percent of voters”, “a phone battery lasts 2 days on average”. Yet the same data can lead to different conclusions, and numbers are sometimes used deliberately to mislead. Understanding statistics is part of modern literacy.'),
      L('<b>Statistika</b> — ma’lumotlarni yig‘ish, tartibga solish, tasvirlash va tahlil qilish haqidagi fan. Bu mavzuda ma’lumotlarni jadval va diagrammalarda ko‘rsatishni, ularni bitta son bilan tavsiflashni (o‘rta qiymat, moda, mediana) va ma’lumotlarning qanchalik «tarqoq» ekanini o‘lchashni (dispersiya, standart chetlanish) o‘rganamiz.', '<b>Статистика</b> — наука о сборе, упорядочении, представлении и анализе данных. В этой теме научимся изображать данные в таблицах и диаграммах, описывать их одним числом (среднее, мода, медиана) и измерять, насколько данные «разбросаны» (дисперсия, стандартное отклонение).', '<b>Statistics</b> is the science of collecting, organising, presenting and analysing data. In this topic we learn to show data in tables and charts, to describe them with a single number (mean, mode, median) and to measure how “spread out” the data are (variance, standard deviation).')
    ] },
    { kind: 'def', h: L('Asosiy tushunchalar', 'Основные понятия', 'Basic notions'), p: [
      L('O‘rganilayotgan barcha ob’ektlar to‘plami — <b>bosh to‘plam</b> (masalan, mamlakatdagi barcha 11-sinf o‘quvchilari). Undan tekshirish uchun olingan qism — <b>tanlanma</b> (masalan, 500 nafar o‘quvchi). Tanlanma bosh to‘plamni yaxshi aks ettirishi uchun <b>tasodifiy</b> va yetarlicha katta bo‘lishi kerak. Tanlanmadagi elementlar soni n — tanlanma <b>hajmi</b>.', 'Совокупность всех изучаемых объектов — <b>генеральная совокупность</b> (например, все 11-классники страны). Часть, взятая для обследования, — <b>выборка</b> (например, 500 учеников). Чтобы выборка хорошо отражала генеральную совокупность, она должна быть <b>случайной</b> и достаточно большой. Число элементов выборки n — её <b>объём</b>.', 'The set of all objects studied is the <b>population</b> (e.g. all grade-11 students in the country). The part taken for study is a <b>sample</b> (e.g. 500 students). For a sample to represent the population well it must be <b>random</b> and large enough. The number of elements n is the sample <b>size</b>.'),
      L('Tartiblangan ma’lumotlar qatori — <b>variatsion qator</b>. Har bir qiymat necha marta uchrashi — uning <b>chastotasi</b> fᵢ, chastotaning n ga nisbati — <b>nisbiy chastota</b> fᵢ/n (barcha nisbiy chastotalar yig‘indisi 1 ga, ya’ni 100% ga teng). Qiymatlar va chastotalar juftliklari jadvali — <b>chastotalar jadvali</b>.', 'Упорядоченный ряд данных — <b>вариационный ряд</b>. Сколько раз встречается каждое значение — его <b>частота</b> fᵢ, отношение частоты к n — <b>относительная частота</b> fᵢ/n (сумма всех относительных частот равна 1, то есть 100%). Таблица пар «значение — частота» — <b>таблица частот</b>.', 'An ordered data series is a <b>variation series</b>. How often each value occurs is its <b>frequency</b> fᵢ; the ratio of frequency to n is the <b>relative frequency</b> fᵢ/n (all relative frequencies add up to 1, i.e. 100%). A table of value–frequency pairs is a <b>frequency table</b>.')
    ] },
    { kind: 'history', h: L('Statistika qanday tug‘ilgan', 'Как родилась статистика', 'How statistics was born'), p: [
      L('Aholi ro‘yxatlari qadimgi Misr, Xitoy va Rimda o‘tkazilgan, lekin ilmiy statistika XVII asrda boshlandi. 1662-yilda londonlik savdogar <b>Jon Graunt</b> cherkovlarning o‘lim haqidagi haftalik ro‘yxatlarini tahlil qilib, o‘g‘il bolalar qiz bolalardan ko‘proq tug‘ilishini va o‘lim sabablarida barqaror qonuniyatlar borligini aniqladi. 1786-yilda Uilyam Pleyfer ustunli diagrammani, 1801-yilda doiraviy diagrammani ixtiro qildi.', 'Переписи населения проводились в Древнем Египте, Китае и Риме, но научная статистика началась в XVII веке. В 1662 году лондонский торговец <b>Джон Граунт</b>, проанализировав еженедельные церковные списки умерших, установил, что мальчиков рождается больше, чем девочек, и что в причинах смерти есть устойчивые закономерности. В 1786 году Уильям Плейфер изобрёл столбчатую диаграмму, в 1801 — круговую.', 'Censuses were held in ancient Egypt, China and Rome, but scientific statistics began in the 17th century. In 1662 the London merchant <b>John Graunt</b> analysed weekly church bills of mortality and found that more boys are born than girls and that causes of death follow stable patterns. In 1786 William Playfair invented the bar chart, and in 1801 the pie chart.'),
      L('1835-yilda belgiyalik <b>Adolf Ketle</b> «o‘rtacha odam» tushunchasini kiritib, odamlarning bo‘yi va vaznini ommaviy o‘rgandi. Hamshira <b>Florens Naytingeyl</b> 1858-yilda o‘zining «atirgul» diagrammasi bilan Qrim urushida askarlar jangdan ko‘ra kasalxonadagi yuqumli kasalliklardan ko‘proq o‘layotganini isbotladi va gigiyena islohotiga erishdi. «Standart chetlanish» atamasini 1893–1894-yillarda ingliz <b>Karl Pirson</b> kiritgan.', 'В 1835 году бельгиец <b>Адольф Кетле</b> ввёл понятие «среднего человека», массово изучая рост и вес людей. Медсестра <b>Флоренс Найтингейл</b> в 1858 году своей диаграммой-«розой» доказала, что в Крымскую войну солдаты гибли больше от инфекций в госпиталях, чем в бою, и добилась гигиенической реформы. Термин «стандартное отклонение» ввёл в 1893–1894 годах англичанин <b>Карл Пирсон</b>.', 'In 1835 the Belgian <b>Adolphe Quetelet</b> introduced the idea of the “average man”, studying people’s heights and weights on a mass scale. In 1858 the nurse <b>Florence Nightingale</b> used her “rose” diagram to prove that in the Crimean War more soldiers died of infections in hospitals than in battle, and won hygiene reforms. The term “standard deviation” was introduced in 1893–1894 by the Englishman <b>Karl Pearson</b>.')
    ] },
    { kind: 'def', h: L('Ma’lumotlarni tasvirlash', 'Представление данных', 'Presenting data'), list: [
      L('<b>Jadval</b> — aniq qiymatlarni saqlaydi, lekin umumiy manzarani ko‘rish qiyin.', '<b>Таблица</b> — хранит точные значения, но общую картину увидеть трудно.', '<b>Table</b> — keeps exact values, but the overall picture is hard to see.'),
      L('<b>Ustunli diagramma</b> — kategoriyalarni (fanlar, oylar) solishtirish uchun.', '<b>Столбчатая диаграмма</b> — для сравнения категорий (предметы, месяцы).', '<b>Bar chart</b> — for comparing categories (subjects, months).'),
      L('<b>Gistogramma</b> — uzluksiz miqdorlar (bo‘y, vaqt) uchun: qiymatlar oraliqlarga bo‘linadi, ustunlar bir-biriga tegib turadi, ustun yuzi chastotaga proporsional.', '<b>Гистограмма</b> — для непрерывных величин (рост, время): значения делят на интервалы, столбцы примыкают друг к другу, площадь столбца пропорциональна частоте.', '<b>Histogram</b> — for continuous quantities (height, time): values are grouped into intervals, bars touch each other, and bar area is proportional to frequency.'),
      L('<b>Chastotalar poligoni</b> — (xᵢ; fᵢ) nuqtalarni siniq chiziq bilan tutashtirish.', '<b>Полигон частот</b> — ломаная, соединяющая точки (xᵢ; fᵢ).', '<b>Frequency polygon</b> — a broken line joining the points (xᵢ; fᵢ).'),
      L('<b>Doiraviy diagramma</b> — butunning qismlarini ko‘rsatadi: sektor burchagi = 360°·(ulush). Masalan, 25% → 90°, 10% → 36°.', '<b>Круговая диаграмма</b> — показывает части целого: угол сектора = 360°·(доля). Например, 25% → 90°, 10% → 36°.', '<b>Pie chart</b> — shows parts of a whole: sector angle = 360°·(share). For example, 25% → 90°, 10% → 36°.')
    ] },
    { kind: 'rule', h: L('Markaziy tendensiya o‘lchovlari', 'Меры центральной тенденции', 'Measures of central tendency'), p: [
      L('<b>O‘rta arifmetik qiymat:</b> x̄ = (x₁ + x₂ + … + xₙ)/n. Chastotalar jadvalida — <b>tortilgan o‘rtacha</b>: x̄ = (x₁f₁ + x₂f₂ + … + xₖfₖ)/n. Xossasi: chetlanishlar yig‘indisi nolga teng: Σ(xᵢ − x̄) = 0 — o‘rtacha ma’lumotlarning «og‘irlik markazi».', '<b>Среднее арифметическое:</b> x̄ = (x₁ + x₂ + … + xₙ)/n. В таблице частот — <b>взвешенное среднее</b>: x̄ = (x₁f₁ + x₂f₂ + … + xₖfₖ)/n. Свойство: сумма отклонений равна нулю: Σ(xᵢ − x̄) = 0 — среднее есть «центр тяжести» данных.', '<b>Arithmetic mean:</b> x̄ = (x₁ + x₂ + … + xₙ)/n. In a frequency table — the <b>weighted mean</b>: x̄ = (x₁f₁ + x₂f₂ + … + xₖfₖ)/n. Property: deviations add up to zero: Σ(xᵢ − x̄) = 0 — the mean is the “centre of mass” of the data.'),
      L('<b>Moda</b> (Mo) — eng ko‘p uchraydigan qiymat. U bir nechta bo‘lishi yoki umuman bo‘lmasligi mumkin; moda sonli bo‘lmagan ma’lumotlar uchun ham ma’noli (eng ommabop rang, o‘lcham). <b>Mediana</b> (Me) — tartiblangan qatorning o‘rtasidagi qiymat: n toq bo‘lsa — (n + 1)/2-o‘rindagi son, juft bo‘lsa — ikki o‘rta sonning o‘rta arifmetigi. Mediana qatorni teng ikki yarimga bo‘ladi.', '<b>Мода</b> (Mo) — самое частое значение. Мод может быть несколько или не быть вовсе; мода имеет смысл и для нечисловых данных (самый популярный цвет, размер). <b>Медиана</b> (Me) — значение в середине упорядоченного ряда: при нечётном n — число на (n + 1)/2-м месте, при чётном — среднее двух средних чисел. Медиана делит ряд пополам.', 'The <b>mode</b> (Mo) is the most frequent value. There may be several modes or none; the mode also makes sense for non-numerical data (most popular colour, size). The <b>median</b> (Me) is the middle value of the ordered series: for odd n, the number in position (n + 1)/2; for even n, the mean of the two middle numbers. The median splits the series in half.'),
      L('Qaysi biri yaxshi? O‘rtacha barcha ma’lumotlardan foydalanadi, lekin <b>chetki qiymatlar</b>ga (juda katta yoki kichik sonlarga) sezgir. Mediana ularga chidamli — shuning uchun daromadlar va uy narxlari haqida gapirganda ko‘pincha mediana keltiriladi.', 'Что лучше? Среднее использует все данные, но чувствительно к <b>выбросам</b> (очень большим или малым числам). Медиана к ним устойчива — поэтому о доходах и ценах на жильё часто сообщают медиану.', 'Which is better? The mean uses all the data but is sensitive to <b>outliers</b> (very large or small numbers). The median is robust to them — which is why incomes and house prices are often reported by the median.')
    ] },
    { kind: 'rule', h: L('Tarqoqlik o‘lchovlari', 'Меры разброса', 'Measures of spread'), p: [
      L('Ikki sinfning o‘rtacha bahosi 4 bo‘lishi mumkin, lekin birinchisida hamma «4» olgan, ikkinchisida yarmi «5», yarmi «3». Farqni o‘lchash uchun tarqoqlik ko‘rsatkichlari kerak. Eng soddasi — <b>kenglik</b> (qulach): R = x<sub>max</sub> − x<sub>min</sub>. U faqat ikki chetki songa bog‘liq, shuning uchun qo‘pol.', 'У двух классов средний балл может быть 4, но в первом все получили «4», а во втором половина «5», половина «3». Чтобы измерить разницу, нужны показатели разброса. Простейший — <b>размах</b>: R = x<sub>max</sub> − x<sub>min</sub>. Он зависит лишь от двух крайних чисел, поэтому груб.', 'Two classes may both average 4, but in the first everyone got “4”, while in the second half got “5” and half “3”. To measure the difference we need measures of spread. The simplest is the <b>range</b>: R = x<sub>max</sub> − x<sub>min</sub>. It depends only on two extreme numbers, so it is crude.'),
      L('<b>Dispersiya</b> — chetlanishlar kvadratlarining o‘rtachasi: D = ((x₁ − x̄)² + … + (xₙ − x̄)²)/n. Kvadratga ko‘tarish musbat va manfiy chetlanishlarning bir-birini yo‘qotishiga yo‘l qo‘ymaydi. Qulay formula: D = (x₁² + … + xₙ²)/n − x̄² («kvadratlar o‘rtachasi minus o‘rtachaning kvadrati»). <b>Standart (o‘rtacha kvadratik) chetlanish</b> σ = √D — ma’lumotlar bilan bir xil birlikda o‘lchanadi (sm, ball, so‘m). Kichik σ — ma’lumotlar o‘rtacha atrofida zich, katta σ — tarqoq.', '<b>Дисперсия</b> — среднее квадратов отклонений: D = ((x₁ − x̄)² + … + (xₙ − x̄)²)/n. Возведение в квадрат не даёт положительным и отрицательным отклонениям взаимно уничтожиться. Удобная формула: D = (x₁² + … + xₙ²)/n − x̄² («среднее квадратов минус квадрат среднего»). <b>Стандартное (среднеквадратическое) отклонение</b> σ = √D измеряется в тех же единицах, что и данные (см, баллы, сумы). Малое σ — данные плотно вокруг среднего, большое — разбросаны.', 'The <b>variance</b> is the mean of the squared deviations: D = ((x₁ − x̄)² + … + (xₙ − x̄)²)/n. Squaring prevents positive and negative deviations from cancelling. A handy formula: D = (x₁² + … + xₙ²)/n − x̄² (“mean of squares minus square of the mean”). The <b>standard deviation</b> σ = √D is measured in the same units as the data (cm, points, sums). Small σ means data packed tightly around the mean; large σ means widely spread.')
    ] },
    { kind: 'steps', h: L('Ma’lumotlarni tahlil qilish tartibi', 'Порядок анализа данных', 'Steps for analysing data'), list: [
      L('Ma’lumotlarni o‘sish tartibida yozing va n ni sanang.', 'Запишите данные в порядке возрастания и сосчитайте n.', 'Write the data in increasing order and count n.'),
      L('Kenglik, moda va medianani tartiblangan qatordan aniqlang.', 'Определите размах, моду и медиану по упорядоченному ряду.', 'Read off the range, mode and median from the ordered series.'),
      L('O‘rtachani hisoblang (chastota bo‘lsa — tortilgan).', 'Вычислите среднее (при частотах — взвешенное).', 'Compute the mean (weighted if there are frequencies).'),
      L('Chetlanishlar jadvalini tuzing: xᵢ − x̄ va (xᵢ − x̄)²; ularning yig‘indisi bo‘yicha D va σ ni toping.', 'Составьте таблицу отклонений xᵢ − x̄ и (xᵢ − x̄)²; по их сумме найдите D и σ.', 'Make a table of deviations xᵢ − x̄ and (xᵢ − x̄)²; use their sum to find D and σ.'),
      L('Tekshiring: Σ(xᵢ − x̄) = 0 bo‘lishi kerak. Natijani so‘z bilan izohlang.', 'Проверьте: Σ(xᵢ − x̄) должна быть 0. Истолкуйте результат словами.', 'Check that Σ(xᵢ − x̄) = 0. Interpret the result in words.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar', 'Решённые примеры', 'Solved examples'), ex: [
      { q: L('10 o‘quvchining test ballari: 5, 7, 7, 8, 9, 10, 10, 10, 6, 8. x̄, Mo, Me, R, D va σ ni toping.', 'Баллы 10 учеников: 5, 7, 7, 8, 9, 10, 10, 10, 6, 8. Найдите x̄, Mo, Me, R, D и σ.', 'Test scores of 10 students: 5, 7, 7, 8, 9, 10, 10, 10, 6, 8. Find x̄, Mo, Me, R, D and σ.'), s: L('Tartib: 5, 6, 7, 7, 8, 8, 9, 10, 10, 10. Yig‘indi 80, x̄ = 8. Mo = 10 (3 marta). Me = (8 + 8)/2 = 8. R = 10 − 5 = 5. Chetlanishlar: −3, −2, −1, −1, 0, 0, 1, 2, 2, 2 (yig‘indi 0 ✓). Kvadratlar: 9, 4, 1, 1, 0, 0, 1, 4, 4, 4, yig‘indi 28. D = 2,8, σ = √2,8 ≈ 1,67.', 'Упорядочим: 5, 6, 7, 7, 8, 8, 9, 10, 10, 10. Сумма 80, x̄ = 8. Mo = 10 (3 раза). Me = (8 + 8)/2 = 8. R = 10 − 5 = 5. Отклонения: −3, −2, −1, −1, 0, 0, 1, 2, 2, 2 (сумма 0 ✓). Квадраты: 9, 4, 1, 1, 0, 0, 1, 4, 4, 4, сумма 28. D = 2,8, σ = √2,8 ≈ 1,67.', 'Ordered: 5, 6, 7, 7, 8, 8, 9, 10, 10, 10. Sum 80, x̄ = 8. Mo = 10 (3 times). Me = (8 + 8)/2 = 8. R = 10 − 5 = 5. Deviations: −3, −2, −1, −1, 0, 0, 1, 2, 2, 2 (sum 0 ✓). Squares: 9, 4, 1, 1, 0, 0, 1, 4, 4, 4, sum 28. D = 2.8, σ = √2.8 ≈ 1.67.') },
      { q: L('Sinfdagi baholar: «2» — 1 ta, «3» — 4 ta, «4» — 10 ta, «5» — 5 ta. O‘rtacha, moda, mediana va σ ni toping.', 'Оценки в классе: «2» — 1, «3» — 4, «4» — 10, «5» — 5. Найдите среднее, моду, медиану и σ.', 'Class grades: “2” — 1, “3” — 4, “4” — 10, “5” — 5. Find the mean, mode, median and σ.'), s: L('n = 20. x̄ = (2 + 12 + 40 + 25)/20 = 79/20 = 3,95. Mo = 4. Me: 10- va 11-o‘rindagi baholar (jamlanma chastotalar 1, 5, 15) — ikkalasi 4, Me = 4. Kvadratlar o‘rtachasi: (4 + 36 + 160 + 125)/20 = 16,25. D = 16,25 − 3,95² = 16,25 − 15,6025 = 0,6475, σ ≈ 0,80.', 'n = 20. x̄ = (2 + 12 + 40 + 25)/20 = 79/20 = 3,95. Mo = 4. Me: оценки на 10-м и 11-м местах (накопленные частоты 1, 5, 15) — обе 4, Me = 4. Среднее квадратов: (4 + 36 + 160 + 125)/20 = 16,25. D = 16,25 − 3,95² = 16,25 − 15,6025 = 0,6475, σ ≈ 0,80.', 'n = 20. x̄ = (2 + 12 + 40 + 25)/20 = 79/20 = 3.95. Mo = 4. Me: grades in positions 10 and 11 (cumulative frequencies 1, 5, 15) are both 4, so Me = 4. Mean of squares: (4 + 36 + 160 + 125)/20 = 16.25. D = 16.25 − 3.95² = 16.25 − 15.6025 = 0.6475, σ ≈ 0.80.') },
      { q: L('Kichik firmada 8 xodimning oylik maoshi (mln so‘m): 3, 3, 4, 4, 5, 5, 6, 30. «O‘rtacha maosh» haqida nima deyish mumkin?', 'Зарплаты 8 сотрудников фирмы (млн сумов): 3, 3, 4, 4, 5, 5, 6, 30. Что можно сказать о «средней зарплате»?', 'Monthly salaries of 8 employees (million sums): 3, 3, 4, 4, 5, 5, 6, 30. What can be said about the “average salary”?'), s: L('x̄ = 60/8 = 7,5 mln, Me = (4 + 5)/2 = 4,5 mln. 8 kishidan 7 tasi 7,5 dan kam oladi! Direktorning 30 mln lik maoshi o‘rtachani «tortib ketdi». Bu holda mediana odatiy maoshni yaxshiroq ifodalaydi.', 'x̄ = 60/8 = 7,5 млн, Me = (4 + 5)/2 = 4,5 млн. 7 из 8 человек получают меньше 7,5! Зарплата директора 30 млн «утянула» среднее. Здесь медиана лучше отражает типичную зарплату.', 'x̄ = 60/8 = 7.5 million, Me = (4 + 5)/2 = 4.5 million. Seven of the eight earn less than 7.5! The director’s 30 million “pulled” the mean up. Here the median describes a typical salary better.') },
      { q: L('Ikki mergan 4 tadan o‘q uzdi: A — 8, 8, 8, 8; B — 6, 10, 6, 10. Kim barqarorroq?', 'Два стрелка сделали по 4 выстрела: A — 8, 8, 8, 8; B — 6, 10, 6, 10. Кто стабильнее?', 'Two shooters fired 4 shots each: A — 8, 8, 8, 8; B — 6, 10, 6, 10. Who is more consistent?'), s: L('Ikkalasida ham x̄ = 8. A: barcha chetlanishlar 0, σ = 0. B: chetlanishlar ±2, D = 4, σ = 2. O‘rtacha bir xil, lekin A ancha barqaror. Faqat o‘rtachaga qarash yetarli emas!', 'У обоих x̄ = 8. A: все отклонения 0, σ = 0. B: отклонения ±2, D = 4, σ = 2. Среднее одинаковое, но A гораздо стабильнее. Смотреть только на среднее недостаточно!', 'Both have x̄ = 8. A: all deviations 0, σ = 0. B: deviations ±2, D = 4, σ = 2. Same mean, but A is far more consistent. Looking at the mean alone is not enough!') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Medianani tartiblanmagan qatordan olish.</b> Avval albatta o‘sish tartibida yozing.', '<b>Брать медиану из неупорядоченного ряда.</b> Сначала обязательно упорядочьте по возрастанию.', '<b>Taking the median from an unordered series.</b> Always sort the data first.'),
      L('<b>Modani chastotaning o‘zi deb yozish.</b> Moda — qiymat (masalan, 10 ball), uning chastotasi (3) emas.', '<b>Записывать моду как частоту.</b> Мода — значение (например, 10 баллов), а не его частота (3).', '<b>Writing the frequency instead of the mode.</b> The mode is the value (e.g. 10 points), not its frequency (3).'),
      L('<b>Chastotalar jadvalida oddiy o‘rtacha olish.</b> (2 + 3 + 4 + 5)/4 = 3,5 — xato; har bir qiymatni chastotasiga ko‘paytirish kerak (3,95).', '<b>Брать простое среднее в таблице частот.</b> (2 + 3 + 4 + 5)/4 = 3,5 — ошибка; каждое значение нужно умножить на частоту (3,95).', '<b>Taking a plain mean in a frequency table.</b> (2 + 3 + 4 + 5)/4 = 3.5 is wrong; each value must be multiplied by its frequency (3.95).'),
      L('<b>σ ni dispersiya bilan chalkashtirish.</b> σ = √D. D birligi — kvadrat birlik (sm²), σ niki — sm.', '<b>Путать σ и дисперсию.</b> σ = √D. Единица D — квадратная (см²), у σ — см.', '<b>Confusing σ with the variance.</b> σ = √D. D is in squared units (cm²), σ in cm.'),
      L('<b>Diagrammada o‘qni noldan boshlamaslik.</b> Ustunli diagrammada o‘qni 95 dan boshlash 96 va 98 orasidagi farqni ulkan qilib ko‘rsatadi — bu manipulyatsiyaning keng tarqalgan usuli.', '<b>Начинать ось диаграммы не с нуля.</b> Если в столбчатой диаграмме ось начинается с 95, разница между 96 и 98 выглядит огромной — распространённый приём манипуляции.', '<b>Not starting a chart axis at zero.</b> Starting a bar chart axis at 95 makes the gap between 96 and 98 look huge — a common manipulation trick.')
    ] },
    { kind: 'life', h: L('Statistika hayotda', 'Статистика в жизни', 'Statistics in real life'), p: [
      L('<b>Davlat va iqtisod:</b> aholi ro‘yxati, inflyatsiya, ishsizlik darajasi, o‘rtacha va median daromad — byudjet va ijtimoiy siyosat shu sonlar asosida tuziladi. <b>Sanoat:</b> zavod mahsulot sifatini nazorat qiladi — agar detal o‘lchamining σ si ruxsat etilgan chegaradan oshsa, uskunani sozlash vaqti keldi. <b>Ta’lim:</b> DTM test natijalari statistikasi savollar qiyinligini baholash va ballarni taqqoslash uchun ishlatiladi.', '<b>Государство и экономика:</b> перепись, инфляция, уровень безработицы, средний и медианный доход — бюджет и социальная политика строятся на этих числах. <b>Промышленность:</b> завод контролирует качество — если σ размера детали превысило допуск, пора настраивать оборудование. <b>Образование:</b> статистика результатов тестов используется для оценки трудности вопросов и сравнения баллов.', '<b>Government and economy:</b> census, inflation, unemployment rate, mean and median income — budgets and social policy are built on these numbers. <b>Industry:</b> a factory monitors quality — if the σ of a part’s size exceeds the tolerance, it is time to adjust the machine. <b>Education:</b> test result statistics are used to judge question difficulty and compare scores.'),
      L('<b>Sport:</b> futbolchining o‘rtacha yugurgan masofasi, basketbolchining to‘p tushirish foizi, merganning natijalari σ si — murabbiylar tarkibni shu ma’lumotlar asosida tanlaydi. <b>Ob-havo:</b> «iqlim me’yori» — 30 yillik o‘rtacha harorat; bugungi harorat undan qancha farq qilishi va bu farq σ ga nisbatan katta-kichikligi anomaliyani aniqlaydi. <b>Tibbiyot:</b> qon tahlilidagi «me’yor» oraliqlari sog‘lom odamlar tanlanmasining o‘rtacha ± 2σ chegaralaridir.', '<b>Спорт:</b> средняя дистанция футболиста, процент попаданий баскетболиста, σ результатов стрелка — тренеры выбирают состав на основе этих данных. <b>Погода:</b> «климатическая норма» — средняя температура за 30 лет; насколько сегодняшняя температура от неё отличается и велико ли это отличие относительно σ, определяет аномалию. <b>Медицина:</b> интервалы «нормы» в анализе крови — это границы среднее ± 2σ для выборки здоровых людей.', '<b>Sport:</b> a footballer’s average distance run, a basketball player’s shooting percentage, the σ of a shooter’s results — coaches pick teams from these data. <b>Weather:</b> the “climate normal” is the 30-year mean temperature; how far today’s temperature is from it, compared with σ, defines an anomaly. <b>Medicine:</b> “normal” ranges in blood tests are the mean ± 2σ limits for a sample of healthy people.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Deyarli hamma odamning oyoqlari soni «o‘rtachadan ko‘p»: oyog‘ini yo‘qotgan oz sonli odamlar tufayli o‘rtacha 2 dan biroz kam (masalan, 1,999), ko‘pchilikda esa 2 ta. Mediana va moda esa aynan 2.', 'Почти у всех людей число ног «больше среднего»: из-за немногих людей, потерявших ногу, среднее чуть меньше 2 (например, 1,999), а у большинства — 2. А медиана и мода ровно 2.', 'Almost everyone has “more legs than average”: because a few people have lost a leg, the mean is slightly below 2 (say 1.999), while most people have 2. The median and mode are exactly 2.'),
      L('«Statistika» so‘zi lotincha <i>status</i> — «davlat holati» so‘zidan kelib chiqqan: dastlab bu davlat haqidagi ma’lumotlar fani edi.', 'Слово «статистика» происходит от латинского <i>status</i> — «состояние государства»: сначала это была наука о сведениях про государство.', 'The word “statistics” comes from the Latin <i>status</i> — “state of the country”: it began as the science of facts about the state.'),
      L('Ingliz statistigi Frensis Enskomb 1973-yilda o‘rtachasi, dispersiyasi va regressiya chizig‘i bir xil, lekin grafiklari butunlay turlicha bo‘lgan 4 ta ma’lumotlar to‘plamini tuzdi («Enskomb kvarteti»). Xulosa: ma’lumotlarni doim chizib ko‘ring!', 'Английский статистик Фрэнсис Энскомб в 1973 году построил 4 набора данных с одинаковыми средними, дисперсиями и линиями регрессии, но совершенно разными графиками («квартет Энскомба»). Вывод: всегда рисуйте данные!', 'In 1973 the English statistician Francis Anscombe built 4 data sets with identical means, variances and regression lines but completely different graphs (“Anscombe’s quartet”). Lesson: always plot your data!')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Ma’lumotlar jadval, gistogramma, poligon, doiraviy diagramma bilan tasvirlanadi.', 'Данные изображают таблицей, гистограммой, полигоном, круговой диаграммой.', 'Data are shown by tables, histograms, polygons and pie charts.'),
      L('O‘rtacha x̄ = Σxᵢ/n (tortilgan: Σxᵢfᵢ/n); chetki qiymatlarga sezgir.', 'Среднее x̄ = Σxᵢ/n (взвешенное: Σxᵢfᵢ/n); чувствительно к выбросам.', 'Mean x̄ = Σxᵢ/n (weighted: Σxᵢfᵢ/n); sensitive to outliers.'),
      L('Moda — eng ko‘p uchraydigan qiymat; mediana — tartiblangan qator o‘rtasi.', 'Мода — самое частое значение; медиана — середина упорядоченного ряда.', 'Mode — the most frequent value; median — the middle of the ordered series.'),
      L('Kenglik R = max − min.', 'Размах R = max − min.', 'Range R = max − min.'),
      L('D = Σ(xᵢ − x̄)²/n = (kvadratlar o‘rtachasi) − x̄²; σ = √D.', 'D = Σ(xᵢ − x̄)²/n = (среднее квадратов) − x̄²; σ = √D.', 'D = Σ(xᵢ − x̄)²/n = (mean of squares) − x̄²; σ = √D.'),
      L('O‘rtacha va tarqoqlikni birga ko‘ring, ma’lumotlarni chizib tekshiring.', 'Смотрите на среднее и разброс вместе, проверяйте данные графиком.', 'Look at the mean and spread together, and always plot the data.')
    ] }
  ] });

  // ---------- t18. Ikki tur ma’lumotlar o‘rtasidagi bog‘liqlik ----------
  T.add(P, 't18', { sections: [
    { kind: 'intro', h: L('Bo‘y va vazn, o‘qish va baho', 'Рост и вес, учёба и оценка', 'Height and weight, study and grades'), p: [
      L('Uzun bo‘yli odamlar odatda og‘irroq bo‘ladimi? Ko‘proq o‘qigan o‘quvchi yuqoriroq ball oladimi? Narx oshsa, sotuv kamayadimi? Bu savollarning har birida bitta ob’ekt uchun <b>ikkita</b> miqdor o‘lchanadi va ular orasida bog‘liqlik bor-yo‘qligi so‘raladi. Bunday bog‘liqlik qat’iy funksional emas: bir xil bo‘yli ikki odam turli vaznda bo‘lishi mumkin. Lekin umumiy tendensiya — «biri oshsa, ikkinchisi ham odatda oshadi» — ko‘rinib turadi.', 'Обычно ли высокие люди тяжелее? Получает ли больше баллов тот, кто больше занимается? Падают ли продажи при росте цены? В каждом вопросе для одного объекта измеряются <b>две</b> величины и спрашивается, есть ли между ними связь. Эта связь не строго функциональная: два человека одного роста могут весить по-разному. Но общая тенденция — «одна растёт, и другая обычно растёт» — видна.', 'Are tall people usually heavier? Does a student who studies more get higher scores? Do sales fall when the price rises? In each question <b>two</b> quantities are measured for one object, and we ask whether they are related. The relation is not strictly functional: two people of the same height may weigh differently. But a general tendency — “when one grows, the other usually grows too” — is visible.'),
      L('Bu mavzuda bunday <b>statistik bog‘liqlik</b>ni ko‘rish (nuqtali diagramma), o‘lchash (korrelyatsiya koeffitsiyenti) va undan bashorat uchun foydalanish (regressiya to‘g‘ri chizig‘i) usullarini o‘rganamiz. Shuningdek, eng muhim ogohlantirishni eslab qolamiz: korrelyatsiya sabab-oqibatni isbotlamaydi.', 'В этой теме научимся видеть такую <b>статистическую связь</b> (диаграмма рассеяния), измерять её (коэффициент корреляции) и использовать для прогноза (линия регрессии). И запомним важнейшее предупреждение: корреляция не доказывает причинно-следственную связь.', 'In this topic we learn to see such a <b>statistical relationship</b> (scatter plot), measure it (correlation coefficient) and use it for prediction (regression line). We will also remember the key warning: correlation does not prove causation.')
    ] },
    { kind: 'def', h: L('Nuqtali diagramma va korrelyatsiya turlari', 'Диаграмма рассеяния и виды корреляции', 'Scatter plots and types of correlation'), p: [
      L('Har bir ob’ekt uchun (xᵢ; yᵢ) juftlik olinadi va koordinata tekisligida nuqta sifatida belgilanadi. Hosil bo‘lgan rasm — <b>nuqtali diagramma</b> (tarqoqlik diagrammasi). Nuqtalar «buluti»ning shakli bog‘liqlik haqida darhol ma’lumot beradi.', 'Для каждого объекта берётся пара (xᵢ; yᵢ) и отмечается точкой на координатной плоскости. Получается <b>диаграмма рассеяния</b>. Форма «облака» точек сразу говорит о характере связи.', 'For each object the pair (xᵢ; yᵢ) is plotted as a point in the coordinate plane. The result is a <b>scatter plot</b>. The shape of the “cloud” of points immediately tells us about the relationship.')
    ], list: [
      L('<b>Musbat korrelyatsiya:</b> nuqtalar o‘suvchi chiziq atrofida — x oshsa, y ham odatda oshadi (bo‘y va vazn).', '<b>Положительная корреляция:</b> точки вдоль возрастающей линии — с ростом x растёт и y (рост и вес).', '<b>Positive correlation:</b> points lie along a rising line — as x grows, y usually grows (height and weight).'),
      L('<b>Manfiy korrelyatsiya:</b> nuqtalar kamayuvchi chiziq atrofida — x oshsa, y kamayadi (avtomobil yoshi va narxi).', '<b>Отрицательная корреляция:</b> точки вдоль убывающей линии — с ростом x y убывает (возраст и цена автомобиля).', '<b>Negative correlation:</b> points lie along a falling line — as x grows, y decreases (a car’s age and price).'),
      L('<b>Korrelyatsiya yo‘q:</b> nuqtalar tartibsiz (bo‘y va matematika bahosi).', '<b>Корреляции нет:</b> точки хаотичны (рост и оценка по математике).', '<b>No correlation:</b> points are scattered randomly (height and maths grade).'),
      L('<b>Chiziqli bo‘lmagan bog‘liqlik:</b> nuqtalar egri chiziq (masalan, parabola) bo‘ylab joylashgan — bog‘liqlik kuchli, lekin chiziqli korrelyatsiya koeffitsiyenti uni sezmasligi mumkin.', '<b>Нелинейная связь:</b> точки вдоль кривой (например, параболы) — связь сильная, но линейный коэффициент корреляции может её не заметить.', '<b>Non-linear relationship:</b> points follow a curve (e.g. a parabola) — the link is strong, but the linear correlation coefficient may miss it.')
    ] },
    { kind: 'history', h: L('Galton, Pirson va eng kichik kvadratlar', 'Гальтон, Пирсон и наименьшие квадраты', 'Galton, Pearson and least squares'), p: [
      L('1805-yilda fransuz <b>Adrien Mari Lejandr</b> kuzatuvlarga eng mos chiziqni topishning <b>eng kichik kvadratlar usuli</b>ni nashr etdi. <b>Gauss</b> 1809-yilda bu usuldan 1795-yildan beri foydalanganini yozdi: aynan shu usul bilan u 1801-yilda yo‘qolib qolgan Tserera mitti sayyorasining orbitasini hisoblab, astronomlarga uni qayta topishda yordam bergan edi.', 'В 1805 году француз <b>Адриен Мари Лежандр</b> опубликовал <b>метод наименьших квадратов</b> для нахождения прямой, наилучшим образом соответствующей наблюдениям. <b>Гаусс</b> в 1809 году написал, что пользуется им с 1795 года: именно этим методом он в 1801 году рассчитал орбиту потерянной карликовой планеты Церера и помог астрономам снова её найти.', 'In 1805 the Frenchman <b>Adrien-Marie Legendre</b> published the <b>method of least squares</b> for finding the line that best fits observations. <b>Gauss</b> wrote in 1809 that he had used it since 1795: with this very method he had computed in 1801 the orbit of the lost dwarf planet Ceres, helping astronomers find it again.'),
      L('«Regressiya» so‘zi esa ingliz olimi <b>Frensis Galton</b>dan (Charlz Darvinning qarindoshi) qolgan. 1886-yilda u 205 oila ota-onalari va 928 nafar voyaga yetgan farzandlarining bo‘yini solishtirib, juda baland ota-onalarning farzandlari odatda ulardan pastroq, juda past ota-onalarning farzandlari esa balandroq bo‘lishini aniqladi. Galton buni «o‘rtachaga qaytish» (regression) deb atadi. Uning shogirdi <b>Karl Pirson</b> 1896-yilda korrelyatsiya koeffitsiyentining bugungi formulasini berdi.', 'Слово «регрессия» осталось от английского учёного <b>Фрэнсиса Гальтона</b> (родственника Чарльза Дарвина). В 1886 году он сравнил рост родителей из 205 семей и 928 их взрослых детей и обнаружил, что дети очень высоких родителей обычно ниже их, а дети очень низких — выше. Гальтон назвал это «возвратом к среднему» (regression). Его ученик <b>Карл Пирсон</b> в 1896 году дал современную формулу коэффициента корреляции.', 'The word “regression” comes from the English scientist <b>Francis Galton</b> (a relative of Charles Darwin). In 1886 he compared the heights of parents from 205 families with their 928 adult children and found that children of very tall parents are usually shorter than them, and children of very short parents taller. Galton called this “regression towards the mean”. His follower <b>Karl Pearson</b> gave the modern formula for the correlation coefficient in 1896.')
    ] },
    { kind: 'rule', h: L('Korrelyatsiya koeffitsiyenti', 'Коэффициент корреляции', 'The correlation coefficient'), p: [
      L('Bog‘liqlik kuchini bitta son bilan o‘lchash uchun <b>Pirson korrelyatsiya koeffitsiyenti</b> ishlatiladi. Avval chetlanishlarni hisoblaymiz: dxᵢ = xᵢ − x̄, dyᵢ = yᵢ − ȳ. So‘ng: <b>r = Σ(dxᵢ·dyᵢ) / √(Σdxᵢ² · Σdyᵢ²)</b>.', 'Чтобы измерить силу связи одним числом, используют <b>коэффициент корреляции Пирсона</b>. Сначала вычисляем отклонения: dxᵢ = xᵢ − x̄, dyᵢ = yᵢ − ȳ. Затем: <b>r = Σ(dxᵢ·dyᵢ) / √(Σdxᵢ² · Σdyᵢ²)</b>.', 'To measure the strength of a relationship with one number we use <b>Pearson’s correlation coefficient</b>. First compute the deviations dxᵢ = xᵢ − x̄ and dyᵢ = yᵢ − ȳ. Then: <b>r = Σ(dxᵢ·dyᵢ) / √(Σdxᵢ² · Σdyᵢ²)</b>.'),
      L('Ma’nosi: agar x va y birga o‘rtachadan yuqori yoki birga pastda bo‘lsa, dx·dy &gt; 0 va ular r ni oshiradi; agar biri yuqori, ikkinchisi past bo‘lsa, ko‘paytma manfiy. <b>Xossalari:</b> −1 ≤ r ≤ 1; r = 1 yoki r = −1 faqat barcha nuqtalar bitta to‘g‘ri chiziqda yotganda; r ≈ 0 — chiziqli bog‘liqlik yo‘q. Taxminiy shkala: |r| &gt; 0,7 — kuchli, 0,3–0,7 — o‘rtacha, |r| &lt; 0,3 — kuchsiz bog‘liqlik. r birliklarga bog‘liq emas: bo‘yni sm yoki metrda o‘lchash natijani o‘zgartirmaydi.', 'Смысл: если x и y вместе выше или вместе ниже среднего, dx·dy &gt; 0 и увеличивает r; если одно выше, а другое ниже — произведение отрицательно. <b>Свойства:</b> −1 ≤ r ≤ 1; r = 1 или r = −1 только когда все точки лежат на одной прямой; r ≈ 0 — линейной связи нет. Примерная шкала: |r| &gt; 0,7 — сильная, 0,3–0,7 — умеренная, |r| &lt; 0,3 — слабая связь. r не зависит от единиц: рост в см или в метрах — результат тот же.', 'Meaning: if x and y are above or below their means together, dx·dy &gt; 0 and pushes r up; if one is above and the other below, the product is negative. <b>Properties:</b> −1 ≤ r ≤ 1; r = 1 or r = −1 only when all points lie on one straight line; r ≈ 0 means no linear relationship. Rough scale: |r| &gt; 0.7 strong, 0.3–0.7 moderate, |r| &lt; 0.3 weak. r does not depend on units: height in cm or in metres gives the same result.')
    ] },
    { kind: 'rule', h: L('Regressiya to‘g‘ri chizig‘i', 'Линия регрессии', 'The regression line'), p: [
      L('Nuqtalar «buluti» orqali o‘tadigan eng mos to‘g‘ri chiziq y = kx + b <b>regressiya to‘g‘ri chizig‘i</b> deyiladi. «Eng mos» degani: nuqtalardan chiziqqacha bo‘lgan vertikal masofalar (qoldiqlar) kvadratlarining yig‘indisi eng kichik. Bu shartdan formulalar kelib chiqadi: <b>k = Σ(dxᵢ·dyᵢ)/Σdxᵢ²</b>, <b>b = ȳ − k·x̄</b>.', 'Наилучшая прямая y = kx + b, проходящая через «облако» точек, называется <b>линией регрессии</b>. «Наилучшая» значит: сумма квадратов вертикальных расстояний от точек до прямой (остатков) минимальна. Из этого условия следуют формулы: <b>k = Σ(dxᵢ·dyᵢ)/Σdxᵢ²</b>, <b>b = ȳ − k·x̄</b>.', 'The best-fitting line y = kx + b through the “cloud” of points is called the <b>regression line</b>. “Best” means the sum of squares of the vertical distances from the points to the line (the residuals) is minimal. This condition gives the formulas: <b>k = Σ(dxᵢ·dyᵢ)/Σdxᵢ²</b>, <b>b = ȳ − k·x̄</b>.'),
      L('Ikkinchi formuladan muhim xulosa: regressiya chizig‘i har doim (x̄; ȳ) — «o‘rtacha nuqta» orqali o‘tadi. k ning ishorasi r ning ishorasi bilan bir xil. Chiziq <b>bashorat</b> uchun ishlatiladi: yangi x berilsa, y ≈ kx + b. Lekin bashorat faqat kuzatilgan x lar oralig‘ida ishonchli (<b>interpolyatsiya</b>); oraliqdan tashqariga chiqish (<b>ekstrapolyatsiya</b>) xavfli.', 'Важный вывод из второй формулы: линия регрессии всегда проходит через (x̄; ȳ) — «среднюю точку». Знак k совпадает со знаком r. Прямая используется для <b>прогноза</b>: при новом x y ≈ kx + b. Но прогноз надёжен лишь внутри диапазона наблюдённых x (<b>интерполяция</b>); выход за него (<b>экстраполяция</b>) опасен.', 'An important consequence of the second formula: the regression line always passes through (x̄; ȳ), the “mean point”. The sign of k matches the sign of r. The line is used for <b>prediction</b>: for a new x, y ≈ kx + b. But prediction is reliable only within the range of observed x (<b>interpolation</b>); going beyond it (<b>extrapolation</b>) is risky.')
    ] },
    { kind: 'steps', h: L('Hisoblash algoritmi', 'Алгоритм вычислений', 'Computation algorithm'), list: [
      L('Nuqtali diagramma chizing — bog‘liqlik chiziqli ekaniga ishonch hosil qiling.', 'Постройте диаграмму рассеяния — убедитесь, что связь линейная.', 'Draw a scatter plot — make sure the relationship is linear.'),
      L('x̄ va ȳ ni toping.', 'Найдите x̄ и ȳ.', 'Find x̄ and ȳ.'),
      L('Jadval tuzing: dx, dy, dx·dy, dx², dy² ustunlari va ularning yig‘indilari.', 'Составьте таблицу со столбцами dx, dy, dx·dy, dx², dy² и их суммами.', 'Make a table with columns dx, dy, dx·dy, dx², dy² and their sums.'),
      L('r = Σdxdy/√(Σdx²·Σdy²), k = Σdxdy/Σdx², b = ȳ − kx̄.', 'r = Σdxdy/√(Σdx²·Σdy²), k = Σdxdy/Σdx², b = ȳ − kx̄.', 'r = Σdxdy/√(Σdx²·Σdy²), k = Σdxdy/Σdx², b = ȳ − kx̄.'),
      L('Natijani izohlang: bog‘liqlik kuchi va yo‘nalishi, k ning ma’nosi (x 1 birlikka oshsa, y o‘rtacha k ga o‘zgaradi).', 'Истолкуйте результат: сила и направление связи, смысл k (при росте x на 1 y в среднем меняется на k).', 'Interpret the result: strength and direction of the link, and the meaning of k (when x rises by 1, y changes on average by k).')
    ] },
    { kind: 'example', h: L('Yechilgan misollar', 'Решённые примеры', 'Solved examples'), ex: [
      { q: L('5 o‘quvchi: tayyorgarlik soatlari x = 1, 2, 3, 4, 5; test balli y = 50, 55, 65, 70, 80. r va regressiya chizig‘ini toping, 6 soat tayyorlangan o‘quvchi balini bashorat qiling.', '5 учеников: часы подготовки x = 1, 2, 3, 4, 5; баллы y = 50, 55, 65, 70, 80. Найдите r и линию регрессии, спрогнозируйте балл при 6 часах подготовки.', '5 students: study hours x = 1, 2, 3, 4, 5; scores y = 50, 55, 65, 70, 80. Find r and the regression line, and predict the score for 6 hours of study.'), s: L('x̄ = 3, ȳ = 64. dx: −2, −1, 0, 1, 2; dy: −14, −9, 1, 6, 16. Σdxdy = 28 + 9 + 0 + 6 + 32 = 75; Σdx² = 10; Σdy² = 196 + 81 + 1 + 36 + 256 = 570. r = 75/√5700 ≈ 75/75,5 ≈ 0,99 — juda kuchli musbat bog‘liqlik. k = 75/10 = 7,5; b = 64 − 7,5·3 = 41,5. y = 7,5x + 41,5. Har bir qo‘shimcha soat ≈ 7,5 ball. x = 6 da y ≈ 86,5.', 'x̄ = 3, ȳ = 64. dx: −2, −1, 0, 1, 2; dy: −14, −9, 1, 6, 16. Σdxdy = 28 + 9 + 0 + 6 + 32 = 75; Σdx² = 10; Σdy² = 196 + 81 + 1 + 36 + 256 = 570. r = 75/√5700 ≈ 75/75,5 ≈ 0,99 — очень сильная положительная связь. k = 75/10 = 7,5; b = 64 − 7,5·3 = 41,5. y = 7,5x + 41,5. Каждый дополнительный час ≈ 7,5 балла. При x = 6 y ≈ 86,5.', 'x̄ = 3, ȳ = 64. dx: −2, −1, 0, 1, 2; dy: −14, −9, 1, 6, 16. Σdxdy = 28 + 9 + 0 + 6 + 32 = 75; Σdx² = 10; Σdy² = 196 + 81 + 1 + 36 + 256 = 570. r = 75/√5700 ≈ 75/75.5 ≈ 0.99 — a very strong positive link. k = 75/10 = 7.5; b = 64 − 7.5·3 = 41.5. y = 7.5x + 41.5. Each extra hour ≈ 7.5 points. At x = 6, y ≈ 86.5.') },
      { q: L('Mahsulot narxi x (ming so‘m): 2, 4, 6, 8; kunlik sotuv y (dona): 9, 7, 4, 2. Bog‘liqlikni tahlil qiling.', 'Цена товара x (тыс. сумов): 2, 4, 6, 8; дневные продажи y (шт.): 9, 7, 4, 2. Проанализируйте связь.', 'Price x (thousand sums): 2, 4, 6, 8; daily sales y (units): 9, 7, 4, 2. Analyse the relationship.'), s: L('x̄ = 5, ȳ = 5,5. dx: −3, −1, 1, 3; dy: 3,5; 1,5; −1,5; −3,5. Σdxdy = −10,5 − 1,5 − 1,5 − 10,5 = −24; Σdx² = 20; Σdy² = 29. r = −24/√580 ≈ −0,997 — kuchli manfiy. k = −24/20 = −1,2; b = 5,5 + 1,2·5 = 11,5. y = −1,2x + 11,5: narx 1000 so‘mga oshsa, sotuv o‘rtacha 1,2 donaga kamayadi.', 'x̄ = 5, ȳ = 5,5. dx: −3, −1, 1, 3; dy: 3,5; 1,5; −1,5; −3,5. Σdxdy = −10,5 − 1,5 − 1,5 − 10,5 = −24; Σdx² = 20; Σdy² = 29. r = −24/√580 ≈ −0,997 — сильная отрицательная. k = −24/20 = −1,2; b = 5,5 + 1,2·5 = 11,5. y = −1,2x + 11,5: при росте цены на 1000 сумов продажи падают в среднем на 1,2 шт.', 'x̄ = 5, ȳ = 5.5. dx: −3, −1, 1, 3; dy: 3.5, 1.5, −1.5, −3.5. Σdxdy = −10.5 − 1.5 − 1.5 − 10.5 = −24; Σdx² = 20; Σdy² = 29. r = −24/√580 ≈ −0.997 — strongly negative. k = −24/20 = −1.2; b = 5.5 + 1.2·5 = 11.5. y = −1.2x + 11.5: each 1000-sum price rise cuts sales by 1.2 units on average.') },
      { q: L('x = −2, −1, 0, 1, 2 va y = x² ma’lumotlari uchun r ni toping. Xulosa?', 'Найдите r для данных x = −2, −1, 0, 1, 2 и y = x². Вывод?', 'Find r for the data x = −2, −1, 0, 1, 2 and y = x². Conclusion?'), s: L('y: 4, 1, 0, 1, 4; x̄ = 0, ȳ = 2. dx·dy: (−2)(2) + (−1)(−1) + 0 + (1)(−1) + (2)(2) = −4 + 1 + 0 − 1 + 4 = 0. r = 0! Lekin y aniq x ga bog‘liq (y = x²). Demak, r = 0 «bog‘liqlik yo‘q» degani emas — faqat <b>chiziqli</b> bog‘liqlik yo‘q.', 'y: 4, 1, 0, 1, 4; x̄ = 0, ȳ = 2. dx·dy: (−2)(2) + (−1)(−1) + 0 + (1)(−1) + (2)(2) = −4 + 1 + 0 − 1 + 4 = 0. r = 0! Но y точно зависит от x (y = x²). Значит, r = 0 не означает «связи нет» — нет лишь <b>линейной</b> связи.', 'y: 4, 1, 0, 1, 4; x̄ = 0, ȳ = 2. dx·dy: (−2)(2) + (−1)(−1) + 0 + (1)(−1) + (2)(2) = −4 + 1 + 0 − 1 + 4 = 0. r = 0! Yet y depends exactly on x (y = x²). So r = 0 does not mean “no relationship” — only no <b>linear</b> relationship.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Korrelyatsiyani sabab deb bilish.</b> Yozda muzqaymoq sotuvi va cho‘kish hodisalari birga oshadi, lekin muzqaymoq cho‘ktirmaydi — ikkalasining umumiy sababi issiq havo (<b>yashirin omil</b>).', '<b>Считать корреляцию причиной.</b> Летом продажи мороженого и случаи утопления растут вместе, но мороженое не топит — общая причина обоих жара (<b>скрытый фактор</b>).', '<b>Treating correlation as causation.</b> In summer ice-cream sales and drownings rise together, but ice cream does not drown anyone — both are caused by hot weather (a <b>hidden factor</b>).'),
      L('<b>Ekstrapolyatsiya.</b> 1–5 soat ma’lumotidan «20 soat o‘qisa, 191,5 ball oladi» degan xulosa absurd — maksimal ball 100.', '<b>Экстраполяция.</b> Вывод по данным 1–5 часов «за 20 часов будет 191,5 балла» абсурден — максимум 100.', '<b>Extrapolation.</b> Concluding from 1–5 hours that “20 hours gives 191.5 points” is absurd — the maximum is 100.'),
      L('<b>r = 0 ni «hech qanday bog‘liqlik yo‘q» deb tushunish.</b> Egri chiziqli bog‘liqlikda r nolga yaqin bo‘lishi mumkin.', '<b>Понимать r = 0 как «нет никакой связи».</b> При криволинейной связи r может быть близок к нулю.', '<b>Reading r = 0 as “no relationship at all”.</b> With a curved relationship r can be close to zero.'),
      L('<b>Chetki nuqtani e’tiborsiz qoldirish.</b> Bitta xato o‘lchov r ni 0,9 dan 0,3 gacha tushirishi yoki aksincha oshirishi mumkin. Diagrammani doim ko‘zdan kechiring.', '<b>Игнорировать выброс.</b> Одно ошибочное измерение может опустить r с 0,9 до 0,3 или наоборот поднять. Всегда смотрите на диаграмму.', '<b>Ignoring an outlier.</b> A single wrong measurement can drop r from 0.9 to 0.3 or push it up. Always look at the plot.'),
      L('<b>Kichik tanlanmaga ishonish.</b> 3–4 nuqtada tasodifan yuqori r chiqishi oson; ishonchli xulosa uchun ko‘proq ma’lumot kerak.', '<b>Доверять маленькой выборке.</b> На 3–4 точках высокий r легко получается случайно; для надёжного вывода нужно больше данных.', '<b>Trusting a tiny sample.</b> With 3–4 points a high r easily appears by chance; reliable conclusions need more data.')
    ] },
    { kind: 'life', h: L('Bog‘liqlik tahlili hayotda', 'Анализ связей в жизни', 'Relationship analysis in real life'), p: [
      L('<b>Tibbiyot:</b> chekish va o‘pka saratoni orasidagi kuchli korrelyatsiya 1950-yillarda aniqlangan; sabab-oqibat ekanini isbotlash uchun esa yillab davom etgan qo‘shimcha tadqiqotlar kerak bo‘lgan. Shifokorlar bo‘y va yoshga ko‘ra me’yoriy vaznni regressiya jadvallari asosida baholaydi. <b>Iqtisod:</b> reklama xarajati va sotuv, daromad va iste’mol orasidagi regressiya biznes rejalashtirishning asosi.', '<b>Медицина:</b> сильную корреляцию между курением и раком лёгких обнаружили в 1950-х; чтобы доказать причинность, понадобились многолетние дополнительные исследования. Врачи оценивают нормальный вес по росту и возрасту по регрессионным таблицам. <b>Экономика:</b> регрессия между расходами на рекламу и продажами, доходом и потреблением — основа бизнес-планирования.', '<b>Medicine:</b> the strong correlation between smoking and lung cancer was found in the 1950s; proving causation took years of further research. Doctors judge normal weight for height and age using regression tables. <b>Economics:</b> regression between advertising spend and sales, or income and consumption, underpins business planning.'),
      L('<b>Sun’iy intellekt:</b> chiziqli regressiya — mashinali o‘qitishning eng oddiy modeli; murakkab neyron tarmoqlar ham aslida «xatolar kvadratlari yig‘indisini kamaytirish» g‘oyasiga tayanadi. <b>Ko‘chmas mulk:</b> kvartira narxi maydon, xonalar soni va joylashuvga regressiya orqali baholanadi. <b>Qishloq xo‘jaligi:</b> o‘g‘it miqdori va hosildorlik bog‘liqligi optimal me’yorni topishga yordam beradi.', '<b>Искусственный интеллект:</b> линейная регрессия — простейшая модель машинного обучения; и сложные нейросети по сути опираются на идею «минимизировать сумму квадратов ошибок». <b>Недвижимость:</b> цену квартиры оценивают регрессией по площади, числу комнат и расположению. <b>Сельское хозяйство:</b> связь количества удобрений и урожайности помогает найти оптимальную норму.', '<b>Artificial intelligence:</b> linear regression is the simplest machine-learning model; even complex neural networks rely on the idea of “minimising the sum of squared errors”. <b>Real estate:</b> apartment prices are estimated by regression on area, rooms and location. <b>Agriculture:</b> the link between fertiliser amount and yield helps find the optimal dose.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Tayler Vigen «soxta korrelyatsiyalar» to‘plamini yaratgan: masalan, AQShda yillar bo‘yicha Nikolas Keyj ishtirokidagi filmlar soni va hovuzda cho‘kish holatlari soni yuqori korrelyatsiyaga ega. Tasodifiy moslik — sabab emas!', 'Тайлер Виген собрал коллекцию «ложных корреляций»: например, число фильмов с Николасом Кейджем по годам и число утоплений в бассейнах в США сильно коррелируют. Случайное совпадение — не причина!', 'Tyler Vigen collected “spurious correlations”: for example, the number of Nicolas Cage films per year and the number of swimming-pool drownings in the USA are highly correlated. Coincidence is not cause!'),
      L('Sportdagi «ikkinchi mavsum inqirozi» ko‘pincha Galtonning o‘rtachaga qaytish hodisasi: rekord natija qisman omad tufayli bo‘ladi, keyingi mavsumda natija o‘rtachaga yaqinlashadi.', '«Синдром второго сезона» в спорте часто — гальтоновский возврат к среднему: рекордный результат отчасти обусловлен удачей, и в следующем сезоне результат приближается к среднему.', 'The “sophomore slump” in sport is often Galton’s regression to the mean: a record result is partly luck, so next season the result drifts back towards average.'),
      L('r² soni <b>determinatsiya koeffitsiyenti</b> deyiladi: r = 0,99 bo‘lsa, r² ≈ 0,98 — y o‘zgarishining taxminan 98% i x bilan tushuntiriladi.', 'Число r² называют <b>коэффициентом детерминации</b>: при r = 0,99 r² ≈ 0,98 — примерно 98% изменения y объясняется x.', 'The number r² is called the <b>coefficient of determination</b>: if r = 0.99, r² ≈ 0.98 — about 98% of the variation in y is explained by x.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('x = 1, 2, 3; y = 3, 5, 7 uchun r va regressiya chizig‘ini toping.', 'Найдите r и линию регрессии для x = 1, 2, 3; y = 3, 5, 7.', 'Find r and the regression line for x = 1, 2, 3; y = 3, 5, 7.'),
      L('r = −0,85 qanday bog‘liqlikni bildiradi?', 'Какую связь означает r = −0,85?', 'What relationship does r = −0.85 indicate?'),
      L('Regressiya chizig‘i y = 2x + 5, x̄ = 4. ȳ = ?', 'Линия регрессии y = 2x + 5, x̄ = 4. ȳ = ?', 'The regression line is y = 2x + 5 and x̄ = 4. ȳ = ?')
    ], after: [
      L('Javoblar: nuqtalar y = 2x + 1 to‘g‘ri chiziqda yotadi, r = 1; kuchli manfiy chiziqli bog‘liqlik; chiziq (x̄; ȳ) dan o‘tadi: ȳ = 2·4 + 5 = 13.', 'Ответы: точки лежат на прямой y = 2x + 1, r = 1; сильная отрицательная линейная связь; прямая проходит через (x̄; ȳ): ȳ = 2·4 + 5 = 13.', 'Answers: the points lie on y = 2x + 1, so r = 1; a strong negative linear relationship; the line passes through (x̄; ȳ): ȳ = 2·4 + 5 = 13.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Ikki o‘zgaruvchi juftliklari nuqtali diagrammada tasvirlanadi.', 'Пары двух переменных изображают на диаграмме рассеяния.', 'Pairs of two variables are shown on a scatter plot.'),
      L('Musbat, manfiy korrelyatsiya yoki bog‘liqlik yo‘qligi nuqtalar shaklidan ko‘rinadi.', 'Положительная, отрицательная корреляция или её отсутствие видны по форме облака.', 'Positive, negative or no correlation is visible from the shape of the cloud.'),
      L('r = Σdxdy/√(Σdx²·Σdy²), −1 ≤ r ≤ 1; |r| = 1 — barcha nuqtalar bir to‘g‘ri chiziqda.', 'r = Σdxdy/√(Σdx²·Σdy²), −1 ≤ r ≤ 1; |r| = 1 — все точки на одной прямой.', 'r = Σdxdy/√(Σdx²·Σdy²), −1 ≤ r ≤ 1; |r| = 1 means all points on one line.'),
      L('Regressiya: y = kx + b, k = Σdxdy/Σdx², b = ȳ − kx̄; chiziq (x̄; ȳ) dan o‘tadi.', 'Регрессия: y = kx + b, k = Σdxdy/Σdx², b = ȳ − kx̄; прямая проходит через (x̄; ȳ).', 'Regression: y = kx + b, k = Σdxdy/Σdx², b = ȳ − kx̄; the line passes through (x̄; ȳ).'),
      L('Bashorat faqat kuzatilgan oraliq ichida ishonchli.', 'Прогноз надёжен лишь внутри наблюдённого диапазона.', 'Prediction is reliable only inside the observed range.'),
      L('Korrelyatsiya sabab-oqibatni isbotlamaydi!', 'Корреляция не доказывает причинно-следственную связь!', 'Correlation does not prove causation!')
    ] }
  ] });

  // ---------- t19. Hodisalar va ehtimollik ----------
  T.add(P, 't19', { sections: [
    { kind: 'intro', h: L('Tasodifni o‘lchash mumkinmi?', 'Можно ли измерить случайность?', 'Can chance be measured?'), p: [
      L('Tanga tashlanganda gerb tushishini oldindan bilib bo‘lmaydi. Ertaga yomg‘ir yog‘ishi, lotereyada yutish, imtihonda tanish bilet chiqishi ham tasodifga bog‘liq. Lekin tasodif ham o‘z qonunlariga ega: tangani 1000 marta tashlasangiz, gerb taxminan 500 marta tushadi. <b>Ehtimollar nazariyasi</b> — tasodifiy hodisalarning qanchalik «kutilgan» ekanini son bilan o‘lchaydigan fan.', 'Нельзя заранее знать, выпадет ли герб при броске монеты. Дождь завтра, выигрыш в лотерею, знакомый билет на экзамене — тоже дело случая. Но и у случая есть законы: бросьте монету 1000 раз — герб выпадет примерно 500 раз. <b>Теория вероятностей</b> — наука, измеряющая числом, насколько «ожидаемо» случайное событие.', 'You cannot know in advance whether a tossed coin will land heads. Rain tomorrow, winning the lottery, getting a familiar exam ticket are matters of chance too. But chance has laws: toss a coin 1000 times and heads will come up about 500 times. <b>Probability theory</b> is the science that measures with a number how “expected” a random event is.'),
      L('Bu mavzuda hodisalar turlari va ular ustidagi amallarni, ehtimolning klassik ta’rifini, hamda ikkita asosiy qoidani — <b>qo‘shish</b> («yoki» uchun) va <b>ko‘paytirish</b> («va» uchun) teoremalarini o‘rganamiz. Ular kombinatorika bilan birga deyarli barcha maktab masalalarini yechish imkonini beradi.', 'В этой теме изучим виды событий и действия над ними, классическое определение вероятности, а также два главных правила — теоремы <b>сложения</b> (для «или») и <b>умножения</b> (для «и»). Вместе с комбинаторикой они позволяют решать почти все школьные задачи.', 'In this topic we study kinds of events and operations on them, the classical definition of probability, and two main rules — the <b>addition</b> theorem (for “or”) and the <b>multiplication</b> theorem (for “and”). Together with combinatorics they solve almost every school problem.')
    ] },
    { kind: 'def', h: L('Tajriba, natija, hodisa', 'Опыт, исход, событие', 'Experiment, outcome, event'), p: [
      L('<b>Tajriba</b> (sinov) — natijasi tasodifga bog‘liq bo‘lgan harakat: kubik tashlash, kartani tortib olish. Tajribaning bo‘linmas natijalari — <b>elementar hodisalar</b>, ularning to‘plami — <b>elementar hodisalar fazosi</b> Ω. Kubik uchun Ω = {1, 2, 3, 4, 5, 6}. <b>Hodisa</b> — Ω ning qism to‘plami: A = «juft son tushdi» = {2, 4, 6}.', '<b>Опыт</b> (испытание) — действие, исход которого зависит от случая: бросок кубика, вытягивание карты. Неделимые исходы опыта — <b>элементарные события</b>, их множество — <b>пространство элементарных событий</b> Ω. Для кубика Ω = {1, 2, 3, 4, 5, 6}. <b>Событие</b> — подмножество Ω: A = «выпало чётное» = {2, 4, 6}.', 'An <b>experiment</b> (trial) is an action whose result depends on chance: rolling a die, drawing a card. The indivisible results are <b>elementary outcomes</b>, and their set is the <b>sample space</b> Ω. For a die, Ω = {1, 2, 3, 4, 5, 6}. An <b>event</b> is a subset of Ω: A = “an even number” = {2, 4, 6}.'),
      L('Har doim ro‘y beradigan hodisa — <b>muqarrar</b> (Ω, ehtimoli 1), hech qachon ro‘y bermaydigani — <b>mumkin bo‘lmagan</b> (∅, ehtimoli 0), qolganlari — <b>tasodifiy</b>. Bir vaqtda ro‘y bera olmaydigan hodisalar <b>birgalikda bo‘lmagan</b> deyiladi. <b>Klassik ta’rif:</b> agar tajribaning n ta teng imkoniyatli natijasidan m tasi A ga qulay bo‘lsa, <b>P(A) = m/n</b>. Doim 0 ≤ P(A) ≤ 1.', 'Событие, которое происходит всегда, — <b>достоверное</b> (Ω, вероятность 1), никогда — <b>невозможное</b> (∅, вероятность 0), остальные — <b>случайные</b>. События, которые не могут произойти одновременно, называются <b>несовместными</b>. <b>Классическое определение:</b> если из n равновозможных исходов опыта m благоприятствуют A, то <b>P(A) = m/n</b>. Всегда 0 ≤ P(A) ≤ 1.', 'An event that always happens is <b>certain</b> (Ω, probability 1); one that never happens is <b>impossible</b> (∅, probability 0); the rest are <b>random</b>. Events that cannot happen together are called <b>mutually exclusive</b>. <b>Classical definition:</b> if m of the n equally likely outcomes favour A, then <b>P(A) = m/n</b>. Always 0 ≤ P(A) ≤ 1.')
    ] },
    { kind: 'history', h: L('Qimor stolidan aksiomalargacha', 'От игорного стола к аксиомам', 'From the gaming table to axioms'), p: [
      L('Italyan shifokori va matematigi <b>Jerolamo Kardano</b> taxminan 1564-yilda «Tasodifiy o‘yinlar haqida kitob» yozdi (1663-yilda nashr etilgan) — unda ehtimolni qulay va barcha natijalar nisbati sifatida hisoblash g‘oyasi bor edi. 1654-yilda fransuz zodagoni shevalye de Mere <b>Paskal</b>ga savol berdi: nega bitta kubikni 4 marta tashlab kamida bitta «6» olishga tikish foydali, ikkita kubikni 24 marta tashlab kamida bitta «6–6» olishga tikish esa zararli? Paskal va <b>Ferma</b> yozishmalari ehtimollar nazariyasining tug‘ilgan kuni hisoblanadi.', 'Итальянский врач и математик <b>Джероламо Кардано</b> около 1564 года написал «Книгу об играх случая» (издана в 1663) — в ней была идея считать вероятность как отношение благоприятных исходов ко всем. В 1654 году французский дворянин шевалье де Мере задал <b>Паскалю</b> вопрос: почему выгодно ставить на хотя бы одну «6» при 4 бросках кубика, но невыгодно — на хотя бы одну «6–6» при 24 бросках двух кубиков? Переписка Паскаля и <b>Ферма</b> считается днём рождения теории вероятностей.', 'The Italian physician and mathematician <b>Gerolamo Cardano</b> wrote “The Book on Games of Chance” around 1564 (published 1663) — it contained the idea of computing probability as favourable over all outcomes. In 1654 the French nobleman Chevalier de Méré asked <b>Pascal</b>: why is it profitable to bet on at least one “6” in 4 rolls of a die, but unprofitable to bet on at least one double six in 24 rolls of two dice? The correspondence of Pascal and <b>Fermat</b> is regarded as the birth of probability theory.'),
      L('1657-yilda gollandiyalik <b>Kristian Gyuygens</b> bu sohadagi birinchi bosma darslikni chiqardi. Keyinchalik Bernulli, Muavr, Laplas va Gauss nazariyani rivojlantirdi. 1933-yilda rus matematigi <b>Andrey Kolmogorov</b> ehtimollar nazariyasini to‘plamlar nazariyasiga asoslangan aksiomalar tizimi sifatida qurdi va u to‘laqonli matematik fanga aylandi.', 'В 1657 году голландец <b>Христиан Гюйгенс</b> выпустил первый печатный учебник в этой области. Затем теорию развивали Бернулли, Муавр, Лаплас и Гаусс. В 1933 году русский математик <b>Андрей Колмогоров</b> построил теорию вероятностей как систему аксиом на основе теории множеств, и она стала полноценной математической наукой.', 'In 1657 the Dutchman <b>Christiaan Huygens</b> published the first printed textbook in the field. Later Bernoulli, de Moivre, Laplace and Gauss developed the theory. In 1933 the Russian mathematician <b>Andrey Kolmogorov</b> built probability theory as an axiom system based on set theory, and it became a full-fledged branch of mathematics.')
    ] },
    { kind: 'def', h: L('Hodisalar ustida amallar', 'Действия над событиями', 'Operations on events'), p: [
      L('Hodisalar to‘plamlar bo‘lgani uchun ular ustidagi amallar <b>Eyler–Venn diagrammalari</b>da qulay tasvirlanadi: to‘g‘ri to‘rtburchak — Ω, doiralar — hodisalar.', 'Так как события — множества, действия над ними удобно изображать <b>диаграммами Эйлера–Венна</b>: прямоугольник — Ω, круги — события.', 'Since events are sets, operations on them are conveniently drawn with <b>Euler–Venn diagrams</b>: the rectangle is Ω, circles are events.')
    ], list: [
      L('<b>Yig‘indi</b> (birlashma) A ∪ B (yoki A + B) — «A yoki B (yoki ikkalasi) ro‘y berdi».', '<b>Сумма</b> (объединение) A ∪ B (или A + B) — «произошло A или B (или оба)».', '<b>Sum</b> (union) A ∪ B (or A + B) — “A or B (or both) occurred”.'),
      L('<b>Ko‘paytma</b> (kesishma) A ∩ B (yoki AB) — «A ham, B ham ro‘y berdi».', '<b>Произведение</b> (пересечение) A ∩ B (или AB) — «произошли и A, и B».', '<b>Product</b> (intersection) A ∩ B (or AB) — “both A and B occurred”.'),
      L('<b>Qarama-qarshi hodisa</b> Ā — «A ro‘y bermadi». P(Ā) = 1 − P(A). «Kamida bitta» so‘zi bor masalalarda bu formula ayniqsa foydali: P(kamida bitta) = 1 − P(hech biri).', '<b>Противоположное событие</b> Ā — «A не произошло». P(Ā) = 1 − P(A). В задачах со словами «хотя бы один» эта формула особенно полезна: P(хотя бы один) = 1 − P(ни одного).', 'The <b>complementary event</b> Ā — “A did not occur”. P(Ā) = 1 − P(A). It is especially useful in “at least one” problems: P(at least one) = 1 − P(none).'),
      L('A va B <b>birgalikda bo‘lmagan</b>: A ∩ B = ∅ (doiralar kesishmaydi).', 'A и B <b>несовместны</b>: A ∩ B = ∅ (круги не пересекаются).', 'A and B are <b>mutually exclusive</b>: A ∩ B = ∅ (the circles do not overlap).')
    ] },
    { kind: 'rule', h: L('Qo‘shish teoremasi', 'Теорема сложения', 'The addition theorem'), p: [
      L('Birgalikda bo‘lmagan hodisalar uchun: <b>P(A ∪ B) = P(A) + P(B)</b>. Umumiy holda: <b>P(A ∪ B) = P(A) + P(B) − P(A ∩ B)</b>. Isbot g‘oyasi: A va B ga qulay natijalarni qo‘shganda, ikkalasiga ham qulay natijalar (kesishma) ikki marta sanaladi — shuning uchun ularni bir marta ayiramiz. Venn diagrammasida bu ikki doira umumiy qismining ikki marta bo‘yalishiga o‘xshaydi.', 'Для несовместных событий: <b>P(A ∪ B) = P(A) + P(B)</b>. В общем случае: <b>P(A ∪ B) = P(A) + P(B) − P(A ∩ B)</b>. Идея доказательства: при сложении исходов, благоприятных A и B, исходы, благоприятные обоим (пересечение), считаются дважды — поэтому их один раз вычитаем. На диаграмме Венна это как дважды закрашенная общая часть двух кругов.', 'For mutually exclusive events: <b>P(A ∪ B) = P(A) + P(B)</b>. In general: <b>P(A ∪ B) = P(A) + P(B) − P(A ∩ B)</b>. Proof idea: adding the outcomes favourable to A and to B counts the outcomes favourable to both (the intersection) twice — so we subtract them once. On a Venn diagram this is like the overlap of two circles being shaded twice.')
    ] },
    { kind: 'rule', h: L('Shartli ehtimol va ko‘paytirish teoremasi', 'Условная вероятность и теорема умножения', 'Conditional probability and the multiplication theorem'), p: [
      L('<b>Shartli ehtimol</b> P(B|A) — A ro‘y bergani ma’lum bo‘lganda B ning ehtimoli: P(B|A) = P(A ∩ B)/P(A). Bundan <b>ko‘paytirish teoremasi</b>: <b>P(A ∩ B) = P(A)·P(B|A)</b>. Masalan, qutida 5 qizil va 3 ko‘k shar bor; ketma-ket qaytarmasdan 2 ta olinadi. Birinchisi qizil: 5/8; shundan keyin qutida 4 qizil va 3 ko‘k qoladi, ikkinchisi qizil: 4/7. Ikkalasi qizil: 5/8·4/7 = 5/14.', '<b>Условная вероятность</b> P(B|A) — вероятность B при условии, что A произошло: P(B|A) = P(A ∩ B)/P(A). Отсюда <b>теорема умножения</b>: <b>P(A ∩ B) = P(A)·P(B|A)</b>. Например, в урне 5 красных и 3 синих шара; подряд без возвращения вынимают 2. Первый красный: 5/8; после этого остаются 4 красных и 3 синих, второй красный: 4/7. Оба красные: 5/8·4/7 = 5/14.', 'The <b>conditional probability</b> P(B|A) is the probability of B given that A has occurred: P(B|A) = P(A ∩ B)/P(A). Hence the <b>multiplication theorem</b>: <b>P(A ∩ B) = P(A)·P(B|A)</b>. For example, a box holds 5 red and 3 blue balls; 2 are drawn in a row without replacement. First red: 5/8; then 4 red and 3 blue remain, so second red: 4/7. Both red: 5/8·4/7 = 5/14.'),
      L('Agar bir hodisaning ro‘y berishi ikkinchisining ehtimoliga ta’sir qilmasa (P(B|A) = P(B)), hodisalar <b>erkli</b> (bog‘liq emas) deyiladi va <b>P(A ∩ B) = P(A)·P(B)</b>. Tanga va kubikni tashlash, sharni qaytarib olish, turli merganlarning o‘q uzishi — erkli hodisalarga misol. Diqqat: «birgalikda bo‘lmagan» va «erkli» — butunlay boshqa tushunchalar; musbat ehtimolli birgalikda bo‘lmagan hodisalar doim bog‘liq.', 'Если наступление одного события не влияет на вероятность другого (P(B|A) = P(B)), события называются <b>независимыми</b> и <b>P(A ∩ B) = P(A)·P(B)</b>. Броски монеты и кубика, вынимание шара с возвращением, выстрелы разных стрелков — примеры независимых событий. Внимание: «несовместные» и «независимые» — совсем разные понятия; несовместные события с положительными вероятностями всегда зависимы.', 'If the occurrence of one event does not affect the probability of the other (P(B|A) = P(B)), the events are <b>independent</b> and <b>P(A ∩ B) = P(A)·P(B)</b>. Tossing a coin and a die, drawing with replacement, shots by different shooters are examples. Note: “mutually exclusive” and “independent” are completely different notions; mutually exclusive events with positive probabilities are always dependent.')
    ] },
    { kind: 'steps', h: L('Masalani yechish tartibi', 'Порядок решения задачи', 'How to solve a problem'), list: [
      L('Tajribani va natijalar fazosini aniqlang; natijalar teng imkoniyatli ekanini tekshiring.', 'Определите опыт и пространство исходов; проверьте, что исходы равновозможны.', 'Identify the experiment and the sample space; check that outcomes are equally likely.'),
      L('Hodisani so‘z bilan aniq yozing va kalit so‘zlarni toping: «yoki» → qo‘shish, «va» → ko‘paytirish, «kamida bitta» → qarama-qarshi hodisa.', 'Точно запишите событие словами и найдите ключевые слова: «или» → сложение, «и» → умножение, «хотя бы один» → противоположное событие.', 'Write the event precisely in words and spot the key words: “or” → addition, “and” → multiplication, “at least one” → complement.'),
      L('Birgalikda bo‘lmaslik va erklilikni tekshiring — qaysi formula qo‘llanishini shu belgilaydi.', 'Проверьте несовместность и независимость — от этого зависит, какую формулу применять.', 'Check exclusivity and independence — this decides which formula applies.'),
      L('Kerak bo‘lsa, m va n ni kombinatorika bilan hisoblang.', 'При необходимости вычислите m и n комбинаторикой.', 'If needed, count m and n with combinatorics.'),
      L('Javob 0 va 1 orasida ekanini tekshiring.', 'Проверьте, что ответ между 0 и 1.', 'Check that the answer lies between 0 and 1.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar', 'Решённые примеры', 'Solved examples'), ex: [
      { q: L('Kubik tashlandi. A = «juft son», B = «5 dan kichik emas». P(A ∪ B) ni toping.', 'Брошен кубик. A = «чётное», B = «не меньше 5». Найдите P(A ∪ B).', 'A die is rolled. A = “even”, B = “at least 5”. Find P(A ∪ B).'), s: L('A = {2, 4, 6}, P(A) = 1/2; B = {5, 6}, P(B) = 1/3; A ∩ B = {6}, P = 1/6. P(A ∪ B) = 1/2 + 1/3 − 1/6 = 4/6 = 2/3. Tekshiruv: A ∪ B = {2, 4, 5, 6} — 4 ta natija, 4/6 ✓.', 'A = {2, 4, 6}, P(A) = 1/2; B = {5, 6}, P(B) = 1/3; A ∩ B = {6}, P = 1/6. P(A ∪ B) = 1/2 + 1/3 − 1/6 = 4/6 = 2/3. Проверка: A ∪ B = {2, 4, 5, 6} — 4 исхода, 4/6 ✓.', 'A = {2, 4, 6}, P(A) = 1/2; B = {5, 6}, P(B) = 1/3; A ∩ B = {6}, P = 1/6. P(A ∪ B) = 1/2 + 1/3 − 1/6 = 4/6 = 2/3. Check: A ∪ B = {2, 4, 5, 6}, 4 outcomes, 4/6 ✓.') },
      { q: L('Ikki kubik tashlandi. Ochkolar yig‘indisi 7 bo‘lishi va kamida bitta «6» tushishi ehtimoli?', 'Брошены два кубика. Вероятность, что сумма очков 7, и что выпадет хотя бы одна «6»?', 'Two dice are rolled. Probability that the sum is 7, and that at least one “6” appears?'), s: L('n = 6·6 = 36. Yig‘indi 7: (1;6), (2;5), (3;4), (4;3), (5;2), (6;1) — 6 ta, P = 6/36 = 1/6. «Kamida bitta 6»: qarama-qarshisi «hech birida 6 yo‘q» — 5·5 = 25 natija. P = 1 − 25/36 = 11/36.', 'n = 6·6 = 36. Сумма 7: (1;6), (2;5), (3;4), (4;3), (5;2), (6;1) — 6, P = 6/36 = 1/6. «Хотя бы одна 6»: противоположное «ни одной 6» — 5·5 = 25 исходов. P = 1 − 25/36 = 11/36.', 'n = 6·6 = 36. Sum 7: (1;6), (2;5), (3;4), (4;3), (5;2), (6;1) — 6 outcomes, P = 6/36 = 1/6. “At least one 6”: the complement “no 6” has 5·5 = 25 outcomes. P = 1 − 25/36 = 11/36.') },
      { q: L('Ikki mergan nishonga 0,8 va 0,7 ehtimol bilan tegizadi. Ikkalasi tegizishi, kamida bittasi tegizishi va aynan bittasi tegizishi ehtimollari?', 'Два стрелка попадают с вероятностями 0,8 и 0,7. Вероятности: оба попадут, хотя бы один попадёт, ровно один попадёт?', 'Two shooters hit with probabilities 0.8 and 0.7. Find the probabilities: both hit, at least one hits, exactly one hits.'), s: L('Erkli. Ikkalasi: 0,8·0,7 = 0,56. Kamida bittasi: 1 − 0,2·0,3 = 1 − 0,06 = 0,94. Aynan bittasi: 0,8·0,3 + 0,2·0,7 = 0,24 + 0,14 = 0,38. Tekshiruv: 0,56 + 0,38 + 0,06 = 1 ✓.', 'Независимы. Оба: 0,8·0,7 = 0,56. Хотя бы один: 1 − 0,2·0,3 = 1 − 0,06 = 0,94. Ровно один: 0,8·0,3 + 0,2·0,7 = 0,24 + 0,14 = 0,38. Проверка: 0,56 + 0,38 + 0,06 = 1 ✓.', 'Independent. Both: 0.8·0.7 = 0.56. At least one: 1 − 0.2·0.3 = 1 − 0.06 = 0.94. Exactly one: 0.8·0.3 + 0.2·0.7 = 0.24 + 0.14 = 0.38. Check: 0.56 + 0.38 + 0.06 = 1 ✓.') },
      { q: L('10 ta lampochkadan 3 tasi nosoz. Tasodifan 2 tasi olinadi. Ikkalasi soz bo‘lishi ehtimoli?', 'Из 10 лампочек 3 неисправны. Наугад берут 2. Вероятность, что обе исправны?', 'Of 10 bulbs, 3 are faulty. Two are taken at random. Probability that both work?'), s: L('Kombinatorika: P = C₇²/C₁₀² = 21/45 = 7/15. Ko‘paytirish teoremasi bilan: 7/10·6/9 = 42/90 = 7/15 ✓.', 'Комбинаторика: P = C₇²/C₁₀² = 21/45 = 7/15. По теореме умножения: 7/10·6/9 = 42/90 = 7/15 ✓.', 'Combinatorics: P = C₇²/C₁₀² = 21/45 = 7/15. By the multiplication theorem: 7/10·6/9 = 42/90 = 7/15 ✓.') },
      { q: L('36 kartali dastadan bitta karta olindi. U tuz yoki chillak (♥) bo‘lishi ehtimoli?', 'Из колоды в 36 карт вынута одна. Вероятность, что это туз или червы (♥)?', 'One card is drawn from a 36-card deck. Probability that it is an ace or a heart (♥)?'), s: L('Tuz: 4/36, chillak: 9/36, chillak tuz: 1/36 (ikki marta sanalmasin). P = 4/36 + 9/36 − 1/36 = 12/36 = 1/3.', 'Туз: 4/36, червы: 9/36, туз червей: 1/36 (чтобы не считать дважды). P = 4/36 + 9/36 − 1/36 = 12/36 = 1/3.', 'Ace: 4/36, heart: 9/36, ace of hearts: 1/36 (to avoid double counting). P = 4/36 + 9/36 − 1/36 = 12/36 = 1/3.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Birgalikda bo‘lgan hodisalarda kesishmani ayirmaslik.</b> P(tuz yoki chillak) = 4/36 + 9/36 = 13/36 — xato, to‘g‘risi 12/36.', '<b>Не вычитать пересечение для совместных событий.</b> P(туз или червы) = 4/36 + 9/36 = 13/36 — ошибка, верно 12/36.', '<b>Not subtracting the overlap for non-exclusive events.</b> P(ace or heart) = 4/36 + 9/36 = 13/36 is wrong; correct is 12/36.'),
      L('<b>Bog‘liq hodisalarga erkli formula qo‘llash.</b> Qaytarmasdan olishda ikkinchi ehtimol o‘zgaradi: 5/8·5/8 emas, 5/8·4/7.', '<b>Применять формулу для независимых к зависимым.</b> При выборе без возвращения вторая вероятность меняется: не 5/8·5/8, а 5/8·4/7.', '<b>Using the independent formula for dependent events.</b> Without replacement the second probability changes: not 5/8·5/8 but 5/8·4/7.'),
      L('<b>Teng imkoniyatli bo‘lmagan natijalarni sanash.</b> Ikki kubikda yig‘indilar 2, 3, …, 12 — 11 ta, lekin ular teng imkoniyatli emas: P(7) = 6/36, P(2) = 1/36.', '<b>Считать неравновозможные исходы.</b> Суммы на двух кубиках 2, 3, …, 12 — 11 штук, но они не равновозможны: P(7) = 6/36, P(2) = 1/36.', '<b>Counting outcomes that are not equally likely.</b> Two dice give 11 sums 2, …, 12, but they are not equally likely: P(7) = 6/36, P(2) = 1/36.'),
      L('<b>«O‘yinchi xatosi».</b> Tanga 5 marta ketma-ket gerb tushsa, keyingisida raqam «chiqishi kerak» deb o‘ylash. Tanganing xotirasi yo‘q — ehtimol yana 1/2.', '<b>«Ошибка игрока».</b> Думать, что после 5 гербов подряд «должна» выпасть решка. У монеты нет памяти — вероятность снова 1/2.', '<b>The “gambler’s fallacy”.</b> Thinking that after 5 heads in a row tails “is due”. A coin has no memory — the probability is still 1/2.'),
      L('<b>Birgalikda bo‘lmaslik va erklilikni chalkashtirish.</b> Bular turli tushunchalar.', '<b>Путать несовместность и независимость.</b> Это разные понятия.', '<b>Confusing exclusivity with independence.</b> They are different notions.')
    ] },
    { kind: 'life', h: L('Ehtimollik hayotda', 'Вероятность в жизни', 'Probability in real life'), p: [
      L('<b>Sug‘urta</b> kompaniyalari baxtsiz hodisa ehtimollarini hisoblab, sug‘urta badalini belgilaydi. <b>Ob-havo</b> prognozidagi «yomg‘ir ehtimoli 70%» — shunday sharoitdagi kunlarning 70 foizida yomg‘ir yog‘ishini bildiradi. <b>Tibbiyot:</b> test natijasini to‘g‘ri talqin qilish uchun shartli ehtimollik kerak — kasallik kam uchrasa, hatto aniq test ham ko‘p «soxta musbat» natija beradi.', '<b>Страховые</b> компании рассчитывают вероятности несчастных случаев и назначают взносы. «Вероятность дождя 70%» в <b>прогнозе погоды</b> означает, что в 70% дней с такими условиями идёт дождь. <b>Медицина:</b> чтобы правильно истолковать результат теста, нужна условная вероятность — при редкой болезни даже точный тест даёт много «ложноположительных» результатов.', '<b>Insurance</b> companies compute accident probabilities to set premiums. “70% chance of rain” in a <b>weather forecast</b> means it rains on 70% of days with such conditions. <b>Medicine:</b> interpreting a test result correctly requires conditional probability — for a rare disease even an accurate test gives many “false positives”.'),
      L('<b>Texnika ishonchliligi:</b> ketma-ket ulangan qurilmalar hammasi ishlagandagina tizim ishlaydi (ehtimollar ko‘paytiriladi), parallel ulanganlarda esa kamida bittasi yetarli: P = 1 − P(hammasi buziladi). Shuning uchun samolyotlarda muhim tizimlar ikki-uch marta takrorlanadi. Agar bitta dvigatelning buzilish ehtimoli 0,001 bo‘lsa, ikkala erkli dvigatelning birga buzilishi 0,000001 — million marta kam.', '<b>Надёжность техники:</b> последовательно соединённые устройства работают, только если работают все (вероятности перемножаются), а при параллельном достаточно хотя бы одного: P = 1 − P(все откажут). Поэтому в самолётах важные системы дублируются два-три раза. Если вероятность отказа одного двигателя 0,001, то одновременный отказ двух независимых — 0,000001, в миллион раз реже.', '<b>Engineering reliability:</b> devices in series work only if all work (probabilities multiply), while in parallel at least one is enough: P = 1 − P(all fail). That is why critical aircraft systems are duplicated two or three times. If one engine fails with probability 0.001, two independent engines fail together with probability 0.000001 — a million times less often.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('De Mere muammosi yechimi: 4 tashlashda kamida bitta «6»: 1 − (5/6)⁴ ≈ 0,518 &gt; 1/2 — foydali. 24 tashlashda kamida bitta «6–6»: 1 − (35/36)²⁴ ≈ 0,491 &lt; 1/2 — zararli. Farq atigi 2,7%, lekin shevalye uni tajribada sezgan!', 'Решение задачи де Мере: хотя бы одна «6» за 4 броска: 1 − (5/6)⁴ ≈ 0,518 &gt; 1/2 — выгодно. Хотя бы одна «6–6» за 24 броска: 1 − (35/36)²⁴ ≈ 0,491 &lt; 1/2 — невыгодно. Разница всего 2,7%, но шевалье почувствовал её на практике!', 'De Méré’s problem solved: at least one “6” in 4 rolls: 1 − (5/6)⁴ ≈ 0.518 &gt; 1/2 — profitable. At least one double six in 24 rolls: 1 − (35/36)²⁴ ≈ 0.491 &lt; 1/2 — unprofitable. A difference of just 2.7%, yet the chevalier noticed it in practice!'),
      L('«Tug‘ilgan kunlar paradoksi»: 23 kishilik guruhda kamida ikki kishining tug‘ilgan kuni bir kunga to‘g‘ri kelish ehtimoli 50% dan oshadi (≈ 0,507), 60 kishida esa 99% dan ko‘p.', '«Парадокс дней рождения»: в группе из 23 человек вероятность совпадения дней рождения хотя бы у двоих больше 50% (≈ 0,507), а для 60 человек — больше 99%.', 'The “birthday paradox”: in a group of 23 people the probability that at least two share a birthday exceeds 50% (≈ 0.507), and with 60 people it exceeds 99%.'),
      L('Monti Xoll masalasi: uchta eshikdan birida avtomobil. Siz eshik tanlaysiz, boshlovchi bo‘sh eshiklardan birini ochadi. Tanlovni almashtirsangiz, yutish ehtimoli 1/3 dan 2/3 ga oshadi — buni ko‘plab professorlar ham dastlab qabul qilmagan.', 'Задача Монти Холла: за одной из трёх дверей автомобиль. Вы выбираете дверь, ведущий открывает одну из пустых. Если сменить выбор, вероятность выигрыша растёт с 1/3 до 2/3 — поначалу в это не верили даже многие профессора.', 'The Monty Hall problem: a car is behind one of three doors. You pick a door, the host opens an empty one. Switching raises your chance of winning from 1/3 to 2/3 — even many professors refused to believe it at first.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Klassik ta’rif: P(A) = m/n, 0 ≤ P(A) ≤ 1.', 'Классическое определение: P(A) = m/n, 0 ≤ P(A) ≤ 1.', 'Classical definition: P(A) = m/n, 0 ≤ P(A) ≤ 1.'),
      L('Qarama-qarshi hodisa: P(Ā) = 1 − P(A); «kamida bitta» masalalarida qulay.', 'Противоположное событие: P(Ā) = 1 − P(A); удобно в задачах «хотя бы один».', 'Complement: P(Ā) = 1 − P(A); handy for “at least one” problems.'),
      L('Qo‘shish: P(A ∪ B) = P(A) + P(B) − P(AB); birgalikda bo‘lmasa — P(A) + P(B).', 'Сложение: P(A ∪ B) = P(A) + P(B) − P(AB); для несовместных — P(A) + P(B).', 'Addition: P(A ∪ B) = P(A) + P(B) − P(AB); if exclusive, P(A) + P(B).'),
      L('Ko‘paytirish: P(AB) = P(A)·P(B|A); erkli bo‘lsa — P(A)·P(B).', 'Умножение: P(AB) = P(A)·P(B|A); для независимых — P(A)·P(B).', 'Multiplication: P(AB) = P(A)·P(B|A); if independent, P(A)·P(B).'),
      L('«Yoki» — qo‘shish, «va» — ko‘paytirish.', '«Или» — сложение, «и» — умножение.', '“Or” — add; “and” — multiply.'),
      L('Ehtimollar nazariyasi Paskal va Ferma yozishmalaridan (1654) boshlangan, Kolmogorov (1933) uni aksiomatik qurgan.', 'Теория вероятностей началась с переписки Паскаля и Ферма (1654), Колмогоров (1933) построил её аксиоматически.', 'Probability began with the Pascal–Fermat letters (1654); Kolmogorov (1933) gave it an axiomatic foundation.')
    ] }
  ] });

  // ---------- t20. Binomial va normal taqsimot ----------
  T.add(P, 't20', { sections: [
    { kind: 'intro', h: L('Ko‘p marta takrorlangan tajriba', 'Многократно повторённый опыт', 'An experiment repeated many times'), p: [
      L('Basketbolchi to‘pni savatga 70% ehtimol bilan tushiradi. 10 ta otishda u aynan 7 marta tushirishi ehtimoli qancha? Kamida 5 marta-chi? Test 10 ta savoldan iborat, har birida 4 ta javob — taxmin bilan nechta to‘g‘ri javob kutish mumkin? Zavod mahsulotining 2% i nosoz bo‘lsa, 1000 tadan nechtasi nosoz chiqadi? Bu savollarning umumiy jihati: bir xil tajriba ko‘p marta erkli takrorlanadi va «muvaffaqiyatlar» soni so‘raladi.', 'Баскетболист попадает в кольцо с вероятностью 70%. Какова вероятность, что из 10 бросков он попадёт ровно 7 раз? А хотя бы 5? Тест из 10 вопросов, в каждом 4 варианта — сколько верных ответов ожидать наугад? Если 2% продукции завода бракованные, сколько брака будет среди 1000 изделий? Общее в этих вопросах: один и тот же опыт независимо повторяется много раз, и спрашивают о числе «успехов».', 'A basketball player scores with probability 70%. What is the probability of exactly 7 baskets in 10 shots? At least 5? A test has 10 questions with 4 options each — how many correct answers can be expected by guessing? If 2% of a factory’s output is defective, how many of 1000 items will be faulty? What these questions share: the same experiment is repeated independently many times, and we ask about the number of “successes”.'),
      L('Bu mavzuda bunday masalalar uchun <b>Bernulli formulasi</b>ni va <b>binomial taqsimot</b>ni, so‘ngra tajribalar soni katta bo‘lganda paydo bo‘ladigan mashhur «qo‘ng‘iroq» — <b>normal taqsimot</b>ni o‘rganamiz. Normal taqsimot tabiat va jamiyatdagi eng ko‘p uchraydigan qonuniyatlardan biri.', 'В этой теме изучим для таких задач <b>формулу Бернулли</b> и <b>биномиальное распределение</b>, а затем знаменитый «колокол», появляющийся при большом числе опытов, — <b>нормальное распределение</b>. Это одна из самых распространённых закономерностей в природе и обществе.', 'In this topic we study the <b>Bernoulli formula</b> and the <b>binomial distribution</b> for such problems, and then the famous “bell” that appears when the number of trials is large — the <b>normal distribution</b>. It is one of the most common patterns in nature and society.')
    ] },
    { kind: 'def', h: L('Bernulli sxemasi', 'Схема Бернулли', 'Bernoulli trials'), p: [
      L('<b>Bernulli sxemasi</b> — n ta tajriba, ularning har biri: 1) erkli; 2) faqat ikki natijaga ega — «muvaffaqiyat» (ehtimoli p) va «muvaffaqiyatsizlik» (ehtimoli q = 1 − p); 3) p barcha tajribalarda bir xil. Misollar: tangani n marta tashlash (p = 1/2), kubikda «6» tushishini kuzatish (p = 1/6), merganning o‘q uzishi, sifat nazoratida mahsulotni tekshirish.', '<b>Схема Бернулли</b> — n опытов, каждый из которых: 1) независим; 2) имеет только два исхода — «успех» (вероятность p) и «неудача» (вероятность q = 1 − p); 3) p одинаково во всех опытах. Примеры: n бросков монеты (p = 1/2), наблюдение «6» на кубике (p = 1/6), выстрелы стрелка, проверка изделий при контроле качества.', '<b>Bernoulli trials</b> are n experiments, each of which: 1) is independent; 2) has only two outcomes — “success” (probability p) and “failure” (probability q = 1 − p); 3) has the same p in every trial. Examples: tossing a coin n times (p = 1/2), watching for a “6” on a die (p = 1/6), a shooter’s shots, checking items in quality control.'),
      L('n ta tajribadagi muvaffaqiyatlar soni X — <b>tasodifiy miqdor</b>: u 0, 1, 2, …, n qiymatlarni turli ehtimollar bilan qabul qiladi. Barcha qiymatlar va ularning ehtimollari ro‘yxati X ning <b>taqsimoti</b> deyiladi. Taqsimotdagi barcha ehtimollar yig‘indisi 1 ga teng.', 'Число успехов X в n опытах — <b>случайная величина</b>: она принимает значения 0, 1, 2, …, n с разными вероятностями. Список всех значений и их вероятностей называется <b>распределением</b> X. Сумма всех вероятностей распределения равна 1.', 'The number of successes X in n trials is a <b>random variable</b>: it takes the values 0, 1, 2, …, n with different probabilities. The list of all values with their probabilities is called the <b>distribution</b> of X. All probabilities in a distribution add up to 1.')
    ] },
    { kind: 'rule', h: L('Bernulli formulasi', 'Формула Бернулли', 'The Bernoulli formula'), p: [
      L('n ta tajribada aynan k marta muvaffaqiyat bo‘lish ehtimoli: <b>Pₙ(k) = Cₙᵏ·pᵏ·qⁿ⁻ᵏ</b>. <b>Isbot g‘oyasi.</b> Muvaffaqiyatlar ma’lum k ta o‘rinda, qolgan n − k ta o‘rinda muvaffaqiyatsizlik bo‘lgan bitta aniq ketma-ketlik (masalan, MMN…N) ning ehtimoli, erklilik tufayli, pᵏqⁿ⁻ᵏ ga teng. Bunday ketma-ketliklar soni — k ta o‘rinni n tadan tanlash usullari soni Cₙᵏ. Ular birgalikda emas, shuning uchun ehtimollar qo‘shiladi.', 'Вероятность ровно k успехов в n опытах: <b>Pₙ(k) = Cₙᵏ·pᵏ·qⁿ⁻ᵏ</b>. <b>Идея доказательства.</b> Вероятность одной конкретной последовательности (например, УУН…Н), где успехи стоят на определённых k местах, а неудачи — на остальных n − k, в силу независимости равна pᵏqⁿ⁻ᵏ. Таких последовательностей столько, сколькими способами можно выбрать k мест из n, — Cₙᵏ. Они несовместны, поэтому вероятности складываются.', 'The probability of exactly k successes in n trials: <b>Pₙ(k) = Cₙᵏ·pᵏ·qⁿ⁻ᵏ</b>. <b>Proof idea.</b> One particular sequence (say SSF…F) with successes in k given places and failures in the other n − k has probability pᵏqⁿ⁻ᵏ by independence. The number of such sequences is the number of ways to choose k places out of n, Cₙᵏ. They are mutually exclusive, so the probabilities add.'),
      L('Nomining sababi: Pₙ(k) — (q + p)ⁿ binom yoyilmasining hadlari. Shuning uchun ularning yig‘indisi (q + p)ⁿ = 1ⁿ = 1. <b>Asosiy xarakteristikalar:</b> kutilma (o‘rtacha muvaffaqiyatlar soni) <b>M = np</b>, dispersiya <b>D = npq</b>, standart chetlanish <b>σ = √(npq)</b>. <b>Eng ehtimolli son</b> k₀ quyidagi tengsizlikni qanoatlantiradi: np − q ≤ k₀ ≤ np + p.', 'Почему распределение «биномиальное»: Pₙ(k) — члены разложения бинома (q + p)ⁿ. Поэтому их сумма (q + p)ⁿ = 1ⁿ = 1. <b>Основные характеристики:</b> математическое ожидание (среднее число успехов) <b>M = np</b>, дисперсия <b>D = npq</b>, стандартное отклонение <b>σ = √(npq)</b>. <b>Наивероятнейшее число</b> k₀ удовлетворяет неравенству np − q ≤ k₀ ≤ np + p.', 'Why “binomial”: the Pₙ(k) are the terms of the expansion of (q + p)ⁿ. So they add up to (q + p)ⁿ = 1ⁿ = 1. <b>Key characteristics:</b> the expected value (mean number of successes) <b>M = np</b>, variance <b>D = npq</b>, standard deviation <b>σ = √(npq)</b>. The <b>most probable number</b> k₀ satisfies np − q ≤ k₀ ≤ np + p.')
    ] },
    { kind: 'history', h: L('Bernullidan Galton taxtasigacha', 'От Бернулли до доски Гальтона', 'From Bernoulli to the Galton board'), p: [
      L('Shveytsariyalik <b>Yakob Bernulli</b> «Taxminlar san’ati» kitobida (vafotidan keyin, 1713-yilda nashr etilgan) shu formulani va <b>katta sonlar qonuni</b>ni isbotladi: tajribalar soni oshgani sari muvaffaqiyatlarning nisbiy chastotasi k/n ehtimol p ga yaqinlashadi. Bernulli bu isbotga 20 yil sarflaganini yozgan. 1733-yilda Angliyada yashagan fransuz <b>Abraam de Muavr</b> n katta bo‘lganda binomial ehtimollarni qo‘ng‘iroqsimon egri chiziq bilan almashtirish mumkinligini ko‘rsatdi.', 'Швейцарец <b>Якоб Бернулли</b> в книге «Искусство предположений» (издана посмертно в 1713 году) доказал эту формулу и <b>закон больших чисел</b>: с ростом числа опытов относительная частота успехов k/n приближается к вероятности p. Бернулли писал, что потратил на это доказательство 20 лет. В 1733 году француз <b>Абрахам де Муавр</b>, живший в Англии, показал, что при больших n биномиальные вероятности можно заменить колоколообразной кривой.', 'The Swiss <b>Jacob Bernoulli</b>, in “The Art of Conjecturing” (published posthumously in 1713), proved this formula and the <b>law of large numbers</b>: as the number of trials grows, the relative frequency k/n of successes approaches the probability p. Bernoulli wrote that the proof took him 20 years. In 1733 the Frenchman <b>Abraham de Moivre</b>, living in England, showed that for large n binomial probabilities can be replaced by a bell-shaped curve.'),
      L('<b>Laplas</b> bu natijani umumlashtirdi, <b>Gauss</b> esa 1809-yilda astronomik o‘lchov xatolari aynan shu egri chiziq bo‘yicha taqsimlanishini ko‘rsatdi — shuning uchun normal taqsimot «Gauss taqsimoti» ham deyiladi. 1873-yilda <b>Frensis Galton</b> mixlar qatorlaridan iborat taxta yasadi: yuqoridan tashlangan sharchalar har bir mixda 1/2 ehtimol bilan chapga yoki o‘ngga buriladi va pastda binomial taqsimotni, ko‘p qatorlarda esa deyarli normal «qo‘ng‘iroq»ni hosil qiladi.', '<b>Лаплас</b> обобщил этот результат, а <b>Гаусс</b> в 1809 году показал, что ошибки астрономических измерений распределены именно по этой кривой, — поэтому нормальное распределение называют также «гауссовым». В 1873 году <b>Фрэнсис Гальтон</b> построил доску с рядами гвоздей: шарики, падающие сверху, на каждом гвозде с вероятностью 1/2 отклоняются влево или вправо и внизу образуют биномиальное распределение, а при многих рядах — почти нормальный «колокол».', '<b>Laplace</b> generalised the result, and in 1809 <b>Gauss</b> showed that astronomical measurement errors follow exactly this curve — which is why the normal distribution is also called “Gaussian”. In 1873 <b>Francis Galton</b> built a board with rows of pins: balls dropped from the top bounce left or right with probability 1/2 at each pin and form a binomial distribution at the bottom — and with many rows an almost normal “bell”.')
    ] },
    { kind: 'table', h: L('Binomial taqsimot: n = 4, p = 1/2', 'Биномиальное распределение: n = 4, p = 1/2', 'Binomial distribution: n = 4, p = 1/2'), p: [
      L('4 ta tanga tashlanganda gerblar soni X. Har bir ehtimol — C₄ᵏ/16; koeffitsiyentlar Paskal uchburchagining 4-qatori.', 'Число гербов X при броске 4 монет. Каждая вероятность — C₄ᵏ/16; коэффициенты — 4-я строка треугольника Паскаля.', 'The number of heads X when 4 coins are tossed. Each probability is C₄ᵏ/16; the coefficients are row 4 of Pascal’s triangle.')
    ], table: { head: [L('Gerblar soni k', 'Число гербов k', 'Number of heads k'), S('0'), S('1'), S('2'), S('3'), S('4')], rows: [
      [L('P(X = k)', 'P(X = k)', 'P(X = k)'), S('1/16'), S('4/16'), S('6/16'), S('4/16'), S('1/16')],
      [L('Foizda', 'В процентах', 'Percent'), S('6,25%'), S('25%'), S('37,5%'), S('25%'), S('6,25%')]
    ] }, after: [
      L('Kutilma M = 4·1/2 = 2, σ = √(4·1/2·1/2) = 1. Taqsimot simmetrik, eng ehtimolli qiymat — 2. p ≠ 1/2 bo‘lsa, taqsimot bir tomonga «og‘adi».', 'Ожидание M = 4·1/2 = 2, σ = √(4·1/2·1/2) = 1. Распределение симметрично, наивероятнейшее значение — 2. При p ≠ 1/2 распределение «перекашивается».', 'Expected value M = 4·1/2 = 2, σ = √(4·1/2·1/2) = 1. The distribution is symmetric, with most probable value 2. When p ≠ 1/2 it becomes skewed.')
    ] },
    { kind: 'rule', h: L('Normal taqsimot va 68–95–99,7 qoidasi', 'Нормальное распределение и правило 68–95–99,7', 'The normal distribution and the 68–95–99.7 rule'), p: [
      L('n katta bo‘lganda binomial taqsimot gistogrammasi silliq qo‘ng‘iroqsimon egri chiziqqa yaqinlashadi. Bu — <b>normal taqsimot</b> egri chizig‘i: f(x) = (1/(σ√(2π)))·e<sup>−(x − μ)²/(2σ²)</sup>. U ikki parametrga bog‘liq: <b>μ</b> — o‘rtacha (cho‘qqi joyi va simmetriya o‘qi) va <b>σ</b> — standart chetlanish (qo‘ng‘iroq kengligi). Egri chiziq ostidagi umumiy yuz 1 ga teng, biror oraliq ustidagi yuz esa qiymatning shu oraliqqa tushish ehtimoli.', 'При больших n гистограмма биномиального распределения приближается к гладкой колоколообразной кривой. Это кривая <b>нормального распределения</b>: f(x) = (1/(σ√(2π)))·e<sup>−(x − μ)²/(2σ²)</sup>. Она зависит от двух параметров: <b>μ</b> — среднее (положение вершины и ось симметрии) и <b>σ</b> — стандартное отклонение (ширина колокола). Вся площадь под кривой равна 1, а площадь над промежутком — вероятность попасть в этот промежуток.', 'For large n the histogram of the binomial distribution approaches a smooth bell-shaped curve. This is the <b>normal distribution</b> curve: f(x) = (1/(σ√(2π)))·e<sup>−(x − μ)²/(2σ²)</sup>. It depends on two parameters: <b>μ</b>, the mean (position of the peak and axis of symmetry), and <b>σ</b>, the standard deviation (width of the bell). The total area under the curve is 1, and the area over an interval is the probability of landing in it.'),
      L('<b>68–95–99,7 qoidasi:</b> normal taqsimlangan qiymatlarning taxminan <b>68%</b> i μ ± σ oralig‘ida, <b>95%</b> i μ ± 2σ da, <b>99,7%</b> i μ ± 3σ da yotadi. Demak, o‘rtachadan 3σ dan ko‘proq farq qiladigan qiymat juda kam uchraydi (1000 tadan 3 ta). Binomial taqsimot uchun μ = np, σ = √(npq); yaqinlashish odatda np va nq ikkalasi ham taxminan 10 dan katta bo‘lganda yaxshi ishlaydi.', '<b>Правило 68–95–99,7:</b> около <b>68%</b> нормально распределённых значений лежит в μ ± σ, <b>95%</b> — в μ ± 2σ, <b>99,7%</b> — в μ ± 3σ. Значит, значение, отличающееся от среднего более чем на 3σ, встречается очень редко (3 из 1000). Для биномиального распределения μ = np, σ = √(npq); приближение обычно хорошо работает, когда и np, и nq больше примерно 10.', '<b>The 68–95–99.7 rule:</b> about <b>68%</b> of normally distributed values lie within μ ± σ, <b>95%</b> within μ ± 2σ and <b>99.7%</b> within μ ± 3σ. So a value more than 3σ from the mean is very rare (3 in 1000). For the binomial distribution μ = np and σ = √(npq); the approximation usually works well when both np and nq exceed about 10.')
    ] },
    { kind: 'steps', h: L('Masalani yechish tartibi', 'Порядок решения задачи', 'How to solve a problem'), list: [
      L('Bernulli sxemasi shartlarini tekshiring: erklilik, ikki natija, o‘zgarmas p.', 'Проверьте условия схемы Бернулли: независимость, два исхода, постоянное p.', 'Check the Bernoulli conditions: independence, two outcomes, constant p.'),
      L('n, p, q = 1 − p va kerakli k (yoki k lar oralig‘i) ni yozing.', 'Запишите n, p, q = 1 − p и нужное k (или диапазон k).', 'Write down n, p, q = 1 − p and the required k (or range of k).'),
      L('n kichik bo‘lsa — Bernulli formulasini qo‘llang; «kamida» bo‘lsa, ehtimollarni qo‘shing yoki qarama-qarshi hodisadan foydalaning.', 'При малом n применяйте формулу Бернулли; для «хотя бы» складывайте вероятности или используйте противоположное событие.', 'For small n use the Bernoulli formula; for “at least”, add probabilities or use the complement.'),
      L('n katta bo‘lsa — μ = np, σ = √(npq) ni toping va 68–95–99,7 qoidasi bilan baholang.', 'При большом n найдите μ = np, σ = √(npq) и оцените по правилу 68–95–99,7.', 'For large n find μ = np, σ = √(npq) and estimate with the 68–95–99.7 rule.'),
      L('Natija ma’nosini tekshiring: ehtimollar 0 va 1 orasida, kutilma 0 va n orasida.', 'Проверьте смысл: вероятности между 0 и 1, ожидание между 0 и n.', 'Check for sense: probabilities between 0 and 1, the expected value between 0 and n.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar: Bernulli formulasi', 'Решённые примеры: формула Бернулли', 'Solved examples: the Bernoulli formula'), ex: [
      { q: L('Tanga 5 marta tashlandi. Aynan 3 marta gerb tushishi ehtimoli?', 'Монету бросили 5 раз. Вероятность ровно 3 гербов?', 'A coin is tossed 5 times. Probability of exactly 3 heads?'), s: L('n = 5, k = 3, p = q = 1/2. P₅(3) = C₅³·(1/2)³·(1/2)² = 10/32 = 5/16 ≈ 0,31.', 'n = 5, k = 3, p = q = 1/2. P₅(3) = C₅³·(1/2)³·(1/2)² = 10/32 = 5/16 ≈ 0,31.', 'n = 5, k = 3, p = q = 1/2. P₅(3) = C₅³·(1/2)³·(1/2)² = 10/32 = 5/16 ≈ 0.31.') },
      { q: L('Kubik 4 marta tashlandi. Aynan 2 marta «6» tushishi ehtimoli?', 'Кубик бросили 4 раза. Вероятность ровно двух «6»?', 'A die is rolled 4 times. Probability of exactly two sixes?'), s: L('p = 1/6, q = 5/6. P₄(2) = C₄²·(1/6)²·(5/6)² = 6·1/36·25/36 = 150/1296 = 25/216 ≈ 0,116.', 'p = 1/6, q = 5/6. P₄(2) = C₄²·(1/6)²·(5/6)² = 6·1/36·25/36 = 150/1296 = 25/216 ≈ 0,116.', 'p = 1/6, q = 5/6. P₄(2) = C₄²·(1/6)²·(5/6)² = 6·1/36·25/36 = 150/1296 = 25/216 ≈ 0.116.') },
      { q: L('Mergan 0,8 ehtimol bilan tegizadi. 5 ta o‘qdan kamida 4 tasi tegishi ehtimoli?', 'Стрелок попадает с вероятностью 0,8. Вероятность хотя бы 4 попаданий из 5?', 'A shooter hits with probability 0.8. Probability of at least 4 hits out of 5?'), s: L('P₅(4) = 5·0,8⁴·0,2 = 5·0,4096·0,2 = 0,4096. P₅(5) = 0,8⁵ = 0,32768. Yig‘indi: 0,73728 ≈ 0,74.', 'P₅(4) = 5·0,8⁴·0,2 = 5·0,4096·0,2 = 0,4096. P₅(5) = 0,8⁵ = 0,32768. Сумма: 0,73728 ≈ 0,74.', 'P₅(4) = 5·0.8⁴·0.2 = 5·0.4096·0.2 = 0.4096. P₅(5) = 0.8⁵ = 0.32768. Total: 0.73728 ≈ 0.74.') },
      { q: L('10 savolli testda har bir savolda 4 ta variant. Taxmin bilan javob berilsa, kutilma va hamma javob to‘g‘ri bo‘lishi ehtimoli?', 'Тест из 10 вопросов по 4 варианта. При ответах наугад — ожидание и вероятность, что все ответы верны?', 'A 10-question test, 4 options each. Guessing — the expected score and the probability that all answers are correct?'), s: L('p = 1/4. M = 10·1/4 = 2,5 ta to‘g‘ri javob. Hammasi to‘g‘ri: (1/4)¹⁰ = 1/1 048 576 — milliondan birdan ham kam.', 'p = 1/4. M = 10·1/4 = 2,5 верных ответа. Все верны: (1/4)¹⁰ = 1/1 048 576 — меньше одного на миллион.', 'p = 1/4. M = 10·1/4 = 2.5 correct answers. All correct: (1/4)¹⁰ = 1/1,048,576 — less than one in a million.') },
      { q: L('n = 10, p = 0,3 uchun eng ehtimolli muvaffaqiyatlar sonini toping.', 'Найдите наивероятнейшее число успехов при n = 10, p = 0,3.', 'Find the most probable number of successes for n = 10, p = 0.3.'), s: L('np − q = 3 − 0,7 = 2,3; np + p = 3 + 0,3 = 3,3. 2,3 ≤ k₀ ≤ 3,3 → k₀ = 3.', 'np − q = 3 − 0,7 = 2,3; np + p = 3 + 0,3 = 3,3. 2,3 ≤ k₀ ≤ 3,3 → k₀ = 3.', 'np − q = 3 − 0.7 = 2.3; np + p = 3 + 0.3 = 3.3. 2.3 ≤ k₀ ≤ 3.3, so k₀ = 3.') }
    ] },
    { kind: 'example', h: L('Yechilgan misollar: normal yaqinlashish', 'Решённые примеры: нормальное приближение', 'Solved examples: the normal approximation'), ex: [
      { q: L('Tanga 100 marta tashlandi. Gerblar soni qaysi oraliqda 95% ehtimol bilan bo‘ladi?', 'Монету бросили 100 раз. В каком промежутке с вероятностью 95% окажется число гербов?', 'A coin is tossed 100 times. In what range will the number of heads lie with 95% probability?'), s: L('μ = 100·0,5 = 50, σ = √(100·0,25) = 5. μ ± 2σ = 50 ± 10 → 40 dan 60 gacha. Qiziq: aynan 50 ta gerb tushish ehtimoli atigi ≈ 0,08!', 'μ = 100·0,5 = 50, σ = √(100·0,25) = 5. μ ± 2σ = 50 ± 10 → от 40 до 60. Интересно: вероятность ровно 50 гербов всего ≈ 0,08!', 'μ = 100·0.5 = 50, σ = √(100·0.25) = 5. μ ± 2σ = 50 ± 10, i.e. from 40 to 60. Curiously, the probability of exactly 50 heads is only ≈ 0.08!') },
      { q: L('Zavod mahsulotining 2% i nosoz. 1000 ta mahsulotda nosozlar sonini baholang.', 'Брак составляет 2% продукции. Оцените число бракованных среди 1000 изделий.', '2% of a factory’s output is defective. Estimate the number of defects among 1000 items.'), s: L('μ = 1000·0,02 = 20, σ = √(1000·0,02·0,98) = √19,6 ≈ 4,43. 95% ehtimol bilan nosozlar 20 ± 8,9, ya’ni taxminan 11 dan 29 gacha. Agar partiyada 40 ta nosoz chiqsa (μ + 4,5σ), bu tasodif emas — dastgohni tekshirish kerak.', 'μ = 1000·0,02 = 20, σ = √(1000·0,02·0,98) = √19,6 ≈ 4,43. С вероятностью 95% брака 20 ± 8,9, то есть примерно от 11 до 29. Если в партии 40 бракованных (μ + 4,5σ), это не случайность — нужно проверить станок.', 'μ = 1000·0.02 = 20, σ = √(1000·0.02·0.98) = √19.6 ≈ 4.43. With 95% probability the defects number 20 ± 8.9, i.e. about 11 to 29. If a batch has 40 defects (μ + 4.5σ), it is no accident — the machine must be checked.') },
      { q: L('Yigitlarning bo‘yi normal taqsimlangan: μ = 170 sm, σ = 6 sm. Necha foizi 182 sm dan baland?', 'Рост юношей распределён нормально: μ = 170 см, σ = 6 см. Какой процент выше 182 см?', 'Young men’s heights are normally distributed with μ = 170 cm, σ = 6 cm. What percentage are taller than 182 cm?'), s: L('182 = 170 + 2·6 = μ + 2σ. μ ± 2σ (158–182 sm) da 95%, tashqarida 5%; simmetriya bo‘yicha yuqori «dum»da 2,5%. Javob: ≈ 2,5% (har 40 yigitdan bittasi).', '182 = 170 + 2·6 = μ + 2σ. В μ ± 2σ (158–182 см) — 95%, вне — 5%; по симметрии в верхнем «хвосте» 2,5%. Ответ: ≈ 2,5% (один из 40 юношей).', '182 = 170 + 2·6 = μ + 2σ. Within μ ± 2σ (158–182 cm) lie 95%, outside 5%; by symmetry the upper “tail” holds 2.5%. Answer: ≈ 2.5% (one young man in 40).') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Cₙᵏ ni unutish.</b> P(5 tangadan 3 gerb) = (1/2)⁵ = 1/32 emas — bu faqat bitta ketma-ketlik ehtimoli; 10 ta shunday ketma-ketlik bor.', '<b>Забыть Cₙᵏ.</b> P(3 герба из 5) — не (1/2)⁵ = 1/32: это вероятность одной последовательности, а их 10.', '<b>Forgetting Cₙᵏ.</b> P(3 heads in 5) is not (1/2)⁵ = 1/32 — that is the probability of a single sequence, and there are 10 of them.'),
      L('<b>«Kamida k» va «aynan k» ni chalkashtirish.</b> «Kamida 4» = P(4) + P(5) + …', '<b>Путать «хотя бы k» и «ровно k».</b> «Хотя бы 4» = P(4) + P(5) + …', '<b>Confusing “at least k” with “exactly k”.</b> “At least 4” = P(4) + P(5) + …'),
      L('<b>Bog‘liq tajribalarga Bernulli formulasini qo‘llash.</b> Qutidan sharlarni qaytarmasdan olishda p har safar o‘zgaradi — bu Bernulli sxemasi emas.', '<b>Применять формулу Бернулли к зависимым опытам.</b> При выборе шаров без возвращения p каждый раз меняется — это не схема Бернулли.', '<b>Applying the Bernoulli formula to dependent trials.</b> Drawing balls without replacement changes p each time — that is not a Bernoulli scheme.'),
      L('<b>σ o‘rniga dispersiyani olish.</b> σ = √(npq), npq emas. 100 tangada σ = 5, 25 emas.', '<b>Брать дисперсию вместо σ.</b> σ = √(npq), а не npq. Для 100 монет σ = 5, а не 25.', '<b>Using the variance instead of σ.</b> σ = √(npq), not npq. For 100 coins σ = 5, not 25.'),
      L('<b>Hamma narsani normal deb hisoblash.</b> Daromadlar, zilzilalar kuchi, shaharlar aholisi kabi miqdorlar normal taqsimlanmaydi — ularda «uzun dum» bor.', '<b>Считать всё нормальным.</b> Доходы, сила землетрясений, население городов не распределены нормально — у них «длинный хвост».', '<b>Assuming everything is normal.</b> Incomes, earthquake strengths and city populations are not normally distributed — they have “long tails”.')
    ] },
    { kind: 'life', h: L('Taqsimotlar hayotda', 'Распределения в жизни', 'Distributions in real life'), p: [
      L('<b>Sanoat va sifat:</b> «olti sigma» boshqaruv tizimi ishlab chiqarishda nuqsonlarni μ dan ±6σ chegarada ushlashga intiladi — bu millionta mahsulotga bir necha nosoz demakdir. <b>Tibbiyot:</b> yangi dori sinovida 200 bemordan nechtasi tuzalishi binomial taqsimot bilan baholanadi va natija tasodif emasligi tekshiriladi. <b>Aviatsiya:</b> aviakompaniyalar yo‘lovchilarning bir qismi kelmasligini (masalan, 5%) bilib, binomial hisob asosida chiptalarni o‘rinlardan biroz ko‘proq sotadi.', '<b>Промышленность и качество:</b> система управления «шесть сигм» стремится держать дефекты в пределах ±6σ от μ — это несколько бракованных на миллион изделий. <b>Медицина:</b> при испытании нового лекарства число выздоровевших из 200 больных оценивают биномиальным распределением и проверяют, что результат не случаен. <b>Авиация:</b> зная, что часть пассажиров не явится (например, 5%), авиакомпании по биномиальному расчёту продают билетов чуть больше, чем мест.', '<b>Industry and quality:</b> the “six sigma” management system aims to keep defects within ±6σ of μ — just a few faulty items per million. <b>Medicine:</b> in a drug trial, the number of patients out of 200 who recover is assessed with the binomial distribution to check the result is not due to chance. <b>Aviation:</b> knowing that some passengers will not show up (say 5%), airlines use binomial calculations to sell slightly more tickets than seats.'),
      L('<b>Ta’lim va psixologiya:</b> IQ testlari natijalari μ = 100, σ = 15 bo‘ladigan qilib moslashtiriladi; demak, odamlarning 95% i 70 dan 130 gacha ball oladi. Xalqaro imtihonlar ballari ham normal shkalaga keltiriladi. <b>Fizika:</b> molekulalar tezliklari, o‘lchov xatolari, shovqin — hammasi normal yoki unga yaqin qonunga bo‘ysunadi. Sababi <b>markaziy limit teoremasi</b>: ko‘plab kichik erkli ta’sirlar yig‘indisi deyarli doim normal taqsimotga ega.', '<b>Образование и психология:</b> результаты IQ-тестов нормируют так, чтобы μ = 100, σ = 15; значит, 95% людей набирают от 70 до 130. Баллы международных экзаменов тоже приводят к нормальной шкале. <b>Физика:</b> скорости молекул, ошибки измерений, шумы подчиняются нормальному или близкому закону. Причина — <b>центральная предельная теорема</b>: сумма многих малых независимых воздействий почти всегда распределена нормально.', '<b>Education and psychology:</b> IQ test results are scaled so that μ = 100 and σ = 15; so 95% of people score between 70 and 130. International exam scores are also mapped to a normal scale. <b>Physics:</b> molecular velocities, measurement errors and noise follow the normal law or something close to it. The reason is the <b>central limit theorem</b>: the sum of many small independent influences is almost always normally distributed.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), list: [
      L('Germaniyaning 10 markalik banknotida (1991–2001) Gauss portreti yonida normal taqsimot egri chizig‘i va uning formulasi tasvirlangan edi.', 'На банкноте в 10 немецких марок (1991–2001) рядом с портретом Гаусса были изображены кривая нормального распределения и её формула.', 'The German 10-mark banknote (1991–2001) showed the normal distribution curve and its formula next to Gauss’s portrait.'),
      L('Galton taxtasini o‘yinchoq sifatida sotib olish mumkin: sharchalar har safar tasodifiy yo‘l bilan tushadi, lekin pastda doim bir xil qo‘ng‘iroq shakli hosil bo‘ladi — tartib tartibsizlikdan tug‘iladi.', 'Доску Гальтона продают как игрушку: шарики каждый раз падают случайно, но внизу всегда получается один и тот же колокол — порядок рождается из хаоса.', 'You can buy a Galton board as a toy: the balls fall randomly every time, yet the same bell shape always forms at the bottom — order is born from chaos.'),
      L('Bernulli o‘zining katta sonlar qonunini «oltin teorema» deb atagan.', 'Бернулли называл свой закон больших чисел «золотой теоремой».', 'Bernoulli called his law of large numbers the “golden theorem”.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Bernulli sxemasi: n ta erkli tajriba, ikki natija, o‘zgarmas p, q = 1 − p.', 'Схема Бернулли: n независимых опытов, два исхода, постоянное p, q = 1 − p.', 'Bernoulli trials: n independent trials, two outcomes, constant p, q = 1 − p.'),
      L('Bernulli formulasi: Pₙ(k) = Cₙᵏpᵏqⁿ⁻ᵏ.', 'Формула Бернулли: Pₙ(k) = Cₙᵏpᵏqⁿ⁻ᵏ.', 'Bernoulli formula: Pₙ(k) = Cₙᵏpᵏqⁿ⁻ᵏ.'),
      L('Kutilma np, dispersiya npq, σ = √(npq); eng ehtimolli son: np − q ≤ k₀ ≤ np + p.', 'Ожидание np, дисперсия npq, σ = √(npq); наивероятнейшее число: np − q ≤ k₀ ≤ np + p.', 'Expected value np, variance npq, σ = √(npq); most probable number: np − q ≤ k₀ ≤ np + p.'),
      L('n katta bo‘lsa, binomial taqsimot normal taqsimotga yaqinlashadi (μ = np, σ = √(npq)).', 'При больших n биномиальное распределение близко к нормальному (μ = np, σ = √(npq)).', 'For large n the binomial distribution approaches the normal one (μ = np, σ = √(npq)).'),
      L('Normal egri chiziq: simmetrik qo‘ng‘iroq, cho‘qqisi μ da, kengligi σ ga bog‘liq.', 'Нормальная кривая: симметричный колокол, вершина в μ, ширина зависит от σ.', 'Normal curve: a symmetric bell, peak at μ, width set by σ.'),
      L('68–95–99,7 qoidasi: μ ± σ, μ ± 2σ, μ ± 3σ.', 'Правило 68–95–99,7: μ ± σ, μ ± 2σ, μ ± 3σ.', 'The 68–95–99.7 rule: μ ± σ, μ ± 2σ, μ ± 3σ.')
    ] }
  ] });

})(this);
